// ═══ ตัวเฝ้าระวังสุขภาพฐานข้อมูล ════════════════════════════════════════════
// 30 ก.ค. 69 ฐานข้อมูลใช้เครดิต Disk IO หมดกลางวันทำการ สาขาล็อกอินไม่ได้ และเรารู้
// ก็ตอนที่สาขาโทรมาแจ้ง — ซึ่งสายไปแล้ว ตัวนี้อ่านผลจากคำขอที่แอปยิงอยู่แล้วทุกครั้ง
// (ไม่ยิงเพิ่มเลยแม้แต่ครั้งเดียว — สำคัญ เพราะตัวเฝ้าระวังที่เพิ่มภาระคือการยิงเท้าตัวเอง)
// แล้วเตือนตอน "ยังตอบได้แต่เริ่มช้า" ซึ่งเป็นจังหวะที่ยังกู้ทันก่อนล่มจริง
//
// จับเฉพาะสัญญาณที่เป็นปัญหาโครงสร้างจริง: ตอบช้าเกิน 4 วินาที, HTTP 5xx, หรือยิงไม่ออก
// ไม่นับ 4xx (นั่นคือบั๊กของแอปเราเอง ไม่ใช่ฐานข้อมูลป่วย) และไม่นับตอนเน็ตผู้ใช้หลุด
// แยกอาการเป็น 3 ระดับ ไม่ใช่ ดี/ไม่ดี เพราะ "ช้า" กับ "พัง" มีน้ำหนักต่างกันมาก:
// ช้าอาจเป็นเน็ตมือถือของผู้ใช้เอง (ไม่ใช่ความผิดฐานข้อมูล) แต่ 5xx/ยิงไม่ออกคือปัญหาจริง
// จึงตั้งเกณฑ์ให้ "พัง 3 ครั้ง" เตือนเลย ส่วน "ช้า" ต้องช้าติดกันถึง 6 ครั้งจึงเตือน
const DBH = {
  ring: [], WINDOW: 12, ERR_TRIGGER: 3, SLOW_TRIGGER: 6,
  SLOW_MS: 4000, HANG_MS: 8000,
  degraded: false, listeners: new Set(), lastMs: 0,
};
const nowMs = () => ((typeof performance!=="undefined"&&performance.now)?performance.now():Date.now());
const dbhSubscribe = (fn) => { DBH.listeners.add(fn); return () => DBH.listeners.delete(fn); };
// เตือนซ้ำได้ไม่เกินทุก 30 นาที (เก็บใน localStorage จึงไม่รีเซ็ตตอนรีเฟรชหน้า)
// ถ้าไม่คุมไว้ การล่ม 2 ชั่วโมงจะยิงแจ้งเตือนเป็นร้อยครั้งจนคนปิดการแจ้งเตือนทิ้ง
function dbhCanAlert(kind){
  try{
    const k=`fc_dbh_${kind}_at`, last=+(localStorage.getItem(k)||0);
    if(Date.now()-last < 30*60*1000) return false;
    localStorage.setItem(k,String(Date.now()));
    return true;
  }catch{ return false; }   // โหมดส่วนตัวเขียนไม่ได้ → ไม่ยิง ดีกว่ายิงรัว
}
// ยิงคำขอที่เล็กที่สุดเท่าที่จะเล็กได้ เพื่อวัดเส้นทางล้วนๆ โดยไม่มีข้อมูลมาถ่วง
async function dbhProbe(){
  const t0=nowMs();
  try{
    const r=await fetch(`${SUPA_URL}/rest/v1/branches?select=id&limit=1`,
      {headers:{apikey:SUPA_KEY,Authorization:`Bearer ${SUPA_KEY}`},cache:"no-store"});
    await r.text();
    return { ms:Math.round(nowMs()-t0), ok:r.ok };
  }catch{ return { ms:Math.round(nowMs()-t0), ok:false }; }
}
async function dbhAlert(kind){
  if(!dbhCanAlert(kind))return;
  let msg;
  if(kind!=="down"){
    msg = { title:"✅ ระบบกลับมาปกติ", body:"ความเร็วกลับมาปกติแล้ว ใช้งานได้ตามปกติ" };
  }else{
    const slowSec = Math.round(DBH.lastMs/100)/10;
    const p = await dbhProbe();
    // คำขอจิ๋วยังเร็ว = ปลายทางปกติ · ช้าทั้งคู่ = เน็ตหรือปลายทางจริงๆ · ยิงไม่ออก = ล่ม
    const where = !p.ok            ? "ต่อฐานข้อมูลไม่ได้เลย — น่าจะล่มจริง ตรวจ Supabase ทันที"
                : p.ms > 3000      ? `คำขอจิ๋วก็ช้า (${p.ms} ms) — เน็ตของสาขาหรือฐานข้อมูลช้าจริง`
                :                    `แต่คำขอจิ๋วเร็วปกติ (${p.ms} ms) — ฐานข้อมูลไม่ได้ช้า ปัญหาอยู่ที่เครื่องนี้ (เช็กสัญญาณ wifi และโหมดประหยัดแบต)`;
    msg = { title:"⚠️ ระบบตอบช้า", body:`คำสั่งใช้เวลา ${slowSec} วินาที ${where}` };
  }
  // ยิงผ่าน Vercel (คนละเครื่องกับฐานข้อมูล) จึงยังส่งได้ตอนฐานข้อมูลเริ่มป่วย
  // ── ส่งเข้ามือถือเจ้าของเมื่อไหร่ ──────────────────────────────────────
  // คำขอจิ๋วเร็วปกติ = ฐานข้อมูลดี ปัญหาอยู่ที่เครื่อง/เน็ตของเครื่องนี้ ⟹ ไม่ส่งเข้ามือถือ
  // แถบเตือนบนจอเครื่องนั้นยังขึ้นตามเดิม (คนที่แก้ได้คือคนที่ถือเครื่องนั้น ไม่ใช่เจ้าของที่บ้าน)
  // ระบบล่มจริงมีตัวเฝ้าระวังภายนอก (GitHub ทุก 10 นาที) ยิงเข้ามือถือ + LINE อยู่แล้ว
  // เดิมส่งทุกครั้ง ข้อความเองยังบอกว่า "ฐานข้อมูลไม่ได้ช้า" แต่ปลุกเจ้าของตอนตีสี่อยู่ดี
  // "กลับมาปกติ" ส่งเฉพาะเมื่อเคยส่ง "มีปัญหา" ออกไปจริง — ไม่งั้นคือแจ้งว่าหายจากสิ่งที่ไม่เคยบอก
  const DOWN_KEY="fc_dbh_down_pushed";
  if(kind==="down"){
    if(!/น่าจะล่มจริง|ช้าจริง/.test(msg.body))return;   // ตัววัดบอกว่าฐานข้อมูลปกติ → จบที่แถบบนจอ
    try{localStorage.setItem(DOWN_KEY,"1");}catch{}
  }else{
    let was=null;try{was=localStorage.getItem(DOWN_KEY);localStorage.removeItem(DOWN_KEY);}catch{}
    if(was!=="1")return;
  }
  try{ fetch("/api/push",{method:"POST",headers:{"Content-Type":"application/json"},
    body:JSON.stringify({...msg, scope:"admin", url:"/"}),keepalive:true}); }catch{}
}
// kind: "ok" | "slow" | "err"
// ไอแพดที่เปิดแอปค้างไว้ข้ามคืน: Safari พักหน้าที่อยู่เบื้องหลัง คำขอที่ค้างอยู่หมดเวลา/พังหมด
// พอกลับมาหน้าจอก็ยิงคำขอที่ค้างไว้พร้อมกันเป็นชุด ⟹ นับเป็น "พัง 3 ครั้ง" แล้วเตือนว่าระบบมีปัญหา
// ทั้งที่ฐานข้อมูลปกติดี (เคสจริง 11 ก.ย. 69 03:59 — ร้านปิดแล้ว ไอแพดวางทิ้งไว้)
// ⟹ ไม่นับตัวอย่างที่เกิดตอนหน้าอยู่เบื้องหลัง และช่วง 20 วินาทีแรกหลังกลับมาหน้าจอ
let dbhResumedAt=0;
if(typeof document!=="undefined"){
  try{document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")dbhResumedAt=Date.now();});}catch{}
}
const dbhQuiet=()=>{
  try{
    if(typeof document!=="undefined"&&document.visibilityState==="hidden")return true;
    return dbhResumedAt>0&&Date.now()-dbhResumedAt<20000;
  }catch{return false;}
};
function dbhRecord(kind, ms){
  try{
    if(kind!=="ok"&&dbhQuiet())return;   // ตัวอย่างช่วงหลับ/เพิ่งตื่นเชื่อไม่ได้ — ห้ามเอามาตัดสินว่าระบบป่วย
    // เน็ตของผู้ใช้หลุด ≠ ฐานข้อมูลป่วย — ถ้าเหมารวมจะเตือนผิดทุกครั้งที่ไวไฟสาขาสะดุด
    if(kind!=="ok" && typeof navigator!=="undefined" && navigator.onLine===false) return;
    if(ms) DBH.lastMs = ms;
    DBH.ring.push(kind);
    if(DBH.ring.length > DBH.WINDOW) DBH.ring.shift();
    const errs = DBH.ring.filter(k=>k==="err").length;
    const slows= DBH.ring.filter(k=>k==="slow").length;
    // ทุกตัวอย่างที่มีล้วนไม่ผ่าน — คือกรณี "ล่มตอนล็อกอิน" ที่เจอวันที่ 30 ก.ค. 69:
    // แอปยิงแค่ 2-3 คำขอแล้วค้างที่หน้าล็อกอิน ไม่มีทางครบ 12 ตัวอย่าง ถ้ารอให้ครบก่อน
    // จะไม่เตือนเลยในสถานการณ์ที่ต้องเตือนที่สุด
    const allBad = DBH.ring.length >= 3 && (errs + slows) === DBH.ring.length;
    // "พัง" ไม่ต้องรอครบหน้าต่าง (3 ครั้งใน 12 ครั้งล่าสุดคือสัญญาณชัดอยู่แล้ว)
    // ส่วน "ช้า" ต้องรอครบ เพราะช้าอาจมาจากเน็ตผู้ใช้ ไม่ใช่ฐานข้อมูล
    const next = errs >= DBH.ERR_TRIGGER || allBad
              || (DBH.ring.length >= DBH.WINDOW && slows >= DBH.SLOW_TRIGGER);
    if(next === DBH.degraded) return;
    DBH.degraded = next;
    DBH.listeners.forEach(fn=>{try{fn(next);}catch{}});
    dbhAlert(next ? "down" : "up");
  }catch{}   // ตัวเฝ้าระวังต้องไม่ทำให้คำขอจริงพัง ไม่ว่าเกิดอะไรขึ้น
}

// แถบเตือนบนสุดของจอ — เขียนลง DOM ตรงๆ ไม่ผ่าน React โดยตั้งใจ เพื่อให้โชว์ได้ทุกหน้า
// รวมถึง "หน้าล็อกอิน" ซึ่งเป็นจุดที่สาขาเจอปัญหาจริงตอนฐานข้อมูลป่วย (ล็อกอินไม่ผ่าน)
// ถ้าผูกกับ React tree หน้าล็อกอินจะไม่ได้แถบนี้ = พลาดจุดที่สำคัญที่สุด
if(typeof document!=="undefined"){
  let dismissed=false;
  dbhSubscribe((bad)=>{
    try{
      const ID="fc-dbh-bar", old=document.getElementById(ID);
      if(!bad){ dismissed=false; if(old)old.remove(); return; }   // หายป่วย → ล้างสถานะปิดแถบ
      if(dismissed||old)return;
      const bar=document.createElement("div");
      bar.id=ID; bar.setAttribute("role","status"); bar.setAttribute("aria-live","polite");
      bar.style.cssText="position:fixed;top:0;left:0;right:0;z-index:2147483647;background:#b45309;color:#fff;font:600 14px/1.45 system-ui,sans-serif;padding:9px 44px 9px 14px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,.25)";
      bar.textContent="⚠️ ระบบตอบสนองช้ากว่าปกติ — ยังใช้งานได้ แต่ถ้ากำลังบันทึกอยู่ กรุณารอให้ขึ้นว่าสำเร็จก่อนปิดหน้าจอ";
      const x=document.createElement("button");
      x.textContent="✕"; x.setAttribute("aria-label","ปิดข้อความแจ้งเตือน");
      x.style.cssText="position:absolute;top:4px;right:8px;background:none;border:none;color:#fff;font-size:18px;font-weight:800;cursor:pointer;padding:4px 8px;line-height:1";
      x.onclick=()=>{dismissed=true;bar.remove();};
      bar.appendChild(x);
      document.body.appendChild(bar);
    }catch{}
  });
}

async function sb(path, opts = {}) {
  const {headers:extraH, prefer, ...fetchOpts} = opts;
  const t0 = nowMs();
  // นับผลได้ครั้งเดียวต่อคำขอ (กันนับซ้ำระหว่างตัวจับค้างกับตอนคำขอเสร็จ)
  let logged = false;
  const mark = (kind, ms) => { if(logged)return; logged=true; dbhRecord(kind, ms); };
  // ฐานข้อมูลที่ป่วยหนักมัก "ค้างไม่ตอบ" ไม่ใช่ "ตอบ error" และ fetch ไม่มีเวลาหมดในตัว
  // (ค้างได้เป็นนาที) จึงต้องนับตอนค้างเกิน 8 วินาทีทันทีโดยไม่รอผล — ไม่ยกเลิกคำขอ
  // เพราะงานหนักบางอย่าง (ส่งออก Excel, ดึงรายงาน) ใช้เวลานานได้ตามปกติ
  const hang = setTimeout(()=>mark("slow", DBH.HANG_MS), DBH.HANG_MS);
  try{
    const res = await fetch(`${SUPA_URL}/rest/v1/${path}`, {
      ...fetchOpts,
      headers: { "apikey": SUPA_KEY, "Authorization": `Bearer ${SUPA_KEY}`, "Content-Type": "application/json", "Prefer": prefer || "return=representation", ...extraH },
    });
    clearTimeout(hang);
    const ms = nowMs() - t0;
    // 5xx = ฝั่งเซิร์ฟเวอร์/ฐานข้อมูลมีปัญหา · 4xx = คำขอของเราเองผิด ไม่ใช่อาการป่วย
    mark(res.status >= 500 ? "err" : (ms > DBH.SLOW_MS ? "slow" : "ok"), ms);
    if (!res.ok) {
      const body = await res.text();
      // 42501 = ตารางนั้นเปิด Row Level Security ไว้แต่ไม่มี policy ให้เขียน
      // ระบบนี้ออกแบบให้ปิด RLS ทุกตาราง (คุมสิทธิ์ที่ชั้นแอป) ตารางที่ยังเปิดอยู่คือของที่หลุด
      // Supabase เปิด RLS ให้อัตโนมัติตอนสร้างตารางใหม่ — เจอซ้ำมาหลายรอบแล้ว
      // แปลเป็นข้อความที่บอกได้ว่าต้องทำอะไร แทนที่จะโยน JSON ดิบใส่หน้าผู้ใช้
      if (/42501|row-level security/i.test(body)) {
        // ตัว body เป็น JSON ชื่อตารางจึงถูกครอบด้วย \" (แบ็กสแลชนำหน้า) — ต้องเผื่อทั้งมีและไม่มี
        const t = (body.match(/table\s+\\?"([a-z_]+)\\?"/i) || [])[1] || "ตารางนี้";
        throw new Error(`บันทึกไม่ได้เพราะตาราง "${t}" ยังเปิดระบบล็อกแถว (RLS) อยู่

ผู้ดูแลระบบต้องรันใน Supabase → SQL Editor:
alter table public.${t} disable row level security;`);
      }
      throw new Error(body);
    }
    const text = await res.text();
    return text ? JSON.parse(text) : [];
  }catch(e){
    clearTimeout(hang);
    mark("err", nowMs() - t0);   // ยิงไม่ออก/เน็ตขาด — ถ้าเป็น 4xx จะถูกนับไปแล้วข้างบน
    throw e;
  }
}

// === Production-grade helpers ============================================
// Money: round to 2 decimals using "banker's-safe" half-away-from-zero
const round2 = (n) => Math.round((+n||0)*100)/100;
// The quantity a document line is actually billed at: the received qty once it's known,
// otherwise the ordered qty. Keeps printed/exported "จำนวน × ราคา" reconciled with the
// received-based line_total after a short-receive/dispute. Handles PO items (qty/
// received_qty) and external-order items (qtyNeeded/receivedQty).
function billedQty(it){
  if(!it)return 0;
  const rec=it.received_qty!=null?it.received_qty:(it.receivedQty!=null?it.receivedQty:null);
  if(rec!=null)return +rec||0;
  return +(it.qty!=null?it.qty:(it.qtyNeeded!=null?it.qtyNeeded:0))||0;
}
// An "asset PO" is a central→branch delivery of assets/equipment (issued from an approved
// asset PR), NOT ingredients. It must NEVER touch ingredient stock (no
// transferStockBetweenBranches); on receive it creates/increments rows in the `assets`
// table instead. Detected purely by the item marker — every line carries kind
// 'asset'|'other'; ordinary ingredient items have no `kind`, so this never misfires on them.
function isAssetPO(po){
  const its=po&&po.items;
  return Array.isArray(its)&&its.length>0&&its.every(it=>it&&(it.kind==="asset"||it.kind==="other"));
}
// Currency formatter (Thai Baht, always 2 decimals)
const fmtTHB = (n) => `฿${(+n||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}`;
// Today in Asia/Bangkok (YYYY-MM-DD) — avoids UTC off-by-one near midnight
const todayBkk = () => new Date().toLocaleDateString("en-CA",{timeZone:"Asia/Bangkok"});
// ISO timestamp → value for <input type="datetime-local"> in the browser's own clock (the input reads it back the
// same way via new Date(v)). Slicing the ISO string instead hands the box UTC time → every "แก้ไขการจอง" moved the booking 7 h earlier.
const toLocalDTInput = (iso) => { const d=new Date(iso); if(isNaN(d))return ""; const p=n=>String(n).padStart(2,"0"); return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`; };
// ── ธง _new = "แถวนี้ยังไม่ได้ส่งครัว" เป็นของหน้าจอล้วนๆ ──────────────
// ถ้ามันหลุดลงฐานข้อมูล แถวนั้นจะขึ้นสีส้มค้างตลอดทุกครั้งที่เปิดโต๊ะ
// พนักงานเห็นส้มก็กด "ส่งรายการ" ซ้ำ → ครัวได้ใบซ้ำ ลูกค้าได้อาหารซ้ำ
// (เกิดขึ้นจริง 10 ก.ย. 69 — ตรวจฐานเจอค้าง 1 รายการในบิลที่เปิดอยู่)
// ล้างทั้ง "ขาเข้า" (อ่านจากฐานมาแสดง) และ "ขาออก" (ก่อนเขียนลงฐาน)
// ขาเข้าสำคัญกว่า เพราะมันซ่อมของที่รั่วไปแล้วให้ทันทีโดยไม่ต้องแก้ข้อมูลเก่า
const stripNewFlags=(arr)=>Array.isArray(arr)?arr.map(({_new,...r})=>r):[];
// ── สถานะเมนูรายสาขา (ปุ่มในหน้า "เมนูทั้งหมด") ────────────────────────
//   ขาย       = ทุกจอเห็น สั่งได้
//   วันนี้หมด  = ทุกจอเห็น ขึ้น "ของหมด" กลางรูป สั่งไม่ได้ ทั้งพนักงานและลูกค้า
//   ซ่อน      = หน้าลูกค้าที่สแกน QR ไม่เห็นเลย · จอพนักงานยังเห็นและสั่งให้ลูกค้าได้
// (เจ้าของกำหนด flow นี้เอง 11 ก.ย. 69 — เดิม "ซ่อน" ซ่อนจากพนักงานด้วย พนักงานสั่งให้ลูกค้าไม่ได้)
// ── วันทำการเวลาไทย ตัดวันตอนตีห้า (ไม่ใช่เที่ยงคืน) ─────────────────────
// ร้านเปิดเลยเที่ยงคืน: ของที่หมดตอนห้าทุ่มต้องยังหมดอยู่ตอนตีหนึ่ง แต่เช้าวันใหม่ต้องกลับมาขายเอง
// เวลาไทย = UTC+7 · ถอยไป 5 ชม. ให้ 00:00–04:59 ยังนับเป็นวันก่อน ⟹ รวมแล้ว UTC + 2 ชม.
const BIZ_DAY_CUT_H=5;
const bizDayBkk=(t=Date.now())=>new Date(t+(7-BIZ_DAY_CUT_H)*3600000).toISOString().slice(0,10);
// "วันนี้หมด" = แค่วันนี้วันเดียว (เจ้าของกำหนด 11 ก.ย. 69) — เก็บเป็น "sold_out@วันทำการที่กด"
// ทุกจอตัดสินเองตอนอ่านว่าหมดอายุหรือยัง ไม่พึ่งงานตั้งเวลาไปล้างค่า ซึ่งถ้าวันไหนไม่รัน
// เมนูจะค้างหมดไปเรื่อยๆ แบบไม่มีใครรู้ · ค่าเก่า "sold_out" ที่ไม่มีวันที่ (มาจากแอปเวอร์ชันก่อน
// ที่ยังไม่รีเฟรช) ถือว่ายังหมดอยู่ — ไม่รู้ว่ากดเมื่อไหร่ ก็ต้องไม่เดาว่าขายได้แล้ว
// (ตอนเปลี่ยน ในฐานมี 0 รายการ · ถ้าเจอ กดปุ่มใหม่ครั้งเดียวก็กลายเป็นแบบมีวันที่)
const soldOutMark=(t)=>"sold_out@"+bizDayBkk(t);
const menuAvailAt=(m,bid)=>{const v=((m&&m.availability)||{})[bid]||"";if(typeof v==="string"&&v.startsWith("sold_out@"))return v.slice(9)===bizDayBkk()?"sold_out":"";return v;};
const menuSoldOutAt=(m,bid)=>menuAvailAt(m,bid)==="sold_out";
const menuHiddenAt=(m,bid)=>menuAvailAt(m,bid)==="hidden";
// "2026-09-10" → ISO ของ "เที่ยงวันเวลาไทย" ของวันนั้น
// ทำไมเที่ยงวัน ไม่ใช่เที่ยงคืน: เที่ยงคืน+07 คือ 17:00 ของ "เมื่อวาน" ในเวลา UTC
// ระบบไหนที่ตัดวันด้วย UTC จะอ่านได้วันก่อนหน้าทันที (ข้ามเดือนได้ถ้าเป็นวันที่ 1)
// เที่ยงวันห่างจากขอบวันทั้งสองด้าน 12 ชม. ไม่ว่าใครตัดวันด้วยโซนไหนก็ได้วันเดียวกัน
const bkkNoonISO = (ymd) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(ymd||""));
  if(!m) return null;
  const ymdStr = `${m[1]}-${m[2]}-${m[3]}`;
  const d = new Date(`${ymdStr}T12:00:00+07:00`);
  if(isNaN(d.getTime())) return null;
  // เบราว์เซอร์ "ปัดวันที่เกิน" ให้เงียบๆ ไม่ได้ตอบว่าผิด — 2026-02-31 กลายเป็น 3 มี.ค.
  // วันที่เพี้ยนแบบไม่มีใครรู้ อันตรายกว่าบันทึกไม่ได้แล้วรู้ตัว ⟹ อ่านกลับมาเทียบเสมอ
  if(d.toLocaleDateString("en-CA",{timeZone:"Asia/Bangkok"})!==ymdStr) return null;
  return d.toISOString();
};
// Current minutes-of-day in Asia/Bangkok (0–1439), regardless of the device timezone.
function bkkNowMinutes(){
  try{
    const p=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Bangkok",hour:"2-digit",minute:"2-digit",hour12:false}).formatToParts(new Date());
    const h=+((p.find(x=>x.type==="hour")||{}).value||0);
    const m=+((p.find(x=>x.type==="minute")||{}).value||0);
    return (h%24)*60+m;
  }catch{const d=new Date();return d.getHours()*60+d.getMinutes();}
}
// เวลาไทยแบบ HH:MM — ใช้ติดป้าย "รอบ" ให้ใบที่สร้างจากสรุปต้องซื้อในการกดครั้งเดียวกัน
function bkkHHMM(){
  try{
    const p=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Bangkok",hour:"2-digit",minute:"2-digit",hour12:false}).formatToParts(new Date());
    const g=t=>(p.find(x=>x.type===t)||{}).value||"00";
    return `${g("hour")}:${g("minute")}`;
  }catch{const d=new Date();return `${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`;}
}
// คำนำหน้า note ของใบที่เกิดจากปุ่ม "สร้างรายการ" ในแท็บสรุปต้องซื้อ — ใช้ทั้งตอนเขียนและ
// ตอนค้นประวัติ ห้ามแก้ข้อความนี้เฉยๆ ไม่งั้นใบเก่าจะหลุดจากประวัติ (ค้นด้วยคำนำหน้านี้)
const SUMMARY_BATCH_PREFIX="สรุปต้องซื้อวันนี้";

// Allowed stock-count window (Asia/Bangkok, minutes-of-day). Branch 16:00–23:30 · Central 12:00–16:00.
// Day of week in Asia/Bangkok (0=Sun … 6=Sat), regardless of device timezone.
function bkkWeekday(){
  try{
    const wd=new Intl.DateTimeFormat("en-US",{timeZone:"Asia/Bangkok",weekday:"short"}).format(new Date());
    const map={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
    return wd in map?map[wd]:new Date().getDay();
  }catch{return new Date().getDay();}
}
// Allowed stock-count window (Asia/Bangkok, end exclusive). Branch 16:00–23:30 every day.
// Central 12:00–16:00 — EXCEPT Saturday, when central shifts to 13:00–18:00.
function stockCountWindow(isCentral){
  if(!isCentral)return{s:16*60,e:23*60+30,lbl:"16:00–23:30"};
  if(bkkWeekday()===6)return{s:13*60,e:18*60,lbl:"13:00–18:00"};
  return{s:12*60,e:16*60,lbl:"12:00–16:00"};
}
// เปิดให้นับสต็อกนอกช่วงเวลาแบบเฉพาะกิจ — ตั้ง "วันที่" (เขตไทย) ไว้ที่ branches.stock_count_open_on
// ใช้ตอนเจ้าของสั่งเปิดให้สาขาหนึ่งนับนอกเวลา (เช่น นับใหญ่ตอนเช้า) · เป็นวันที่ ไม่ใช่สวิตช์เปิดค้าง
// ⟹ พ้นวันนั้นก็ปิดเอง ไม่มีทางลืมเปิดค้างไว้ · ค่าว่าง/รูปแบบผิด = ใช้ช่วงเวลาปกติ (ปลอดภัยไว้ก่อน)
const stockCountOpenToday=(branch)=>{
  const raw=branch&&branch.stock_count_open_on;if(!raw)return false;
  const day=String(raw).slice(0,10);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(day))return false;
  try{return day===new Date().toLocaleDateString("en-CA",{timeZone:"Asia/Bangkok"});}catch{return false;}
};
const hhmmOfMin=m=>`${String(Math.floor(m/60)).padStart(2,"0")}:${String(m%60).padStart(2,"0")}`;
// Friendly error mapping (avoid leaking Postgres internals to cashiers)
function friendlyError(err){
  const raw=(err&&err.message)?err.message:String(err||"");
  if(/duplicate key/.test(raw))return "ข้อมูลซ้ำกับที่มีอยู่ในระบบ";
  if(/violates row-level security/.test(raw))return "ไม่มีสิทธิ์ทำรายการนี้ — กรุณาติดต่อแอดมิน";
  if(/violates foreign key/.test(raw))return "ข้อมูลที่อ้างอิงไม่ถูกต้อง — อาจมีรายการที่เกี่ยวข้องถูกลบไปแล้ว";
  if(/violates not-null/.test(raw))return "ข้อมูลที่จำเป็นยังไม่ครบ — ตรวจสอบฟอร์มอีกครั้ง";
  if(/violates check constraint/.test(raw))return "ข้อมูลไม่ถูกต้องตามกติกาของระบบ";
  if(/Failed to fetch|NetworkError/.test(raw))return "เชื่อมต่อเซิร์ฟเวอร์ไม่ได้ — ตรวจสอบอินเทอร์เน็ต";
  if(raw.length>120)return "ทำรายการไม่สำเร็จ ลองใหม่อีกครั้ง";
  return raw||"เกิดข้อผิดพลาด";
}
// Show friendly error + log raw to console in dev only
// กล่องเตือนแบบไม่บล็อกเธรดหลัก
// alert() ของเบราว์เซอร์หยุดทุกอย่างจนกว่าจะมีคนกดปิด และบนไอแพดที่เปิดจากไอคอนหน้าจอโฮม
// มีจังหวะที่มันไม่ขึ้นให้เห็นแต่ยังล็อกเธรดไว้ ⟹ จอค้างทั้งใบ แตะอะไรไม่ติดสักอย่าง
// ต้องฆ่าแอปทิ้งอย่างเดียว ซึ่งตรงกับอาการที่หน้าร้านเจอเป๊ะ
// ตัวนี้ใช้หน้าต่างของแอปเองแทน — ไม่บล็อกอะไร และปิดเองได้เสมอ
function notifyDlg(msg){ try{ confirmDlg({title:"แจ้งเตือน",message:String(msg),confirmLabel:"รับทราบ",cancelLabel:null}); }catch{ console.warn(msg); } }
function showErr(prefix,err){console.error(prefix,err);notifyDlg(prefix+": "+friendlyError(err));}
// Detect image MIME from magic bytes (browser File). Returns 'image/jpeg' | 'image/png' | 'image/webp' | null
async function detectImageMime(file){
  const buf=await file.slice(0,12).arrayBuffer();
  const b=new Uint8Array(buf);
  if(b[0]===0xFF&&b[1]===0xD8&&b[2]===0xFF)return "image/jpeg";
  if(b[0]===0x89&&b[1]===0x50&&b[2]===0x4E&&b[3]===0x47)return "image/png";
  if(b[0]===0x47&&b[1]===0x49&&b[2]===0x46)return "image/gif";
  if(b[0]===0x52&&b[1]===0x49&&b[2]===0x46&&b[3]===0x46&&b[8]===0x57&&b[9]===0x45&&b[10]===0x42&&b[11]===0x50)return "image/webp";
  return null;
}
// Open print/PDF popup with blocker detection — caller falls back if returns null
function openPrintWindow(width=860,height=900){
  const w=window.open("","_blank",`width=${width},height=${height}`);
  if(!w){alert("เบราว์เซอร์บล็อกหน้าต่างพิมพ์ — กรุณาอนุญาต popup ในแถบที่อยู่ของเบราว์เซอร์ แล้วลองอีกครั้ง");return null;}
  return w;
}
// Print HTML WITHOUT opening a popup window — renders into a hidden iframe and prints
// that. Works even when called AFTER an await (no popup-blocker, no blank about:blank
// window). Use this where the print is triggered after async work (e.g. create-then-print).
function printHtml(html){
  try{
    const iframe=document.createElement("iframe");
    iframe.setAttribute("aria-hidden","true");
    iframe.style.cssText="position:fixed;left:-99999px;top:0;width:794px;height:1123px;border:0;opacity:0;pointer-events:none";
    document.body.appendChild(iframe);
    const cw=iframe.contentWindow,doc=cw.document;
    doc.open();doc.write(html);doc.close();
    let cleaned=false;const cleanup=()=>{if(cleaned)return;cleaned=true;setTimeout(()=>{try{document.body.removeChild(iframe);}catch{}},300);};
    try{cw.addEventListener("afterprint",cleanup);}catch{}
    let printed=false;const doPrint=()=>{if(printed)return;printed=true;try{cw.focus();cw.print();}catch{}};
    iframe.onload=()=>setTimeout(doPrint,200);
    setTimeout(doPrint,800);       // fallback if onload doesn't fire
    setTimeout(cleanup,60000);     // safety: never leak the iframe
    return true;
  }catch(e){return false;}
}
// แปะแถบปุ่ม "🖨 พิมพ์ / ✕ ปิดหน้าต่าง" ลอยบนสุดของทุกหน้าต่างพิมพ์/พรีวิว (ซ่อนตอนพิมพ์จริง) — เรียกหลัง document.close()
function addPrintClose(w){
  if(!w)return;
  const inject=()=>{try{
    const d=w.document;if(!d||!d.body||d.getElementById("fc-closebar"))return;
    if(d.head){const st=d.createElement("style");st.textContent="@media print{.fc-noprint{display:none!important}}";d.head.appendChild(st);}
    d.body.insertAdjacentHTML("afterbegin",`<div id="fc-closebar" class="fc-noprint" style="position:fixed;top:0;left:0;right:0;display:flex;gap:10px;justify-content:center;padding:9px;background:#f8fafc;border-bottom:1px solid #cbd5e1;z-index:99999;box-shadow:0 2px 6px rgba(0,0,0,.12)"><button onclick="window.print()" style="padding:9px 20px;border:none;border-radius:9px;background:#0D9488;color:#fff;font-weight:800;font-size:15px;cursor:pointer;font-family:sans-serif">🖨 พิมพ์</button><button onclick="window.close()" style="padding:9px 22px;border:none;border-radius:9px;background:#64748b;color:#fff;font-weight:800;font-size:15px;cursor:pointer;font-family:sans-serif">✕ ปิดหน้าต่าง</button></div><div class="fc-noprint" style="height:52px"></div>`);
  }catch(e){}};
  inject();try{w.addEventListener&&w.addEventListener("load",inject);}catch{}
}
// Random suffix for filenames so they're not enumerable by sequential ID
const randId=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4);
// HTML-escape user-content before injecting into print popup HTML (XSS guard)
const esc=(s)=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
// UUID v4 that also works on an insecure context (http:// on the LAN). crypto.randomUUID
// is gated to secure contexts (HTTPS/localhost) and is undefined on a plain-http LAN page,
// so we fall back to crypto.getRandomValues (available everywhere) then Math.random.
function uuidv4(){
  try{if(typeof crypto!=="undefined"&&crypto.randomUUID)return crypto.randomUUID();}catch{}
  try{if(typeof crypto!=="undefined"&&crypto.getRandomValues){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&0x0f)|0x40;b[8]=(b[8]&0x3f)|0x80;const h=[...b].map(x=>x.toString(16).padStart(2,"0"));return `${h[0]}${h[1]}${h[2]}${h[3]}-${h[4]}${h[5]}-${h[6]}${h[7]}-${h[8]}${h[9]}-${h[10]}${h[11]}${h[12]}${h[13]}${h[14]}${h[15]}`;}}catch{}
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g,c=>{const r=Math.random()*16|0;const v=c==="x"?r:(r&0x3|0x8);return v.toString(16);});
}
// Canonical PUBLIC base URL for CUSTOMER-facing links (table-scan QR codes that
// customers open on their own phone via mobile data). When the staff app is served
// over http:// on the LAN, window.location.origin is a private IP customers can't
// reach — so set PUBLIC_APP_URL to the live Vercel address and customer QRs always
// point there. Empty string → fall back to the current origin (default; no change).
const PUBLIC_APP_URL = "https://foodcost-eta.vercel.app";   // live public URL — customer-scan QR links always point here (so QRs printed from the http LAN page still open for customers on mobile data)
function publicBaseUrl(){
  const raw=PUBLIC_APP_URL||((typeof window!=="undefined")?window.location.origin+window.location.pathname:"");
  return raw.replace(/\/+$/,"")+"/";
}

// ── ดึงทั้งตารางแบบแบ่งหน้า ─────────────────────────────────────────────────
// PostgREST คืนสูงสุด 1000 แถวต่อคำขอ ถ้าตารางโตเกินนั้นแล้วเราขอครั้งเดียว
// แถวที่เหลือจะ "หายเงียบ" ไม่มี error ไม่มีอะไรบอก
// เคสจริง 22/08/2569: assets มี 1,187 แถว ดึงมา 1,000 → บางใหญ่เห็นสินทรัพย์
// 82 จาก 188 (หาย 106 เช่น กระทะ ×125, หม้อแจ่วฮ้อน ×40) · อยุธยา หาย 46 · คลองสาม หาย 35
// วนขอทีละหน้าจนกว่าจะได้ไม่ครบหน้า = หมดแล้ว
async function sbAll(pathNoRange, page = 1000, maxPages = 60) {
  const out = [];
  for (let i = 0; i < maxPages; i++) {
    const sep = pathNoRange.includes("?") ? "&" : "?";
    const chunk = await sb(`${pathNoRange}${sep}limit=${page}&offset=${i * page}`);
    if (!Array.isArray(chunk)) break;
    out.push(...chunk);
    if (chunk.length < page) break;
  }
  return out;
}

// ── อ่าน visible_branches ล่าสุดจากฐานข้อมูลก่อนเขียนทับ ────────────────────
// ทุกที่ที่แก้ "สาขาไหนเห็นของชิ้นนี้" เคยอ่านค่าจากข้อมูลที่ค้างอยู่ในหน้าจอ
// แล้วเขียนทั้งชุดกลับไป → ของที่คนอื่นเพิ่งเปิดให้สาขาอื่นถูกลบทิ้งเงียบๆ
// (หน้าจอโหลดข้อมูลตอนเปิดแท็บ/สลับสาขาเท่านั้น ค่าที่ถืออยู่เก่าได้เป็นชั่วโมง)
// โยน error ถ้าอ่านไม่ได้ — ให้ผู้ใช้ลองใหม่ ดีกว่าเขียนทับด้วยค่าเก่า
async function freshVisibleBranches(table, id) {
  const rows = await sb(`${table}?select=visible_branches&id=eq.${id}&limit=1`);
  if (!Array.isArray(rows) || !rows.length) throw new Error("อ่านค่าล่าสุดไม่ได้ — ลองใหม่อีกครั้ง");
  return rows[0].visible_branches;
}
// ── เมนูที่สาขานี้เห็น กรองที่ฐานข้อมูล (หน้าลูกค้า) ──────────────────────
// กติกาเดียวกับ menuVisibleAt: null = เปิดหมด · [] = ปิดหมด · [ids] = เฉพาะที่ระบุ
// visible_branches เป็น jsonb → ต้องใช้ cs.[5] (cs.{5} คือรูปแบบ array ของ postgres ได้ 400)
// ใส่ "5" แบบข้อความด้วย — menuVisibleAt ยอมรับเลขสาขาที่เก็บเป็นข้อความ ฐานต้องคืนครบเท่ากัน
// เดิมโหลดเมนูทั้งเครือ (~105 KB) ทุกครั้งแล้วค่อยกรองในมือถือ — สาขา 5 ใช้จริงแค่ ~14 KB
// ไม่รู้สาขา = ไม่กรอง (แบบเดิม) หน้าลูกค้ายังกรองซ้ำด้วย menuVisibleAt อีกชั้นเสมอ
const menuVisibleQS=(bid)=>Number.isFinite(+bid)&&bid!==null&&bid!==""?`&or=(visible_branches.is.null,visible_branches.cs.%5B${+bid}%5D,visible_branches.cs.%5B%22${+bid}%22%5D)`:"";

// ── ค่ารายสาขาในคอลัมน์ JSON ของเมนู (availability / options_by_branch) ─────────
// เดิมเอาก้อนที่ค้างบนจอ (โหลดตอนเปิดจอ) มาแก้คีย์ตัวเองแล้วเขียนทับทั้งก้อน
// → River กด "วันนี้หมด" 18:00 · สาขา 5 เปิดจอค้างไว้แล้วมากดเมนูเดียวกัน 18:30 = สถานะของ River หาย
// ตอนนี้อ่านค่าล่าสุดของแถวนั้นก่อนเขียน แล้วแตะเฉพาะคีย์ของสาขาตัวเอง คีย์สาขาอื่นคงเดิม
// เขียนแบบมีเงื่อนไข: PATCH เฉพาะเมื่อค่าในฐานยังเท่ากับที่เพิ่งอ่าน (jsonb เทียบ eq ได้ — ทดสอบกับค่าจริงทุกแบบแล้ว)
// สองสาขากดพร้อมกันในเสี้ยววินาที = อีกฝั่งได้ [] กลับมา → อ่านใหม่แล้วลองอีก สูงสุด 3 รอบ ไม่งั้นแจ้งให้กดใหม่
// (ผู้ใช้เป็นคนกดเขียนฐานข้อมูล ไม่ใช่งานพิมพ์ — กติกาห้ามพิมพ์ซ้ำเองไม่เกี่ยว)
// val เป็น null/undefined = ลบคีย์สาขานี้ (กลับเป็น "ขาย") · [] คือค่าจริง ไม่ใช่การลบ
const patchBranchKey=(obj,branchId,val)=>{const o=(obj&&typeof obj==="object"&&!Array.isArray(obj))?{...obj}:{};const k=String(branchId);if(val==null)delete o[k];else o[k]=val;return o;};
async function writeMenuBranchKey(menuId,field,branchId,val){
  for(let i=0;i<3;i++){
    const rows=await sb(`menus?select=${field}&id=eq.${menuId}&limit=1`);
    if(!Array.isArray(rows)||!rows.length)throw new Error("อ่านค่าล่าสุดไม่ได้ — ลองใหม่อีกครั้ง");
    const old=rows[0][field];
    const next=patchBranchKey(old,branchId,val);
    const same=old==null?"is.null":"eq."+encodeURIComponent(JSON.stringify(old));
    const r=await sb(`menus?id=eq.${menuId}&${field}=${same}`,{method:"PATCH",body:JSON.stringify({[field]:next})});
    if(Array.isArray(r)&&r.length)return next;
  }
  throw new Error("มีสาขาอื่นแก้เมนูนี้พร้อมกัน — กดใหม่อีกครั้ง");
}

// ── แพ็คเกจบุฟเฟต์: คลังแพ็คเกจรายสาขา (pos_settings.buffet_packages) ─────────────
// [{id:'pk_…',name,active,lines:[{key:'adult'|'child'|'x_…',label,price,guest}],menu_ids:[เลขเมนู],menu_prices?:{"เลขเมนู":ราคา},updated_at,updated_by}]
// menu_prices = ราคาของเมนูเมื่อสั่งในโต๊ะแพ็คเกจนี้ (เช่น โปรเบียร์ราคาบุฟเฟต์) · ไม่มี = ราคาเมนูปกติ · 0 = รวมในแพ็คเกจ
// ลำดับใน array = ลำดับที่โชว์ · ลบ = active:false (โต๊ะที่เปิดด้วยแพ็คเกจนั้นยังหาเมนูเจอ)
// ราคาถูกจดลงบิลตอนเปิดโต๊ะ — แก้ราคาที่นี่ไม่ย้อนไปเปลี่ยนโต๊ะที่เปิดอยู่
// ยังไม่ได้รัน sql/buffet-packages.sql (42703/PGRST204) = ถือว่ายังไม่มีแพ็คเกจ ไม่ใช่ error
const bpPrice=(v)=>{
  if(v==null||v===""||typeof v==="boolean")return null;
  const n=typeof v==="number"?v:Number(String(v).trim());
  return Number.isFinite(n)&&n>=0?Math.round(n*100)/100:null;
};
// เวลาสั่งอาหารของแพ็คเกจ (order_minutes · นาที) — ใบเปิดโต๊ะพิมพ์ "เริ่ม / หมดเวลาสั่ง" ตามนี้
// ไม่ได้ตั้ง = 120 (2 ชม. ตามที่ร้านใช้กับ FoodStory) · 0 = ไม่จำกัดเวลา · จำนวนเต็ม 0–1440 เท่านั้น
const PKG_ORDER_MIN_DEFAULT=120;
const bpMinutes=(v)=>{if(v==null||v===""||typeof v==="boolean")return null;const n=Number(v);return Number.isInteger(n)&&n>=0&&n<=1440?n:null;};
const pkgOrderMinutesOf=(p)=>{const n=bpMinutes(p&&p.order_minutes);return n==null?PKG_ORDER_MIN_DEFAULT:n;};
const pkgDurText=(m)=>{const n=Math.max(0,Math.floor(+m||0));if(!n)return "ไม่จำกัดเวลา";const h=Math.floor(n/60),r=n%60;return [h?h+" ชม.":"",r?r+" นาที":""].filter(Boolean).join(" ");};
// อ่านของในฐานแล้วกรองของเสียทิ้ง: ไม่มี id/ชื่อ · id ซ้ำ · ราคาไม่ใช่ตัวเลข/ติดลบ · ไม่มีบรรทัดนับคน
// ราคาเป็นข้อความ ("299") แปลงเป็นตัวเลข ปัดทศนิยม 2 ตำแหน่ง · ลำดับเดิมคงไว้
function normalizeBuffetPackages(raw){
  if(!Array.isArray(raw))return [];
  const out=[],seen=new Set();
  for(const p of raw){
    if(!p||typeof p!=="object"||Array.isArray(p))continue;
    const id=typeof p.id==="string"?p.id.trim():"";
    const name=typeof p.name==="string"?p.name.trim():"";
    if(!id||!name||seen.has(id))continue;
    const lines=[],keys=new Set();
    for(const l of (Array.isArray(p.lines)?p.lines:[])){
      if(!l||typeof l!=="object")continue;
      const key=typeof l.key==="string"?l.key.trim():"";
      const price=bpPrice(l.price);
      if(!key||keys.has(key)||price==null)continue;
      const label=(typeof l.label==="string"&&l.label.trim())||(key==="adult"?"ผู้ใหญ่":key==="child"?"เด็ก":"");
      if(!label)continue;
      keys.add(key);
      lines.push({...l,key,label,price,guest:key==="adult"||key==="child"});   // นับเป็นคน = ผู้ใหญ่/เด็กเท่านั้น (รายการเพิ่มไม่นับ)
    }
    if(!lines.some(l=>l.guest))continue;   // ไม่มีบรรทัดนับคน = เปิดโต๊ะด้วยแพ็คเกจนี้ไม่ได้
    const menu_ids=[],ms=new Set();
    for(const v of (Array.isArray(p.menu_ids)?p.menu_ids:[])){const n=Number(v);if(Number.isInteger(n)&&n>0&&!ms.has(n)){ms.add(n);menu_ids.push(n);}}
    // ราคาในแพ็คเกจ: เก็บเฉพาะเมนูที่ยังอยู่ในแพ็คเกจ และราคาเป็นตัวเลข 0 ขึ้นไป · ไม่มีสักตัว = ไม่มีช่องนี้ (แพ็คเกจเดิมหน้าตาเหมือนเดิม)
    const mpRaw=p.menu_prices&&typeof p.menu_prices==="object"&&!Array.isArray(p.menu_prices)?p.menu_prices:{};
    const menu_prices={};
    for(const n of menu_ids){const v=bpPrice(mpRaw[String(n)]);if(v!=null)menu_prices[String(n)]=v;}
    seen.add(id);
    const o={...p,id,name,active:p.active!==false,lines,menu_ids,updated_at:p.updated_at||null,updated_by:p.updated_by||null};
    if(Object.keys(menu_prices).length)o.menu_prices=menu_prices;else delete o.menu_prices;
    const om=bpMinutes(p.order_minutes);if(om==null)delete o.order_minutes;else o.order_minutes=om;   // ไม่ได้ตั้ง/ผิดรูป = ไม่มีช่องนี้ (ใช้ค่าเริ่มต้น)
    out.push(o);
  }
  return out;
}
const bpMissingCol=(e)=>/42703|PGRST204|does not exist|schema cache/i.test(String((e&&e.message)||e));
const BP_NO_COL="ต้องรัน SQL เพิ่มคอลัมน์ก่อน (sql/buffet-packages.sql ครั้งเดียว)";
// เงื่อนไขเขียนแบบมีเงื่อนไข: ปกติเทียบทั้งก้อน (eq.<json>) แบบเดียวกับ writeMenuBranchKey
// ก้อนใหญ่จน URL ยาว (ทดสอบกับฐานจริง: ~20 KB ผ่าน · ~30 KB ได้ 400) → เทียบ "ลายนิ้วมือ" แทน
// = จำนวนแพ็คเกจ + id และ updated_at ของทุกตำแหน่ง (ทุกการแก้จากจอนี้ตั้ง updated_at ใหม่ให้แพ็คเกจที่แก้เสมอ)
const BP_CAS_MAX=6000;
function bpCasFilter(raw){
  if(raw==null)return "buffet_packages=is.null";
  const full="buffet_packages=eq."+encodeURIComponent(JSON.stringify(raw));
  if(full.length<=BP_CAS_MAX||!Array.isArray(raw))return full;
  const f=[`buffet_packages->>${raw.length}=is.null`,`buffet_packages->>${raw.length-1}=not.is.null`];
  raw.forEach((p,i)=>{
    const id=p&&p.id,at=p&&p.updated_at;
    f.push(`buffet_packages->${i}->>id=`+(id==null?"is.null":"eq."+encodeURIComponent(String(id))));
    f.push(`buffet_packages->${i}->>updated_at=`+(at==null?"is.null":"eq."+encodeURIComponent(String(at))));
  });
  return f.join("&");
}
async function buffetPkgRead(bid){
  try{
    const r=await sb(`pos_settings?branch_id=eq.${+bid}&select=buffet_packages&limit=1`);
    const row=Array.isArray(r)&&r[0]?r[0]:null;
    const raw=row?(row.buffet_packages??null):null;
    return {packages:normalizeBuffetPackages(raw),raw,hasRow:!!row,missingColumn:false};
  }catch(e){
    if(bpMissingCol(e))return {packages:[],raw:null,hasRow:false,missingColumn:true};
    throw e;
  }
}
// change(คลังล่าสุด) → คลังใหม่ หรือข้อความ (= ไม่บันทึก แจ้งผู้ใช้) · prev = ค่าดิบที่จอถืออยู่ (undefined = อ่านก่อน)
// PATCH เฉพาะคอลัมน์นี้ เมื่อค่าในฐานยังเท่ากับที่อ่านมา — อีกเครื่องแทรกเขียนก่อน = ได้ [] กลับมา
// → อ่านใหม่ แล้วทำ "การแก้ครั้งเดียวของผู้ใช้" ซ้ำบนค่าล่าสุด (ลองใหม่สูงสุด 3 รอบ) ไม่เขียนทับของอีกเครื่อง
// ยังไม่มีแถวตั้งค่าของสาขา = สร้างแถวด้วยคอลัมน์นี้อย่างเดียว (ชนกับอีกเครื่อง = ไม่ทับ วนอ่านใหม่)
async function buffetPkgSave(bid,change,prev){
  let raw=prev,hasRow=true;
  for(let i=0;i<4;i++){
    if(i>0||raw===undefined){
      const cur=await buffetPkgRead(bid);
      if(cur.missingColumn){const e=new Error(BP_NO_COL);e.missingColumn=true;throw e;}
      raw=cur.raw;hasRow=cur.hasRow;
    }
    const before=normalizeBuffetPackages(raw);
    const next=change(normalizeBuffetPackages(raw));   // สำเนาใหม่ — change แก้ของตัวเองได้ ไม่กระทบ before
    if(typeof next==="string")return {ok:false,msg:next,packages:before,raw};
    const body=normalizeBuffetPackages(next);
    if(JSON.stringify(body)===JSON.stringify(before))return {ok:true,packages:before,raw,before,unchanged:true};   // ไม่มีอะไรเปลี่ยน ไม่ต้องเขียน
    let r;
    try{
      r=hasRow
        ?await sb(`pos_settings?branch_id=eq.${+bid}&${bpCasFilter(raw)}&select=buffet_packages`,{method:"PATCH",body:JSON.stringify({buffet_packages:body})})
        :await sb("pos_settings?select=buffet_packages",{method:"POST",body:JSON.stringify({branch_id:+bid,buffet_packages:body}),headers:{"Prefer":"resolution=ignore-duplicates,return=representation"}});
    }catch(e){if(bpMissingCol(e)){const e2=new Error(BP_NO_COL);e2.missingColumn=true;throw e2;}throw e;}
    if(Array.isArray(r)&&r.length){const w=r[0].buffet_packages??null;return {ok:true,packages:normalizeBuffetPackages(w),raw:w,before};}
  }
  throw new Error("มีเครื่องอื่นแก้แพ็คเกจพร้อมกัน — กดบันทึกอีกครั้ง");
}
const bpNameKey=(s)=>String(s||"").trim().replace(/\s+/g," ").toLowerCase();
const bpNewId=(pre)=>`${pre}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,7)}`;
// การแก้หนึ่งครั้งของผู้ใช้ ทำบนคลังล่าสุดจากฐาน (เรียกซ้ำได้เมื่อชนกับอีกเครื่อง) · คืนข้อความ = ไม่บันทึก
// op.at/op.by ประทับให้เฉพาะแพ็คเกจที่แก้ · ชื่อซ้ำดูเฉพาะแพ็คเกจที่ยังใช้อยู่ (ชื่อที่ลบไปแล้วใช้ใหม่ได้)
function buffetPkgOp(list,op){
  const L=Array.isArray(list)?list:[];
  const GONE="แพ็คเกจนี้ถูกลบจากอีกเครื่องไปแล้ว — รายการบนจอโหลดใหม่ให้แล้ว";
  const dup=(name,selfId)=>L.some(p=>p.active&&p.id!==selfId&&bpNameKey(p.name)===bpNameKey(name));
  const stamp={updated_at:op.at,updated_by:op.by||null};
  if(op.type==="create"){
    if(dup(op.name,null))return "มีแพ็คเกจชื่อนี้แล้ว";
    return [...L,{id:op.id,name:String(op.name).trim(),active:true,lines:op.lines,menu_ids:[],...(bpMinutes(op.minutes)!=null?{order_minutes:bpMinutes(op.minutes)}:{}),...stamp}];
  }
  const cur=L.find(p=>p.id===op.id);
  if(!cur||(!cur.active&&op.type!=="delete"))return GONE;
  if(op.type==="edit"){
    // ราคา: ถ้าอีกเครื่องเพิ่งแก้แพ็คเกจเดียวกัน ห้ามเขียนทับเงียบๆ ให้ดูราคาล่าสุดก่อน
    if((cur.updated_at||null)!==(op.base||null))return "แพ็คเกจนี้เพิ่งถูกแก้จากอีกเครื่อง — โหลดราคาล่าสุดให้แล้ว ตรวจแล้วกดบันทึกอีกครั้ง";
    if(dup(op.name,cur.id))return "มีแพ็คเกจชื่อนี้แล้ว";
    // เวลาสั่งอาหาร: ฟอร์มส่งมา = ตั้งตามนั้น · ไม่ส่ง (ผู้เรียกรุ่นเก่า) = คงค่าเดิม
    return L.map(p=>p.id===cur.id?{...p,name:String(op.name).trim(),lines:op.lines,...(bpMinutes(op.minutes)!=null?{order_minutes:bpMinutes(op.minutes)}:{}),...stamp}:p);
  }
  if(op.type==="menus"){
    // เมนูในแพ็คเกจ: ทำเฉพาะส่วนต่าง (เพิ่ม/เอาออก) — เมนูที่อีกเครื่องเพิ่งติ๊กเพิ่มไม่หาย
    const rm=new Set((op.remove||[]).map(Number)),have=new Set(cur.menu_ids.map(Number));
    const ids=[...new Set([...cur.menu_ids.filter(id=>!rm.has(+id)),...(op.add||[]).map(Number).filter(id=>!have.has(id)&&!rm.has(id))])];
    // ราคาในแพ็คเกจ: แก้เฉพาะเมนูที่ผู้ใช้แก้ (op.prices {เลขเมนู: ราคา | null=กลับไปใช้ราคาเมนู})
    // ราคาที่อีกเครื่องเพิ่งตั้งให้เมนูอื่นไม่หาย · เมนูที่ออกจากแพ็คเกจ ราคาของมันหายไปด้วย
    const mp={...(cur.menu_prices||{})};
    for(const [k,v] of Object.entries(op.prices||{})){const pv=bpPrice(v);if(pv==null)delete mp[String(k)];else mp[String(k)]=pv;}
    const keep=new Set(ids.map(String));for(const k of Object.keys(mp))if(!keep.has(k))delete mp[k];
    return L.map(p=>p.id===cur.id?{...p,menu_ids:ids,menu_prices:mp,...stamp}:p);
  }
  if(op.type==="delete"){
    if(!cur.active)return L;   // อีกเครื่องลบไปแล้ว = ผลเหมือนกัน ไม่ต้องเขียน
    return L.map(p=>p.id===cur.id?{...p,active:false,...stamp}:p);
  }
  return "ไม่รู้จักคำสั่งนี้";
}
// ฟอร์มแพ็คเกจ → บรรทัดราคา (หรือข้อความบอกช่องที่ผิด) · ราคา 0 ขึ้นไป ทศนิยมไม่เกิน 2 ตำแหน่ง
// form = {name,adult,child,extras:[{key?,label,price}]} · key เดิมของรายการเพิ่มคงไว้ตอนแก้ (บิลอ้าง key นี้)
const BP_PRICE_RE=/^\d+(\.\d{1,2})?$/;
// ช่องราคาตอนพิมพ์: เหลือแค่ตัวเลขกับจุดเดียว ทศนิยมไม่เกิน 2 ตำแหน่ง (ติดลบพิมพ์ไม่ได้)
const bpPriceInput=(v)=>{let s=String(v??"").replace(/[^\d.]/g,"");const i=s.indexOf(".");if(i>=0)s=s.slice(0,i+1)+s.slice(i+1).replace(/\./g,"").slice(0,2);return s;};
function buffetFormToLines(form){
  const f=form||{};
  if(!String(f.name||"").trim())return "ใส่ชื่อแพ็คเกจ";
  const px=(v)=>{const s=String(v??"").trim();return BP_PRICE_RE.test(s)?Math.round(Number(s)*100)/100:null;};
  const a=px(f.adult),c=px(f.child);
  if(a==null)return "ราคาผู้ใหญ่ต้องเป็นตัวเลข 0 ขึ้นไป ทศนิยมไม่เกิน 2 ตำแหน่ง";
  if(c==null)return "ราคาเด็กต้องเป็นตัวเลข 0 ขึ้นไป ทศนิยมไม่เกิน 2 ตำแหน่ง";
  const lines=[{key:"adult",label:"ผู้ใหญ่",price:a,guest:true},{key:"child",label:"เด็ก",price:c,guest:true}];
  const names=new Set(["ผู้ใหญ่","เด็ก"].map(bpNameKey));
  for(const x of (Array.isArray(f.extras)?f.extras:[])){
    const label=String((x&&x.label)||"").trim();
    if(!label)return "ใส่ชื่อรายการเพิ่มให้ครบ (เช่น เด็กเล็ก เตาเพิ่ม)";
    if(names.has(bpNameKey(label)))return `ชื่อรายการ "${label}" ซ้ำ`;
    const p=px(x.price);
    if(p==null)return `ราคา "${label}" ต้องเป็นตัวเลข 0 ขึ้นไป ทศนิยมไม่เกิน 2 ตำแหน่ง`;
    names.add(bpNameKey(label));
    const key=typeof x.key==="string"&&/^x_/.test(x.key)?x.key:bpNewId("x");
    lines.push({key,label,price:p,guest:false});
  }
  return lines;
}
// ประวัติการแก้ (action_history) — ใคร สาขาไหน แพ็คเกจไหน จากอะไรเป็นอะไร · ไม่มีอะไรเปลี่ยน = ""
// nameOf(id) = ชื่อเมนู (ไม่รู้ชื่อ = #id)
function buffetAuditText(before,after,who,branch,nameOf){
  const fm=(n)=>"฿"+(+n||0).toLocaleString("en-US",{maximumFractionDigits:2});
  const mn=(id)=>{const n=nameOf&&nameOf(id);return n||("#"+id);};
  const head=`แพ็คเกจบุฟเฟต์ · ${(branch&&branch.name)||"-"} (#${(branch&&branch.id)??"-"}) · โดย ${who||"ไม่ทราบชื่อ"} — `;
  const lineTxt=(l)=>`${l.label} ${fm(l.price)}`;
  if(!before&&after)return head+`สร้าง "${after.name}": `+after.lines.map(lineTxt).join(" · ");
  if(!before||!after)return "";
  if(before.active&&!after.active)return head+`ลบ "${before.name}"`;
  const ch=[];
  if(before.name!==after.name)ch.push(`ชื่อ: ${before.name} → ${after.name}`);
  const bk=new Map(before.lines.map(l=>[l.key,l])),ak=new Map(after.lines.map(l=>[l.key,l]));
  for(const l of after.lines){
    const o=bk.get(l.key);
    if(!o){ch.push("เพิ่ม "+lineTxt(l));continue;}
    if(o.label!==l.label)ch.push(`ชื่อรายการ: ${o.label} → ${l.label}`);
    if(+o.price!==+l.price)ch.push(`${l.label}: ${fm(o.price)} → ${fm(l.price)}`);
  }
  for(const o of before.lines)if(!ak.has(o.key))ch.push("เอาออก "+lineTxt(o));
  if(pkgOrderMinutesOf(before)!==pkgOrderMinutesOf(after))ch.push(`เวลาสั่งอาหาร: ${pkgDurText(pkgOrderMinutesOf(before))} → ${pkgDurText(pkgOrderMinutesOf(after))}`);
  const bm=new Set(before.menu_ids),am=new Set(after.menu_ids);
  const add=after.menu_ids.filter(id=>!bm.has(id)),rem=before.menu_ids.filter(id=>!am.has(id));
  const lst=(ids)=>ids.slice(0,8).map(mn).join(", ")+(ids.length>8?` และอีก ${ids.length-8}`:"");
  if(add.length)ch.push(`เพิ่มเมนู ${add.length}: ${lst(add)}`);
  if(rem.length)ch.push(`เอาเมนูออก ${rem.length}: ${lst(rem)}`);
  // ราคาในแพ็คเกจ (เรื่องเงิน — ต้องรู้ว่าใครแก้ จากเท่าไรเป็นเท่าไร) · เมนูที่เอาออกบอกไว้ข้างบนแล้ว
  const bp=before.menu_prices||{},ap=after.menu_prices||{};
  const pch=after.menu_ids.filter(id=>(bp[String(id)]??null)!==(ap[String(id)]??null))
    .map(id=>{const o=bp[String(id)],n=ap[String(id)];return `${mn(id)} ${o==null?"ราคาเมนู":fm(o)} → ${n==null?"ราคาเมนู":fm(n)}`;});
  if(pch.length)ch.push(`ราคาในแพ็คเกจ ${pch.length}: `+pch.slice(0,8).join(", ")+(pch.length>8?` และอีก ${pch.length-8}`:""));
  if(!ch.length)return "";
  return head+`แก้ "${after.name}": `+ch.join(" · ");
}
// เมนูที่เลือกใส่แพ็คเกจได้ = เมนูที่สาขานี้เห็นตามปุ่มติ๊กเท่านั้น (menuVisibleAt ห้ามผ่อนปรน) เรียงแบบเดียวกับที่ลูกค้าเห็น
const bpPickableMenus=(menus,bid,catOrder,menuOrder)=>(Array.isArray(menus)?menus:[]).filter(m=>menuVisibleAt(m,bid)).sort(menuSorter(catOrder,menuOrder));

