const ROLE_DEFAULT_PERMS={
  admin:ALL_PERMS.map(p=>p.id),
  area:["approve","po","orders","summary","history"],
  manager:["pos","crm","ingredients","waste","menus","sop","production","summary","fs_sales","po","orders","history","suppliers","assets","approve"],
  staff:["pos","crm","ingredients","waste","menus","sop","summary","fs_sales","po","orders","history","suppliers"],
  viewer:["pos","menus","sop"],
};
// Coerce a value to an array (handles JSON string from legacy DB rows, null = treat as null sentinel)
function asArr(x){
  if(Array.isArray(x))return x;
  if(typeof x==="string"){try{const p=JSON.parse(x);return Array.isArray(p)?p:[];}catch{return [];}}
  return null;  // null/undefined preserved as sentinel
}
// Normalize a perms array: dedupe + only keep ids that exist in ALL_PERMS today.
// Cleans legacy/duplicate/renamed entries so we never see counts like "17/12".
function normalizePerms(input){
  const arr=asArr(input)||[];
  const valid=new Set(ALL_PERMS.map(p=>p.id));
  return [...new Set(arr.filter(p=>typeof p==="string"&&valid.has(p)))];
}
// Same idea for allowed_branches: dedupe + only keep numeric ids
function normalizeBranchIds(input){
  const arr=asArr(input);
  if(arr==null)return null;  // sentinel preserved (null = unrestricted)
  return [...new Set(arr.map(x=>+x).filter(x=>Number.isFinite(x)&&x>0))];
}
function getUserPerms(user){const a=normalizePerms(user?.perms);return(a&&a.length>0)?a:(ROLE_DEFAULT_PERMS[user?.role]||[]);}
function hasPerm(user,perm){
  if(!user)return false;
  if(user.role==="admin")return true;
  return getUserPerms(user).includes(perm);
}
// ── สิทธิ์ POS สองชั้น ─────────────────────────────────────────────────────
// settings  = ทุกอย่าง รวมเรื่องเงิน (VAT/ค่าบริการ/ปัดเศษ/พร้อมเพย์/หัว-ท้ายใบเสร็จ/โปรโมชั่น)
// admin     = งานประจำของผู้จัดการสาขา: PIN พนักงานขาย ผังโต๊ะ เพิ่ม/ลบเครื่องพิมพ์ — ได้จาก settings หรือ pos_admin
// คนที่เข้าด้วย PIN (saleOnly) ไม่ได้ทั้งสองชั้นเสมอ ไม่ว่าผู้ใช้จำลองจะถูกแก้ให้มีสิทธิ์อะไรก็ตาม
function posAccess(user,saleOnly){
  const settings=!saleOnly&&hasPerm(user,"settings");
  const admin=settings||(!saleOnly&&hasPerm(user,"pos_admin"));
  return{settings,admin};
}
const ROLES={admin:{label:"Admin",color:"purple"},area:{label:"Area / พื้นที่",color:"orange"},manager:{label:"Manager",color:"blue"},staff:{label:"Staff",color:"green"},viewer:{label:"Viewer",color:"gray"}};
const ppg=(price,gram)=>(gram>0?price/gram:0);
// === Ingredient category codes ===========================================
// Categories carry a 3-char code in trailing parens, e.g. "เนื้อสัตว์ (M01)". Every
// ingredient in a coded category gets a sequential code "<prefix>-<00001>". These helpers
// derive the prefix and compute the NEXT code so a newly-created ingredient continues from
// the current max in its category (per the one-time recoding). Codes are a LABEL, never a key,
// so a rare collision is harmless — but we still read the max live from the DB before assigning
// so two admins adding at once don't reuse a number.
// Accept 2+ digits so a group that grows past 99 (…(M100)) still parses as coded instead of
// silently falling out of the scheme and breaking ingredient auto-numbering.
const catCodePrefix=(cat)=>{const m=/\(([A-Za-z]\d{2,})\)\s*$/.exec(cat||"");return m?m[1]:null;};
// A category's main-group LETTER (first char of its code): "วัตถุดิบ (M01)" → "M". null if uncoded.
const catCodeLetter=(cat)=>{const p=catCodePrefix(cat);return p?p[0].toUpperCase():null;};
// The readable category name with its trailing "(M01)" code stripped, for chip display.
const catNameNoCode=(cat)=>String(cat||"").replace(/\s*\([A-Za-z]\d{2,}\)\s*$/,"").trim();
// Distinct accent per main-group letter so each column reads as its own group. Unknown → slate.
// All shades hit ≥4.5:1 against white so the small 10px code badge stays legible on a tablet.
const CAT_LETTER_COLORS={M:"#2563EB",D:"#B45309",B:"#7C3AED",C:"#0F766E",E:"#BE123C",A:"#047857",F:"#BE185D",G:"#0E7490"};
const catLetterColor=(l)=>CAT_LETTER_COLORS[String(l||"").toUpperCase()]||"#64748B";
// Largest existing number for a prefix across a list of ingredient rows (0 if none). Robust to
// unpadded/legacy codes because it compares NUMERICALLY, not lexically.
function maxIngCodeNum(prefix,list){
  let mx=0;const re=new RegExp("^"+prefix+"-(\\d+)$");
  (Array.isArray(list)?list:[]).forEach(r=>{const m=re.exec((r&&r.code||"").trim());if(m){const n=+m[1];if(Number.isFinite(n)&&n>mx)mx=n;}});
  return mx;
}
const fmtIngCode=(prefix,num)=>`${prefix}-${String(num).padStart(5,"0")}`;
// Next code for a prefix, reading the current max straight from the DB (fresh, avoids a stale
// page cache). Throws on network failure so callers can fall back to their local list.
async function nextIngCodeForPrefix(prefix){
  const rows=await sbAll(`ingredients?select=code&code=like.${prefix}-*&order=code.asc`);
  return fmtIngCode(prefix,maxIngCodeNum(prefix,rows)+1);
}
// Recipe amounts are stored CANONICALLY in grams (amountGram) because every cost path multiplies
// them by a price-per-GRAM. The picker lets the operator type in กก./ลิตร/ช้อน etc., so convert at
// write time — storing "1" for "1 กก." made that ingredient cost 1/1000 of reality.
// Units with no mass equivalence (ชิ้น / custom) stay 1:1 — the operator is expected to type grams.
// ⚠️ คีย์ในตารางนี้คือ "ข้อความหน่วย" ตรง ๆ ตัวไหนไม่อยู่ในตารางจะถูกคูณ 1
// เดิมมีแต่ "กก." พอดรอปดาวน์มาตรฐานส่งคำว่า "กิโลกรัม" เข้ามาจะกลายเป็นคูณ 1
// = 1 กิโลกรัมถูกคิดเป็น 1 กรัม ต้นทุนและการตัดสต๊อกเพี้ยน 1000 เท่า
// (คอมเมนต์ข้างบนบันทึกไว้ว่าบั๊คนี้เคยเกิดจริงมาแล้ว) จึงต้องใส่ชื่อเต็มเป็นคีย์คู่กันไว้ด้วย
const UNIT_G={"กรัม":1,"ก.":1,"g":1,"มล.":1,"ml":1,"มิลลิลิตร":1,"ช้อนชา":5,"ช้อนโต๊ะ":15,"ถ้วย":240,"กก.":1000,"kg":1000,"กิโลกรัม":1000,"ลิตร":1000,"l":1000};
// หน่วยมาตรฐานที่เจ้าของกำหนด (8 ส.ค. 69) — ดรอปดาวน์ทุกที่ให้เลือกได้แค่ 9 ตัวนี้
// ของเดิมในฐานข้อมูลมี 41 หน่วย (กก. 187 · ชิ้น 37 · กล่อง 25 · แกลลอน 17 …) ห้ามไปแก้
// ให้คงค่าเดิมไว้ทั้งหมด แค่ตอนกดเปลี่ยนถึงจะเห็นเฉพาะ 9 หน่วยนี้
// ── หน่วยมาตรฐานของระบบ ────────────────────────────────────────────────────
// เดิมมี 9 หน่วย ซึ่งครอบไม่พอ: วัดจากข้อมูลจริง 15/08/2569 มี 33 หน่วยที่ถูกใช้
// อยู่แล้วแต่เลือกจากดรอปดาวน์ไม่ได้ (ชิ้น 37 รายการ · กล่อง 24 · แกลลอน 17 · อัน 15 …)
// พนักงานเลยต้องมาขอเพิ่มทีละหน่วย — คราวนี้ใส่ให้ครบทุกหน่วยที่มีใช้จริง
//
// ⚠️ ไม่ใส่ตัวย่อ/ตัวสะกดผิดที่ค้างในข้อมูลเก่า (กก. · กิโล · กส. · แพ็ึค · แพ็ค.)
//    เพราะจะทำให้หน่วยเดียวกันแตกเป็นหลายชื่อจนรวมยอดไม่ได้
//    ของเก่ายังใช้ได้ปกติ — UnitPicker โชว์ค่าเดิมพร้อมป้าย "เดิม" อยู่แล้ว
//    และ UNIT_G ก็รู้จัก "กก." อยู่ จึงยังแปลงเป็นกรัมได้ถูกต้อง
const UNIT_GROUPS=[
  // กลุ่มนี้เท่านั้นที่แปลงเป็นกรัมได้เอง (ดู UNIT_G) — ต้นทุนคิดตรงได้ทันที
  {label:"น้ำหนัก / ปริมาตร",units:["กิโลกรัม","กรัม","ลิตร","มิลลิลิตร"]},
  {label:"บรรจุภัณฑ์",units:["ถุง","แพ็ค","ขวด","ลัง","กล่อง","แผง","ซอง","ห่อ","กระป๋อง","กระปุก","แกลลอน","ถัง","กระสอบ","ถาด","หม้อ","ม้วน","รีม"]},
  {label:"นับเป็นชิ้น",units:["ชิ้น","อัน","ใบ","ก้อน","ลูก","ตัว","แผ่น","แท่ง","ด้าม","คู่","ชุด","เครื่อง","แถว","มัด","กำ","ผืน"]},
];
const STD_UNITS=UNIT_GROUPS.flatMap(g=>g.units);
const UNIT_GROUP_OF=Object.fromEntries(UNIT_GROUPS.flatMap(g=>g.units.map(u=>[u,g.label])));
// ช่อง "รวมทั้งหมด" (convert_to_gram) เก็บเป็น "กรัม" เสมอ เพราะทุกอย่างท้ายน้ำหารด้วยมัน
// (ต้นทุนต่อกรัม · การตัดสต๊อกตอนผลิต · การกระจายของเข้าสาขา) จึงรับได้เฉพาะหน่วยที่
// แปลงเป็นกรัมได้จริง — ถุง/แพ็ค/ลัง/แผง/ขวด ไม่มีน้ำหนัก ใส่ตรงนี้แล้วไม่มีความหมาย
// ("1 ขวด = 3 ขวด" แปลงเป็นกรัมไม่ได้) จึงไม่อยู่ในรายการของช่องนี้
const MASS_UNITS=["กรัม","กิโลกรัม","มิลลิลิตร","ลิตร"];
// ── แปลงจำนวนในสูตร → กรัม ───────────────────────────────────────────────────
// ดรอปดาวน์มาตรฐานมีหน่วยบรรจุภัณฑ์ (ถุง แพ็ค แผง ลัง ขวด) ซึ่งไม่มีค่าน้ำหนักใน UNIT_G
// ของเดิมจะตกไปคูณ 1 = "2 ขวด" ถูกบันทึกเป็น 2 กรัม ทั้งที่จริง 1 ขวดอาจ 700 กรัม
// ผลคือต้นทุนต่ำกว่าจริง 700 เท่า และตอนผลิตก็ตัดสต๊อกแทบไม่ลด ของค้างในระบบตลอดไป
//
// ทางออก: วัตถุดิบแต่ละตัวมีช่อง "รวมทั้งหมดกี่กรัม" (convert_to_gram) อยู่แล้ว
// ซึ่งแปลว่า "กรัมต่อ 1 หน่วยที่ซื้อ" ถ้าหน่วยในสูตรตรงกับหน่วยที่ซื้อของตัวนั้น
// ก็ใช้ค่านั้นแปลงได้ตรง ๆ — 2 ขวด × 700 = 1400 กรัม ถูกต้องทั้งต้นทุนและสต๊อก
//
// เหลือกรณีที่ยังไม่รู้จริง ๆ (หน่วยบรรจุภัณฑ์ที่ไม่ตรงกับหน่วยซื้อ หรือยังไม่ได้ตั้งน้ำหนัก)
// อันนั้นคงพฤติกรรมเดิมคือคิดเป็นกรัมตรง ๆ แต่ต้องถามยืนยันก่อน ห้ามบันทึกเงียบ ๆ
// เพิ่มทางที่สาม: "หน่วยย่อย" — ซื้อมาเป็นลัง แต่สูตรหยิบเป็นขวด
// เดิมมีแค่ 2 ทาง (หน่วยน้ำหนัก · หน่วยที่ซื้อ) เคสซื้อยกลังแล้วใช้ทีละขวดจึงตกท่อ
// วัดจริง 14/08/2569: เบียร์ลีโอ ซื้อ ฿640/ลัง สูตรใส่ "1 ขวด" ได้ต้นทุน ฿0.64
// ทั้งที่ควรเป็น ฿53.33 (1 ลัง 12 ขวด) = ผิด 83 เท่า
//
// สูตรแปลง: กรัม = จำนวน × (กรัมต่อ 1 หน่วยที่ซื้อ ÷ จำนวนหน่วยย่อยต่อ 1 หน่วยที่ซื้อ)
// ข้อดีที่สำคัญ: ต้นทุนถูกเสมอแม้ค่า convert_to_gram จะไม่ใช่น้ำหนักจริง เพราะ
//   ต้นทุน = กรัม × ราคาต่อกรัม = n×(per/subPer) × (ราคาซื้อ/per) = n × ราคาซื้อ/subPer
// ตัว per ตัดกันหมด → ได้ "ราคาซื้อ ÷ จำนวนต่อลัง" ตรงๆ เสมอ
// และตอนตัดสต๊อกก็ถูกด้วย เพราะระบบแปลงกรัมกลับเป็นหน่วยที่ซื้อ: 12 ขวด = 1 ลัง พอดี
function recipeGrams(amt,unit,ing){
  const u=String(unit||"").trim(), n=+amt||0;
  if(UNIT_G[u])return{grams:round2(n*UNIT_G[u]),exact:true};
  const bu=String(ing&&ing.buy_unit||"").trim(), per=+(ing&&ing.convert_to_gram)||0;
  if(u&&bu&&u===bu&&per>0)return{grams:round2(n*per),exact:true,per};
  const su=String(ing&&ing.sub_unit||"").trim(), subPer=+(ing&&ing.sub_per_buy)||0;
  // ⚠️ ทางนี้ปัด 6 ตำแหน่ง ไม่ใช่ round2 เหมือนทางอื่น เพราะ per/subPer มักเป็นเศษไม่ลงตัว
  //    (1000÷12 = 83.333…) แล้วต้นทุนคำนวณจาก กรัม × ราคาต่อกรัม — ปัดกรัมทิ้งก่อนคูณ
  //    ทำให้ error ถูกขยายด้วยราคาต่อกรัม ยิ่งราคาต่อกรัมสูงยิ่งเพี้ยนมาก
  //    ทดสอบจริง: ปัด 2 ตำแหน่ง ทำให้ ฿53.33/ขวด กลายเป็น ฿51.20 (เพี้ยน ฿2.13/ขวด)
  //    6 ตำแหน่งทำให้ error เล็กกว่าเศษสตางค์ในทุกกรณีที่เป็นไปได้
  if(u&&su&&u===su&&subPer>0&&per>0)return{grams:Math.round(n*(per/subPer)*1e6)/1e6,exact:true,per:per/subPer,sub:true};
  return{grams:round2(n),exact:false};
}
// กรัมต่อ 1 หน่วยย่อย · null = ยังไม่ได้ตั้งหน่วยย่อย (ใช้โชว์ในฟอร์มและคิดราคาต่อหน่วยย่อย)
function subUnitGrams(ing){
  const per=+(ing&&ing.convert_to_gram)||0, subPer=+(ing&&ing.sub_per_buy)||0;
  if(!(per>0)||!(subPer>0)||!String(ing&&ing.sub_unit||"").trim())return null;
  return round2(per/subPer);
}
// จำนวนในสูตรสำหรับ "แสดงผล" (ชิป SOP + ใบ SOP ที่พิมพ์) — ไม่แตะการคิดต้นทุน/ตัดสต๊อก (ยังใช้ amountGram เหมือนเดิม)
// ใช้เลขที่คนพิมพ์ไว้ (displayAmount/displayUnit เช่น "2 ฟอง") เฉพาะเมื่อแปลงกลับแล้วได้กรัมตรงกับที่ระบบคิดจริง
// ไม่ตรง (หน่วยที่ระบบไม่รู้น้ำหนักแล้วกดยืนยัน · หน้าเมนูบวกกรัมเพิ่มเข้าไป · แก้น้ำหนักต่อหน่วยทีหลัง) → โชว์กรัมจริงปัด 2 ตำแหน่ง
// ห้ามโชว์ "1 ถุง" ทั้งที่ระบบคิดเป็น 1 กรัม — จะซ่อนต้นทุนผิดไว้หลังป้ายที่ดูถูก
function recipeQty(mi,ing){
  const g=+mi.amountGram||0;
  if(mi.displayAmount!=null&&mi.displayUnit){
    const c=recipeGrams(mi.displayAmount,mi.displayUnit,ing);
    if(c.exact&&Math.abs(c.grams-g)<0.01)return{amt:round2(+mi.displayAmount),unit:mi.displayUnit};
  }
  return{amt:round2(g),unit:mi.unit||"กรัม"};
}
// บรรทัดสูตรรุ่นเก่า (ก่อน 43e8ce2) เก็บเลขที่พิมพ์คู่หน่วยที่ไม่ใช่กรัม (เช่น "2 ฟอง") แต่ทุกจุดคิดต้นทุน/ตัดสต๊อกเป็นกรัม
// → ต้นทุนต่ำกว่าจริงมาก ใช้ติดป้ายเตือนให้คนที่แก้ SOP ได้เห็น (ไม่แก้ข้อมูลเอง — ต้องให้เจ้าของตัดสินใจ)
const recipeLegacyUnit=mi=>{const u=String(mi.unit||"").trim();return !!u&&mi.displayAmount==null&&UNIT_G[u]!==1;};
const toGrams=(amt,unit)=>round2((+amt||0)*(UNIT_G[String(unit||"").trim()]||1));
// ตัวเลือกหน่วย — ใช้ <select> ธรรมดาไม่ได้ เพราะค่าเดิมที่ไม่อยู่ใน 9 หน่วย (เช่น "กก.")
// จะทำให้ select แสดงว่าง แล้วพนักงานเผลอเซฟทับจนหน่วยหาย จึงต้องแยก
// "ค่าที่แสดง" (อะไรก็ได้ตามที่เก็บไว้) ออกจาก "ตัวเลือกที่กดได้" (9 หน่วยเท่านั้น)
// options = จำกัดรายการเฉพาะบางที่ได้ เช่นช่อง "รวมทั้งหมด" ที่รับได้แต่หน่วยที่มีน้ำหนักจริง
function UnitPicker({value,onChange,placeholder="เลือกหน่วย",options=STD_UNITS}){
  const[open,setOpen]=useState(false);
  const[uq,setUq]=useState("");
  const box=useRef(null);
  const menuRef=useRef(null);
  // ── ตำแหน่งเมนูแบบ fixed ───────────────────────────────────────────────────
  // เดิมเมนูเป็น position:absolute อยู่ในตัว Modal ซึ่ง body มี overflowY:auto
  // → เมนูโดนตัดที่ขอบกล่อง เห็นแค่ 1-2 บรรทัดแรก เลือกไม่ได้
  // fixed หลุดออกจากกรอบ overflow ได้ และคำนวณเองว่าจะกางลงหรือกางขึ้น
  const[pos,setPos]=useState(null);
  function place(){
    const r=box.current&&box.current.getBoundingClientRect();
    if(!r)return;
    const GAP=4,PAD=8;
    const below=window.innerHeight-r.bottom-PAD;
    const above=r.top-PAD;
    const up=below<200&&above>below;              // ที่ข้างล่างไม่พอและข้างบนกว้างกว่า → กางขึ้น
    setPos({left:r.left,width:r.width,
      top:up?undefined:r.bottom+GAP,
      bottom:up?(window.innerHeight-r.top+GAP):undefined,
      maxH:Math.max(150,Math.min(320,up?above:below))});
  }
  useEffect(()=>{
    if(!open){setPos(null);return;}
    setUq("");   // เปิดใหม่ทุกครั้งเริ่มจากรายการเต็ม ไม่ค้างคำค้นเดิม
    place();
    // ── เลื่อน "หน้าข้างหลัง" → เมนู fixed จะลอยค้างผิดที่ ต้องขยับตาม ──────────
    // ⚠️ ห้ามปิดเมนูทิ้ง และห้ามนับการเลื่อน "ในตัวเมนูเอง" ด้วย
    //    เดิมดัก scroll แบบ capture แล้วสั่งปิด → พอแตะเลื่อนดูรายการในเมนู
    //    (37 หน่วยต้องเลื่อน) เมนูปิดทันที เลือกหน่วยล่างๆ ไม่ได้เลย
    //    ตอนนี้ข้ามอีเวนต์ที่มาจากในเมนู แล้ววัดตำแหน่งใหม่แทนการปิด
    const onScroll=e=>{
      if(menuRef.current&&e.target instanceof Node&&menuRef.current.contains(e.target))return;
      place();
    };
    const onResize=()=>place();
    // เมนูอยู่นอก box แล้ว (fixed) จึงต้องเช็คทั้งสองกล่อง ไม่งั้นกดในเมนูแล้วเมนูปิดทันที
    const away=e=>{
      if(box.current&&box.current.contains(e.target))return;
      if(menuRef.current&&menuRef.current.contains(e.target))return;
      setOpen(false);
    };
    document.addEventListener("mousedown",away);
    window.addEventListener("scroll",onScroll,true);
    window.addEventListener("resize",onResize);
    return()=>{
      document.removeEventListener("mousedown",away);
      window.removeEventListener("scroll",onScroll,true);
      window.removeEventListener("resize",onResize);
    };
  },[open]);
  const cur=String(value||"").trim();
  const legacy=cur&&!options.includes(cur);
  // รายการยาว (37 หน่วย) — ใส่ช่องค้นหาและหัวข้อกลุ่ม ไม่งั้นต้องเลื่อนหาทีละตัว
  const longList=options.length>12;
  const shown=uq.trim()?options.filter(u=>u.includes(uq.trim())):options;
  return <div ref={box} style={{position:"relative"}}>
    <button type="button" onClick={()=>{if(!open)place();setOpen(o=>!o);}}
      style={{...iS,textAlign:"left",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
      <span style={{minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",color:cur?C.ink:C.ink4}}>{cur||placeholder}</span>
      <span style={{display:"flex",alignItems:"center",gap:6,flexShrink:0}}>
        {legacy&&<span title="หน่วยเดิมที่ไม่อยู่ในรายการมาตรฐาน — ยังใช้ได้ กดเลือกใหม่เพื่อเปลี่ยน"
          style={{fontSize:9.5,fontWeight:800,color:"#B45309",background:"#FEF3C7",borderRadius:5,padding:"1px 5px"}}>เดิม</span>}
        <Ic d={I.chevD} s={14} c={C.ink3}/>
      </span>
    </button>
    {open&&pos&&<div ref={menuRef} style={{position:"fixed",left:pos.left,width:pos.width,
      ...(pos.top!=null?{top:pos.top}:{bottom:pos.bottom}),
      zIndex:4000,background:C.white,
      border:`1px solid ${C.line}`,borderRadius:10,boxShadow:"0 12px 34px rgba(15,23,42,.22)",maxHeight:pos.maxH,display:"flex",flexDirection:"column"}}>
      {longList&&<div style={{padding:8,borderBottom:`1px solid ${C.line}`,flexShrink:0,background:C.bg}}>
        <input autoFocus value={uq} onChange={e=>setUq(e.target.value)} placeholder="พิมพ์ค้นหาหน่วย…"
          style={{...iS,padding:"7px 10px",fontSize:13}}/>
      </div>}
      {/* overscrollBehavior:contain = เลื่อนสุดรายการแล้วไม่ลามไปเลื่อนหน้าข้างหลัง
          (ถ้าลาม หน้าหลังขยับ เมนูก็ต้องขยับตาม กลายเป็นกระตุกตอนนิ้วยังลากอยู่)
          WebkitOverflowScrolling = ให้เลื่อนลื่นแบบมีแรงส่งบน iPad */}
      <div style={{overflowY:"auto",flex:1,overscrollBehavior:"contain",WebkitOverflowScrolling:"touch"}}>
      {shown.length===0
        ?<div style={{padding:"14px 12px",fontSize:12.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif",textAlign:"center"}}>ไม่พบหน่วยที่ค้นหา</div>
        :(()=>{let lastG=null;return shown.map(u=>{
          const on=u===cur;
          // หัวข้อกลุ่ม — โชว์เมื่อรายการยาวและยังไม่ได้กรองด้วยคำค้น (กรองแล้วกลุ่มไม่ช่วย)
          const g=UNIT_GROUP_OF[u];
          const head=(longList&&!uq.trim()&&g&&g!==lastG)?g:null;
          lastG=g;
          return <div key={u}>
            {head&&<div style={{padding:"6px 12px 4px",fontSize:10.5,fontWeight:900,color:C.ink4,fontFamily:"'Sarabun',sans-serif",background:C.bg,letterSpacing:.3}}>{head}</div>}
            <button type="button" onClick={()=>{onChange(u);setOpen(false);}}
              style={{display:"block",width:"100%",textAlign:"left",padding:"10px 12px",border:"none",
                borderBottom:`1px solid ${C.lineLight}`,background:on?C.brandLight:"transparent",cursor:"pointer",
                fontFamily:"'Sarabun',sans-serif",fontSize:13.5,color:C.ink,fontWeight:on?800:500}}>{u}{on?" ✓":""}</button>
          </div>;});})()}
      </div>
    </div>}
  </div>;
}
// A menu that exists but has NO recipe has an UNKNOWN cost, not a zero cost. Every costing site
// must use this so its revenue is never booked as 100%-margin profit (single source of truth —
// the previous partial fix left the snapshot, its editor and the daily table disagreeing).
const hasRecipe=(m)=>!!m&&Array.isArray(m.ingredients)&&m.ingredients.length>0;
// หมวดหมู่ของเมนู — ครัวกลางเป็นเจ้าของคนเดียว ทุกสาขาเห็นเหมือนกัน (เจ้าของสั่ง 8 ส.ค. 69)
// เดิมแต่ละสาขาจัดหมวดเองได้ผ่าน local_categories เมนูตัวเดียวกันจึงอยู่คนละหมวดในแต่ละสาขา
// และสาขายังสร้างหมวดของตัวเองได้ ทำให้ควบคุมจากที่เดียวไม่ได้
// ตอนนี้ทุกที่อ่าน menus.category อย่างเดียว · คอลัมน์ local_categories ยังคงอยู่ในฐานข้อมูล
// ไม่ได้ลบทิ้ง เผื่อต้องย้อนกลับ แต่ไม่มีโค้ดไหนอ่านมันแล้ว
const menuCatOf=(m)=>{const c=String((m&&m.category)||"").trim();return c||null;};
// เรียงข้อความไทยแบบพจนานุกรม — สระหน้า (เ แ โ ใ ไ) ต้องไปนับที่พยัญชนะตัวถัดไป
// เช่น "ไก่ทอด" อยู่หมวด ก และ "เคลียมัทฉะ" อยู่หมวด ค ไม่ใช่ไปกองท้ายตาราง
// แบบที่ .sort() เปล่าๆ ให้ (มันเรียงตามรหัสตัวอักษร สระหน้ามีรหัสสูงกว่าพยัญชนะทุกตัว)
// สร้าง Collator ไว้ตัวเดียวใช้ซ้ำ — สร้างใหม่ทุกครั้งที่เทียบจะช้ามากเมื่อรายการยาว
const _thColl=new Intl.Collator("th",{numeric:true});
const thCmp=(a,b)=>_thColl.compare(String(a==null?"":a),String(b==null?"":b));
// ลำดับหมวดหมู่ที่ร้านจัดเอง — เก็บเป็นรายชื่อเรียงลำดับใน pos_settings.category_order
// เก็บที่นั่นเพราะทั้งจอขาย จอจัดการเมนู และหน้าลูกค้าสแกน อ่าน pos_settings อยู่แล้ว
// ทั้งสามจอจึงเรียงตรงกันเองโดยไม่ต้องซิงก์อะไรเพิ่ม (เจ้าของสั่ง "ให้ตรงกับที่ลูกค้าสแกนด้วย")
// ไม่ใช้ตาราง categories เพราะข้อมูลจริงไม่ครบ: 7 หมวดที่เมนูใช้อยู่ไม่มีแถวเลย
// และอีก 4 หมวดมีแถวซ้ำ 2 แถว — เก็บลำดับที่นั่นจะจัดไม่ได้บางหมวดและต้องอัปเดตหลายแถวให้ตรงกัน
// หมวดที่ไม่อยู่ในรายการ (ครัวกลางเพิ่งเพิ่มมา) ไปต่อท้ายแล้วเรียงตามตัวอักษรไทย
// ยังไม่เคยจัดลำดับ = เรียงไทยล้วน เหมือนพฤติกรรมเดิมทุกประการ
const catOrderOf=(s)=>{const a=s&&s.category_order;return Array.isArray(a)?a.map(String):[];};
const catSorter=(order)=>{
  const r=new Map((order||[]).map((n,i)=>[String(n),i]));
  return (a,b)=>{const ia=r.has(a)?r.get(a):Infinity,ib=r.has(b)?r.get(b):Infinity;return ia!==ib?ia-ib:thCmp(a,b);};
};
// ลำดับ "เมนู" ที่ร้านจัดเอง — เก็บเป็นรายการ id ใน pos_settings.menu_order
// อยู่คอลัมน์เดียวกับลำดับหมวด จอจัดการ/จอขาย/หน้าลูกค้าสแกน จึงเรียงตรงกันเองโดยไม่ต้องซิงก์อะไรเพิ่ม
// เจ้าของสั่ง: "จะเอาเมนูไหนขึ้นก่อนลูกค้าจะได้เห็นเมนูนั้นก่อน"
// เรียงหมวดก่อนเสมอ แล้วค่อยเรียงเมนูภายในหมวด — เมนูที่ยังไม่เคยจัดไปต่อท้ายโดยคงลำดับเดิมไว้
// (คืน 0 = ไม่สลับที่ เพราะ .sort() ของ JS เสถียร) ยังไม่เคยจัด = เหมือนพฤติกรรมเดิมทุกประการ
const menuOrderOf=(s)=>{const a=s&&s.menu_order;return Array.isArray(a)?a.map(String):[];};
const menuSorter=(catOrder,menuOrder)=>{
  const cs=catSorter(catOrder);
  const r=new Map((menuOrder||[]).map((id,i)=>[String(id),i]));
  const rk=(m)=>{const k=String(m&&m.id);return r.has(k)?r.get(k):Infinity;};
  return (a,b)=>{
    const c=cs(menuCatOf(a),menuCatOf(b));if(c)return c;
    const ia=rk(a),ib=rk(b);return ia!==ib?ia-ib:0;
  };
};
// แบ่งยอดเท่ากัน n คน — คิดเป็นสตางค์เพื่อให้ "บวกกลับได้เท่าเดิมเป๊ะ"
// หารไม่ลงตัวเป็นเรื่องปกติ (฿1000 / 3) เศษสตางค์ต้องไปตกอยู่กับใครสักคน
// ไม่ใช่หายไปเฉยๆ — ร้านจะเก็บเงินขาดทุกบิลที่หารไม่ลง
// ให้คนแรกๆ รับเศษไปคนละ 1 สตางค์ (มาตรฐาน POS ทั่วไป)
// ปัดเศษ "ยอดที่ลูกค้าจ่ายจริง" ให้เป็นจำนวนเต็ม — ร้านเลือกได้ว่าปัดขึ้นหรือปัดลง
// ปัดที่ยอดสุดท้ายตัวเดียว ไม่ไปยุ่งกับยอดรวม/ส่วนลด/ค่าบริการ/VAT ที่คำนวณไว้แล้ว
// ส่วนต่างจากการปัดต้องขึ้นเป็นบรรทัดของตัวเองบนใบเสร็จและเก็บลงบิลเสมอ
// ไม่งั้นตัวเลขบนใบบวกไม่ลง และยอดขายในระบบจะไม่ตรงกับเงินที่รับมาจริง
// ตัวที่กันทศนิยมลอยคือบรรทัดปัดเป็นสตางค์ก่อน (Math.round(v*100)/100) — สำคัญมาก
// ไม่มีบรรทัดนั้น 0.1+0.2+318.7 จะได้ 319.00000000000006 แล้วปัดขึ้นกลายเป็น 320 = เก็บเงินเกินทุกบิล
// ปัดเป็นสตางค์ก่อนแล้วค่านั้นจะเป็น k/100 พอดี จำนวนเต็มจึงลงตัวเป๊ะ ไม่ต้องมีค่าเผื่ออะไรอีก
const roundModeOf=(cfg)=>{const m=cfg&&cfg.rounding;return (m==="up"||m==="down")?m:"none";};
const roundBill=(amount,mode)=>{
  const v=Math.round((+amount||0)*100)/100;   // ปัดเป็นสตางค์ก่อนเสมอ — อย่าเอาออก
  if(mode==="up")return Math.ceil(v);
  if(mode==="down")return Math.floor(v);
  return v;
};
// สูตรยอดบิล — ที่เดียวทั้งระบบ (จอโต๊ะตอนปิดบิล + จอแก้บิลที่ปิดแล้ว)
// สองที่คิดคนละสูตรเมื่อไหร่ ใบแก้กับใบเดิมจะได้ยอดคนละตัวทันทีโดยไม่มีใครรู้
function billTotalsOf({items,manualDiscount=0,promoDiscount=0,voucherDiscount=0,posSettings=null}){
  const subtotal=round2((items||[]).reduce((s,i)=>s+(+i.price||0)*(+i.qty||0),0));
  // คูปองเป็นส่วนลดท้ายบิลเหมือน FoodStory — ลดยอดสุทธิ แล้วภาษีคิดจากยอดหลังหัก
  const totalDiscount=round2((+manualDiscount||0)+(+promoDiscount||0)+(+voucherDiscount||0));
  const subAfterDisc=round2(Math.max(0,subtotal-totalDiscount));
  const scRate=posSettings?.service_charge_enabled?(+posSettings.service_charge_rate||0):0;
  const sc=round2(subAfterDisc*scRate/100);
  const vatRate=posSettings?.vat_enabled?(+posSettings.vat_rate||0):0;
  const vatIncluded=posSettings?.vat_included!==false;
  const vatBase=subAfterDisc+sc;
  const vat=round2(vatRate>0?(vatIncluded?vatBase*vatRate/(100+vatRate):vatBase*vatRate/100):0);
  const rawTotal=round2(vatIncluded?subAfterDisc+sc:subAfterDisc+sc+vat);
  const total=roundBill(rawTotal,roundModeOf(posSettings));
  // ปัดเศษแล้ว ภาษีต้องคิดจาก "ยอดที่เก็บเงินจริง" (ยอดหลังปัด) ไม่ใช่ยอดก่อนปัด
  // เดิมคิดก่อนปัด ⟹ ด่านภาษีฝั่งบัญชี (ภาษี = (ยอดขาย−ภาษี)×7% คลาดได้ ฿1) คลาดสะสม 0.07×Σปัดเศษ
  // วันที่บิลเยอะ (~100 บิลขึ้นไป) ใบปิดยอดจะถูกบล็อกทุกวัน · ไม่ปัด (rounding ว่าง) = ค่าเดิมทุกตัว
  // สูตรเดียวใช้ได้ทั้ง VAT ในราคาและบวกเพิ่ม เพราะยอดสุดท้ายมี VAT อยู่ในนั้นแล้วทั้งสองแบบ
  const vatF=(vatRate>0&&total!==rawTotal)?round2(total*vatRate/(100+vatRate)):vat;
  const roundAdj=round2(total-(vatIncluded?subAfterDisc+sc:subAfterDisc+sc+vatF));
  return{subtotal,totalDiscount,subAfterDisc,scRate,sc,vatRate,vatIncluded,vat:vatF,rawTotal,total,roundAdj};
}
// ส่วนลดของบิลแตกเป็นสามก้อน — orders.discount เก็บ "ส่วนลดทั้งหมด" ก้อนเดียว (ลดเอง+โปรฯ+คูปอง = totalDiscount)
// ทั้งบิลจริงในฐาน และใบที่ส่งไปพิมพ์ตอนปิดบิล ต้องใช้รูปเดียวกันนี้ แล้วให้ตัวพิมพ์/ใบปิดกะแตกเองที่นี่ที่เดียว
// เดิมใบพิมพ์ซ้ำ/ใบปิดกะพิมพ์ "ส่วนลดรวม" (ซึ่งรวมคูปองแล้ว) แล้วพิมพ์บรรทัดคูปองซ้ำอีก
// ⟹ บิล #385 คูปอง ฿992 ขึ้นส่วนลด ฿1,984 · ใบตอนปิดบิลไม่มีบรรทัดคูปองเลย ยอดบวกลบไม่ลง
const billDiscParts=(o)=>{
  const total=round2(Math.max(0,+(o&&o.discount)||0));
  const promo=round2(Math.max(0,+(o&&o.promo_amount)||0));
  const voucher=round2(Math.max(0,+(o&&o.voucher&&o.voucher.amount)||0));
  return{total,promo,voucher,manual:round2(Math.max(0,total-promo-voucher))};
};
// มูลค่าคูปองจากยอดที่เหลือหลังหักส่วนลดอื่น — ห้ามเกินยอดนั้น (คูปองไม่กลายเป็นเงินทอน) กติกาเดียวกับจอเก็บเงิน
const voucherAmountOf=(v,base)=>{
  if(!v)return 0;
  const b=Math.max(0,round2(base));
  const face=v.value!=null?+v.value:+v.amount;
  const raw=v.mode==="percent"?round2(b*(+v.value||0)/100):round2(+face||0);
  return Math.min(Math.max(0,raw),b);
};
// คิดยอดใหม่ของบิลที่ปิดแล้ว (จอแก้บิล) — ต้องได้ยอดเดิมเป๊ะถ้าไม่ได้แก้อะไร
// เดิมส่งส่วนลดก้อนรวมเข้าไปเป็น "ลดเอง" แล้วส่งโปรฯ ซ้ำ หรือคิดส่วนลดรายเมนูใหม่แล้วทิ้งคูปอง
// ⟹ แค่เปิดแก้ ระบบสั่งเก็บเงินลูกค้าเพิ่มเท่าค่าคูปอง · ภาษีใช้แบบของบิลใบนั้น ไม่ใช่การตั้งค่าวันนี้
function paidBillRecalc({order,items,posSettings=null}){
  const dp=billDiscParts(order);
  const hasItemDisc=((order&&order.items)||[]).some(i=>+i.item_discount>0);
  const manualDiscount=hasItemDisc?round2((items||[]).reduce((s,i)=>s+(+i.item_discount||0),0)):dp.manual;
  const sub=round2((items||[]).reduce((s,i)=>s+(+i.price||0)*(+i.qty||0),0));
  const v=order&&order.voucher&&(+order.voucher.amount||0)>0?order.voucher:null;
  const voucherDiscount=v?voucherAmountOf(v,sub-manualDiscount-dp.promo):0;
  const cfg=(order&&order.vat_rate!=null)
    ?{...(posSettings||{}),vat_enabled:+order.vat_rate>0,vat_rate:+order.vat_rate||0,vat_included:order.vat_included!==false}
    :posSettings;
  const T=billTotalsOf({items,manualDiscount,promoDiscount:dp.promo,voucherDiscount,posSettings:cfg});
  return{...T,manualDiscount,promoDiscount:dp.promo,voucherDiscount,voucher:v?{...v,amount:voucherDiscount}:null};
}
// บิลนี้อยู่ในกะที่ปิดไปแล้วหรือยัง (สาขาหนึ่งเปิดได้ทีละกะ ⟹ ไม่ใช่กะที่เปิดอยู่ = กะที่ปิดแล้ว)
// กะที่ปิดแล้ว = ยอดของกะนั้นสรุปและส่งเข้าบัญชีไปแล้ว แก้บิลตรงนี้ ฝั่งบัญชีไม่เปลี่ยนตาม
const billShiftClosed=(o,cur)=>{
  if(!o)return false;
  const curId=cur&&cur.id!=null?+cur.id:null;
  if(o.shift_id!=null)return curId==null||+o.shift_id!==curId;
  // บิลเก่าที่ยังไม่มีเลขกะ: ปิดบิลก่อนกะที่เปิดอยู่จะเริ่ม = อยู่กะก่อน
  const t=Date.parse(o.updated_at||o.created_at||""),s=Date.parse((cur&&cur.opened_at)||"");
  if(curId==null||!Number.isFinite(s))return true;
  return Number.isFinite(t)&&t<s;
};
// ── ผลส่งยอดปิดกะเข้าบัญชี (pos_closing) ──────────────────────────────
// "ข้าม" มีสองแบบที่ต้องแยกให้ออก: กะนี้ไม่มีบิล (ปิดเงียบได้) กับ สาขานี้ยังไม่เปิดท่อบัญชี (ต้องเตือน)
// เดิมปิดเงียบทั้งสองแบบ ⟹ สาขาที่ยังไม่เปิดท่อปิดกะยอดหลายหมื่นแล้วไม่มีใครรู้ว่ายอดไม่ถึงบัญชี
// ── ปิดกะ: ตอบ 200 แต่ยอด "ยังไม่ลงสมุด" ── ความหมายสถานะที่ฝั่งบัญชีกำหนดให้ (18 ต.ค. 69)
// income:    posted / exists = ลงแล้ว · skipped / error = ยังไม่ลง · mismatch = ลงแล้วแต่ยอดอ่านกลับไม่ตรง
// safe_cash: deposited / exists = เข้าตู้แล้ว · skipped = ปกติ (ใบแรกของกะข้ามเที่ยงคืน / วันไม่มีเงินสด) · error / mismatch = ผิด
// cash_doc:  skipped = ปกติ (สาขาบุคคลธรรมดาไม่ออก CA-) · blocked / error / mismatch = ผิด
// เดิมทุกคำตอบ 200 ขึ้นเขียว "ส่งเข้าระบบบัญชีแล้ว" — ยอดที่ไม่ลงสมุดจะไม่มีใครรู้ (บทเรียน duplicate 19-22 ก.ย. ฿32,705)
// ใช้เฉพาะใบปิดกะ ไม่ปนกับ slipWarnings (ตัวตอบของใบสั่งซื้อไม่มีช่องเหล่านี้)
function closingStatusWarnings(reply){
  const st=(k)=>String((reply&&reply[k]&&reply[k].status)||"");
  const out=[];
  const inc=st("income");
  if(inc==="skipped"||inc==="error")out.push("รายรับยังไม่ลงสมุด ("+inc+")");
  else if(inc==="mismatch")out.push("รายรับลงแล้วแต่ยอดอ่านกลับไม่ตรง (mismatch)");
  const safe=st("safe_cash");
  if(safe==="error"||safe==="mismatch")out.push("เงินเข้าตู้เซฟมีปัญหา ("+safe+")");
  const doc=st("cash_doc");
  if(doc==="blocked"||doc==="error"||doc==="mismatch")out.push("ใบขายเงินสด CA- ออกไม่ได้ ("+doc+")");
  return out;
}
// รูปใบปิดยอด (ฝั่งบัญชีเพิ่ม 20 ต.ค. 69) — แยกจากสถานะยอด: ขาดรูป ≠ ยอดไม่ลง ห้ามพาคนไปส่งยอดซ้ำ
// attached / exists = มีรูปแล้ว · ตัวรับรุ่นที่ไม่มีช่องนี้ = ไม่เตือน · อื่นๆ (missing / error / not_found / หมดเวลา) = ขาดรูป
// ไม่แสดงข้อความของฝั่งบัญชีตรงๆ — เขาเคยแนะนำ "ส่งซ้ำ external_id เดิม" ซึ่งสำหรับพนักงานคือการส่งยอดซ้ำ
function closingSlipMissing(reply){
  const a=reply&&reply.attachment;
  if(!a||typeof a!=="object")return false;
  const st=String(a.status||"");
  return st!=="attached"&&st!=="exists";
}
const SLIP_WHY={render:"เครื่องนี้วาดรูปไม่สำเร็จ",timeout:"ส่งรูปไม่ทันเวลา",network:"เน็ตสะดุดตอนส่งรูป"};
