// Persist newly-failed stock moves onto the PO for the 🔁 retry button. MERGES with the
// row's CURRENT stock_pending (re-read from DB, not a possibly-stale snapshot) so:
//   • a ship-time deduct failure survives the later receive (which must not erase it), and
//   • an already-retried+cleared line is NOT re-added (which would double-apply on retry).
// If nothing newly failed, it leaves existing pending untouched. Best-effort (never throws).
async function persistPending(poId,...groups){
  const fresh=groups.filter(g=>g&&Array.isArray(g.items)&&g.items.length);
  if(!fresh.length)return;
  let existing=[];
  try{ const row=await api.getPO(poId); if(Array.isArray(row)&&row[0]&&Array.isArray(row[0].stock_pending))existing=row[0].stock_pending; }catch{}
  try{ await api.updatePO(poId,{stock_pending:[...existing,...fresh]}); }catch{}
}
// (removed applyReceiveDelta — it was dead code encoding the OLD "moved at create"
//  model with an UN-clamped over-receive branch that would mint stock if ever reused.
//  The live acceptDispute inlines its own credit+variance logic clamped to <= ordered.)
// Ingredient visibility resolver:
//   visible_branches = null/undefined → visible to all branches (legacy default)
//   visible_branches = []              → explicitly visible to NO branch (user "untick all")
//   visible_branches = [ids]           → visible to those branches only
// Central kitchen always sees every ingredient regardless of this setting.
function ingVisibleAt(ing,branchId,isCentral){
  if(isCentral)return true;
  const vb=ing?.visible_branches;
  if(vb==null)return true;
  if(!Array.isArray(vb))return true;
  if(vb.length===0)return false;
  // แปลงชนิดก่อนเทียบเสมอ — ถ้ามีทางเขียนไหนเก็บเป็นสตริง ("6" แทน 6)
  // includes() จะพลาดเงียบ แล้วของที่ครัวกลางเปิดให้จะหายจากสาขา
  // (menuVisibleAt/supVisibleAt แปลงอยู่แล้ว ตัวนี้เคยเป็นตัวเดียวที่ไม่แปลง)
  return vb.map(Number).includes(+branchId);
}
// Supplier visibility (OPT-IN, unlike ingredients): a supplier is owned by the branch
// that created it (s.branch_id) and also shows at any branch central ticked into its
// visible_branches. Central creates + opens per branch; branches see own + opened.
function supVisibleAt(s,branchId){
  if(s==null||branchId==null)return false;
  if(+s.branch_id===+branchId)return true;
  const vb=s.visible_branches;
  return Array.isArray(vb)&&vb.map(Number).includes(+branchId);
}
const marginColor=(m)=>m>=60?C.green:m>=40?C.yellow:C.red;
const marginLabel=(m)=>m>=60?"ดี":m>=40?"พอใช้":"ต่ำ";
// ── Canonical date handling ──────────────────────────────────────────────
// One display format across the WHOLE app: "DD/MM/พ.ศ." (zero-padded day, NUMERIC
// month, Buddhist-era year), plus " HH:mm" for date+time.  e.g. 5 มิ.ย. 2026 → 05/06/2569.
// parseAnyDate is the ONLY parser: it reads Date | epoch-ms | ISO | "D/M/YYYY[ HH:mm[:ss]]"
// (Gregorian OR Buddhist year) and — crucially — parses the D/M/Y form MANUALLY so a
// "03/07/2026" can never be mis-read by the engine as American M/D (7 March) — the exact
// day↔month swap bug that made receipts show wrong months.
function parseAnyDate(v){
  if(v==null||v==="")return null;
  if(v instanceof Date)return isNaN(v.getTime())?null:v;
  if(typeof v==="number")return isNaN(v)?null:new Date(v);
  const s=String(v).trim();
  const m=/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ ,T]+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/.exec(s);
  if(m){const y=+m[3],yr=y>2400?y-543:y;const d=new Date(yr,(+m[2])-1,+m[1],+(m[4]||0),+(m[5]||0),+(m[6]||0));return isNaN(d.getTime())?null:d;}
  const iso=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s);            // bare date → LOCAL midnight (never UTC-shift the calendar day)
  if(iso)return new Date(+iso[1],+iso[2]-1,+iso[3]);
  const t=Date.parse(s);return isNaN(t)?null:new Date(t);   // ISO datetime / RFC — unambiguous, safe
}
const _b2=n=>String(n).padStart(2,"0");
// Buddhist-era numeric display — pass null/undefined for "now". Returns the raw string
// unchanged if it can't be parsed (so odd legacy values never render as blank/NaN).
// Only a MISSING arg (undefined, e.g. fmtDT()) means "now". An explicit null/""/bad value
// returns "" — so a null DB field never masquerades as a real current timestamp.
const fmtD=(d)=>{const x=d===undefined?new Date():parseAnyDate(d);return x?`${_b2(x.getDate())}/${_b2(x.getMonth()+1)}/${x.getFullYear()+543}`:(typeof d==="string"?d:"");};
const fmtDT=(d)=>{const x=d===undefined?new Date():parseAnyDate(d);return x?`${_b2(x.getDate())}/${_b2(x.getMonth()+1)}/${x.getFullYear()+543} ${_b2(x.getHours())}:${_b2(x.getMinutes())}`:(typeof d==="string"?d:"");};
const nowStr=()=>new Date().toISOString();   // STORAGE: unambiguous ISO (was a th locale string → the swap-bug root cause)
// Compact quantity: integers plain, decimals trimmed of trailing zeros. GLOBAL (was only a
// local in one component → RequisitionView referenced it out of scope and white-screened).
const fmtQty=n=>{const v=+n||0;return v%1===0?String(v):v.toFixed(3).replace(/0+$/,"").replace(/\.$/,"");};
