// ── POS BACK OFFICE (หลังบ้าน) ─────────────────────────
// ══════════════════════════════════════════════════════
function POSBackOffice({currentBranch,currentUser,printers,reloadPrinters,branches,zones=[],reloadZones,menus=[],reloadMenus,onExit}){
  // ผู้จัดการที่มีแค่ pos_admin: จัดการ PIN/โต๊ะ/เครื่องพิมพ์ได้ แต่เรื่องเงิน (ตั้งค่า POS/โปรโมชั่น) ต้องมีสิทธิ์ตั้งค่า
  const canMoney=posAccess(currentUser,false).settings;
  const[section,setSection]=useState("tables");
  const[tables,setTables]=useState([]);const[loadingT,setLoadingT]=useState(true);
  const[shifts,setShifts]=useState([]);const[loadingS,setLoadingS]=useState(false);
  async function loadTables(){setLoadingT(true);try{const t=await api.getPOSTables(currentBranch.id);setTables(t);}catch{}setLoadingT(false);}
  async function loadShifts(){setLoadingS(true);try{const s=await api.getShifts(currentBranch.id,30);setShifts(s);}catch{}setLoadingS(false);}
  useEffect(()=>{loadTables();},[]);
  useEffect(()=>{if(section==="shifts")loadShifts();},[section]);
  const SECS=[
    {id:"tables",l:"ผังโต๊ะ",icon:I.table,c:C.brand},
    {id:"menu",l:"เมนู & หมวดหมู่",icon:I.food,c:"#0EA5E9"},
    {id:"sellers",l:"พนักงานขาย",icon:I.user,c:C.teal},
    {id:"printers",l:"เครื่องพิมพ์",icon:I.print,c:C.purple},
    ...(canMoney?[{id:"settings",l:"ตั้งค่า POS",icon:I.settings,c:C.green},
    {id:"promotions",l:"โปรโมชั่น",icon:I.tag,c:C.yellow}]:[]),
    {id:"shifts",l:"ประวัติกะ",icon:I.clock,c:C.blue},
  ];
  return <div style={{margin:"-20px -24px",display:"flex",flexDirection:"column",height:"calc(100vh - 150px)"}}>
    <div style={{padding:"0 16px",background:"linear-gradient(135deg,#0F172A,#1E293B)",borderBottom:`1px solid ${C.line}`,display:"flex",alignItems:"center",height:54,gap:2,flexShrink:0}}>
      <button onClick={onExit} style={{background:"rgba(255,255,255,0.1)",border:"none",color:C.white,padding:"7px 14px",borderRadius:9,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:700,marginRight:14,display:"flex",alignItems:"center",gap:6}}>← กลับ</button>
      <div style={{color:C.white,fontFamily:"'Sarabun',sans-serif",fontSize:15,fontWeight:900,marginRight:24}}>⚙️ จัดการหลังบ้าน</div>
      {SECS.map(s=>{const active=section===s.id;return <button key={s.id} onClick={()=>setSection(s.id)} style={{display:"flex",alignItems:"center",gap:6,padding:"0 14px",height:54,border:"none",background:active?"rgba(255,255,255,0.1)":"transparent",cursor:"pointer",fontSize:13,fontWeight:active?800:600,color:active?C.white:"rgba(255,255,255,0.5)",fontFamily:"'Sarabun',sans-serif",borderBottom:active?`3px solid ${s.c}`:"3px solid transparent",transition:"all .15s"}}><Ic d={s.icon} s={14} c={active?s.c:"rgba(255,255,255,0.5)"}/>{s.l}</button>;})}
    </div>
    <div style={{flex:1,overflow:"auto",padding:"20px 24px",background:C.bg}}>
      <AcctUnsentBanner branchId={currentBranch.id} canResolve/>
      {section==="tables"&&(loadingT?<Loading text="โหลดโต๊ะ..."/>:<POSTableManage tables={tables} branch={currentBranch} zones={zones} reloadZones={reloadZones} onDone={loadTables}/>)}
      {section==="menu"&&<POSMenuTools currentBranch={currentBranch} currentUser={currentUser} saleOnly={false} menus={menus} variant="cards" onChanged={reloadMenus}/>}
      {section==="sellers"&&<POSSellerPanel currentBranch={currentBranch}/>}
      {section==="printers"&&<POSPrinterPanel printers={printers} reloadPrinters={reloadPrinters} branches={branches} currentUser={currentUser} menus={menus} currentBranch={currentBranch}/>}
      {section==="settings"&&canMoney&&<POSSettingsPanel currentBranch={currentBranch} currentUser={currentUser}/>}
      {section==="promotions"&&canMoney&&<POSPromotionManager currentBranch={currentBranch} menus={menus}/>}
      {section==="shifts"&&<POSShiftHistory shifts={shifts} loading={loadingS} reload={loadShifts} branch={currentBranch} user={currentUser}/>}
    </div>
  </div>;
}

// ── แก้รายชื่อ PIN บน "รายชื่อล่าสุดจากฐานข้อมูล" ไม่ใช่สำเนาตอนเปิดจอ ─────────────
// เดิมส่งทั้งรายชื่อที่ค้างบนจอ: ผู้จัดการอีกเครื่องปิด PIN คนลาออกตอน 22:00 → เครื่องนี้เพิ่มคนใหม่ 22:30
// → PIN คนลาออกกลับมาใช้ได้เงียบๆ (หรือ PIN ที่อีกเครื่องเพิ่งเพิ่มหายไป)
// อ้างตัวคนด้วย id (แถวเก่าที่ไม่มี id ใช้ PIN) ไม่ใช้ลำดับในรายการ · คืนข้อความ = ไม่บันทึก ให้แจ้งเตือน
const posSellerKey=s=>s&&s.id?"i:"+s.id:"p:"+String(s&&s.pin);
function posSellerApply(fresh,op){
  const list=Array.isArray(fresh)?fresh:[];
  const at=op.who?list.findIndex(s=>posSellerKey(s)===posSellerKey(op.who)):-1;
  if(op.who&&at<0)return op.type==="remove"?list:"พนักงานคนนี้ถูกลบจากอีกเครื่องไปแล้ว — รายชื่อบนจอโหลดใหม่ให้แล้ว";
  if(op.type==="remove")return list.filter((_,i)=>i!==at);
  // ตั้งเป็นค่าที่ผู้ใช้เลือกจากจอ ไม่ใช่สลับค่า — อีกเครื่องปิดไปแล้ว กด "ปิด" ซ้ำต้องยังปิดอยู่
  if(op.type==="active")return list.map((s,i)=>i===at?{...s,active:!!op.active}:s);
  if(list.some((s,i)=>String(s.pin)===String(op.pin)&&i!==at))return "PIN นี้ถูกใช้แล้ว — เลือกเลขอื่น";
  if(op.type==="edit")return list.map((s,i)=>i===at?{...s,name:op.name,pin:op.pin}:s);
  return [...list,{id:`s_${Date.now()}_${Math.floor(Math.random()*1000)}`,name:op.name,pin:op.pin,active:true}];
}
// Manage this branch's cashier PINs + show the sell link. Staff are stored in
// pos_settings.sales_staff (jsonb array) so no extra table/RLS is needed.
function POSSellerPanel({currentBranch}){
  const lbl={display:"block",fontSize:12,fontWeight:600,color:C.ink2,marginBottom:5,fontFamily:"'Sarabun',sans-serif"};
  const[settings,setSettings]=useState(null);
  const[staff,setStaff]=useState([]);
  const[loading,setLoading]=useState(true);
  const[saving,setSaving]=useState(false);
  const[form,setForm]=useState({name:"",pin:""});
  const[editWho,setEditWho]=useState(null);   // คนที่กำลังแก้ (เก็บตัวคน ไม่ใช่ลำดับ — รายชื่อโหลดใหม่ทุกครั้งที่บันทึก)
  const sellLink=(typeof window!=="undefined"?window.location.origin+window.location.pathname:"")+"?pos=1&branch="+currentBranch.id;
  async function load(){setLoading(true);try{const ps=await api.getPOSSettings(currentBranch.id);const s=ps&&ps[0]?ps[0]:{branch_id:currentBranch.id};setSettings(s);setStaff(Array.isArray(s.sales_staff)?s.sales_staff:[]);}catch(e){console.error("loadSellers",e);}setLoading(false);}
  useEffect(()=>{load();},[currentBranch.id]);
  async function persist(op){
    setSaving(true);
    try{
      // อ่านรายชื่อล่าสุดก่อนแก้ทุกครั้ง (อีกเครื่องอาจเพิ่งปิด/เพิ่ม PIN) — อ่านไม่ได้ = ไม่บันทึก ไม่เดาจากจอ
      const ps=await api.getPOSSettings(currentBranch.id);
      const fresh=Array.isArray(ps?.[0]?.sales_staff)?ps[0].sales_staff:[];
      const next=posSellerApply(fresh,op);
      if(typeof next==="string"){setStaff(fresh);alert(next);return false;}
      // แก้เฉพาะรายชื่อ PIN — ห้ามส่งทั้งแถวจากค่าตอนเปิดจอ ไม่งั้น VAT/พร้อมเพย์ที่อีกเครื่องเพิ่งแก้ถูกเขียนกลับเป็นค่าเก่า
      const row=await api.patchPOSSettings(currentBranch.id,{sales_staff:next});
      setSettings(row||{...(settings||{}),sales_staff:next});setStaff(next);return true;
    }catch(e){alert("บันทึกไม่สำเร็จ: "+(e&&e.message||e));return false;}
    finally{setSaving(false);}
  }
  async function submit(){
    const name=(form.name||"").trim();const pin=(form.pin||"").trim();
    if(!name)return alert("ใส่ชื่อพนักงาน");
    if(!/^\d{4}$/.test(pin))return alert("PIN ต้องเป็นตัวเลข 4 หลักเท่านั้น");
    if(await persist(editWho?{type:"edit",who:editWho,name,pin}:{type:"add",name,pin})){setForm({name:"",pin:""});setEditWho(null);}
  }
  async function toggleActive(s){await persist({type:"active",who:s,active:s.active===false});}
  async function remove(s){if(!await confirmDlg({title:"ลบพนักงานขาย",message:`ลบ "${s.name}" ออกจากระบบขาย?`}))return;await persist({type:"remove",who:s});}
  if(loading)return <Loading text="โหลดพนักงานขาย..."/>;
  return <div>
    <div style={{background:`linear-gradient(135deg,${C.brandLight},${C.tealLight})`,border:`1px solid ${C.brandBorder}`,borderRadius:14,padding:"14px 16px",marginBottom:18}}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}><span style={{fontSize:18}}>🔗</span><span style={{fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:900,color:C.ink}}>ลิงก์ขายหน้าร้าน — {currentBranch.name}</span></div>
      <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:12,color:C.ink3,lineHeight:1.6,marginBottom:10}}>ส่งลิงก์นี้ให้พนักงานสาขา — เปิดแล้วใส่ <b>PIN 4 หลัก</b> ก็เข้าขายได้เลย ไม่ต้อง login</div>
      <div style={{display:"flex",gap:14,flexWrap:"wrap",alignItems:"flex-start"}}>
        {/* QR code — สแกนด้วยกล้องหรือ Chrome เพื่อเปิดหน้าขายได้ทันที */}
        <div style={{flexShrink:0,background:C.white,borderRadius:12,padding:8,border:`1px solid ${C.line}`,display:"flex",flexDirection:"column",alignItems:"center",gap:4}}>
          <QRImg url={sellLink} size={130}/>
          <span style={{fontSize:10,color:C.ink4,fontFamily:"'Sarabun',sans-serif",fontWeight:600}}>สแกนเพื่อเปิดหน้าขาย</span>
        </div>
        <div style={{flex:1,minWidth:220,display:"flex",flexDirection:"column",gap:8}}>
          <input readOnly value={sellLink} onFocus={e=>e.target.select()} style={{...iS,fontSize:11,background:C.white,wordBreak:"break-all"}}/>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <button onClick={()=>{try{navigator.clipboard.writeText(sellLink);posToast("คัดลอกลิงก์แล้ว ✅");}catch{window.prompt("คัดลอกลิงก์:",sellLink);}}} style={{flex:1,background:C.brand,color:C.white,border:"none",borderRadius:9,padding:"9px 14px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12.5,fontWeight:800,whiteSpace:"nowrap"}}>📋 คัดลอกลิงก์</button>
            <button onClick={()=>window.open(sellLink,"_blank")} style={{flex:1,background:C.teal,color:C.white,border:"none",borderRadius:9,padding:"9px 14px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12.5,fontWeight:800,whiteSpace:"nowrap"}}>🔗 เปิดลิงก์</button>
          </div>
          <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11,color:C.ink4,lineHeight:1.6}}>💡 <b>วิธีเปิดบนแท็บเล็ต Android:</b> เปิดกล้อง → ส่องที่ QR → แตะลิงก์ที่ขึ้นมา → เปิดใน Chrome</div>
        </div>
      </div>
    </div>
    <Card style={{padding:"14px 16px",marginBottom:16}}>
      <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:13,fontWeight:800,color:C.ink,marginBottom:10}}>{editWho?"✏️ แก้ไขพนักงานขาย":"➕ เพิ่มพนักงานขาย"}</div>
      <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"flex-end"}}>
        <div style={{flex:"2 1 180px"}}><label style={lbl}>ชื่อพนักงาน</label><input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="เช่น น้องเอ" style={iS}/></div>
        <div style={{flex:"1 1 120px"}}><label style={lbl}>PIN (4 หลัก)</label><input value={form.pin} onChange={e=>setForm(f=>({...f,pin:e.target.value.replace(/\D/g,"").slice(0,4)}))} inputMode="numeric" placeholder="0000" style={{...iS,letterSpacing:4,fontWeight:800}}/></div>
        <Btn onClick={submit} loading={saving} icon={I.check}>{editWho?"บันทึก":"เพิ่ม"}</Btn>
        {editWho&&<Btn v="ghost" onClick={()=>{setForm({name:"",pin:""});setEditWho(null);}}>ยกเลิก</Btn>}
      </div>
    </Card>
    {staff.length===0?<div style={{textAlign:"center",padding:40,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}><Ic d={I.user} s={44} c={C.line}/><p style={{marginTop:10,fontSize:13}}>ยังไม่มีพนักงานขาย — เพิ่มด้านบนเพื่อให้เข้าขายด้วย PIN</p></div>
    :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(260px,100%),1fr))",gap:10}}>
      {staff.map((s,idx)=>{const inactive=s.active===false;return <Card key={s.id||idx} style={{padding:"12px 14px",opacity:inactive?.6:1}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8}}>
          <div style={{minWidth:0}}>
            <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:15,fontWeight:800,color:C.ink,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{s.name}</div>
            <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:12,color:C.ink3,marginTop:2}}>PIN: <b style={{letterSpacing:2,color:C.brand}}>{s.pin}</b></div>
          </div>
          <Chip color={inactive?"gray":"green"}>{inactive?"ปิด":"ใช้งาน"}</Chip>
        </div>
        <div style={{display:"flex",gap:6,marginTop:10}}>
          <button onClick={()=>{setForm({name:s.name,pin:String(s.pin)});setEditWho(s);}} style={{flex:1,padding:"6px 0",border:`1px solid ${C.line}`,borderRadius:8,background:C.blueLight,color:C.blue,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>แก้ไข</button>
          <button onClick={()=>toggleActive(s)} style={{flex:1,padding:"6px 0",border:`1px solid ${C.line}`,borderRadius:8,background:inactive?C.greenLight:C.bg,color:inactive?C.green:C.ink3,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>{inactive?"เปิด":"ปิด"}</button>
          <button onClick={()=>remove(s)} style={{padding:"6px 10px",border:`1px solid ${C.line}`,borderRadius:8,background:C.redLight,color:C.red,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>ลบ</button>
        </div>
      </Card>;})}
    </div>}
  </div>;
}

// ══════════════════════════════════════════════════════
// ── POS MENU & CATEGORY TOOLS (sale screen + back office)
// ══════════════════════════════════════════════════════
// Same management surface from two places: a dropdown on the sale screen and a
// section in the back office. Branch-level only — set availability & assign a
// (local) category; the price/recipe stays central.
// ทั้งสองที่ส่ง currentUser + saleOnly มาเหมือนกัน → แพ็คเกจบุฟเฟต์คิดสิทธิ์ด้วย posAccess ชุดเดียวกัน
// (คนเข้าด้วย PIN บนจอขาย = ดูอย่างเดียว) · menus = เมนูที่จอแม่โหลดไว้แล้ว ไม่ต้องดึงก้อนใหญ่ซ้ำ
function POSMenuTools({currentBranch,currentUser,saleOnly=false,menus,variant="dropdown",onChanged}){
  const[open,setOpen]=useState(false);
  const[active,setActive]=useState(null);  // 'menus' | 'options' | 'packages' | null
  const items=[
    {id:"menus",l:"เมนูทั้งหมด",icon:"🍔",sub:"สถานะ + จัดหมวด"},
    {id:"options",l:"ตัวเลือกในเมนู",icon:"➕",sub:"add-on รายเมนู"},
    {id:"packages",l:"แพ็คเกจบุฟเฟต์",icon:"🍖",sub:"ราคา/คน + เลือกเมนู"},
  ];
  return <>
    {variant==="dropdown"
      ?<div style={{position:"relative"}}>
        <button onClick={()=>setOpen(o=>!o)} style={{display:"flex",alignItems:"center",gap:6,padding:"0 12px",height:46,border:"none",background:open?C.brandLight:"none",cursor:"pointer",fontSize:12,fontWeight:700,color:C.brand,fontFamily:"'Sarabun',sans-serif",borderBottom:"2.5px solid transparent"}}>🍔 จัดการเมนูและหมวดหมู่ <span style={{fontSize:9}}>▾</span></button>
        {open&&<><div onClick={()=>setOpen(false)} style={{position:"fixed",inset:0,zIndex:60}}/>
          <div style={{position:"absolute",top:"100%",left:0,zIndex:61,background:C.white,border:`1px solid ${C.line}`,borderRadius:12,boxShadow:"0 14px 40px rgba(15,23,42,.16)",minWidth:240,overflow:"hidden",marginTop:2}}>
            {items.map(it=><button key={it.id} onClick={()=>{setActive(it.id);setOpen(false);}} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"11px 14px",border:"none",borderBottom:`1px solid ${C.lineLight}`,background:C.white,cursor:"pointer",textAlign:"left",fontFamily:"'Sarabun',sans-serif"}} onMouseEnter={e=>e.currentTarget.style.background=C.brandLight} onMouseLeave={e=>e.currentTarget.style.background=C.white}>
              <span style={{fontSize:18}}>{it.icon}</span>
              <span style={{minWidth:0}}><span style={{display:"block",fontSize:13.5,fontWeight:800,color:C.ink}}>{it.l}</span><span style={{display:"block",fontSize:11,color:C.ink4}}>{it.sub}</span></span>
            </button>)}
          </div></>}
      </div>
      :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(220px,100%),1fr))",gap:12}}>
        {items.map(it=><button key={it.id} onClick={()=>setActive(it.id)} style={{display:"flex",alignItems:"center",gap:12,padding:"16px 16px",border:`1.5px solid ${C.line}`,borderRadius:14,background:C.white,cursor:"pointer",textAlign:"left",fontFamily:"'Sarabun',sans-serif"}} onMouseEnter={e=>{e.currentTarget.style.borderColor=C.brand;e.currentTarget.style.background=C.brandLight;}} onMouseLeave={e=>{e.currentTarget.style.borderColor=C.line;e.currentTarget.style.background=C.white;}}>
          <span style={{fontSize:26}}>{it.icon}</span>
          <span><span style={{display:"block",fontSize:15,fontWeight:800,color:C.ink}}>{it.l}</span><span style={{display:"block",fontSize:12,color:C.ink4,marginTop:2}}>{it.sub}</span></span>
        </button>)}
      </div>}
    {active==="menus"&&<POSMenuAvailManager currentBranch={currentBranch} onClose={()=>{setActive(null);onChanged&&onChanged();}}/>}
    {active==="options"&&<POSOptionLibrary currentBranch={currentBranch} onClose={()=>{setActive(null);onChanged&&onChanged();}}/>}
    {active==="packages"&&<POSBuffetPackages currentBranch={currentBranch} currentUser={currentUser} saleOnly={saleOnly} menus={menus} onClose={()=>{setActive(null);onChanged&&onChanged();}}/>}
  </>;
}

// "เมนูทั้งหมด" — branch sets availability (ขาย/วันนี้หมด/ซ่อน) + binds add-on
// options to each menu (chosen from the option library). Category assignment now
// lives in the หมวดหมู่ manager (one category per menu).
// สถานะขายของเมนู — ใช้ร่วมกันระหว่างการ์ดกับตัวจอ อยู่นอกคอมโพเนนต์เพื่อไม่ให้สร้างใหม่ทุกเรนเดอร์
const MENU_AVS=[{v:"",l:"ขาย",c:C.green},{v:"sold_out",l:"วันนี้หมด",c:"#92400E"},{v:"hidden",l:"ซ่อน",c:C.red}];
// แยกการ์ดออกมาเป็นคอมโพเนนต์ของตัวเองแล้วครอบ memo เพราะจอนี้มีเมนูกว่า 250 ใบ
// กดปุ่มสถานะทีเดียวแล้วเรนเดอร์ใหม่ทั้ง 250 ใบ = จอสะดุดและรูปกระพริบ
// memo ทำให้เรนเดอร์ใหม่เฉพาะใบที่ค่าเปลี่ยนจริง (ใบอื่นยังเป็นวัตถุ m ตัวเดิม)
// ทุก prop จึงต้องนิ่ง — ฟังก์ชันที่ส่งเข้ามาห่อ useCallback ไว้หมดแล้ว
// data-mid = ที่หมายให้ตัวลากรู้ว่าใบไหนคือใบไหน
// ปุ่มข้างในกัน pointerdown ไม่ให้ไปเริ่มจับลาก ไม่งั้นกดปุ่ม "ขาย" ค้างครึ่งวินาทีก็กลายเป็นลากทั้งใบ
const MenuMgrCard=memo(function MenuMgrCard({m,cur,nOpt,busy,onAvail,onBind,onHold}){
  return <div data-mid={m.id} onPointerDown={(e)=>onHold(e,m.id)} onContextMenu={(e)=>e.preventDefault()}
    style={{position:"relative",display:"flex",flexDirection:"column",background:C.white,borderRadius:14,overflow:"hidden",
    border:`1px solid ${cur?(cur==="sold_out"?"#F59E0B":C.red):C.line}`,boxShadow:"0 2px 8px rgba(15,23,42,.06)",
    opacity:busy?.5:(cur==="hidden"?.62:1),cursor:"grab",
    WebkitUserSelect:"none",userSelect:"none",WebkitTouchCallout:"none"}}>
    <div style={{position:"relative",width:"100%",height:104,flexShrink:0}}>
      {m.image
        ?<img src={driveImgSrc(m.image,160)} alt={m.name} loading="lazy" decoding="async" draggable={false}
          style={{width:"100%",height:"100%",objectFit:"cover",pointerEvents:"none",filter:cur?"grayscale(80%)":""}}/>
        :<div style={{width:"100%",height:"100%",background:`linear-gradient(135deg,${C.brandLight},#FEF9C3)`,display:"flex",alignItems:"center",justifyContent:"center"}}><Ic d={I.food} s={30} c={cur?C.ink4:C.brand}/></div>}
      {cur==="sold_out"&&<span style={{position:"absolute",top:6,left:6,fontSize:10,fontWeight:700,color:"#92400E",background:"#FEF3C7",border:"1px solid #F59E0B",borderRadius:10,padding:"1px 7px",fontFamily:"'Sarabun',sans-serif"}}>วันนี้หมด</span>}
      {cur==="hidden"&&<span style={{position:"absolute",top:6,left:6,fontSize:10,fontWeight:700,color:C.white,background:C.red,borderRadius:10,padding:"1px 7px",fontFamily:"'Sarabun',sans-serif"}}>ซ่อน</span>}
      {nOpt>0&&<span style={{position:"absolute",top:6,right:6,fontSize:9.5,fontWeight:800,color:C.teal,background:C.tealLight,borderRadius:10,padding:"1px 7px",fontFamily:"'Sarabun',sans-serif"}}>{nOpt} ตัวเลือก</span>}
    </div>
    <div style={{padding:"8px 9px 9px",display:"flex",flexDirection:"column",gap:6,flex:1}}>
      <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:13,fontWeight:800,color:C.ink,lineHeight:1.3,minHeight:34,
        display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{m.name}</div>
      <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11,color:C.ink4,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>
        ฿{(+m.price||0).toLocaleString()}{menuCatOf(m)?` · ${menuCatOf(m)}`:""}
      </div>
      <div style={{display:"flex",gap:3,marginTop:"auto"}}>
        {MENU_AVS.map(a=><button key={a.v} onPointerDown={(e)=>e.stopPropagation()} onClick={()=>onAvail(m,a.v)}
          style={{flex:1,padding:"8px 0",minHeight:36,borderRadius:8,cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif",
          border:`1.5px solid ${cur===a.v?a.c:C.line}`,background:cur===a.v?a.c:C.white,color:cur===a.v?C.white:C.ink3}}>{a.l}</button>)}
      </div>
      <button onPointerDown={(e)=>e.stopPropagation()} onClick={()=>onBind(m)}
        style={{padding:"8px 0",minHeight:36,borderRadius:8,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif",
        border:`1.5px solid ${nOpt>0?C.teal:C.line}`,background:nOpt>0?C.tealLight:C.white,color:nOpt>0?C.teal:C.ink3}}>➕ ตัวเลือก{nOpt>0?` (${nOpt})`:""}</button>
    </div>
  </div>;
});

// ── รายการติ๊กเลือกเมนู — ใช้ร่วมกัน: "ผูกตัวเลือกหลายเมนู" และ "เลือกเมนูในแพ็คเกจบุฟเฟต์" ──
// menus = เมนูที่สาขานี้เห็นแล้ว เรียงแล้ว (คนเรียกกรองด้วยปุ่มติ๊กเอง) · sel = {id:true} · onChange(selใหม่)
// ค้นหา + ชิปหมวด (จำนวน/ที่เลือก) + เลือกทั้งหมวด + เลือกทั้งหมด/ล้าง
// ป้าย: ฿0 · วันนี้หมด · ซ่อน · ไม่มีหมวด (จอขายไม่แสดง) · extra(m) = ป้ายเพิ่มของแต่ละจอ · readOnly = ดูอย่างเดียว
const MPL_NOCAT="__nocat";
const menuPickFilter=(menus,cat,q)=>{
  const t=String(q||"").trim().toLowerCase();
  return (Array.isArray(menus)?menus:[]).filter(m=>{
    const c=menuCatOf(m);
    if(cat===MPL_NOCAT){if(c)return false;}else if(cat&&c!==cat)return false;
    return !t||String((m&&m.name)||"").toLowerCase().includes(t);
  });
};
// priceCell(m,ติ๊กอยู่) = ช่องราคาแทนป้ายราคาเดิม (คืน null = ป้ายเดิม) — ช่องพิมพ์อยู่ใน <label> ได้: แตะช่องพิมพ์ไม่สลับติ๊ก
function MenuPickList({menus,branchId,sel,onChange,readOnly=false,extra,priceCell,initialCat="",initialQ="",accent=C.teal,accentLight=C.tealLight,maxHeight="40vh"}){
  const[q,setQ]=useState(initialQ||"");const[cat,setCat]=useState(initialCat||"");
  const list=Array.isArray(menus)?menus:[];
  const on=(m)=>!!(sel&&sel[m.id]);
  const chips=useMemo(()=>{const mp=new Map();for(const m of list){const c=menuCatOf(m)||MPL_NOCAT;mp.set(c,(mp.get(c)||0)+1);}return [...mp.entries()];},[list]);
  const shown=useMemo(()=>menuPickFilter(list,cat,q),[list,cat,q]);
  const inCat=cat?menuPickFilter(list,cat,""):[];
  const setMany=(ms,v)=>{const n={...(sel||{})};ms.forEach(m=>{if(v)n[m.id]=true;else delete n[m.id];});onChange&&onChange(n);};
  const nSel=list.filter(on).length;
  const sb2={padding:"5px 11px",borderRadius:8,border:`1px solid ${C.line}`,background:C.white,color:C.ink2,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:11.5,fontWeight:700,minHeight:32};
  const tag=(t,fg,bg,title)=><span title={title||""} style={{fontSize:10.5,fontWeight:800,color:fg,background:bg,borderRadius:8,padding:"1px 7px",fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>{t}</span>;
  return <div>
    <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:8,flexWrap:"wrap"}}>
      <input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหาเมนู..." style={{...iS,flex:"1 1 180px",padding:"8px 12px",fontSize:14}}/>
      <span style={{fontSize:12,color:C.ink3,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>เลือกแล้ว <b style={{color:accent}}>{nSel}</b> / {list.length}</span>
    </div>
    {chips.length>0&&<div style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:6,marginBottom:6}}>
      {[["","ทั้งหมด",list.length],...chips.map(([c,n])=>[c,c===MPL_NOCAT?"ไม่มีหมวด":c,n])].map(([v,l,n])=>{
        const act=cat===v;const k=v?list.filter(m=>(menuCatOf(m)||MPL_NOCAT)===v&&on(m)).length:nSel;
        return <button key={v||"__all"} onClick={()=>setCat(v)} style={{flexShrink:0,padding:"5px 12px",borderRadius:16,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:act?800:600,whiteSpace:"nowrap",border:`1px solid ${act?accent:C.line}`,background:act?accent:C.white,color:act?C.white:C.ink2}}>
          {l} <span style={{opacity:.75,fontSize:11}}>{k>0?`${k}/`:""}{n}</span>
        </button>;
      })}
    </div>}
    {!readOnly&&<div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:8}}>
      {cat&&<button onClick={()=>setMany(inCat,true)} style={{...sb2,borderColor:accent,color:accent}}>เลือกทั้งหมวด ({inCat.length})</button>}
      {cat&&<button onClick={()=>setMany(inCat,false)} style={sb2}>เอาออกทั้งหมวด</button>}
      {/* เลือกเฉพาะที่เห็นบนจอ (หมวด/คำค้นที่กรองอยู่) — เดิมเลือกทุกเมนูของสาขา: กรองน้ำแล้วกดเลือก = ผูกตัวเลือกให้ทั้งร้าน */}
      <button onClick={()=>setMany(shown,true)} style={sb2}>{(cat||String(q).trim())?`เลือกที่แสดง (${shown.length})`:"เลือกทั้งหมด"}</button>
      <button onClick={()=>onChange&&onChange({})} style={sb2}>ล้าง</button>
    </div>}
    <div style={{display:"flex",flexDirection:"column",gap:5,maxHeight,overflowY:"auto"}}>
      {shown.map(m=>{const v=on(m);const av=menuAvailAt(m,branchId);const x=extra?extra(m):null;const pc=priceCell?priceCell(m,v):null;return <label key={m.id} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 11px",borderRadius:9,cursor:readOnly?"default":"pointer",background:v?accentLight:C.white,border:`1.5px solid ${v?accent:C.line}`}}>
        <input type="checkbox" checked={v} disabled={readOnly} onChange={()=>setMany([m],!v)} style={{accentColor:accent,width:17,height:17,flexShrink:0}}/>
        <span style={{flex:1,minWidth:0}}>
          <span style={{display:"block",fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:v?800:600,color:v?accent:C.ink,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{m.name}</span>
          {x&&<span style={{display:"block",fontFamily:"'Sarabun',sans-serif",fontSize:10.5,color:C.ink4,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{x}</span>}
        </span>
        <span style={{display:"flex",gap:4,alignItems:"center",flexShrink:0}}>
          {av==="sold_out"&&tag("วันนี้หมด","#92400E","#FEF3C7")}
          {av==="hidden"&&tag("ซ่อน",C.white,C.red,"ลูกค้าที่สแกน QR ไม่เห็น")}
          {!menuCatOf(m)&&tag("ไม่มีหมวด",C.red,C.redLight,"จอขายไม่แสดงเมนูที่ไม่มีหมวด")}
          {pc!=null?pc:(+m.price||0)===0?tag("฿0","#92400E","#FEF9C3"):<span style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>฿{(+m.price||0).toLocaleString()}</span>}
        </span>
      </label>;})}
      {shown.length===0&&<div style={{padding:20,textAlign:"center",color:C.ink4,fontSize:12.5,fontFamily:"'Sarabun',sans-serif"}}>ไม่พบเมนู</div>}
    </div>
  </div>;
}

function POSMenuAvailManager({currentBranch,onClose}){
  const isCentral=currentBranch?.type==="central";
  const[menus,setMenus]=useState([]);const[lib,setLib]=useState([]);const[loading,setLoading]=useState(true);
  const[q,setQ]=useState("");const[busyId,setBusyId]=useState(null);
  const[catOrder,setCatOrder]=useState([]);      // ลำดับหมวดที่ร้านจัดเอง (ชื่อเรียงตามลำดับ)
  const[drag,setDrag]=useState(null);            // {from,to,names} ระหว่างลากอยู่
  const dragRef=useRef(null);                    // อ่านค่าล่าสุดใน event handler ที่ผูกไว้ครั้งเดียว
  const holdRef=useRef(null);                    // ตัวจับเวลากดค้าง
  const rowRef=useRef(null);
  const[cat,setCat]=useState("");   // "" = ทุกหมวด · หมวดมาจากครัวกลาง สาขาแก้ไม่ได้
  const[menuOrder,setMenuOrder]=useState([]);   // ลำดับเมนูที่ร้านจัดเอง (รายการ id)
  const[mDrag,setMDrag]=useState(false);        // กำลังลากการ์ดเมนูอยู่ไหม
  const mDragRef=useRef(null);                  // ข้อมูลการลาก อ่าน/เขียนตรงๆ ไม่ผ่าน state
  const mHoldRef=useRef(null);                  // ตัวจับเวลากดค้างของการ์ด
  const gridRef=useRef(null);
  const stRef=useRef({});                       // ค่าล่าสุดให้ตัวลากอ่าน โดยตัวลากยังเป็นฟังก์ชันตัวเดิม (memo ถึงจะทำงาน)
  const[bindMenu,setBindMenu]=useState(null);const[bindSel,setBindSel]=useState({});const[bindBusy,setBindBusy]=useState(false);
  const[bulkOpen,setBulkOpen]=useState(false);const[bulkGroups,setBulkGroups]=useState({});const[bulkMenus,setBulkMenus]=useState({});const[bulkBusy,setBulkBusy]=useState(false);
  async function load(){setLoading(true);try{const[ms,ps]=await Promise.all([api.getMenus(),api.getPOSSettings(currentBranch.id)]);setMenus(ms||[]);const s=ps&&ps[0]?ps[0]:null;setLib(Array.isArray(s&&s.option_library)?s.option_library:[]);}catch(e){console.error("menuMgr",e);}setLoading(false);}
  useEffect(()=>{load();},[currentBranch.id]);
  // เรียงเหมือนที่ลูกค้าเห็นเป๊ะๆ — จอนี้คือจอที่ใช้ "จัด" ลำดับนั้น ถ้าเรียงคนละแบบก็จัดไม่ถูก
  const visible=useMemo(()=>menus
    .filter(m=>{const okB=isCentral||menuVisibleAt(m,currentBranch.id);if(!okB)return false;if(cat&&menuCatOf(m)!==cat)return false;if(q.trim()&&!m.name.toLowerCase().includes(q.toLowerCase()))return false;return true;})
    .sort(menuSorter(catOrder,menuOrder)),[menus,cat,q,isCentral,currentBranch.id,catOrder,menuOrder]);
  // เมนูทั้งหมดของสาขา (ไม่ผูกกับคำค้น/หมวดบนจอ) — ให้รายการติ๊กของ "ผูกหลายเมนู" ค้น/กรองเองได้
  const branchAll=useMemo(()=>menus.filter(m=>isCentral||menuVisibleAt(m,currentBranch.id)).sort(menuSorter(catOrder,menuOrder)),[menus,isCentral,currentBranch.id,catOrder,menuOrder]);
  stRef.current={visible,menus,catOrder,menuOrder,isCentral,bid:currentBranch.id};
  // อ่าน availability ล่าสุดของเมนูนี้ก่อนเขียน แตะเฉพาะคีย์สาขานี้ (เมนูใช้ร่วมกับ River — ห้ามทับสถานะของสาขาอื่นด้วยค่าที่ค้างบนจอ)
  const setAvail=useCallback(async function setAvail(m,status){setBusyId(m.id);try{const avail=await writeMenuBranchKey(m.id,"availability",currentBranch.id,!status?null:status==="sold_out"?soldOutMark():status);setMenus(ms=>ms.map(x=>x.id===m.id?{...x,availability:avail}:x));}catch(e){alert("บันทึกไม่สำเร็จ: "+e.message);}setBusyId(null);},[currentBranch.id]);
  // หมวดที่มีอยู่จริงในเมนูของสาขานี้ — ไม่เอาหมวดของสาขาอื่นมาให้กดแล้วว่างเปล่า
  // นับจำนวนเมนูต่อหมวดไว้ด้วย จะได้รู้ว่ากดแล้วเจออะไรบ้างโดยไม่ต้องกดลองทีละอัน
  useEffect(()=>{let ok=true;(async()=>{
    try{const r=await api.getPOSSettings(currentBranch.id);if(ok){setCatOrder(catOrderOf(r&&r[0]));setMenuOrder(menuOrderOf(r&&r[0]));}}catch{}
  })();return()=>{ok=false;};},[currentBranch.id]);

  // ลากสลับตำแหน่ง: กดค้างที่ชิปหมวดแล้วลากซ้าย-ขวา
  // กดค้างก่อนถึงจะเริ่มลาก ไม่งั้นการปัดเลื่อนแถบหมวดจะกลายเป็นการลากสลับโดยไม่ตั้งใจ
  // ขยับเกิน 8px ก่อนครบเวลา = ตั้งใจปัดเลื่อน ไม่ใช่จะลาก → ยกเลิกตัวจับเวลา
  const HOLD_MS=350;
  function orderedNames(){ return catList.map(([c])=>c); }
  // ระหว่างลาก "ไม่สลับตำแหน่งจริง" แม้แต่ครั้งเดียว
  // รอบก่อนสลับลำดับจริงทุกครั้งที่นิ้วขยับ ชิปเลยกระโดดสลับที่รัวๆ และเพราะความกว้าง
  // แต่ละใบไม่เท่ากัน ทั้งแถวจึงขยับตามทุกครั้ง = ภาพกระพริบลายตา
  // วิธีที่ถูก: ลำดับจริงอยู่นิ่ง ขยับแค่ "ภาพ" ด้วย transform ซึ่งไม่ต้องคำนวณผังใหม่
  // ใบที่จับอยู่วิ่งตามนิ้วแบบไม่มีหน่วง · ใบอื่นไถลหลบด้วย transition สั้นๆ
  // แล้วค่อยสลับลำดับจริงครั้งเดียวตอนปล่อยนิ้ว
  const GAP=6;
  function paint(){
    const d=dragRef.current;if(!d)return;
    const w=d.rects[d.from].w+GAP;
    d.chips.forEach((el,i)=>{
      let x=0;
      if(i===d.from)x=d.dx;
      else if(d.from<d.to&&i>d.from&&i<=d.to)x=-w;
      else if(d.from>d.to&&i>=d.to&&i<d.from)x=w;
      el.style.transform=x?`translate3d(${x}px,0,0)`+(i===d.from?" scale(1.06)":""):(i===d.from?"scale(1.06)":"");
      el.style.transition=i===d.from?"none":"transform .18s cubic-bezier(.2,.7,.3,1)";
      if(i===d.from){el.style.zIndex="5";el.style.boxShadow="0 8px 20px rgba(15,23,42,.25)";}
    });
  }
  function beginHold(e,name){
    if(e.pointerType==="mouse"&&e.button!==0)return;
    const sx=e.clientX,sy=e.clientY;
    const el=e.currentTarget;
    const cancel=(ev)=>{if(Math.abs(ev.clientX-sx)>8||Math.abs(ev.clientY-sy)>8)clear();};
    const clear=()=>{if(holdRef.current){clearTimeout(holdRef.current);holdRef.current=null;}
      el.removeEventListener("pointermove",cancel);el.removeEventListener("pointerup",clear);el.removeEventListener("pointercancel",clear);};
    el.addEventListener("pointermove",cancel);el.addEventListener("pointerup",clear);el.addEventListener("pointercancel",clear);
    holdRef.current=setTimeout(()=>{
      clear();
      const names=orderedNames();const from=names.indexOf(name);
      if(from<0||!rowRef.current)return;
      // วัดตำแหน่งทุกใบครั้งเดียวตอนเริ่มจับ — ระหว่างลากลำดับจริงไม่ขยับ ค่าจึงใช้ได้ตลอด
      // (ถ้าไปวัดใหม่ทุกครั้งที่นิ้วขยับ จะเป็นการบังคับให้เบราว์เซอร์คำนวณผังใหม่ทุกเฟรม)
      const chips=[...rowRef.current.querySelectorAll("[data-cat]")];
      const rects=chips.map(c=>{const r=c.getBoundingClientRect();return {c:r.left+r.width/2,w:r.width};});
      try{el.setPointerCapture(e.pointerId);}catch{}
      if(navigator.vibrate)try{navigator.vibrate(12);}catch{}   // บอกด้วยการสั่นว่าจับได้แล้ว
      dragRef.current={from,to:from,names,chips,rects,sx,dx:0};
      setDrag(true);
      paint();
    },HOLD_MS);
  }
  function moveDrag(e){
    const d=dragRef.current;if(!d)return;
    e.preventDefault();
    d.dx=e.clientX-d.sx;
    // ใบที่จับอยู่ไปหยุดตรงไหน แล้วเทียบกับกึ่งกลางของใบอื่น (ที่วัดไว้ตั้งแต่ต้น)
    const cx=d.rects[d.from].c+d.dx;
    let to=0;for(let i=0;i<d.rects.length;i++)if(cx>d.rects[i].c)to=i;
    if(cx<=d.rects[0].c)to=0;
    d.to=to;
    // เขียน transform ลง DOM ตรงๆ ไม่ผ่าน state — ไม่มีการเรนเดอร์ใหม่แม้แต่ครั้งเดียวระหว่างลาก
    if(!d.raf)d.raf=requestAnimationFrame(()=>{d.raf=null;paint();});
  }
  async function endDrag(){
    const d=dragRef.current;dragRef.current=null;
    if(d){ if(d.raf)cancelAnimationFrame(d.raf);
      d.chips.forEach(el=>{el.style.transform="";el.style.transition="";el.style.zIndex="";el.style.boxShadow="";}); }
    setDrag(false);
    if(!d||d.to===d.from)return;
    const names=[...d.names];const[moved]=names.splice(d.from,1);names.splice(d.to,0,moved);
    setCatOrder(names);                                  // ให้จอขยับทันที ไม่ต้องรอเน็ต
    try{ await api.setCategoryOrder(currentBranch.id,names); }
    catch(e){ setCatOrder(catOrder); alert("บันทึกลำดับไม่สำเร็จ: "+friendlyError(e)); }
  }
  const dragging=!!drag;
  useEffect(()=>{
    if(!dragging)return;
    const el=rowRef.current;if(!el)return;
    const stop=(e)=>{e.preventDefault();};
    el.addEventListener("touchmove",stop,{passive:false});
    return()=>el.removeEventListener("touchmove",stop,{passive:false});
  },[dragging]);

  // ── ลากการ์ดเมนูเพื่อจัดลำดับ (เป็นตาราง จึงมีทั้งซ้ายขวาและขึ้นลง) ──
  // เจ้าของสั่ง "กดค้างลากเมนูเพื่อปรับเปลี่ยนได้ว่าจะเอาเมนูไหนขึ้นก่อน ลูกค้าจะได้เห็นเมนูนั้นก่อน"
  // ใช้วิธีเดียวกับแถบหมวดที่พิสูจน์แล้วว่าลื่น: ลำดับจริงอยู่นิ่งตลอดการลาก ขยับแค่ "ภาพ" ด้วย transform
  // (ถ้าสลับลำดับจริงทุกครั้งที่นิ้วขยับ ทั้งตารางจะคำนวณผังใหม่รัวๆ = ภาพกระพริบลายตา)
  // ต่างจากแถบหมวดตรงต้องคิดทั้ง x และ y และใบที่หลบต้องเลื่อนไป "ช่องข้างเคียง" ซึ่งคำนวณจาก
  // ตำแหน่งจริงที่วัดไว้ตอนเริ่มจับ ไม่ใช่เดาจากขนาดการ์ด — พอตกบรรทัดขนาดที่เดาไว้จะไม่ตรงทันที
  // สลับได้เฉพาะภายในหมวดเดียวกัน เพราะการเรียงยึดหมวดเป็นหลัก ลากข้ามหมวดปล่อยแล้วก็เด้งกลับที่เดิม
  // (จะสลับข้ามหมวด ใช้การลากชิปหมวดด้านบนแทน)
  const MHOLD_MS=350;
  function paintM(all){
    const d=mDragRef.current;if(!d)return;
    d.cards[d.from].style.transform=`translate3d(${d.dx}px,${d.dy}px,0) scale(1.05)`;
    if(!all)return;   // ใบอื่นขยับเฉพาะตอนเป้าหมายเปลี่ยน ไม่ต้องไล่เขียนทั้ง 250 ใบทุกเฟรม
    for(let i=d.lo;i<=d.hi;i++){
      if(i===d.from)continue;
      let x=0,y=0;
      if(d.from<d.to&&i>d.from&&i<=d.to){x=d.rects[i-1].l-d.rects[i].l;y=d.rects[i-1].t-d.rects[i].t;}
      else if(d.from>d.to&&i>=d.to&&i<d.from){x=d.rects[i+1].l-d.rects[i].l;y=d.rects[i+1].t-d.rects[i].t;}
      d.cards[i].style.transform=(x||y)?`translate3d(${x}px,${y}px,0)`:"";
    }
  }
  function tickM(){
    const d=mDragRef.current;if(!d)return;
    d.raf=requestAnimationFrame(tickM);
    // ลากไปชิดขอบแล้วให้จอไถลตาม ไม่งั้นย้ายเมนูไปไกลกว่าหนึ่งหน้าจอไม่ได้เลย
    // เลื่อนแล้วต้องเลื่อนค่าที่วัดไว้ตามด้วย ไม่งั้นตำแหน่งเพี้ยนทั้งกระดาน
    const box=d.box,b=box?box.getBoundingClientRect():null;
    if(b){
      let sp=0;
      if(d.py<b.top+70)sp=-14;else if(d.py>b.bottom-70)sp=14;
      if(sp){
        const p0=box.scrollTop;box.scrollTop=p0+sp;
        const mv=box.scrollTop-p0;
        if(mv){d.rects.forEach(r=>{r.t-=mv;r.cy-=mv;});d.sy-=mv;}
      }
    }
    d.dx=d.px-d.sx;d.dy=d.py-d.sy;
    const cx=d.rects[d.from].cx+d.dx,cy=d.rects[d.from].cy+d.dy;
    let best=d.to,bd=Infinity;
    for(let i=d.lo;i<=d.hi;i++){const r=d.rects[i];const dd=(cx-r.cx)*(cx-r.cx)+(cy-r.cy)*(cy-r.cy);if(dd<bd){bd=dd;best=i;}}
    let changed=false;
    if(best!==d.to){
      const r=d.rects[d.to],cd=(cx-r.cx)*(cx-r.cx)+(cy-r.cy)*(cy-r.cy);
      if(bd<cd-900){d.to=best;changed=true;}   // ต้องใกล้กว่าเป้าเดิมชัดเจน (30px) ถึงเปลี่ยน — กันภาพสั่นสลับไปมา
    }
    paintM(changed);
  }
  // กดค้างก่อนถึงจะเริ่มลาก ไม่งั้นการเลื่อนดูเมนูจะกลายเป็นการลากสลับโดยไม่ตั้งใจ
  // ขยับเกิน 8px ก่อนครบเวลา = ตั้งใจเลื่อนดู ไม่ใช่จะลาก → ยกเลิกตัวจับเวลา
  // ห่อ useCallback ไว้เพราะส่งเข้าไปในการ์ดที่ครอบ memo — ถ้าเปลี่ยนตัวทุกเรนเดอร์ memo จะไม่ทำงานเลย
  const beginMHold=useCallback((e,id)=>{
    if(e.pointerType==="mouse"&&e.button!==0)return;
    // จับได้ทีละนิ้วเท่านั้น — นิ้วที่สองที่กดค้างระหว่างลากอยู่จะไปทับข้อมูลการลากของนิ้วแรก
    // ทำให้การ์ดใบแรกค้างเงาลอยไว้ถาวรและมีวงวนวาดภาพสองชุดพร้อมกัน
    if(mHoldRef.current||mDragRef.current)return;
    const pid=e.pointerId;
    const sx=e.clientX,sy=e.clientY;
    const el=e.currentTarget;
    const cancel=(ev)=>{if(Math.abs(ev.clientX-sx)>8||Math.abs(ev.clientY-sy)>8)clear();};
    const clear=()=>{if(mHoldRef.current){clearTimeout(mHoldRef.current);mHoldRef.current=null;}
      el.removeEventListener("pointermove",cancel);el.removeEventListener("pointerup",clear);el.removeEventListener("pointercancel",clear);};
    el.addEventListener("pointermove",cancel);el.addEventListener("pointerup",clear);el.addEventListener("pointercancel",clear);
    mHoldRef.current=setTimeout(()=>{
      clear();
      const st=stRef.current,box=gridRef.current;if(!box||!st.visible)return;
      const ids=st.visible.map(m=>String(m.id));
      const from=ids.indexOf(String(id));if(from<0)return;
      const cards=[...box.querySelectorAll("[data-mid]")];
      if(cards.length!==ids.length)return;   // จอกำลังเปลี่ยนอยู่ อย่าเพิ่งเริ่มลาก
      // วัดตำแหน่งทุกใบครั้งเดียวตอนเริ่มจับ — ระหว่างลากลำดับจริงไม่ขยับ ค่าจึงใช้ได้ตลอด
      // (ถ้าไปวัดใหม่ทุกเฟรม จะเป็นการบังคับให้เบราว์เซอร์คำนวณผังใหม่ทุกเฟรม = หนืด)
      const rects=cards.map(c=>{const r=c.getBoundingClientRect();return {l:r.left,t:r.top,cx:r.left+r.width/2,cy:r.top+r.height/2};});
      // ขอบเขตของหมวดเดียวกัน — รายการเรียงตามหมวดอยู่แล้ว หมวดหนึ่งจึงเป็นช่วงที่ติดกันเสมอ
      const myCat=menuCatOf(st.visible[from]);
      let lo=from,hi=from;
      while(lo>0&&menuCatOf(st.visible[lo-1])===myCat)lo--;
      while(hi<ids.length-1&&menuCatOf(st.visible[hi+1])===myCat)hi++;
      try{el.setPointerCapture(e.pointerId);}catch{}
      if(navigator.vibrate)try{navigator.vibrate(12);}catch{}   // บอกด้วยการสั่นว่าจับติดแล้ว
      for(let i=lo;i<=hi;i++){
        cards[i].style.willChange="transform";
        cards[i].style.transition=i===from?"none":"transform .18s cubic-bezier(.2,.7,.3,1)";
      }
      cards[from].style.zIndex="5";cards[from].style.boxShadow="0 14px 30px rgba(15,23,42,.3)";
      mDragRef.current={pid,from,to:from,ids,cards,rects,lo,hi,sx,sy,px:sx,py:sy,dx:0,dy:0,box,raf:0};
      setMDrag(true);
      paintM(true);
      mDragRef.current.raf=requestAnimationFrame(tickM);
    },MHOLD_MS);
  },[]);
  function moveMDrag(e){
    const d=mDragRef.current;if(!d||e.pointerId!==d.pid)return;   // นิ้ว/ฝ่ามือที่ไถผ่านต้องไม่ไปย้ายเป้าหมายของนิ้วที่จับอยู่
    e.preventDefault();
    d.px=e.clientX;d.py=e.clientY;   // งานจริงทำใน tickM รอบเดียวต่อเฟรม ไม่ทำต่อ event
  }
  function endMDrag(e){ return finishMDrag(e,true); }
  // ระบบยกเลิกท่าทางให้เอง (สายเรียกเข้า สลับแอป ฯลฯ) = "ยังไม่ได้ปล่อยตรงนั้น" ต้องคืนที่เดิม
  function cancelMDrag(e){ return finishMDrag(e,false); }
  async function finishMDrag(e,commit){
    const d=mDragRef.current;
    if(!d)return;
    if(e&&e.pointerId!=null&&e.pointerId!==d.pid)return;   // ปล่อยนิ้วอื่น ไม่ใช่นิ้วที่จับการ์ดอยู่
    mDragRef.current=null;
    if(d.raf)cancelAnimationFrame(d.raf);
    for(let i=d.lo;i<=d.hi;i++){const el=d.cards[i];el.style.transform="";el.style.transition="";el.style.willChange="";}
    d.cards[d.from].style.zIndex="";d.cards[d.from].style.boxShadow="";
    setMDrag(false);
    if(!commit||d.to===d.from)return;
    // ลำดับที่บันทึกต้องครอบคลุมเมนูทั้งหมดของสาขา ไม่ใช่เฉพาะที่กำลังกรองอยู่บนจอ
    // ไม่งั้นพอล้างคำค้นหา เมนูที่ไม่ได้อยู่ในผลค้นหาจะหลุดลำดับไปกองท้ายทันที
    const st=stRef.current;
    const all=st.menus.filter(m=>st.isCentral||menuVisibleAt(m,st.bid)).sort(menuSorter(st.catOrder,st.menuOrder)).map(m=>String(m.id));
    const src=String(d.ids[d.from]),dst=String(d.ids[d.to]);
    const ai=all.indexOf(src);if(ai<0)return;
    all.splice(ai,1);
    const bi=all.indexOf(dst);
    all.splice(bi<0?all.length:(d.to>d.from?bi+1:bi),0,src);   // ลากลง = ไปอยู่หลังใบเป้าหมาย · ลากขึ้น = ไปอยู่หน้า
    setMenuOrder(all);                                          // ให้จอขยับทันที ไม่ต้องรอเน็ต
    try{ await api.setMenuOrder(st.bid,all); }
    catch(e){
      setMenuOrder(st.menuOrder);
      const noCol=/column .* does not exist|PGRST204|schema cache/i.test(String((e&&e.message)||e));
      alert(noCol?"ยังบันทึกลำดับเมนูไม่ได้ — ฐานข้อมูลยังไม่มีช่องเก็บลำดับเมนู (ต้องรัน SQL เพิ่มคอลัมน์ menu_order ครั้งเดียว)"
                 :"บันทึกลำดับเมนูไม่สำเร็จ: "+friendlyError(e));
    }
  }
  // iOS ไม่สนใจ touch-action ที่เปลี่ยนกลางคัน — ต้องกันการเลื่อนจอด้วย touchmove ที่ไม่ passive
  useEffect(()=>{
    if(!mDrag)return;
    const el=gridRef.current;if(!el)return;
    const stop=(e)=>{e.preventDefault();};
    el.addEventListener("touchmove",stop,{passive:false});
    return()=>el.removeEventListener("touchmove",stop,{passive:false});
  },[mDrag]);

  const catList=(()=>{
    const m=new Map();
    for(const x of menus){
      if(!(isCentral||menuVisibleAt(x,currentBranch.id)))continue;
      const c=menuCatOf(x);if(!c)continue;
      m.set(c,(m.get(c)||0)+1);
    }
    // ลำดับนี้เปลี่ยนเฉพาะตอนปล่อยนิ้ว — ระหว่างลากต้องอยู่นิ่ง ไม่งั้นภาพกระพริบ
    return [...m.entries()].sort((a,b)=>catSorter(catOrder)(a[0],b[0]));
  })();
  const openBind=useCallback(function openBind(m){const sel={};const raw=((m.options_by_branch||{})[String(currentBranch.id)])||[];raw.forEach(b=>{const id=(typeof b==="string"||typeof b==="number")?b:(b&&b.id);if(id)sel[id]=true;});setBindSel(sel);setBindMenu(m);},[currentBranch.id]);
  async function saveBind(){
    if(!bindMenu)return;setBindBusy(true);
    const chosen=lib.filter(g=>bindSel[g.id]).map(g=>g.id);  // store group IDs (reference — library edits propagate live)
    // อ่าน options_by_branch ล่าสุดก่อนเขียน แทนที่เฉพาะคีย์สาขานี้ (ไม่ทับที่ผูกของสาขาอื่นด้วยค่าที่ค้างบนจอ)
    try{const map=await writeMenuBranchKey(bindMenu.id,"options_by_branch",currentBranch.id,chosen);setMenus(ms=>ms.map(x=>x.id===bindMenu.id?{...x,options_by_branch:map}:x));setBindMenu(null);}catch(e){alert("บันทึกไม่สำเร็จ: "+(e&&e.message||e));}
    setBindBusy(false);
  }
  // Bulk-bind: apply the SAME option group(s) to many menus at once → they all become consistent.
  async function applyBulk(){
    const groupIds=lib.filter(g=>bulkGroups[g.id]).map(g=>g.id);
    const menuIds=branchAll.filter(m=>bulkMenus[m.id]).map(m=>m.id);
    if(menuIds.length===0){alert("เลือกเมนูอย่างน้อย 1 เมนู");return;}
    if(groupIds.length===0&&!await confirmDlg({title:"ล้างตัวเลือก?",message:`ยังไม่ได้เลือกกลุ่มตัวเลือก — เมนูที่เลือก (${menuIds.length}) จะถูก “ล้างตัวเลือกออกทั้งหมด” ใช่ไหม?`,confirmLabel:"ล้างตัวเลือก",cancelLabel:"ยกเลิก",danger:true}))return;
    setBulkBusy(true);
    let done=0;
    try{
      // ทีละเมนู: อ่านค่าล่าสุดของแถวนั้นก่อน แล้วแทนที่เฉพาะคีย์สาขานี้ · อัปเดตจอทีละตัว (พังกลางทางก็ไม่หลอกว่าครบ)
      for(const mid of menuIds){if(!menus.some(x=>x.id===mid))continue;const map=await writeMenuBranchKey(mid,"options_by_branch",currentBranch.id,groupIds);setMenus(ms=>ms.map(x=>x.id===mid?{...x,options_by_branch:map}:x));done++;}
      setBulkOpen(false);posToast(`✅ ผูกตัวเลือกให้ ${done} เมนูเหมือนกันแล้ว`);
    }catch(e){alert(`บันทึกไม่สำเร็จ (ทำไปแล้ว ${done} จาก ${menuIds.length} เมนู): `+(e&&e.message||e));}
    setBulkBusy(false);
  }
  return <Modal title="🍔 เมนูทั้งหมด — สถานะ & ตัวเลือก" onClose={onClose} extraWide>
    {loading?<Loading text="โหลดเมนู..."/>:<>
      <div style={{display:"flex",gap:10,alignItems:"center",marginBottom:12,flexWrap:"wrap"}}>
        <input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหาเมนู..." style={{...iS,flex:1,minWidth:200}}/>
        <span style={{fontSize:12,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>{visible.length} เมนู</span>
        <Btn v="ghost" onClick={()=>{setBulkGroups({});setBulkMenus({});setBulkOpen(true);}} s={{padding:"9px 14px",minHeight:40,fontSize:12.5}}>🔗 ผูกหลายเมนูพร้อมกัน</Btn>
      </div>
      {catList.length>0&&<>
      <div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",marginBottom:5}}>
        👆 กดค้างที่หมวดแล้วลากซ้าย-ขวา เพื่อจัดลำดับ · ลำดับนี้ใช้ทั้งจอขายและหน้าที่ลูกค้าสแกน
      </div>
      <div ref={rowRef} onPointerMove={moveDrag} onPointerUp={endDrag} onPointerCancel={endDrag}
        style={{display:"flex",gap:6,overflowX:drag?"hidden":"auto",paddingBottom:8,marginBottom:10,borderBottom:`1px solid ${C.line}`,touchAction:drag?"none":"pan-x"}}>
        {[["","ทั้งหมด",menus.filter(x=>isCentral||menuVisibleAt(x,currentBranch.id)).length],...catList.map(([c,n])=>[c,c,n])].map(([v,l,n])=>{
          const on=cat===v;
          return <button key={v||"__all"} {...(v?{"data-cat":v,onPointerDown:(e)=>beginHold(e,v),onContextMenu:(e)=>e.preventDefault()}:{})}
            onClick={()=>{if(!drag)setCat(v);}}
            style={{flexShrink:0,padding:"5px 13px",borderRadius:16,cursor:v?"grab":"pointer",position:"relative",
            WebkitUserSelect:"none",userSelect:"none",WebkitTouchCallout:"none",
            fontFamily:"'Sarabun',sans-serif",fontSize:12.5,fontWeight:on?800:600,whiteSpace:"nowrap",
            border:`1px solid ${on?C.brand:C.line}`,background:on?C.brand:C.white,color:on?C.white:C.ink2}}>
            {l} <span style={{opacity:.7,fontSize:11}}>{n}</span>
          </button>;
        })}
      </div></>}
      {visible.length===0?<div style={{textAlign:"center",padding:40,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>ไม่พบเมนู</div>
      :<>
        <div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",marginBottom:6}}>
          👆 กดค้างที่การ์ดเมนูแล้วลากเพื่อจัดลำดับ (สลับได้ภายในหมวดเดียวกัน) · เมนูที่อยู่ก่อน ลูกค้าเห็นก่อน
        </div>
        <div ref={gridRef} onPointerMove={moveMDrag} onPointerUp={endMDrag} onPointerCancel={cancelMDrag}
          style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gridAutoRows:"max-content",gap:10,alignContent:"start",
          maxHeight:"58vh",overflowY:mDrag?"hidden":"auto",overflowX:"hidden",padding:"2px 2px 8px",
          touchAction:mDrag?"none":"pan-y"}}>
          {visible.map(m=><MenuMgrCard key={m.id} m={m}
            cur={menuAvailAt(m,currentBranch.id)}
            nOpt={getMenuOptions(m,currentBranch.id,lib).length}
            busy={busyId===m.id}
            onAvail={setAvail} onBind={openBind} onHold={beginMHold}/>)}
        </div>
      </>}
    </>}
    {bindMenu&&<Modal title={`ผูกตัวเลือก — ${bindMenu.name}`} onClose={()=>setBindMenu(null)}>
      {lib.length===0?<div style={{padding:"24px 16px",textAlign:"center",color:C.ink3,fontFamily:"'Sarabun',sans-serif",fontSize:13,lineHeight:1.7}}>ยังไม่มีกลุ่มตัวเลือกในคลัง<br/>ไปสร้างที่ <b>"➕ ตัวเลือกในเมนู"</b> ก่อน แล้วกลับมาผูก</div>
      :<>
        <div style={{fontSize:12,color:C.ink3,fontFamily:"'Sarabun',sans-serif",marginBottom:10}}>เลือก<b>กลุ่มตัวเลือก</b>ที่จะผูกกับเมนูนี้ (ลูกค้า/พนักงานจะเห็นตอนสั่ง)</div>
        <div style={{display:"flex",flexDirection:"column",gap:6,maxHeight:"45vh",overflowY:"auto",marginBottom:14}}>
          {lib.map(g=>{const on=!!bindSel[g.id];const chTxt=(g.choices||[]).map(c=>c.name).join(", ");return <label key={g.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",borderRadius:10,cursor:"pointer",background:on?C.brandLight:C.white,border:`1.5px solid ${on?C.brandBorder:C.line}`}}>
            <input type="checkbox" checked={on} onChange={()=>setBindSel(s=>({...s,[g.id]:!s[g.id]}))} style={{accentColor:C.brand,width:17,height:17,flexShrink:0}}/>
            <span style={{flex:1,minWidth:0}}>
              <span style={{display:"block",fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:on?800:600,color:on?C.brand:C.ink}}>📦 {g.name} {g.required&&<span style={{fontSize:10,fontWeight:800,color:C.red}}>*บังคับ</span>}</span>
              {chTxt&&<span style={{display:"block",fontFamily:"'Sarabun',sans-serif",fontSize:11,color:C.ink4,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{chTxt}</span>}
            </span>
          </label>;})}
        </div>
        <div style={{display:"flex",justifyContent:"flex-end",gap:10,paddingTop:12,borderTop:`1px solid ${C.line}`}}>
          <Btn v="ghost" onClick={()=>setBindMenu(null)}>ยกเลิก</Btn>
          <Btn onClick={saveBind} loading={bindBusy} icon={I.check}>บันทึก</Btn>
        </div>
      </>}
    </Modal>}
    {bulkOpen&&<Modal title="🔗 ผูกตัวเลือกหลายเมนูพร้อมกัน" onClose={()=>setBulkOpen(false)} wide>
      {lib.length===0?<div style={{padding:"24px 16px",textAlign:"center",color:C.ink3,fontFamily:"'Sarabun',sans-serif",fontSize:13,lineHeight:1.7}}>ยังไม่มีกลุ่มตัวเลือกในคลัง<br/>ไปสร้างที่ <b>"➕ ตัวเลือกในเมนู"</b> ก่อน</div>
      :<>
        <div style={{fontSize:12.5,fontWeight:800,color:C.ink,fontFamily:"'Sarabun',sans-serif",marginBottom:8}}>1️⃣ เลือกกลุ่มตัวเลือก <span style={{fontSize:11,fontWeight:600,color:C.ink4}}>(เมนูที่เลือกจะได้กลุ่มชุดนี้เหมือนกันทั้งหมด)</span></div>
        <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:16}}>
          {lib.map(g=>{const on=!!bulkGroups[g.id];return <button key={g.id} onClick={()=>setBulkGroups(s=>({...s,[g.id]:!s[g.id]}))} style={{padding:"7px 13px",borderRadius:20,border:`1.5px solid ${on?C.brand:C.line}`,background:on?C.brandLight:C.white,color:on?C.brand:C.ink3,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12.5,fontWeight:700}}>{on?"✓ ":""}📦 {g.name}{g.required?" *":""}</button>;})}
        </div>
        <div style={{fontSize:12.5,fontWeight:800,color:C.ink,fontFamily:"'Sarabun',sans-serif",marginBottom:8}}>2️⃣ เลือกเมนูที่จะผูก</div>
        <div style={{marginBottom:14}}>
          <MenuPickList menus={branchAll} branchId={currentBranch.id} sel={bulkMenus} onChange={setBulkMenus} initialCat={cat} initialQ={q}
            extra={m=>{const nOpt=getMenuOptions(m,currentBranch.id,lib).length;return nOpt>0?`มี ${nOpt} กลุ่ม`:null;}}/>
        </div>
        <div style={{display:"flex",justifyContent:"flex-end",gap:10,paddingTop:12,borderTop:`1px solid ${C.line}`}}>
          <Btn v="ghost" onClick={()=>setBulkOpen(false)}>ยกเลิก</Btn>
          <Btn v="teal" onClick={applyBulk} loading={bulkBusy} icon={I.check} disabled={Object.values(bulkMenus).filter(Boolean).length===0}>ผูกให้ {Object.values(bulkMenus).filter(Boolean).length} เมนู</Btn>
        </div>
      </>}
    </Modal>}
  </Modal>;
}

// "หมวดหมู่" — manage categories AND assign menus into them. Click a category →
// tick the menus that belong to it. A menu lives in exactly ONE category, so menus
// already in another category are shown disabled here.
function POSLocalCatManager({currentBranch,onClose}){
  const isCentral=currentBranch?.type==="central";
  const[cats,setCats]=useState([]);const[menus,setMenus]=useState([]);const[loading,setLoading]=useState(true);
  const[newName,setNewName]=useState("");const[editId,setEditId]=useState(null);const[editName,setEditName]=useState("");const[busy,setBusy]=useState(false);
  const[selCat,setSelCat]=useState(null);const[q,setQ]=useState("");
  async function load(){setLoading(true);try{const[all,ms]=await Promise.all([api.getCats(),api.getMenus()]);setCats((all||[]).filter(c=>c.type==="menu"&&!c.branch_id));setMenus(ms||[]);}catch(e){console.error("catMgr",e);}setLoading(false);}
  useEffect(()=>{load();},[currentBranch.id]);
  const catOf=(m)=>menuCatOf(m)||"";
  const visibleMenus=menus.filter(m=>{const okB=isCentral||menuVisibleAt(m,currentBranch.id);if(!okB)return false;if(q.trim()&&!m.name.toLowerCase().includes(q.toLowerCase()))return false;return true;});
  async function add(){const n=newName.trim();if(!n)return;if(cats.some(c=>c.name===n))return alert("มีหมวดนี้แล้ว");
    if(!isCentral){alert("หมวดหมู่ควบคุมจากครัวกลางที่เดียว — สาขาสร้างหมวดใหม่ไม่ได้");return;}
    setBusy(true);try{await api.addCat({type:"menu",name:n,branch_id:isCentral?null:currentBranch.id});setNewName("");await load();}catch(e){alert("เพิ่มไม่สำเร็จ: "+e.message);}setBusy(false);}
  async function rename(){const n=editName.trim();if(!n||!editId)return;
    if(!isCentral){alert("หมวดหมู่ควบคุมจากครัวกลางที่เดียว — สาขาแก้ชื่อหมวดไม่ได้");return;}
    const old=cats.find(c=>c.id===editId)?.name;setBusy(true);try{await api.updateCat(editId,{name:n});if(old&&old!==n){for(const m of menus.filter(x=>catOf(x)===old)){await api.updateMenu(m.id,{category:n});}}setEditId(null);setEditName("");if(selCat===old)setSelCat(n);await load();}catch(e){alert("บันทึกไม่สำเร็จ: "+e.message);}setBusy(false);}
  async function del(c){
    // หมวดเป็นของครัวกลาง สาขาลบไม่ได้ — ลบทีเดียวหายทุกสาขา
    if(!isCentral){alert("หมวดหมู่ควบคุมจากครัวกลางที่เดียว — สาขาลบหมวดไม่ได้");return;}
    if(!await confirmDlg({title:"ลบหมวดหมู่",message:`ลบหมวด "${c.name}"? เมนูในหมวดนี้จะกลายเป็นไม่มีหมวด`}))return;setBusy(true);try{await api.deleteCat(c.id);if(selCat===c.name)setSelCat(null);await load();}catch(e){alert("ลบไม่สำเร็จ: "+e.message);}setBusy(false);}
  async function toggleMenu(m,catName){
    // หมวดเป็นของครัวกลาง สาขาแก้ไม่ได้ ไม่งั้นย้ายหมวดที่สาขาหนึ่งแล้วอีกหกสาขาเปลี่ยนตาม
    if(!isCentral){alert("หมวดหมู่ควบคุมจากครัวกลางที่เดียว — สาขาแก้ไม่ได้");return;}
    const nextCat=(menuCatOf(m)===catName)?null:catName;
    try{await api.updateMenu(m.id,{category:nextCat||""});setMenus(ms=>ms.map(x=>x.id===m.id?{...x,category:nextCat||""}:x));}catch(e){alert("บันทึกไม่สำเร็จ: "+e.message);}}
  return <Modal title="📂 จัดการหมวดหมู่ & จัดเมนูเข้าหมวด" onClose={onClose} extraWide>
    {loading?<Loading text="โหลดหมวดหมู่..."/>:<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(min(260px,100%),1fr))",gap:16}}>
      {/* Left: categories */}
      <div>
        <div style={{display:"flex",gap:8,marginBottom:12}}>
          <input value={newName} onChange={e=>setNewName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&add()} placeholder="ชื่อหมวดใหม่ เช่น ของทอด" style={{...iS,flex:1}}/>
          <Btn onClick={add} loading={busy} icon={I.plus}>เพิ่ม</Btn>
        </div>
        {cats.length===0?<div style={{textAlign:"center",padding:30,color:C.ink4,fontFamily:"'Sarabun',sans-serif",fontSize:13}}>ยังไม่มีหมวดหมู่ — เพิ่มด้านบน</div>
        :<div style={{display:"flex",flexDirection:"column",gap:6,maxHeight:"52vh",overflowY:"auto"}}>
          {cats.map(c=>{const n=menus.filter(m=>catOf(m)===c.name).length;const on=selCat===c.name;return <div key={c.id} style={{display:"flex",alignItems:"center",gap:8,padding:"9px 12px",border:`1.5px solid ${on?C.brand:C.line}`,borderRadius:10,background:on?C.brandLight:C.white}}>
            {editId===c.id?<>
              <input value={editName} onChange={e=>setEditName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&rename()} autoFocus style={{...iS,flex:1}}/>
              <Btn onClick={rename} loading={busy} s={{padding:"5px 10px",fontSize:11}}>✓</Btn>
              <Btn v="ghost" onClick={()=>{setEditId(null);setEditName("");}} s={{padding:"5px 10px",fontSize:11}}>✕</Btn>
            </>:<>
              <button onClick={()=>setSelCat(c.name)} style={{flex:1,textAlign:"left",background:"none",border:"none",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:on?800:700,color:on?C.brand:C.ink}}>📂 {c.name} <span style={{fontSize:11,color:C.ink4,fontWeight:600}}>({n})</span></button>
              <button onClick={()=>{setEditId(c.id);setEditName(c.name);}} style={{background:C.blueLight,border:"none",borderRadius:7,padding:"5px 9px",cursor:"pointer",fontSize:11,fontWeight:700,color:C.blue,fontFamily:"'Sarabun',sans-serif"}}>แก้</button>
              <button onClick={()=>del(c)} style={{background:C.redLight,border:"none",borderRadius:7,padding:"5px 9px",cursor:"pointer",fontSize:11,fontWeight:700,color:C.red,fontFamily:"'Sarabun',sans-serif"}}>ลบ</button>
            </>}
          </div>;})}
        </div>}
      </div>
      {/* Right: assign menus to the selected category */}
      <div>
        {!selCat?<div style={{padding:"40px 16px",textAlign:"center",color:C.ink4,fontFamily:"'Sarabun',sans-serif",border:`1px dashed ${C.line}`,borderRadius:12}}><Ic d={I.tag} s={40} c={C.line}/><p style={{marginTop:8,fontSize:13}}>คลิกหมวดทางซ้าย แล้วเลือกเมนูที่จะเพิ่มเข้าหมวดนั้น</p></div>
        :<>
          <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:900,color:C.ink,marginBottom:8}}>เมนูในหมวด "{selCat}"</div>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหาเมนู..." style={{...iS,marginBottom:8}}/>
          <div style={{display:"flex",flexDirection:"column",gap:5,maxHeight:"44vh",overflowY:"auto"}}>
            {visibleMenus.map(m=>{const cur=catOf(m);const here=cur===selCat;const elsewhere=cur&&cur!==selCat;return <label key={m.id} title={elsewhere?`อยู่ในหมวด "${cur}" แล้ว`:""} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",borderRadius:9,cursor:elsewhere?"not-allowed":"pointer",background:here?C.brandLight:C.white,border:`1px solid ${here?C.brandBorder:C.line}`,opacity:elsewhere?.55:1}}>
              <input type="checkbox" checked={here} disabled={elsewhere} onChange={()=>toggleMenu(m,selCat)} style={{accentColor:C.brand,width:16,height:16,flexShrink:0}}/>
              <span style={{flex:1,fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:here?800:600,color:here?C.brand:C.ink,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.name}</span>
              {elsewhere&&<span style={{fontSize:10.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>อยู่ใน {cur}</span>}
            </label>;})}
            {visibleMenus.length===0&&<div style={{padding:20,textAlign:"center",color:C.ink4,fontSize:12,fontFamily:"'Sarabun',sans-serif"}}>ไม่พบเมนู</div>}
          </div>
        </>}
      </div>
    </div>}
  </Modal>;
}

// "ตัวเลือกในเมนู" — the branch's option-GROUP library. Create a group (name +
// required), then add sub-choices (name + price) under it. Bind whole groups to
// menus at "เมนูทั้งหมด". Stored in pos_settings.option_library =
// [{id,name,required,choices:[{id,name,price}]}].
function POSOptionLibrary({currentBranch,onClose}){
  const lbl={display:"block",fontSize:12,fontWeight:600,color:C.ink2,marginBottom:5,fontFamily:"'Sarabun',sans-serif"};
  const[settings,setSettings]=useState(null);const[lib,setLib]=useState([]);
  const[loading,setLoading]=useState(true);const[busy,setBusy]=useState(false);
  const[gName,setGName]=useState("");const[gReq,setGReq]=useState(false);const[gPick,setGPick]=useState(1);   // บังคับเลือกกี่อย่างในกลุ่มนี้
  const[ci,setCi]=useState({});                 // {groupId:{name,price}}
  const[editG,setEditG]=useState(null);const[eg,setEg]=useState({name:"",required:false});
  async function load(){setLoading(true);try{const ps=await api.getPOSSettings(currentBranch.id);const s=ps&&ps[0]?ps[0]:{branch_id:currentBranch.id};setSettings(s);setLib(Array.isArray(s.option_library)?s.option_library:[]);}catch(e){console.error("optLib",e);}setLoading(false);}
  useEffect(()=>{load();},[currentBranch.id]);
  // แก้เฉพาะคลังตัวเลือก — ไม่ส่งทั้งแถว (กันทับ VAT/PIN ที่อีกเครื่องแก้ระหว่างเปิดจอนี้)
  // และแก้บนคลังล่าสุดจากฐานข้อมูลตาม id (fn รับคลังล่าสุด คืนคลังใหม่ หรือคืนข้อความ = ไม่บันทึก)
  // ไม่ใช้สำเนาตอนเปิดจอ — ไม่งั้นตัวเลือกที่อีกเครื่องเพิ่งเพิ่ม/ลบ ถูกเขียนกลับเงียบๆ
  async function persist(fn){setBusy(true);try{const ps=await api.getPOSSettings(currentBranch.id);const fresh=Array.isArray(ps?.[0]?.option_library)?ps[0].option_library:[];const next=fn(fresh);if(typeof next==="string"){setLib(fresh);alert(next);return false;}const row=await api.patchPOSSettings(currentBranch.id,{option_library:next});setSettings(row||{...(settings||{}),option_library:next});setLib(next);return true;}catch(e){alert("บันทึกไม่สำเร็จ: "+(e&&e.message||e));return false;}finally{setBusy(false);}}
  const GONE="กลุ่มนี้ถูกลบจากอีกเครื่องไปแล้ว — รายการบนจอโหลดใหม่ให้แล้ว";
  async function addGroup(){const name=gName.trim();if(!name)return alert("ใส่ชื่อกลุ่มตัวเลือก");if(await persist(l=>l.some(g=>g.name===name)?"มีกลุ่มนี้แล้ว":[...l,{id:`g_${Date.now()}_${Math.floor(Math.random()*1000)}`,name,required:gReq,pick:gReq?Math.max(1,+gPick||1):1,choices:[]}])){setGName("");setGReq(false);setGPick(1);}}
  async function delGroup(g){if(!await confirmDlg({title:"ลบกลุ่มตัวเลือก",message:`ลบกลุ่ม "${g.name}" และตัวเลือกย่อยทั้งหมด?`}))return;await persist(l=>l.filter(x=>x.id!==g.id));}
  async function saveEditG(){const name=(eg.name||"").trim();if(!name)return;if(await persist(l=>!l.some(g=>g.id===editG)?GONE:l.map(g=>g.id===editG?{...g,name,required:!!eg.required,pick:eg.required?Math.max(1,+eg.pick||1):1}:g)))setEditG(null);}
  async function addChoice(g){const f=ci[g.id]||{};const name=(f.name||"").trim();const price=+f.price||0;if(!name)return alert("ใส่ชื่อตัวเลือกย่อย");if(await persist(l=>!l.some(x=>x.id===g.id)?GONE:l.map(x=>x.id===g.id?{...x,choices:[...(x.choices||[]),{id:`c_${Date.now()}_${Math.floor(Math.random()*1000)}`,name,price}]}:x)))setCi(s=>({...s,[g.id]:{name:"",price:""}}));}
  async function delChoice(g,cid){await persist(l=>l.map(x=>x.id===g.id?{...x,choices:(x.choices||[]).filter(c=>c.id!==cid)}:x));}
  return <Modal title="➕ ตัวเลือกในเมนู (กลุ่ม add-on)" onClose={onClose} extraWide>
    {loading?<Loading text="โหลดตัวเลือก..."/>:<>
      {/* Add group */}
      <div style={{display:"flex",gap:8,alignItems:"flex-end",marginBottom:14,flexWrap:"wrap",background:C.bg,borderRadius:10,padding:"10px 12px",border:`1px dashed ${C.line}`}}>
        <div style={{flex:"2 1 160px"}}><label style={lbl}>ชื่อกลุ่มตัวเลือก</label><input value={gName} onChange={e=>setGName(e.target.value)} onKeyDown={e=>e.key==="Enter"&&addGroup()} placeholder="เช่น ขนาด, ระดับเผ็ด" style={iS}/></div>
        <div style={{flex:"0 0 auto"}}><label style={lbl}>การเลือก</label><div style={{display:"flex",gap:5}}>{[{v:false,l:"ไม่บังคับ"},{v:true,l:"บังคับเลือก"}].map(o=><button key={String(o.v)} onClick={()=>{setGReq(o.v);if(!o.v)setGPick(1);}} style={{padding:"8px 12px",borderRadius:8,border:`2px solid ${gReq===o.v?(o.v?C.red:C.green):C.line}`,background:gReq===o.v?(o.v?C.redLight:C.greenLight):C.white,color:gReq===o.v?(o.v?C.red:C.green):C.ink3,cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>{o.l}</button>)}</div></div>
        {gReq&&<div style={{flex:"0 0 auto"}}><label style={lbl}>ต้องเลือกกี่อย่าง</label><input type="text" inputMode="numeric" value={gPick} onChange={e=>{const v=e.target.value.replace(/[^0-9]/g,"");setGPick(v===""?"":Math.min(20,+v||1));}} onBlur={()=>setGPick(p=>Math.max(1,+p||1))} style={{...iS,width:86,textAlign:"center",fontWeight:800}}/></div>}
        <Btn onClick={addGroup} loading={busy} icon={I.plus}>เพิ่มกลุ่ม</Btn>
      </div>
      {/* Groups */}
      {lib.length===0?<div style={{textAlign:"center",padding:36,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}><div style={{fontSize:40,marginBottom:6}}>📦</div><p style={{fontSize:13}}>ยังไม่มีกลุ่มตัวเลือก — เพิ่มด้านบน</p></div>
      :<div style={{display:"flex",flexDirection:"column",gap:12}}>
        {lib.map(g=>{const cf=ci[g.id]||{};return <div key={g.id} style={{border:`1.5px solid ${C.line}`,borderRadius:12,overflow:"hidden"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,padding:"10px 12px",background:C.bg,borderBottom:`1px solid ${C.line}`,flexWrap:"wrap"}}>
            {editG===g.id?<>
              <input value={eg.name} onChange={e=>setEg(s=>({...s,name:e.target.value}))} autoFocus style={{...iS,flex:"1 1 140px"}}/>
              <div style={{display:"flex",gap:5}}>{[{v:false,l:"ไม่บังคับ"},{v:true,l:"บังคับ"}].map(o=><button key={String(o.v)} onClick={()=>setEg(s=>({...s,required:o.v,pick:o.v?(s.pick||1):1}))} style={{padding:"7px 11px",borderRadius:8,border:`2px solid ${eg.required===o.v?(o.v?C.red:C.green):C.line}`,background:eg.required===o.v?(o.v?C.redLight:C.greenLight):C.white,color:eg.required===o.v?(o.v?C.red:C.green):C.ink3,cursor:"pointer",fontSize:11.5,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>{o.l}</button>)}</div>
              {eg.required&&<label style={{display:"flex",alignItems:"center",gap:6,fontSize:11.5,fontWeight:700,color:C.ink3,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>ต้องเลือก<input type="text" inputMode="numeric" value={eg.pick??1} onChange={e=>{const v=e.target.value.replace(/[^0-9]/g,"");setEg(s=>({...s,pick:v===""?"":Math.min(20,+v||1)}));}} onBlur={()=>setEg(s=>({...s,pick:Math.max(1,+s.pick||1)}))} style={{...iS,width:62,textAlign:"center",fontWeight:800,padding:"7px 6px"}}/>อย่าง</label>}
              <Btn onClick={saveEditG} loading={busy} s={{padding:"6px 12px",fontSize:12}}>บันทึก</Btn>
              <Btn v="ghost" onClick={()=>setEditG(null)} s={{padding:"6px 12px",fontSize:12}}>ยกเลิก</Btn>
            </>:<>
              <span style={{fontFamily:"'Sarabun',sans-serif",fontSize:15,fontWeight:900,color:C.ink}}>📦 {g.name}</span>
              {g.required?<span style={{fontSize:10.5,fontWeight:800,color:C.red,background:C.redLight,borderRadius:8,padding:"2px 8px"}}>* บังคับเลือก {Math.max(1,+g.pick||1)} อย่าง</span>:<span style={{fontSize:10.5,fontWeight:700,color:C.ink4,background:C.white,borderRadius:8,padding:"2px 8px",border:`1px solid ${C.line}`}}>ไม่บังคับ</span>}
              <span style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>· {(g.choices||[]).length} ตัวเลือกย่อย</span>
              {/* เคยเตือน "ตั้งให้เลือก N แต่มีแค่ M ตัวเลือก — ลูกค้าสั่งไม่ได้" · ตอนนี้เลือกตัวเดิมซ้ำได้ จึงสั่งได้เสมอ */}
              <div style={{marginLeft:"auto",display:"flex",gap:6}}>
                <button onClick={()=>{setEditG(g.id);setEg({name:g.name,required:!!g.required,pick:Math.max(1,+g.pick||1)});}} style={{background:C.blueLight,border:"none",borderRadius:7,padding:"6px 11px",cursor:"pointer",fontSize:12,fontWeight:700,color:C.blue,fontFamily:"'Sarabun',sans-serif"}}>แก้กลุ่ม</button>
                <button onClick={()=>delGroup(g)} style={{background:C.redLight,border:"none",borderRadius:7,padding:"6px 11px",cursor:"pointer",fontSize:12,fontWeight:700,color:C.red,fontFamily:"'Sarabun',sans-serif"}}>ลบกลุ่ม</button>
              </div>
            </>}
          </div>
          <div style={{padding:"10px 12px"}}>
            {(g.choices||[]).length>0&&<div style={{display:"flex",flexDirection:"column",gap:5,marginBottom:8}}>
              {(g.choices||[]).map(c=><div key={c.id} style={{display:"flex",alignItems:"center",gap:10,padding:"7px 10px",border:`1px solid ${C.lineLight}`,borderRadius:8,background:C.white}}>
                <span style={{flex:1,fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:600,color:C.ink}}>{c.name}</span>
                <span style={{fontFamily:"'Sarabun',sans-serif",fontSize:13,fontWeight:800,color:(+c.price||0)>0?C.brand:C.ink4}}>{(+c.price||0)>0?`+฿${(+c.price).toLocaleString()}`:"ฟรี"}</span>
                <button onClick={()=>delChoice(g,c.id)} style={{background:C.redLight,border:"none",borderRadius:6,padding:"4px 9px",cursor:"pointer",fontSize:11,fontWeight:700,color:C.red,fontFamily:"'Sarabun',sans-serif"}}>ลบ</button>
              </div>)}
            </div>}
            <div style={{display:"flex",gap:8,alignItems:"flex-end",flexWrap:"wrap"}}>
              <div style={{flex:"2 1 130px"}}><input value={cf.name||""} onChange={e=>setCi(s=>({...s,[g.id]:{...cf,name:e.target.value}}))} onKeyDown={e=>e.key==="Enter"&&addChoice(g)} placeholder="ชื่อตัวเลือกย่อย เช่น ใหญ่" style={{...iS,fontSize:13}}/></div>
              <div style={{flex:"0 0 100px"}}><input value={cf.price||""} onChange={e=>setCi(s=>({...s,[g.id]:{...cf,price:e.target.value.replace(/[^\d.]/g,"")}}))} inputMode="decimal" placeholder="+฿0" style={{...iS,fontSize:13}}/></div>
              <Btn onClick={()=>addChoice(g)} loading={busy} icon={I.plus} s={{padding:"8px 14px",fontSize:12}}>เพิ่มตัวเลือกย่อย</Btn>
            </div>
          </div>
        </div>;})}
      </div>}
    </>}
  </Modal>;
}

// ══════════════════════════════════════════════════════
// "แพ็คเกจบุฟเฟต์" — คลังแพ็คเกจของสาขา: ราคา/คน (ผู้ใหญ่ เด็ก + รายการนับเพิ่ม) + เมนูที่โต๊ะแพ็คเกจนั้นเห็น
// จอเดียวกันทั้งหลังบ้าน และ "จัดการเมนูและหมวดหมู่" บนจอขาย (มาทาง POSMenuTools ทั้งคู่)
// สิทธิ์: สร้าง/ลบ/แก้ชื่อ-ราคา/ราคาในแพ็คเกจ = สิทธิ์ตั้งค่า (เรื่องเงิน) · เลือกเมนู = ตั้งค่า หรือ pos_admin
// พนักงานขายที่เข้าด้วย PIN = ทำได้ครบเหมือนหลังบ้าน (เจ้าของสั่ง 19 ต.ค. 69 — ร้านจัดแพ็คเกจหน้างาน) · ประวัติจดชื่อคนแก้
// ทุกการแก้จดประวัติ · เขียนเฉพาะคอลัมน์ buffet_packages แบบมีเงื่อนไข (buffetPkgSave) ไม่ทับของอีกเครื่อง
// ราคาถูกจดลงบิลตอนเปิดโต๊ะ — แก้ระหว่างกะได้ โต๊ะที่เปิดอยู่ยังคิดราคาเดิม
// ══════════════════════════════════════════════════════
const bpFm=(n)=>"฿"+(+n||0).toLocaleString("en-US",{maximumFractionDigits:2});
const bpFormOf=(p)=>{
  const ln=(k)=>{const l=p&&p.lines.find(x=>x.key===k);return l?String(l.price):"";};
  return p?{id:p.id,name:p.name,adult:ln("adult"),child:ln("child"),base:p.updated_at||null,minutes:String(pkgOrderMinutesOf(p)),
    extras:p.lines.filter(l=>l.key!=="adult"&&l.key!=="child").map(l=>({key:l.key,label:l.label,price:String(l.price)}))}
    :{id:null,name:"",adult:"",child:"",base:null,extras:[],minutes:String(PKG_ORDER_MIN_DEFAULT)};
};
// ส่วนต่างราคาในแพ็คเกจจากจอเลือกเมนู → {เลขเมนู: ราคา | null} หรือข้อความ (= ไม่บันทึก บอกเมนูที่ผิด)
// chosen = เมนูที่ติ๊ก · now/was = ข้อความในช่องตอนนี้/ตอนเปิดจอ · ว่าง = ราคาเมนูปกติ · "12." นับเป็น 12
function bpPriceDiff(chosen,now,was,nameOf){
  const out={};
  for(const id of chosen){
    const s=String((now||{})[id]??"").trim().replace(/\.$/,""),o=String((was||{})[id]??"").trim();
    if(s!==""&&!BP_PRICE_RE.test(s))return `ราคาในแพ็คเกจของ "${nameOf?nameOf(id):id}" ต้องเป็นตัวเลข 0 ขึ้นไป ทศนิยมไม่เกิน 2 ตำแหน่ง`;
    const nv=s===""?null:Math.round(Number(s)*100)/100,ov=o===""?null:Math.round(Number(o)*100)/100;
    if(nv!==ov)out[id]=nv;
  }
  return out;
}
function POSBuffetPackages({currentBranch,currentUser,saleOnly=false,menus:menusProp,onClose}){
  const bid=currentBranch.id;
  const acc=posAccess(currentUser,saleOnly);
  // พนักงานขาย (PIN) แก้แพ็คเกจได้ครบ — เฉพาะจอนี้ สิทธิ์อื่นของจอขายยังคุมด้วย posAccess เหมือนเดิม
  const canMoney=acc.settings||saleOnly;   // สร้าง/ลบ/แก้ชื่อ-ราคา/ราคาในแพ็คเกจ
  const canMenus=acc.admin||saleOnly;      // เลือกเมนูในแพ็คเกจ
  const who=(currentUser&&(currentUser.name||currentUser.username))||"";
  const LOCK_MONEY="สร้าง/ลบ/แก้ราคาแพ็คเกจ ต้องมีสิทธิ์ตั้งค่า";
  const LOCK_MENUS="เลือกเมนูในแพ็คเกจ ต้องมีสิทธิ์ตั้งค่า หรือจัดการ POS";
  const lbl={display:"block",fontSize:12,fontWeight:700,color:C.ink2,marginBottom:5,fontFamily:"'Sarabun',sans-serif"};
  const[loading,setLoading]=useState(true);const[busy,setBusy]=useState(false);
  const[pkgs,setPkgs]=useState([]);const[raw,setRaw]=useState(undefined);const[noCol,setNoCol]=useState(false);
  const[menus,setMenus]=useState(Array.isArray(menusProp)?menusProp:[]);
  const[order,setOrder]=useState({cat:[],menu:[]});
  const[shiftOpen,setShiftOpen]=useState(false);
  const[form,setForm]=useState(null);   // ฟอร์มสร้าง/แก้ {id|null,name,adult,child,extras,base}
  const[pick,setPick]=useState(null);   // เลือกเมนู {id,sel:{id:true},opened:[ids],prices:{id:"ข้อความในช่อง"},openedPrices}
  async function load(){
    setLoading(true);
    try{
      const[bp,ps,sh,ms]=await Promise.all([
        api.getBuffetPackages(bid),
        api.getPOSSettings(bid).catch(()=>null),
        api.getActiveShift(bid).catch(()=>null),
        (Array.isArray(menusProp)&&menusProp.length)?menusProp:api.getMenus().catch(()=>[]),
      ]);
      setPkgs(bp.packages);setRaw(bp.raw);setNoCol(!!bp.missingColumn);
      const s=Array.isArray(ps)&&ps[0]?ps[0]:null;setOrder({cat:catOrderOf(s),menu:menuOrderOf(s)});
      setShiftOpen(Array.isArray(sh)&&!!sh[0]);
      setMenus(Array.isArray(ms)?ms:[]);
    }catch(e){notifyDlg("โหลดแพ็คเกจไม่สำเร็จ: "+friendlyError(e));}
    setLoading(false);
  }
  useEffect(()=>{load();},[bid]);   // eslint-disable-line react-hooks/exhaustive-deps
  const pickable=useMemo(()=>bpPickableMenus(menus,bid,order.cat,order.menu),[menus,bid,order]);
  const pickIds=useMemo(()=>new Set(pickable.map(m=>+m.id)),[pickable]);
  const active=pkgs.filter(p=>p.active);
  // เมนูนี้อยู่ในแพ็คเกจไหนบ้าง (เฉพาะที่ยังใช้อยู่) — ป้าย "อยู่ในแพ็คเกจอื่น" ในจอเลือกเมนู
  const inPkgs=useMemo(()=>{const mp=new Map();for(const p of pkgs){if(!p.active)continue;for(const id of p.menu_ids){const a=mp.get(id)||[];a.push(p);mp.set(id,a);}}return mp;},[pkgs]);
  // การแก้หนึ่งครั้ง → เขียนบนคลังล่าสุดในฐาน → จดประวัติ → อัปเดตจอ · คืน {ok,packages}
  async function persist(op){
    setBusy(true);
    try{
      const res=await api.saveBuffetPackages(bid,(L)=>buffetPkgOp(L,op),raw);
      setPkgs(res.packages);setRaw(res.raw);
      if(!res.ok){notifyDlg(res.msg);return res;}
      if(!res.unchanged){
        const b=(res.before||[]).find(p=>p.id===op.id)||null,a=res.packages.find(p=>p.id===op.id)||null;
        const txt=buffetAuditText(b,a,who,currentBranch,(id)=>{const m=menus.find(x=>+x.id===+id);return m&&m.name;});
        if(txt){try{await api.addActionHist({action:txt,time:nowStr()});}catch(e){console.warn("bpAudit",e);}}
      }
      return res;
    }catch(e){
      if(e&&e.missingColumn)setNoCol(true);
      notifyDlg("บันทึกไม่สำเร็จ: "+(e&&e.missingColumn?BP_NO_COL:friendlyError(e)));
      return {ok:false,packages:null};
    }finally{setBusy(false);}
  }
  async function saveForm(){
    if(!canMoney){notifyDlg(LOCK_MONEY);return;}
    if(!form||busy)return;
    const lines=buffetFormToLines(form);
    if(typeof lines==="string"){notifyDlg(lines);return;}
    // เวลาสั่งอาหาร (นาที) — ฟอร์มรุ่นนี้มีช่องเสมอ · ไม่มีช่อง (undefined) = ไม่แตะค่าเดิม
    let minutes;
    if(form.minutes!==undefined){const s=String(form.minutes??"").trim();minutes=bpMinutes(s===""?null:s);if(minutes==null){notifyDlg("เวลาสั่งอาหารต้องเป็นจำนวนนาที 0–1440 (120 = 2 ชม. · 0 = ไม่จำกัดเวลา)");return;}}
    const name=String(form.name).trim(),at=nowStr();
    const op=form.id?{type:"edit",id:form.id,name,lines,base:form.base,minutes,at,by:who}:{type:"create",id:bpNewId("pk"),name,lines,minutes,at,by:who};
    const res=await persist(op);
    if(res.ok){
      setForm(null);
      if(shiftOpen)posToast("บันทึกแล้ว — โต๊ะที่เปิดอยู่ยังคิดราคาเดิม (จดไว้ตอนเปิดโต๊ะ) · โต๊ะที่เปิดใหม่ใช้ราคาใหม่","warn",7000);
      else posToast("✅ บันทึกแพ็คเกจแล้ว");
    }else if(res.packages&&form.id){
      // อีกเครื่องเพิ่งแก้/ลบ — เปิดฟอร์มด้วยค่าล่าสุดให้ตรวจก่อน (ไม่เขียนทับราคาที่ไม่เคยเห็น)
      const p=res.packages.find(x=>x.id===form.id);
      setForm(p&&p.active?bpFormOf(p):null);
    }
  }
  async function del(p){
    if(!canMoney){notifyDlg(LOCK_MONEY);return;}
    if(busy)return;
    if(!await confirmDlg({title:"ลบแพ็คเกจ",message:`ลบแพ็คเกจ "${p.name}"?\nโต๊ะที่เปิดด้วยแพ็คเกจนี้อยู่ ยังใช้ต่อได้จนปิดบิล · เปิดโต๊ะใหม่จะไม่เห็นแพ็คเกจนี้แล้ว`,confirmLabel:"ลบแพ็คเกจ",cancelLabel:"ยกเลิก",danger:true}))return;
    if((await persist({type:"delete",id:p.id,at:nowStr(),by:who})).ok)posToast("ลบแพ็คเกจแล้ว");
  }
  function openPick(p){
    const sel={};p.menu_ids.forEach(id=>{if(pickIds.has(+id))sel[id]=true;});
    const prices={};for(const [k,v] of Object.entries(p.menu_prices||{}))prices[k]=String(v);
    setPick({id:p.id,sel,opened:p.menu_ids.slice(),prices,openedPrices:{...prices}});
  }
  async function savePick(){
    if(!canMenus){notifyDlg(LOCK_MENUS);return;}
    if(!pick||busy)return;
    const chosen=new Set(Object.keys(pick.sel).filter(k=>pick.sel[k]).map(Number));
    const opened=new Set(pick.opened.map(Number));
    // ส่งเฉพาะส่วนต่าง เรียงตามลำดับที่โชว์ · เมนูที่สาขามองไม่เห็นแล้วหลุดออกตอนบันทึก (ติ๊กไม่ได้อยู่แล้ว)
    const add=pickable.filter(m=>chosen.has(+m.id)&&!opened.has(+m.id)).map(m=>+m.id);
    const remove=[...opened].filter(id=>!chosen.has(id));
    // ราคาในแพ็คเกจ: ส่งเฉพาะเมนูที่ติ๊กอยู่และราคาเปลี่ยนจากตอนเปิดจอ (ว่าง = กลับไปใช้ราคาเมนู)
    const prices=bpPriceDiff(chosen,pick.prices,pick.openedPrices,(id)=>{const m=pickable.find(x=>+x.id===+id);return m?m.name:"#"+id;});
    if(typeof prices==="string"){notifyDlg(prices);return;}
    if(Object.keys(prices).length&&!canMoney){notifyDlg(LOCK_MONEY);return;}
    if(!add.length&&!remove.length&&!Object.keys(prices).length){setPick(null);return;}
    const res=await persist({type:"menus",id:pick.id,add,remove,prices,at:nowStr(),by:who});
    if(res.ok){
      setPick(null);
      const np=Object.keys(((res.packages||[]).find(p=>p.id===pick.id)||{}).menu_prices||{}).length;
      posToast(`✅ บันทึกเมนูในแพ็คเกจแล้ว (${chosen.size} เมนู${np?` · ราคาในแพ็คเกจ ${np} เมนู`:""})`);
    }
    else if(res.packages&&!res.packages.some(p=>p.id===pick.id&&p.active))setPick(null);
  }
  const setF=(k,v)=>setForm(f=>({...f,[k]:v}));
  const setX=(i,k,v)=>setForm(f=>({...f,extras:f.extras.map((x,j)=>j===i?{...x,[k]:v}:x)}));
  const note=(bg,bd,fg,children)=><div style={{background:bg,border:`1px solid ${bd}`,color:fg,borderRadius:10,padding:"9px 12px",fontSize:12.5,fontWeight:600,lineHeight:1.6,fontFamily:"'Sarabun',sans-serif",marginBottom:10}}>{children}</div>;
  const btn=(c,bg)=>({background:bg,border:"none",borderRadius:8,padding:"8px 12px",minHeight:36,cursor:"pointer",fontSize:12,fontWeight:700,color:c,fontFamily:"'Sarabun',sans-serif"});
  const pk=pick?pkgs.find(x=>x.id===pick.id):null;
  const stale=pk?pk.menu_ids.filter(id=>!pickIds.has(+id)).length:0;
  return <Modal title="🍖 แพ็คเกจบุฟเฟต์" onClose={onClose} wide>
    {loading?<Loading text="โหลดแพ็คเกจ..."/>
    :noCol?note("#FEF3C7","#F59E0B","#92400E",<><b>ต้องรัน SQL เพิ่มคอลัมน์ก่อน</b><br/>ผู้ดูแลระบบรันไฟล์ sql/buffet-packages.sql ใน Supabase ครั้งเดียว แล้วเปิดหน้านี้ใหม่ · ระหว่างนี้ร้านขายแบบสั่งตามเมนูได้ตามปกติ</>)
    :<>
      {!canMenus?note(C.bg,C.line,C.ink3,<>🔒 ดูได้อย่างเดียว — {LOCK_MONEY}</>)
        :!canMoney?note(C.bg,C.line,C.ink3,<>🔒 {LOCK_MONEY} · เลือกเมนูในแพ็คเกจได้</>):null}
      {shiftOpen&&note("#FFFBEB","#FCD34D","#92400E",<>⚠️ กะเปิดอยู่ — แก้ราคาตอนนี้ได้ โต๊ะที่เปิดไปแล้วยังคิดราคาเดิม (จดไว้ในบิลตอนเปิดโต๊ะ) · โต๊ะที่เปิดใหม่ใช้ราคาใหม่</>)}
      {canMoney&&<div style={{marginBottom:12}}><Btn onClick={()=>setForm(bpFormOf(null))} icon={I.plus}>สร้างแพ็คเกจ</Btn></div>}
      {active.length===0?<div style={{textAlign:"center",padding:"32px 16px",color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}><div style={{fontSize:40,marginBottom:6}}>🍖</div><p style={{fontSize:13}}>ยังไม่มีแพ็คเกจ{canMoney?" — กด \"สร้างแพ็คเกจ\"":""}</p></div>
      :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(260px,100%),1fr))",gap:10}}>
        {active.map(p=>{const n=p.menu_ids.filter(id=>pickIds.has(+id)).length;return <div key={p.id} style={{border:`1.5px solid ${C.line}`,borderRadius:14,background:C.white,padding:"12px 14px",display:"flex",flexDirection:"column",gap:8}}>
          <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:15.5,fontWeight:900,color:C.ink}}>🍖 {p.name}</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
            {p.lines.map(l=><span key={l.key} style={{fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif",borderRadius:8,padding:"2px 8px",background:l.guest?C.brandLight:C.bg,color:l.guest?C.brand:C.ink2,border:`1px solid ${l.guest?C.brandBorder:C.line}`}}>{l.label} {bpFm(l.price)}</span>)}
            <span style={{fontSize:12,fontWeight:700,fontFamily:"'Sarabun',sans-serif",borderRadius:8,padding:"2px 8px",background:C.bg,color:C.ink2,border:`1px solid ${C.line}`}}>⏱ สั่งได้ {pkgDurText(pkgOrderMinutesOf(p))}</span>
          </div>
          <div style={{fontSize:12,color:n?C.ink3:C.red,fontFamily:"'Sarabun',sans-serif",fontWeight:600}}>{n} เมนู{n===0?" — ยังไม่ได้เลือกเมนู":""}{(()=>{const k=Object.keys(p.menu_prices||{}).filter(id=>pickIds.has(+id)).length;return k?<span style={{color:C.brand}}> · ราคาในแพ็คเกจ {k} เมนู</span>:null;})()}</div>
          <div style={{display:"flex",gap:6,marginTop:"auto"}}>
            <button onClick={()=>openPick(p)} style={{...btn(C.teal,C.tealLight),flex:1}}>🍽 {canMenus?"เลือกเมนู":"ดูเมนู"}</button>
            {canMoney&&<button onClick={()=>setForm(bpFormOf(p))} style={btn(C.blue,C.blueLight)}>แก้ไข</button>}
            {canMoney&&<button onClick={()=>del(p)} style={btn(C.red,C.redLight)}>ลบ</button>}
          </div>
        </div>;})}
      </div>}
    </>}
    {form&&<Modal title={form.id?"แก้แพ็คเกจ":"สร้างแพ็คเกจ"} onClose={()=>setForm(null)}>
      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        <div><label style={lbl}>ชื่อแพ็คเกจ</label><input value={form.name} onChange={e=>setF("name",e.target.value)} placeholder="เช่น หมูกระทะ 299" style={iS}/></div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <div><label style={lbl}>ผู้ใหญ่ ฿ / คน</label><input type="text" inputMode="decimal" value={form.adult} onChange={e=>setF("adult",bpPriceInput(e.target.value))} placeholder="0" style={{...iS,textAlign:"right",fontWeight:800}}/></div>
          <div><label style={lbl}>เด็ก ฿ / คน</label><input type="text" inputMode="decimal" value={form.child} onChange={e=>setF("child",bpPriceInput(e.target.value))} placeholder="0" style={{...iS,textAlign:"right",fontWeight:800}}/></div>
        </div>
        <div>
          <label style={lbl}>เวลาสั่งอาหาร (นาที) <span style={{fontWeight:500,color:C.ink4}}>— พิมพ์บนใบเปิดโต๊ะ "เริ่ม / หมดเวลาสั่ง" · 120 = 2 ชม. · 0 = ไม่จำกัด</span></label>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <input type="text" inputMode="numeric" value={form.minutes??""} onChange={e=>setF("minutes",String(e.target.value).replace(/[^0-9]/g,"").slice(0,4))} placeholder="120" style={{...iS,width:120,textAlign:"right",fontWeight:800}}/>
            <span style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>{String(form.minutes??"").trim()===""?"":pkgDurText(+form.minutes)}</span>
          </div>
        </div>
        <div>
          <label style={lbl}>รายการนับเพิ่ม <span style={{fontWeight:500,color:C.ink4}}>(เช่น เด็กเล็ก ผู้สูงอายุ เตาเพิ่ม · ไม่คิดเงินใส่ 0)</span></label>
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            {form.extras.map((x,i)=><div key={x.key||i} style={{display:"flex",gap:6,alignItems:"center"}}>
              <input value={x.label} onChange={e=>setX(i,"label",e.target.value)} placeholder="ชื่อรายการ" style={{...iS,flex:"2 1 120px",padding:"9px 12px",fontSize:14}}/>
              <input type="text" inputMode="decimal" value={x.price} onChange={e=>setX(i,"price",bpPriceInput(e.target.value))} placeholder="฿" style={{...iS,flex:"1 1 80px",padding:"9px 12px",fontSize:14,textAlign:"right",fontWeight:800}}/>
              <button onClick={()=>setForm(f=>({...f,extras:f.extras.filter((_,j)=>j!==i)}))} aria-label="เอารายการนี้ออก" style={{...btn(C.red,C.redLight),flexShrink:0}}>ลบ</button>
            </div>)}
            <button onClick={()=>setForm(f=>({...f,extras:[...f.extras,{key:bpNewId("t"),label:"",price:""}]}))} style={{...btn(C.ink2,C.bg),border:`1px dashed ${C.line}`,alignSelf:"flex-start"}}>+ เพิ่มรายการ</button>
          </div>
        </div>
        {shiftOpen&&<div style={{fontSize:12,color:"#92400E",fontFamily:"'Sarabun',sans-serif",lineHeight:1.6}}>⚠️ กะเปิดอยู่ — โต๊ะที่เปิดไปแล้วยังคิดราคาเดิม · โต๊ะที่เปิดใหม่ใช้ราคาใหม่</div>}
        <div style={{display:"flex",justifyContent:"flex-end",gap:10,paddingTop:12,borderTop:`1px solid ${C.line}`}}>
          <Btn v="ghost" onClick={()=>setForm(null)}>ยกเลิก</Btn>
          <Btn onClick={saveForm} loading={busy} icon={I.check}>บันทึก</Btn>
        </div>
      </div>
    </Modal>}
    {pick&&pk&&<Modal title={`🍽 เมนูในแพ็คเกจ — ${pk.name}`} onClose={()=>setPick(null)} wide>
      <div style={{fontSize:12,color:C.ink3,fontFamily:"'Sarabun',sans-serif",lineHeight:1.6,marginBottom:10}}>
        โต๊ะที่เปิดด้วยแพ็คเกจนี้เห็น<b>เฉพาะเมนูที่ติ๊ก</b> (ทั้งหน้าลูกค้าและจอพนักงาน) · เครื่องดื่ม/เบียร์ ติ๊กใส่ถ้าจะให้สั่งได้
        <br/>💰 <b>ราคาในแพ็คเกจ</b>: เมนูที่ติ๊กแล้วมีช่องราคาด้านขวา — ใส่ราคาที่จะคิดเมื่อสั่งในแพ็คเกจนี้ · <b>เว้นว่าง = ราคาเมนูปกติ</b> · ใส่ 0 = รวมในแพ็คเกจ
        <br/>มีผลกับรายการที่สั่งหลังบันทึก (รวมโต๊ะที่เปิดอยู่) · รายการที่สั่งไปแล้วไม่เปลี่ยนราคา
      </div>
      {!canMenus&&note(C.bg,C.line,C.ink3,<>🔒 ดูได้อย่างเดียว — {LOCK_MENUS}</>)}
      {stale>0&&note("#FFFBEB","#FCD34D","#92400E",<>มี {stale} เมนูในแพ็คเกจที่สาขานี้มองไม่เห็นแล้ว (ถูกปิดติ๊กหรือถูกลบ){canMenus?" — กดบันทึกแล้วจะเอาออก":""}</>)}
      <MenuPickList menus={pickable} branchId={bid} sel={pick.sel} onChange={sel=>setPick(s=>s&&({...s,sel}))} readOnly={!canMenus}
        accent={C.brand} accentLight={C.brandLight} maxHeight="46vh"
        extra={m=>{const o=(inPkgs.get(+m.id)||[]).filter(p=>p.id!==pk.id).map(p=>p.name);return o.length?`อยู่ในแพ็คเกจอื่น: ${o.join(", ")}`:null;}}
        priceCell={(m,v)=>{
          if(!v)return null;   // ยังไม่ติ๊ก = ป้ายราคาเมนูเดิม
          const base=+m.price||0,val=String((pick.prices||{})[m.id]??"");
          if(!canMoney)return val===""?null:<span style={{fontSize:12,fontWeight:800,color:C.brand,fontFamily:"'Sarabun',sans-serif"}}>{bpFm(val)} <s style={{fontWeight:500,color:C.ink4}}>{bpFm(base)}</s></span>;
          return <span style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:1}}>
            <input type="text" inputMode="decimal" value={val} placeholder={String(base)} aria-label={`ราคาในแพ็คเกจ ${m.name}`}
              onChange={e=>{const s=bpPriceInput(e.target.value);setPick(p=>p&&({...p,prices:{...(p.prices||{}),[m.id]:s}}));}}
              style={{width:90,padding:"6px 9px",borderRadius:8,border:`1.5px solid ${val!==""?C.brand:C.line}`,background:C.white,textAlign:"right",fontSize:15,fontWeight:800,color:val!==""?C.brand:C.ink,fontFamily:"'Sarabun',sans-serif",boxSizing:"border-box"}}/>
            <span style={{fontSize:10,color:C.ink4,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>{val===""?"ราคาเมนูปกติ":`ปกติ ${bpFm(base)}`}</span>
          </span>;
        }}/>
      <div style={{display:"flex",justifyContent:"flex-end",gap:10,paddingTop:12,marginTop:12,borderTop:`1px solid ${C.line}`}}>
        <Btn v="ghost" onClick={()=>setPick(null)}>{canMenus?"ยกเลิก":"ปิด"}</Btn>
        {canMenus&&<Btn onClick={savePick} loading={busy} icon={I.check}>บันทึก</Btn>}
      </div>
    </Modal>}
  </Modal>;
}

function POSShiftHistory({shifts,loading,reload,branch,user}){
  // ต้องประกาศก่อน return ก่อนกำหนดทุกตัว (กติกา hooks ของ React)
  const[busyId,setBusyId]=useState(null);
  async function reprintZ(s){
    if(busyId||!branch)return;
    // เดสก์ท็อป: เปิดหน้าต่างเปล่ารอไว้ตั้งแต่จังหวะกด ไม่งั้นโดนบล็อกป็อปอัพหลัง await
    const isHttps=typeof location!=="undefined"&&location.protocol==="https:";
    const win=isHttps?null:openPrintWindow(420,720);
    setBusyId(s.id);
    try{
      const{totals,mismatches,daySplit}=await loadShiftTotalsForReprint(s,branch.id);
      printZReport({shift:s,totals,branch,user:user||{},note:s.notes||"",reprint:true,mismatches,win,daySplit});
      if(mismatches.length)notifyDlg("⚠️ ยอดที่คำนวณวันนี้ไม่ตรงกับตอนปิดกะ "+mismatches.length+" รายการ\n\nใบที่พิมพ์ใช้ตัวเลขตอนปิดกะ และพิมพ์ส่วนที่ไม่ตรงไว้ท้ายใบแล้ว\n\n"+mismatches.join("\n"));
    }catch(e){
      if(win){try{win.close();}catch{}}
      notifyDlg("โหลดข้อมูลกะไม่สำเร็จ: "+friendlyError(e));
    }
    setBusyId(null);
  }
  // ── ส่งรูปใบปิดกะเข้าบัญชีย้อนหลัง (ฝั่งบัญชีเปิดโหมด "แนบรูปอย่างเดียว" 20 ต.ค. 69) ──
  // ใช้กับกะที่ปิดไปแล้วแต่ใบในบัญชียังไม่มีรูป (เช่น ปิดกะจากเครื่องที่ยังเปิดหน้าเว็บรุ่นเก่า / จอขึ้นเหลืองว่าไม่มีรูป)
  // ไม่ส่งยอดซ้ำ — เซิร์ฟเวอร์ขอแค่ผูกรูปกับใบที่มีอยู่ ไม่มีใบ = ไม่สร้าง · มีรูปแล้ว = ไม่ทับ
  async function sendSlipZ(s){
    if(busyId||!branch)return;
    setBusyId("slip"+s.id);
    try{
      const{totals,mismatches,daySplit}=await loadShiftTotalsForReprint(s,branch.id);
      const img=await zReportSlipImage({shift:s,totals,branch,user:user||{},note:s.notes||"",reprint:true,mismatches,daySplit});
      if(!img){notifyDlg("วาดรูปใบปิดกะไม่สำเร็จ (เครื่องนี้ทำรูปไม่ได้หรือรูปใหญ่เกิน) — ลองจากเครื่องอื่น");setBusyId(null);return;}
      const rr=await fetch("/api/sliptrack-push",{method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({kind:"pos_closing_slip",shift_id:s.id,slip_base64:img.slip_base64,slip_content_type:img.slip_content_type})});
      const j=await rr.json().catch(()=>({}));
      const rows=Array.isArray(j.results)?j.results:[];
      const lbl=(r)=>r.attach==="attached"?"แนบแล้ว":r.attach==="exists"?"มีรูปอยู่แล้ว (ไม่ทับ)":r.attach==="not_found"?"ไม่พบใบในบัญชี":("ไม่สำเร็จ"+(r.message||r.error?": "+(r.message||r.error):""));
      notifyDlg(j.not_enabled?"สาขานี้ยังไม่เปิดท่อบัญชี — ไม่มีใบให้แนบรูป"
        :j.nothing?"กะนี้ไม่มียอด จึงไม่มีใบในบัญชีให้แนบรูป"
        :rows.length?("📎 รูปใบปิดกะ #"+s.id+"\n"+rows.map(r=>(r.ok?"✅ ":"⚠️ ")+fmtD(r.business_date)+" — "+lbl(r)).join("\n"))
        :("ส่งรูปไม่สำเร็จ: "+(j.error||("ระบบตอบ "+rr.status))));
    }catch(e){notifyDlg("ส่งรูปใบปิดกะไม่สำเร็จ: "+friendlyError(e));}
    setBusyId(null);
  }
  if(loading)return <Loading text="โหลดประวัติกะ..."/>;
  if(shifts.length===0)return <div style={{textAlign:"center",padding:60,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}><Ic d={I.clock} s={48} c={C.line}/><p style={{marginTop:12}}>ยังไม่มีประวัติกะ</p></div>;
  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
      <h3 style={{fontFamily:"'Sarabun',sans-serif",fontSize:18,fontWeight:900,color:C.ink,margin:0}}>ประวัติกะ ({shifts.length})</h3>
      <Btn v="ghost" onClick={reload} icon={I.refresh} s={{padding:"7px 14px",fontSize:12}}>รีเฟรช</Btn>
    </div>
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(320px,100%),1fr))",gap:12}}>
      {shifts.map(s=>{
        const isOpen=s.status==='open';
        return <Card key={s.id} style={{padding:0,overflow:"hidden"}}>
          <div style={{padding:"10px 14px",background:isOpen?C.greenLight:C.bg,borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div style={{fontFamily:"'Sarabun',sans-serif",fontWeight:800,fontSize:14,color:C.ink}}>กะ #{s.id}</div>
            <Chip color={isOpen?"green":"gray"}>{isOpen?"เปิดอยู่":"ปิดแล้ว"}</Chip>
          </div>
          <div style={{padding:"12px 14px",fontFamily:"'Sarabun',sans-serif",fontSize:12,color:C.ink2,lineHeight:1.7}}>
            <div>👤 {s.username||'-'}</div>
            <div>🕐 เปิด: {fmtDT(s.opened_at)}</div>
            {s.closed_at&&<div>🕔 ปิด: {fmtDT(s.closed_at)}</div>}
            <div style={{marginTop:8,paddingTop:8,borderTop:`1px dashed ${C.line}`,display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,fontSize:12}}>
              <div>เริ่มต้น: <b>฿{(+s.opening_cash||0).toLocaleString()}</b></div>
              <div>บิล: <b>{s.order_count||0}</b></div>
              <div>ขาย: <b style={{color:C.brand}}>฿{(+s.total_sales||0).toLocaleString()}</b></div>
              <div>เงินสด: <b style={{color:C.green}}>฿{(+s.total_cash||0).toLocaleString()}</b></div>
              {!isOpen&&<>
                <div>ปิดที่: <b>฿{(+s.closing_cash||0).toLocaleString()}</b></div>
                <div>ส่วนต่าง: <b style={{color:s.cash_diff===0?C.green:s.cash_diff>0?C.blue:C.red}}>{+s.cash_diff>0?'+':+s.cash_diff<0?'-':''}฿{Math.abs(+s.cash_diff||0).toLocaleString()}</b></div>
              </>}
            </div>
            {s.notes&&<div style={{marginTop:8,padding:"6px 10px",background:C.yellowLight,borderRadius:7,fontSize:11,color:C.ink3}}>📝 {s.notes}</div>}
            {!isOpen&&<button onClick={()=>reprintZ(s)} disabled={!!busyId}
              style={{marginTop:10,width:"100%",padding:"10px 12px",borderRadius:10,border:`1.5px solid ${C.blue}`,background:busyId===s.id?C.blueLight:C.white,color:C.blue,cursor:busyId?"not-allowed":"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:13,fontWeight:800,opacity:busyId&&busyId!==s.id?.5:1}}>
              {busyId===s.id?"กำลังเตรียมใบปิดกะ...":"🖨 พิมพ์ใบปิดกะ (ใบพิมพ์ซ้ำ)"}
            </button>}
            {!isOpen&&(+s.total_sales||0)>0&&<button onClick={()=>sendSlipZ(s)} disabled={!!busyId}
              style={{marginTop:6,width:"100%",padding:"8px 12px",borderRadius:10,border:`1px solid ${C.line}`,background:busyId==="slip"+s.id?C.bg:C.white,color:C.ink3,cursor:busyId?"not-allowed":"pointer",fontFamily:"'Sarabun',sans-serif",fontWeight:700,fontSize:12}}>
              {busyId==="slip"+s.id?"กำลังส่งรูป...":"📎 ส่งรูปใบปิดกะเข้าบัญชี (กรณีบัญชียังไม่มีรูป)"}
            </button>}
          </div>
        </Card>;
      })}
    </div>
  </div>;
}

// Printer panel (extracted from SettingsTab for back-office)
function POSPrinterPanel({printers,reloadPrinters,branches,currentUser,menus=[],currentBranch}){
  // เลือกสาขาได้เฉพาะสาขาที่เปิดอยู่ — รายการด้านล่างกรองตามสาขาแล้ว
  // ถ้าเลือกสาขาอื่นได้ จะสร้างเสร็จแล้วหายไปจากจอทันที หาไม่เจอว่าไปอยู่ไหน
  const branchOpts=(branches||[]).filter(b=>+b.id===+((currentBranch&&currentBranch.id)||0));
  const isAdmin=posAccess(currentUser,false).admin;   // สิทธิ์ตั้งค่า หรือ จัดการ POS (pos_admin)
  // เครื่องใหม่ผูกสาขาที่เปิดอยู่เสมอ (เดิมค่าเริ่มต้น "ทุกสาขา" — ลืมเลือก = ตัวพิมพ์ทุกสาขายิงใบไป IP นี้)
  const pF0={name:"",ip:"",port:9100,description:"",type:"kitchen",branch_id:(currentBranch&&currentBranch.id)||null,active:true,conn:"ip",btName:""};
  const[pForm,setPForm]=useState(pF0);const[editPID,setEditPID]=useState(null);const[pSaving,setPSaving]=useState(false);
  const[testResults,setTestResults]=useState({});const[btScanning,setBtScanning]=useState(false);
  // Category routing state
  const[catEditP,setCatEditP]=useState(null);  // printer object being edited
  const[catSel,setCatSel]=useState(null);       // null=catch-all, [] or [names]=specific
  const[catMenuOverride,setCatMenuOverride]=useState({});  // menu_id → assigned printer_id (for override view)
  const[catSaving,setCatSaving]=useState(false);
  const[openCats,setOpenCats]=useState(()=>new Set());  // category names expanded to show per-menu checkboxes
  function toggleOpenCat(c){setOpenCats(prev=>{const n=new Set(prev);if(n.has(c))n.delete(c);else n.add(c);return n;});}
  // หมวดหมู่คุมจากครัวกลางที่เดียว ทุกสาขาเห็นชุดเดียวกัน (menuCatOf อ่านจาก menus.category)
  // สาขาไหนยังไม่ได้สร้างหมวด → ว่าง (ขึ้นข้อความให้ไปสร้างก่อน) · เครื่อง branch=null = รวมทุกสาขา
  // เครื่องพิมพ์เครื่องหนึ่งรับงานได้เฉพาะออเดอร์ของสาขาตัวเอง หมวดที่ให้ติ๊กจึงต้องเป็นหมวด
  // ที่ "สาขานั้นมีเมนูอยู่จริง" ไม่ใช่หมวดทั้งเครือ
  // ของเดิมกวาดจากเมนูทุกสาขา → เครื่องที่สาขา 8 เห็น "คุณนายแจ่วฮ้อน" ของสาขา 6 ที่ไม่มีทางพิมพ์เลย
  // และตัวเลขจำนวนเมนูก็เป็นยอดทั้งเครือ (คุณนายตื่นสาย 39) ทั้งที่สาขานั้นเห็นแค่ 6
  // ร้ายกว่านั้นคือปุ่ม "เลือกทั้งหมด" ติ๊กหมวดของสาขาอื่นติดไปด้วยแล้วบันทึกลงเครื่อง
  // เครื่องที่ยังไม่ผูกสาขา (branch_id ว่าง = ใช้ร่วมทุกสาขา) ยังเห็นครบเหมือนเดิม ไม่งั้นจะกลายเป็นตัดหมวดที่มันเคยรับ
  const branchMenus=useMemo(()=>{
    const bid=catEditP&&catEditP.branch_id;
    if(bid==null)return menus||[];
    return (menus||[]).filter(m=>menuVisibleAt(m,bid));
  },[menus,catEditP]);
  const allCategories=useMemo(()=>{
    if(!catEditP)return [];
    const s=new Set();
    branchMenus.forEach(m=>{const c0=menuCatOf(m);if(c0)s.add(c0);});
    return [...s].sort(thCmp);   // เรียงตามพยัญชนะไทย ไม่ใช่รหัสตัวอักษร (ไม่งั้น Refill เด้งไปอยู่หัวตาราง)
  },[branchMenus,catEditP]);
  // หมวดที่เครื่องนี้ติ๊กค้างไว้แต่สาขานี้ไม่มีเมนูในหมวดนั้นแล้ว — ต้องเห็น ไม่ใช่ซ่อนเงียบๆ
  // (เช่น เซตหมู สาขา 8 ติ๊ก "ยำบุฟเฟต์/เนื้อบุฟเฟต์" ของสาขา 5 ค้างไว้ ดูจากจอไม่ออกเลยว่ามีติ๊กอยู่)
  const staleCats=useMemo(()=>{
    if(!catEditP||!Array.isArray(catSel))return [];
    const live=new Set(allCategories);
    return catSel.filter(c=>!live.has(c));
  },[catSel,allCategories,catEditP]);
  // เมนูในหมวด c — นับเฉพาะเมนูที่สาขานี้เห็น ตัวเลขจะได้ตรงกับที่พิมพ์ออกจริง
  const menusInCat=(c)=>branchMenus.filter(m=>menuCatOf(m)===c);
  function openCatEdit(p){
    setCatEditP(p);
    setCatSel(p.categories===undefined||p.categories===null?null:[...p.categories]);
    // Build menu→printer override map for the menus visible
    const ov={};menus.forEach(m=>{if(m.printer_id)ov[m.id]=+m.printer_id;});
    setCatMenuOverride(ov);
    setOpenCats(new Set());
  }
  async function saveCatEdit(){
    if(!catEditP)return;
    setCatSaving(true);
    try{
      // เก็บเป็นรายการเสมอ — null คือ catch-all ซึ่งเลิกใช้แล้ว
      await api.updatePrinter(catEditP.id,{categories:catSel||[...allCategories]});
      // Save menu-level overrides
      const updates=[];
      menus.forEach(m=>{const newPid=catMenuOverride[m.id]||null;const oldPid=m.printer_id||null;if(String(newPid)!==String(oldPid))updates.push(api.updateMenu(m.id,{printer_id:newPid}));});
      await Promise.all(updates);
      await reloadPrinters();
      setCatEditP(null);
    }catch(e){alert("บันทึกไม่สำเร็จ: "+e.message);}
    setCatSaving(false);
  }
  async function testPrinter(p){
    const conn=getPConn(p);
    setTestResults(r=>({...r,[p.id]:{status:"testing"}}));
    if(conn.type==="bluetooth"){
      try{
        if(!navigator.bluetooth)throw new Error("เบราว์เซอร์ไม่รองรับ Bluetooth");
        const device=await navigator.bluetooth.requestDevice({filters:conn.btName?[{name:conn.btName}]:undefined,acceptAllDevices:!conn.btName,optionalServices:_BT_SVC});
        const server=await device.gatt.connect();await server.getPrimaryServices();device.gatt.disconnect();
        setTestResults(r=>({...r,[p.id]:{status:"ok",msg:"เชื่อมต่อ Bluetooth สำเร็จ: "+device.name}}));
      }catch(e){setTestResults(r=>({...r,[p.id]:{status:"fail",msg:e.message}}));}
      return;
    }
    // IP/Network printer: POST a real ESC-POS test page.
    // Raw thermal printers at port 9100 don't speak HTTP, so we treat AbortError after timeout
    // as success (TCP connection was accepted, bytes sent, printer printed but never replied).
    // Only TypeError "Failed to fetch" (immediate refused) is a true failure.
    const enc=new TextEncoder();
    const concat=arrs=>{const len=arrs.reduce((a,b)=>a+b.length,0);const out=new Uint8Array(len);let off=0;for(const a of arrs){out.set(a,off);off+=a.length;}return out;};
    const body=concat([
      new Uint8Array([0x1B,0x40]),                // ESC @  init
      new Uint8Array([0x1B,0x61,0x01]),           // center
      new Uint8Array([0x1B,0x21,0x30]),           // double height/width
      enc.encode("PRINTER TEST\n"),
      new Uint8Array([0x1B,0x21,0x00]),           // normal
      enc.encode("FOODCOST POS\n"),
      enc.encode((p.name||"")+"\n"),
      enc.encode(new Date().toISOString().replace("T"," ").slice(0,19)+"\n"),
      enc.encode("--------------------------------\n"),
      new Uint8Array([0x1B,0x45,0x01]),           // bold on
      enc.encode("Connection OK\n"),
      new Uint8Array([0x1B,0x45,0x00]),           // bold off
      new Uint8Array([0x0A,0x0A,0x0A,0x0A]),      // feed
      new Uint8Array([0x1D,0x56,0x42,0x00]),      // partial cut
    ]);
    const ctrl=new AbortController();const tid=setTimeout(()=>ctrl.abort(),5000);
    let connectedFast=false;
    const startedAt=Date.now();
    try{
      await fetch(`http://${p.ip}:${p.port||9100}/`,{method:"POST",mode:"no-cors",cache:"no-store",headers:{"Content-Type":"application/octet-stream"},body,signal:ctrl.signal});
      clearTimeout(tid);
      setTestResults(r=>({...r,[p.id]:{status:"ok",msg:"ส่งคำสั่งพิมพ์ทดสอบแล้ว — ตรวจที่เครื่องว่ามีกระดาษออกมาไหม"}}));
    }catch(e){
      clearTimeout(tid);
      const elapsed=Date.now()-startedAt;
      if(e.name==="AbortError"){
        // 5s timeout reached — TCP almost certainly accepted the connection (raw printer doesn't HTTP-reply)
        setTestResults(r=>({...r,[p.id]:{status:"ok",msg:"✅ ส่งคำสั่งพิมพ์แล้ว (เครื่องไม่ตอบ HTTP เป็นเรื่องปกติ) — ดูที่เครื่องว่ามีกระดาษออกมาไหม"}}));
      }else if(elapsed<300){
        // Quick TypeError = network refused
        setTestResults(r=>({...r,[p.id]:{status:"fail",msg:"เชื่อมต่อไม่ได้ — ตรวจ IP/Port หรือไฟเครื่องพิมพ์"}}));
      }else{
        setTestResults(r=>({...r,[p.id]:{status:"ok",msg:"ส่งคำสั่งไปแล้ว — ดูที่เครื่อง"}}));
      }
    }
  }
  async function scanBTPrinter(all=false){
    if(!navigator.bluetooth){alert("เบราว์เซอร์ไม่รองรับ Bluetooth ต้องใช้ Chrome/Edge");return;}
    setBtScanning(true);
    try{
      const opts=all?{acceptAllDevices:true,optionalServices:_BT_SVC}:{filters:[{namePrefix:"XP-"},{namePrefix:"Xprinter"},{namePrefix:"MTP"},{namePrefix:"MPT"},{namePrefix:"RPP"},{namePrefix:"BT Printer"},{namePrefix:"BT-Printer"},{namePrefix:"Printer"},{namePrefix:"POS"},{namePrefix:"Thermal"},{namePrefix:"SPP"},{namePrefix:"GP-"},{namePrefix:"Gprinter"},{namePrefix:"PT-"},{namePrefix:"MP-"},{namePrefix:"P80"},{namePrefix:"P58"},{namePrefix:"HOIN"},{namePrefix:"Goojprt"},{namePrefix:"GOOJPRT"},{namePrefix:"BlueTooth"},{namePrefix:"HC-"},{namePrefix:"ESC"},{namePrefix:"TP"},..._BT_SVC.map(s=>({services:[s]}))],optionalServices:_BT_SVC};
      const device=await navigator.bluetooth.requestDevice(opts);
      setPForm(f=>({...f,btName:device.name||"",conn:"bluetooth"}));
    }catch(e){
      if(e.name==="NotFoundError"&&!all){if(await confirmDlg({title:"ไม่พบเครื่องปริ้น",message:"ไม่พบอุปกรณ์ที่ตรงกับชื่อเครื่องปริ้น\nต้องการแสดงอุปกรณ์ Bluetooth ทั้งหมดไหม?",confirmLabel:"แสดงทั้งหมด",danger:false})){setBtScanning(false);scanBTPrinter(true);return;}}
      else if(e.name!=="NotFoundError"&&e.name!=="NotAllowedError")alert("เกิดข้อผิดพลาด: "+e.message);
    }
    setBtScanning(false);
  }
  async function savePrinter(){
    const isBT=pForm.conn==="bluetooth";
    if(!pForm.name||(isBT?!pForm.btName:!pForm.ip))return;
    const bid=printerSaveBranch(editPID,pForm.branch_id,currentBranch&&currentBranch.id);
    if(!editPID&&!bid){notifyDlg("ยังไม่รู้ว่าเครื่องนี้เป็นของสาขาไหน — เปิดสาขาที่จะใช้เครื่องนี้ก่อน แล้วค่อยเพิ่มเครื่องพิมพ์");return;}
    setPSaving(true);
    try{
      const d={name:pForm.name,ip:isBT?"bluetooth":pForm.ip,port:isBT?0:+pForm.port||9100,type:pForm.type,branch_id:bid,active:true,description:isBT?JSON.stringify({c:"bt",n:pForm.btName}):pForm.description};
      if(editPID)await api.updatePrinter(editPID,d);else await api.addPrinter(d);
      await reloadPrinters();setPForm(pF0);setEditPID(null);
    }catch(e){alert("บันทึกไม่สำเร็จ: "+e.message);}
    setPSaving(false);
  }
  return <div>
    <div style={{background:"linear-gradient(135deg,#0F172A 0%,#1E293B 100%)",borderRadius:16,padding:"22px 26px",marginBottom:20,display:"flex",alignItems:"center",justifyContent:"space-between",boxShadow:"0 4px 24px rgba(15,23,42,0.18)"}}>
      <div style={{display:"flex",alignItems:"center",gap:14}}>
        <div style={{width:48,height:48,background:"linear-gradient(135deg,#6366F1,#8B5CF6)",borderRadius:14,display:"flex",alignItems:"center",justifyContent:"center"}}><Ic d={I.print} s={22} c="#fff" sw={1.5}/></div>
        <div>
          <h2 style={{fontFamily:"'Sarabun',sans-serif",fontSize:20,fontWeight:900,color:"#F8FAFC",margin:0}}>เครื่องพิมพ์</h2>
          <p style={{fontSize:12,color:"rgba(255,255,255,0.45)",margin:"3px 0 0",fontFamily:"'Sarabun',sans-serif"}}>Network/Bluetooth Printer — Xprinter / ESC-POS 80mm</p>
        </div>
      </div>
      <div style={{display:"flex",gap:8}}>
        {[{label:"เครื่องพิมพ์ทั้งหมด",count:printers.length,color:"#6366F1"}].map(s=><div key={s.label} style={{textAlign:"center",background:"rgba(255,255,255,0.07)",borderRadius:10,padding:"7px 14px",border:"1px solid rgba(255,255,255,0.1)"}}>
          <div style={{fontSize:18,fontWeight:900,color:s.color,lineHeight:1}}>{s.count}</div>
          <div style={{fontSize:10,color:"rgba(255,255,255,0.45)",fontFamily:"'Sarabun',sans-serif",marginTop:2}}>{s.label}</div>
        </div>)}
      </div>
    </div>
    {isAdmin&&<div style={{background:C.white,borderRadius:14,border:`1px solid ${C.line}`,marginBottom:20,overflow:"hidden",boxShadow:"0 2px 12px rgba(0,0,0,0.05)"}}>
      <div style={{padding:"14px 22px",borderBottom:`1px solid ${C.line}`,background:editPID?"#FFF7ED":"#F8FAFF",display:"flex",alignItems:"center",gap:10}}>
        <div style={{width:28,height:28,background:editPID?"#F59E0B22":"#6366F122",borderRadius:8,display:"flex",alignItems:"center",justifyContent:"center"}}><Ic d={editPID?I.pencil:I.plus} s={13} c={editPID?"#F59E0B":"#6366F1"}/></div>
        <span style={{fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:800,color:C.ink}}>{editPID?"แก้ไขเครื่องพิมพ์":"เพิ่มเครื่องพิมพ์ใหม่"}</span>
        {editPID&&<Chip color="yellow">กำลังแก้ไข</Chip>}
      </div>
      <div style={{padding:"18px 22px"}}>
        <div style={{display:"grid",gridTemplateColumns:"2fr 1.4fr 1fr",gap:12,marginBottom:12}}>
          <Inp label="ชื่อเครื่องพิมพ์ *" value={pForm.name} onChange={e=>setPForm(f=>({...f,name:e.target.value}))} placeholder="เช่น ครัวหลัก, บาร์"/>
          <div>
            <label style={{display:"block",fontSize:13,fontWeight:600,color:C.ink2,marginBottom:6,fontFamily:"'Sarabun',sans-serif"}}>ประเภทการเชื่อมต่อ</label>
            <div style={{display:"flex",gap:0,borderRadius:10,overflow:"hidden",border:`1.5px solid ${C.line}`}}>
              {[{v:"ip",label:"🌐 IP"},{v:"bluetooth",label:"📶 BT"}].map(o=><button key={o.v} onClick={()=>setPForm(f=>({...f,conn:o.v}))} style={{flex:1,padding:"9px 0",border:"none",background:pForm.conn===o.v?`linear-gradient(135deg,${C.brand},${C.brandDark})`:C.white,color:pForm.conn===o.v?C.white:C.ink3,fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:700,cursor:"pointer"}}>{o.label}</button>)}
            </div>
          </div>
                    <div><label style={{display:"block",fontSize:13,fontWeight:600,color:C.ink2,marginBottom:6,fontFamily:"'Sarabun',sans-serif"}}>สาขา</label><select value={editPID?(pForm.branch_id||""):((currentBranch&&currentBranch.id)||"")} onChange={e=>setPForm(f=>({...f,branch_id:e.target.value?+e.target.value:null}))} style={{...iS,appearance:"none"}}>{editPID&&pForm.branch_id==null&&<option value="">ทุกสาขา (แถวเดิม)</option>}{branchOpts.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></div>
        </div>
        {pForm.conn==="ip"?<div style={{display:"grid",gridTemplateColumns:"1fr auto auto",gap:12,marginBottom:12,alignItems:"flex-end"}}>
          <Inp label="IP Address *" value={pForm.ip} onChange={e=>setPForm(f=>({...f,ip:e.target.value}))} placeholder="192.168.1.100"/>
          <Inp label="Port" type="number" value={pForm.port} onChange={e=>setPForm(f=>({...f,port:+e.target.value}))} placeholder="9100" style={{width:90}}/>
          <Inp label="หมายเหตุ" value={pForm.description} onChange={e=>setPForm(f=>({...f,description:e.target.value}))} placeholder="ครัวหลัก..."/>
        </div>:<div style={{marginBottom:12,background:C.bg,borderRadius:10,padding:"14px 16px",border:`1.5px dashed ${C.brand}44`}}>
          <div style={{fontSize:12,fontWeight:700,color:C.ink3,marginBottom:8,fontFamily:"'Sarabun',sans-serif"}}>อุปกรณ์ Bluetooth</div>
          {pForm.btName?<div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
            <div style={{width:34,height:34,background:C.brandLight,borderRadius:9,display:"flex",alignItems:"center",justifyContent:"center",fontSize:17}}>📶</div>
            <div><div style={{fontWeight:800,fontSize:13,color:C.ink,fontFamily:"'Sarabun',sans-serif"}}>{pForm.btName}</div><div style={{fontSize:11,color:C.green,fontWeight:600}}>✅ จับคู่แล้ว</div></div>
            <button onClick={()=>setPForm(f=>({...f,btName:""}))} style={{marginLeft:"auto",background:C.redLight,border:"none",borderRadius:7,padding:"4px 9px",cursor:"pointer",color:C.red,fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>ล้าง</button>
          </div>:<div style={{color:C.ink4,fontSize:12,fontFamily:"'Sarabun',sans-serif",marginBottom:8}}>ยังไม่ได้จับคู่อุปกรณ์</div>}
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <button onClick={()=>scanBTPrinter(false)} disabled={btScanning} style={{background:`linear-gradient(135deg,${C.brand},${C.brandDark})`,color:C.white,border:"none",borderRadius:9,padding:"8px 16px",cursor:btScanning?"not-allowed":"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:700,opacity:btScanning?.6:1,display:"flex",alignItems:"center",gap:6}}>📶 {btScanning?"กำลังสแกน...":"สแกนเครื่องปริ้น"}</button>
            <button onClick={()=>scanBTPrinter(true)} disabled={btScanning} style={{background:C.white,color:C.ink2,border:`1.5px solid ${C.line}`,borderRadius:9,padding:"8px 14px",cursor:btScanning?"not-allowed":"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:600,opacity:btScanning?.6:1}}>🔍 แสดงทั้งหมด</button>
          </div>
        </div>}
        <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
          {editPID&&<Btn v="ghost" onClick={()=>{setPForm(pF0);setEditPID(null);}}>ยกเลิก</Btn>}
          <Btn onClick={savePrinter} icon={I.check} disabled={!pForm.name||(pForm.conn==="bluetooth"?!pForm.btName:!pForm.ip)} loading={pSaving} s={{minWidth:160}}>{editPID?"บันทึกการแก้ไข":"เพิ่มเครื่องพิมพ์"}</Btn>
        </div>
      </div>
    </div>}
    <div style={{marginBottom:14,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
      <h3 style={{fontFamily:"'Sarabun',sans-serif",fontSize:15,fontWeight:800,color:C.ink,margin:0}}>เครื่องพิมพ์ที่เชื่อมต่อ <span style={{fontSize:12,fontWeight:600,color:C.ink4}}>({printers.length} เครื่อง)</span></h3>
      <div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",background:C.blueLight,padding:"5px 12px",borderRadius:18,border:`1px solid #BFDBFE`}}>💡 ไปที่หน้า <b>เมนู</b> เพื่อกำหนดเครื่องพิมพ์ให้แต่ละเมนู</div>
    </div>
    {printers.length===0?<div style={{background:C.white,border:`2px dashed ${C.line}`,borderRadius:14,padding:"50px 20px",textAlign:"center"}}>
      <div style={{width:56,height:56,background:C.lineLight,borderRadius:18,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 12px"}}><Ic d={I.print} s={26} c={C.ink4}/></div>
      <div style={{fontSize:15,fontWeight:700,color:C.ink3,fontFamily:"'Sarabun',sans-serif",marginBottom:6}}>ยังไม่มีเครื่องพิมพ์</div>
      <div style={{fontSize:12,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>เพิ่มเครื่องพิมพ์แรกของคุณด้านบน</div>
    </div>:<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(320px,100%),1fr))",gap:14}}>
      {printers.map(p=>{
        const typeConf={label:getPConn(p).type==="bluetooth"?"บลูทูธ":"เครือข่าย",emoji:"🖨️",color:C.ink3,bg:C.bg,border:C.line};
        return <div key={p.id} style={{background:C.white,border:`1px solid ${C.line}`,borderRadius:14,overflow:"hidden",boxShadow:"0 2px 8px rgba(0,0,0,0.05)"}}>
          <div style={{padding:"14px 18px 12px",borderBottom:`1px solid ${C.line}`,background:`linear-gradient(135deg,${typeConf.bg},${C.white})`,display:"flex",alignItems:"flex-start",gap:12}}>
            <div style={{width:42,height:42,background:typeConf.bg,border:`2px solid ${typeConf.border}`,borderRadius:12,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>{typeConf.emoji}</div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontWeight:800,fontSize:14,color:C.ink,fontFamily:"'Sarabun',sans-serif",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",marginBottom:4}}>{p.name}</div>
              <div style={{display:"inline-flex",alignItems:"center",gap:5,background:typeConf.bg,border:`1px solid ${typeConf.border}`,borderRadius:18,padding:"2px 10px"}}>
                <span style={{fontSize:11,fontWeight:700,color:typeConf.color,fontFamily:"'Sarabun',sans-serif"}}>{typeConf.label}</span>
              </div>
            </div>
            {isAdmin&&<div style={{display:"flex",gap:5,flexShrink:0}}>
              <button onClick={()=>openCatEdit(p)} title="หมวดหมู่ที่รับผิดชอบ" style={{background:"#FEF3C7",border:`1px solid #FDE68A`,borderRadius:8,padding:"5px 8px",cursor:"pointer",display:"flex",alignItems:"center",gap:4}}><span style={{fontSize:13}}>🍳</span><span style={{fontSize:11,color:"#92400E",fontFamily:"'Sarabun',sans-serif",fontWeight:700}}>หมวด</span></button>
              <button onClick={()=>{const pc=getPConn(p);setPForm({name:p.name,ip:pc.type==="bluetooth"?"":p.ip,port:p.port||9100,description:pc.type==="bluetooth"?"":p.description||"",type:p.type||"kitchen",branch_id:p.branch_id,active:p.active,conn:pc.type,btName:pc.btName||""});setEditPID(p.id);}} title="แก้ไข" style={{background:C.blueLight,border:`1px solid #BFDBFE`,borderRadius:8,padding:"5px 8px",cursor:"pointer",display:"flex",alignItems:"center",gap:4}}><Ic d={I.pencil} s={12} c={C.blue}/><span style={{fontSize:11,color:C.blue,fontFamily:"'Sarabun',sans-serif",fontWeight:700}}>แก้</span></button>
              <button onClick={async()=>{if(!await confirmDlg({title:"ลบเครื่องปริ้น",message:`ต้องการลบ "${p.name}" ใช่หรือไม่?`}))return;try{await api.deletePrinter(p.id);await reloadPrinters();}catch{alert("ลบไม่สำเร็จ");}}} title="ลบ" style={{background:C.redLight,border:`1px solid #FECACA`,borderRadius:8,padding:"5px 8px",cursor:"pointer",display:"flex",alignItems:"center",gap:4}}><Ic d={I.trash} s={12} c={C.red}/><span style={{fontSize:11,color:C.red,fontFamily:"'Sarabun',sans-serif",fontWeight:700}}>ลบ</span></button>
            </div>}
          </div>
          <div style={{padding:"12px 18px"}}>
            {(()=>{const tr=testResults[p.id];const dotColor=!tr?C.ink3:tr.status==="testing"?C.yellow:tr.status==="ok"?C.green:C.red;const pc=getPConn(p);const isBT=pc.type==="bluetooth";return<div style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",background:"#F8FAFC",borderRadius:9,border:`1px solid ${tr?.status==="ok"?C.green:tr?.status==="fail"?C.red:C.line}`}}>
              <div style={{width:9,height:9,borderRadius:"50%",background:dotColor,boxShadow:`0 0 6px ${dotColor}88`,flexShrink:0,animation:tr?.status==="testing"?"pulse 1s infinite":"none"}}/>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",alignItems:"center",gap:6}}>
                  <span style={{fontSize:10,background:isBT?C.brandLight:C.blueLight,color:isBT?C.brand:C.blue,border:`1px solid ${isBT?C.brandBorder:"#BFDBFE"}`,borderRadius:5,padding:"1px 6px",fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>{isBT?"📶 BT":"🌐 IP"}</span>
                  <span style={{fontSize:12,fontWeight:800,color:C.ink,fontFamily:"monospace"}}>{isBT?pc.btName||"—":`${p.ip}:${p.port||9100}`}</span>
                </div>
                <div style={{fontSize:10,color:tr?.status==="ok"?C.green:tr?.status==="fail"?C.red:C.ink4,fontFamily:"'Sarabun',sans-serif",fontWeight:tr?600:400,marginTop:1}}>
                  {!tr&&(isBT?"กดทดสอบเพื่อจับคู่":"IP : Port")}
                  {tr?.status==="testing"&&"⏳ กำลังทดสอบ..."}
                  {tr?.status==="ok"&&`✅ ${tr.msg}`}
                  {tr?.status==="fail"&&`❌ ${tr.msg}`}
                </div>
              </div>
              <button onClick={()=>testPrinter(p)} disabled={testResults[p.id]?.status==="testing"} style={{padding:"5px 12px",borderRadius:7,border:`1.5px solid ${C.brand}`,background:testResults[p.id]?.status==="testing"?C.lineLight:C.brandLight,color:C.brand,cursor:testResults[p.id]?.status==="testing"?"not-allowed":"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>{testResults[p.id]?.status==="testing"?"...":"🔌 ทดสอบ"}</button>
            </div>;})()}
            {/* Categories badge */}
            {(()=>{const cats=p.categories;const overrideCount=menus.filter(m=>+m.printer_id===p.id).length;return <div style={{marginTop:6,padding:"7px 11px",borderRadius:8,background:cats===null||cats===undefined?C.greenLight:cats.length===0?C.lineLight:"#FEF3C7",border:`1px solid ${cats===null||cats===undefined?"#86EFAC":cats.length===0?C.line:"#FDE68A"}`,fontSize:11,fontFamily:"'Sarabun',sans-serif",color:cats===null||cats===undefined?C.green:cats.length===0?C.ink4:"#92400E",display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
              <span style={{fontWeight:800}}>🍳 รับผิดชอบ:</span>
              <span style={{fontWeight:600}}>{cats===null||cats===undefined?"ทุกหมวด (ค่าเดิม — เปิดตั้งค่าแล้วกดบันทึกเพื่อระบุหมวด)":cats.length===0?"ไม่รับงานอัตโนมัติ":cats.join(", ")}</span>
              {overrideCount>0&&<span style={{marginLeft:"auto",background:C.purpleLight,color:C.purple,padding:"1px 8px",borderRadius:10,fontSize:10,fontWeight:700}}>+{overrideCount} เมนู (override)</span>}
            </div>;})()}
            {p.branch_id&&(branches||[]).find(b=>b.id===p.branch_id)&&<div style={{fontSize:11,color:C.ink3,fontFamily:"'Sarabun',sans-serif",marginTop:6,display:"flex",alignItems:"center",gap:5}}><Ic d={I.branch} s={12} c={C.ink4}/>สาขา: <b>{branches.find(b=>b.id===p.branch_id)?.name}</b></div>}
            {!p.branch_id&&<div style={{fontSize:11,color:C.teal,fontFamily:"'Sarabun',sans-serif",marginTop:6,display:"flex",alignItems:"center",gap:5}}><Ic d={I.shop} s={12} c={C.teal}/>ใช้งานได้ทุกสาขา</div>}
          </div>
        </div>;
      })}
    </div>}
    {/* Category routing modal */}
    {catEditP&&<Modal title={`🍳 หมวดหมู่ที่รับผิดชอบ — ${catEditP.name}`} onClose={()=>setCatEditP(null)} extraWide>
      <div>
        {/* Header: title + quick actions */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8,flexWrap:"wrap",gap:8}}>
          <div style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>📂 หมวดหมู่</div>
          <div style={{display:"flex",gap:6}}>
            <button onClick={()=>setCatSel([...allCategories])} style={{padding:"4px 10px",borderRadius:7,border:`1px solid ${C.line}`,background:C.white,color:C.ink3,cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>เลือกทั้งหมด</button>
            <button onClick={()=>setCatSel([])} style={{padding:"4px 10px",borderRadius:7,border:`1px solid ${C.line}`,background:C.white,color:C.ink3,cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>ล้าง</button>
          </div>
        </div>
        {allCategories.length===0
            ?<div style={{padding:30,textAlign:"center",color:C.ink4,fontSize:13,fontFamily:"'Sarabun',sans-serif"}}>ยังไม่มีหมวดหมู่เมนู — เพิ่มหมวดในแท็บ "เมนู" ก่อน</div>
            :<>
              {staleCats.length>0&&<div style={{marginBottom:8,padding:"9px 12px",borderRadius:10,background:"#FEF3C7",border:"1px solid #FDE68A",fontFamily:"'Sarabun',sans-serif"}}>
                <div style={{fontSize:12,fontWeight:800,color:"#92400E",marginBottom:5}}>⚠️ ติ๊กค้างไว้ {staleCats.length} หมวด ที่สาขานี้ไม่มีเมนูแล้ว</div>
                <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                  {staleCats.map(c=><button key={c} onClick={()=>setCatSel(prev=>(prev||[]).filter(x=>x!==c))}
                    style={{padding:"3px 9px",borderRadius:14,border:"1px solid #FDE68A",background:C.white,color:"#92400E",cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>{c} ✕</button>)}
                </div>
                <div style={{fontSize:10.5,color:"#92400E",marginTop:5,opacity:.85}}>กดที่หมวดเพื่อเอาออก แล้วกดบันทึก · ไม่เอาออกก็ไม่มีผลอะไร แค่ค้างอยู่เฉยๆ</div>
              </div>}
              <div style={{display:"flex",flexDirection:"column",gap:8,maxHeight:"58vh",overflowY:"auto",paddingRight:2}}>
                {allCategories.map(c=>{
                  // catSel เป็น null = เครื่องเก่าที่เคยเป็น catch-all → ถือว่าติ๊กครบ
                  // (ตรงกับที่มันทำอยู่จริง) · [] = ล้างแล้ว ต้องไม่กลายเป็นครบ
                  const has=(catSel||allCategories).includes(c);
                  const catMenus=menusInCat(c);
                  const isOpen=openCats.has(c);
                  const pinnedHereCount=catMenus.filter(m=>{const cur=catMenuOverride[m.id];return cur!=null&&+cur===+catEditP.id;}).length;
                  // ติ๊กครบทุกเมนู → หัวหมวดติ๊กอัตโนมัติ (รู้ว่าเลือกครบทั้งหมวด) · ติ๊กบางส่วน → ขีดครึ่ง (–)
                  const allHere=catMenus.length>0&&pinnedHereCount===catMenus.length;const checked=has||allHere;const indet=!checked&&pinnedHereCount>0;
                  const toggleCatMaster=()=>{if(checked){setCatSel(prev=>{const cur=prev===null?allCategories.slice():prev;return cur.filter(x=>x!==c);});setCatMenuOverride(prev=>{const n={...prev};catMenus.forEach(m=>{if(n[m.id]!=null&&+n[m.id]===+catEditP.id)n[m.id]=null;});return n;});}else{setCatSel(prev=>{const cur=prev===null?allCategories.slice():prev;return cur.includes(c)?cur:[...cur,c];});}};
                  return <div key={c} style={{border:`1.5px solid ${checked?C.brandBorder:(indet?`${C.brand}66`:C.line)}`,borderRadius:10,overflow:"hidden",background:checked?C.brandLight:C.white,transition:"all .15s",flexShrink:0}}>
                    {/* Category header */}
                    <div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px"}}>
                      <input type="checkbox" checked={checked} ref={el=>{if(el)el.indeterminate=indet;}} onChange={toggleCatMaster} style={{accentColor:C.brand,width:17,height:17,cursor:"pointer",flexShrink:0}}/>
                      <div style={{flex:1,minWidth:0,cursor:"pointer"}} onClick={()=>toggleOpenCat(c)}>
                        <div style={{fontSize:14,fontFamily:"'Sarabun',sans-serif",fontWeight:checked?800:600,color:checked?C.brand:C.ink2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{c}</div>
                        <div style={{fontSize:10.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>{catMenus.length} เมนู{allHere?" · ✓ เลือกครบทั้งหมวด":pinnedHereCount>0?` · 📌 ปักหมุดเครื่องนี้ ${pinnedHereCount}`:""}</div>
                      </div>
                      <button onClick={()=>toggleOpenCat(c)} style={{display:"flex",alignItems:"center",gap:5,background:isOpen?C.brand:C.white,color:isOpen?C.white:C.ink3,border:`1px solid ${isOpen?C.brand:C.line}`,borderRadius:8,padding:"5px 10px",cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap",flexShrink:0}}>
                        <span style={{fontSize:9}}>{isOpen?"▼":"▶"}</span> ระบุรายเมนู
                      </button>
                    </div>
                    {/* Expanded: per-menu checkboxes — ติ๊กเพื่อปักหมุดเมนูให้ออกเครื่องนี้ */}
                    {isOpen&&<div style={{borderTop:`1px dashed ${C.line}`,padding:"10px 12px",background:C.white}}>
                      {catMenus.length===0
                        ?<div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",textAlign:"center",padding:8}}>ไม่มีเมนูในหมวดนี้</div>
                        :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(min(240px,100%),1fr))",gap:6}}>
                          {catMenus.map(m=>{
                            const cur=catMenuOverride[m.id];
                            const pinnedHere=cur!=null&&+cur===+catEditP.id;
                            const pinnedOther=cur!=null&&+cur!==+catEditP.id;
                            const otherName=pinnedOther?(printers.find(pr=>+pr.id===+cur)?.name||"เครื่องอื่น"):"";
                            return <label key={m.id} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 10px",borderRadius:8,cursor:"pointer",background:pinnedHere?C.brandLight:C.bg,border:`1px solid ${pinnedHere?C.brandBorder:C.line}`,transition:"all .12s"}}>
                              <input type="checkbox" checked={pinnedHere} onChange={()=>setCatMenuOverride(prev=>({...prev,[m.id]:pinnedHere?null:catEditP.id}))} style={{accentColor:C.brand,width:15,height:15,cursor:"pointer",flexShrink:0}}/>
                              <div style={{flex:1,minWidth:0}}>
                                <div style={{fontSize:12.5,fontFamily:"'Sarabun',sans-serif",fontWeight:pinnedHere?800:600,color:pinnedHere?C.brand:C.ink2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.name}</div>
                                {pinnedOther&&<div style={{fontSize:9.5,color:"#B45309",fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>📌 ปักหมุดที่ {otherName}</div>}
                              </div>
                            </label>;
                          })}
                        </div>}
                    </div>}
                  </div>;
                })}
              </div>
            </>}
      </div>
      <div style={{display:"flex",justifyContent:"flex-end",gap:8,paddingTop:14,borderTop:`1px solid ${C.line}`,marginTop:14}}>
        <Btn v="ghost" onClick={()=>setCatEditP(null)}>ยกเลิก</Btn>
        <Btn onClick={saveCatEdit} loading={catSaving} icon={I.check}>บันทึก</Btn>
      </div>
    </Modal>}
  </div>;
}

// ══════════════════════════════════════════════════════
// ── POS SALE MODE (โหมดขายหน้าร้าน) ────────────────────
// ══════════════════════════════════════════════════════
// ── ปุ่ม "พิมพ์ไม่สำเร็จ" (ข้างปุ่มรายงาน) ──────────────────────────────────
// กด "รีปริ้น" = ติ๊กเวลาไว้ที่รายการนั้น → ตัวพิมพ์พิมพ์ให้รอบถัดไป (~5 วิ) เป็นใบชนิดเดิม
// (ใบสั่งอาหารที่ไม่ออก = พิมพ์เป็นใบสั่งอาหารปกติ ห้ามติดป้าย "พิมพ์ซ้ำ" — ครัวยังไม่เคยได้ใบนี้)
// ออกจริง = ตัวพิมพ์ลบออกเอง ปุ่มหายเอง · ไม่ออก = คงไว้ ปลดติ๊กให้กดใหม่ได้
const PRINT_RETRY_TTL=10*60*1000;   // ต้องเท่ากับ RETRY_TTL ใน print-agent.js — ติ๊กเก่ากว่านี้ตัวพิมพ์ไม่พิมพ์ย้อนหลัง
// อ่านของล่าสุดก่อนเขียนเสมอ — ตัวพิมพ์เขียนช่องเดียวกันอยู่ตลอด (สถานะเครื่อง/รายการไม่ออก)
async function editPrintFail(holderId,fn){
  const all=await api.getAllPrinters();
  const p=(all||[]).find(x=>+x.id===+holderId);if(!p)return false;
  let d={};try{d=JSON.parse(p.description||"{}");}catch{}
  const next=fn(Array.isArray(d.failed)?d.failed:[]);if(!next)return false;
  d.failed=next;
  await api.updatePrinter(p.id,{description:JSON.stringify(d)});
  return true;
}
// ติ๊กเฉพาะรายการที่ขอ · ไม่เจอรายการ (ตัวพิมพ์เพิ่งพิมพ์ออกแล้วลบไป) = ไม่เขียนอะไร
function markPrintRetry(list,failId,ks,now){
  const f=list.find(x=>x&&x.id===failId);if(!f||!Array.isArray(f.items))return null;
  const want=new Set((ks||[]).map(String));let hit=0;
  f.items=f.items.map(it=>{if(it&&want.has(String(it.k))){hit++;return{...it,r:now};}return it;});
  return hit?list:null;
}
const printRetryWaiting=(it,now)=>!!(it&&it.r&&now-(+it.r||0)<PRINT_RETRY_TTL);
const samePrintFail=(a,b)=>!!(a&&b&&(b.id?a.id===b.id:(!a.id&&a.at===b.at&&String(a.orderId)===String(b.orderId))));
// ── แถบสถานะการพิมพ์บนจอขาย ─────────────────────────────────────────────
// เหตุจริง 10 ต.ค. 69 (The River): ใบครัว/ใบเสร็จไม่ออกครึ่งวัน แต่จอขายไม่บอกอะไร ทุกปุ่มขึ้น ✅
// ขึ้นเฉพาะตอนมีปัญหา (ปกติไม่กินที่จอ): ตัวพิมพ์ไม่ตอบ/ไม่เคยเต้น · ตัวพิมพ์ 2 เครื่องชนกัน · เครื่องพิมพ์ออฟไลน์
// · ใบที่ไม่มีเครื่องรับ (orphan) · ใบไม่ออกใน 20 นาทีล่าสุด — ทุกแถวเป็นแดง
// ค่า on ของเครื่องเชื่อได้เฉพาะตอนตัวพิมพ์ยังหายใจ (agentSeen) — ตัวพิมพ์ดับ = ค่า on ค้างจากรอบสุดท้าย
const PRINT_RECENT_MS=20*60*1000;
function PrintHealthStrip({printers,failPrinters,branchId,onOpenFails,orders,who}){
  const[,setTick]=useState(0);
  useEffect(()=>{const t=setInterval(()=>setTick(x=>x+1),30000);return()=>clearInterval(t);},[]);   // หน้าต่าง 20 นาที/นาทีที่ไม่ตอบ เดินเองแม้ข้อมูลไม่เปลี่ยน
  // กดรับทราบ/พิมพ์ซ้ำ (ที่แถบนี้หรือปุ่ม 🖨 ในจอโต๊ะ) = แถบหายทันที ไม่ต้องรอรอบ 30 วิ
  useEffect(()=>{const f=()=>setTick(x=>x+1);try{window.addEventListener(ORPH_ACK_EVT,f);}catch{}return()=>{try{window.removeEventListener(ORPH_ACK_EVT,f);}catch{}};},[]);
  const[orphBusy,setOrphBusy]=useState(null);
  // พิมพ์ซ้ำบรรทัดที่ไม่ออก (ตั้งเครื่องแล้ว) ตรงจากแถบ — ทางเดียวกับปุ่ม 🖨 ในจอโต๊ะ (ส่งทุกเครื่องที่รับหมวดนั้น)
  async function reprintOrph(o){
    if(!o||!o.line||orphBusy)return;
    setOrphBusy(o.key);
    try{
      const r=await agentPrintItems([{...o.line}],o.table||"-",branchId,{bill:o.orderId??null,by:who||null,kind:"reprint"});
      if(r&&r.sent){orphAck(branchId,[o.key]);posToast(`🔁 ส่งพิมพ์ซ้ำ ${o.name}${o.table?" โต๊ะ "+o.table:""} ไปครัวแล้ว — ไม่ออกใน 10 วิ ดูปุ่ม พิมพ์ไม่สำเร็จ`,"ok",7000);}
      else posToast("⚠️ ยังไม่มีเครื่องพิมพ์รับเมนูนี้ — ตั้งที่ 🖨 → กำหนดการพิมพ์","warn",7000);
    }catch(e){notifyDlg("ส่งคำสั่งพิมพ์ไม่สำเร็จ: "+friendlyError(e));}
    setOrphBusy(null);
  }
  // รายชื่อเครื่องพิมพ์มาจากรอบดึง 60 วิ (หยุดตอนสลับแท็บ) — ตัดสินว่า "ตัวพิมพ์ไม่ตอบ" จากอายุสัญญาณ ณ ตอนที่ได้ข้อมูลมา
  // ไม่ใช่ ณ ตอนนี้ ไม่งั้นกลับมาจากแท็บอื่นแล้วขึ้นแดงหลอกจนกว่ารอบดึงจะมาถึง · ข้อมูลเก่าเกิน 2.5 นาที = ไม่พูดอะไรเรื่องเครื่อง
  const gotAt=useMemo(()=>Date.now(),[printers]);
  // จำค่า agentDev ล่าสุดของแต่ละแถว — ใช้ข้อมูลที่แถบได้อยู่แล้ว (รอบ 60 วิ + รอบรายการค้าง 6 วิ) ไม่ถามฐานเพิ่ม
  const devHistRef=useRef(new Map());
  useMemo(()=>{trackAgentDev(devHistRef.current,printersAt([...(printers||[]),...(failPrinters||[])],branchId),Date.now());},[printers,failPrinters,branchId]);
  const now=Date.now();
  const all=printersAt(printers,branchId);
  const mine=all.filter(p=>p&&p.active!==false&&p.ip&&getPConn(p).type!=="bluetooth");
  if(!mine.length)return null;
  const fresh=now-gotAt<150000;
  const hh=agentHealth(all,branchId);
  const h=!fresh||!hh.seen?{state:"unknown"}:{...hh,state:(gotAt-hh.seen)>120000?"down":"ok",ageSec:Math.round((now-hh.seen)/1000)};
  // มีเครื่องพิมพ์แต่ไม่เคยได้สัญญาณจากตัวพิมพ์เลย (สาขาใหม่ยังไม่ได้ติดตั้ง/ไม่เคยเปิด) — เดิมเงียบ ทุกอย่างดูปกติ
  const never=fresh&&!hh.seen;
  const off=h.state==="ok"?mine.filter(p=>{try{return JSON.parse(p.description||"{}").on===0;}catch{return false;}}):[];
  const acked=orphAcked(branchId);
  const orphs=orphanTicketsOf(all,branchId,orders,now,PRINT_RECENT_MS).filter(o=>!acked.has(o.key));
  const fight=agentFight(devHistRef.current,now);
  const recent=printFailList(failPrinters).filter(f=>now-(+f.at||0)<PRINT_RECENT_MS);
  const last=recent[recent.length-1];
  const lastErr=last&&Array.isArray(last.errs)?last.errs[0]:null;
  const rows=[];
  if(never)rows.push({c:C.red,bg:C.redLight,t:"⛔ ยังไม่เคยได้สัญญาณจากโปรแกรมตัวพิมพ์ของสาขานี้ — ใบครัว/ใบเสร็จจะไม่ออกเลย",s:"เปิดโปรแกรมตัวพิมพ์ที่มือถือของร้าน · ต่อ Wi-Fi ร้าน · เสียบชาร์จ แล้วรอสักครู่"});
  if(h.state==="down")rows.push({c:C.red,bg:C.redLight,t:`⛔ โปรแกรมตัวพิมพ์ที่ร้านไม่ตอบมา ${Math.max(1,Math.round((h.ageSec||0)/60))} นาที — ใบครัว/ใบเสร็จจะไม่ออกเลย`,s:"เช็คเครื่องที่รันตัวพิมพ์: เปิดอยู่ไหม · ต่อ Wi-Fi ร้าน · เสียบชาร์จ"});
  if(fight)rows.push({c:C.red,bg:C.redLight,t:"⛔ มีตัวพิมพ์ 2 เครื่องทำงานพร้อมกัน — ใบครัวจะออกซ้ำ",s:"ปิดโปรแกรมตัวพิมพ์ให้เหลือเครื่องเดียว (เครื่องสำรองต้องปิดไว้)"});
  if(off.length)rows.push({c:C.red,bg:C.redLight,t:`🔴 เครื่องพิมพ์ ${off.map(p=>p.name).join(" · ")} ไม่ตอบ — ใบที่ส่งเข้าเครื่องนี้จะไม่ออก`,s:"เช็คไฟ · กระดาษ · สายแลน/Wi-Fi ของเครื่อง แล้วรอจุดเขียว"});
  // ใบครัวที่ไม่มีเครื่องรับ — ทีละรายการ: เมนู · โต๊ะ · เวลา · ตอนนี้ตั้งเครื่องแล้วหรือยัง
  //   ยังไม่มีเครื่องรับ = แดง บอกหมวดที่ต้องติ๊ก · ตั้งแล้ว = ส้ม "สั่งก่อนตั้งเครื่อง ใบยังไม่ออก" + ปุ่มพิมพ์ซ้ำ
  for(const o of orphs){
    const at=`${o.table?"โต๊ะ "+o.table+" · ":""}สั่ง ${pkgTimeOf(o.at)} น.`;
    if(o.fixed)rows.push({c:"#B45309",bg:"#FFFBEB",t:`🟠 ใบครัวยังไม่ออก: ${o.name} (${at})`,s:`ตอนสั่งยังไม่มีเครื่องพิมพ์รับหมวด "${o.category||"-"}" — ตอนนี้ตั้งแล้ว กดพิมพ์ซ้ำให้ครัว (ครัวทำแล้ว = กดรับทราบ)`,orph:o});
    else rows.push({c:C.red,bg:C.redLight,t:`🔴 ใบครัวไม่ออก: ${o.name} (${at})`,
      s:o.line?`ยังไม่มีเครื่องพิมพ์รับหมวด "${o.category||"ไม่มีหมวด"}" — บอกครัวเอง แล้วติ๊กหมวดนี้ใน 🖨 → กำหนดการพิมพ์`:"ไม่มีเครื่องพิมพ์รับ — บอกครัวเอง แล้วติ๊กหมวดของเมนูนี้ใน 🖨 → กำหนดการพิมพ์",orph:o});
  }
  if(recent.length)rows.push({c:C.red,bg:C.redLight,t:`⚠️ ใบไม่ออก ${recent.reduce((s,f)=>s+printFailWeight(f),0)} ใบใน 20 นาทีล่าสุด${last&&Array.isArray(last.pnames)&&last.pnames.length?` (${last.pnames.join(" · ")})`:""}`,s:lastErr?printErrText(lastErr):"",click:true});
  if(!rows.length)return null;
  return <div style={{flexShrink:0}}>
    {rows.map((r,i)=><div key={i} onClick={r.click?onOpenFails:undefined} style={{padding:"6px 16px",background:r.bg,borderBottom:`1px solid ${r.c}33`,color:r.c,fontFamily:"'Sarabun',sans-serif",cursor:r.click?"pointer":"default",display:"flex",flexWrap:"wrap",alignItems:"baseline",gap:"2px 10px"}}>
      <span style={{fontSize:13,fontWeight:900}}>{r.t}</span>
      {r.s&&<span style={{fontSize:12,fontWeight:600,opacity:.9}}>{r.s}</span>}
      {r.click&&<span style={{marginLeft:"auto",alignSelf:"center",padding:"6px 12px",borderRadius:8,background:r.c,color:C.white,fontSize:12.5,fontWeight:900,whiteSpace:"nowrap"}}>ดูและรีปริ้น ›</span>}
      {r.orph&&<span style={{marginLeft:"auto",alignSelf:"center",display:"flex",gap:6,flexShrink:0}}>
        {r.orph.fixed&&r.orph.line&&<button type="button" onClick={()=>reprintOrph(r.orph)} disabled={!!orphBusy} style={{padding:"6px 12px",borderRadius:8,border:"none",background:r.c,color:C.white,fontSize:12.5,fontWeight:900,whiteSpace:"nowrap",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",opacity:orphBusy?.6:1}}>{orphBusy===r.orph.key?"กำลังส่ง…":"🖨 พิมพ์ซ้ำ"}</button>}
        <button type="button" onClick={()=>orphAck(branchId,[r.orph.key])} style={{padding:"6px 12px",borderRadius:8,border:`1.5px solid ${r.c}`,background:C.white,color:r.c,fontSize:12.5,fontWeight:800,whiteSpace:"nowrap",cursor:"pointer",fontFamily:"'Sarabun',sans-serif"}}>รับทราบ</button>
      </span>}
    </div>)}
  </div>;
}
function PrintFailModal({branchId,branch,posSettings,onClose,onChanged}){
  const[list,setList]=useState(null);
  const[now,setNow]=useState(()=>Date.now());
  // ถามทุก 4 วิระหว่างเปิดจอนี้ — เห็นทันทีว่าออกแล้ว (รายการหาย) หรือยังไม่ออก (ขึ้นให้กดใหม่)
  const load=useCallback(async()=>{try{const r=await api.getPrintersWithFails(branchId);setList(printFailList(printersAt(r,branchId)));setNow(Date.now());}catch{}},[branchId]);
  useEffect(()=>{load();const t=setInterval(()=>{if(!document.hidden)load();},4000);return()=>clearInterval(t);},[load]);
  async function retry(f,ks){
    try{
      const ok=await editPrintFail(f.holder,l=>markPrintRetry(l,f.id,ks,Date.now()));
      posToast(ok?"🖨️ ส่งคำสั่งพิมพ์แล้ว — ออกจริงแล้วรายการจะหายเอง":"รายการนี้เพิ่งเปลี่ยน (อาจพิมพ์ออกแล้ว) — ดูรายการล่าสุด",ok?"ok":"warn");
    }catch(e){notifyDlg("ส่งคำสั่งพิมพ์ไม่สำเร็จ: "+friendlyError(e));}
    await load();onChanged&&onChanged();
  }
  async function dismiss(f){
    // ใบเรียกพนักงานที่ไม่ออก: ไม่มีอะไรให้พิมพ์ใหม่ — "รับทราบ" = เอาออกเลย ไม่ใช่กล่องแดงเรื่องบอกครัว
    if(!(f.kind==="pj"&&f.what==="เรียกพนักงาน")&&!await confirmDlg({title:"ไม่ต้องพิมพ์แล้ว?",message:`โต๊ะ ${f.table||"-"}: ${(f.names||[]).join(", ")}\n\nเอาออกจากรายการโดยไม่พิมพ์ — ใช้เมื่อบอกครัวด้วยปากแล้ว หรือไม่ต้องทำแล้ว`,confirmLabel:"เอาออก",cancelLabel:"ไม่เอาออก",danger:true}))return;
    try{await editPrintFail(f.holder,l=>l.filter(x=>!samePrintFail(x,f)));}catch(e){notifyDlg("เอาออกไม่สำเร็จ: "+friendlyError(e));}
    await load();onChanged&&onChanged();
  }
  // ใบเสร็จที่ไม่ออก: ตัวพิมพ์ไม่ได้เก็บรูปไว้ → ดึงบิลล่าสุดมาสั่งพิมพ์ใหม่ (ใบเดียวกับตอนปิดบิล) แล้วเอารายการเดิมออก
  // ถ้ารอบใหม่ไม่ออกอีก ตัวพิมพ์จะเพิ่มรายการใหม่ให้เอง ไม่มีใบหายเงียบ
  async function printReceiptAgain(f){
    if(!branch){notifyDlg("ไม่รู้ว่าสาขาไหน — พิมพ์ใหม่จาก 📊 รายงาน → แตะบิล");return;}
    try{
      const r=await sb("orders?id=eq."+(+f.orderId)+"&limit=1");
      const o=Array.isArray(r)?r[0]:null;
      if(!o){notifyDlg("ไม่เจอบิล #"+f.orderId);return;}
      // เอารายการเดิมออกเฉพาะเมื่อส่งเข้าตัวพิมพ์ได้จริง — ส่งไม่ได้ (ไม่มีเครื่องใบเสร็จ/เน็ตสะดุด) ต้องค้างไว้ให้เห็น
      const sent=await printBillReceipt(o,o.table_number,{branch,posSettings,paid:o.status==="paid"});
      if(sent)await editPrintFail(f.holder,l=>{const k=l.filter(x=>!samePrintFail(x,f));return k.length===l.length?null:k;});
    }catch(e){notifyDlg("สั่งพิมพ์ใบเสร็จใหม่ไม่สำเร็จ: "+friendlyError(e));}
    await load();onChanged&&onChanged();
  }
  // ล้างของเก่าทีเดียว (อ่านของล่าสุดของแต่ละเครื่องก่อนเขียน — ตัวพิมพ์เขียนช่องเดียวกันอยู่)
  async function clearOld(oldList){
    const n=oldList.reduce((s,f)=>s+printFailWeight(f),0);
    if(!await confirmDlg({title:"ล้างรายการเก่า?",message:`เอารายการที่ค้างเกิน 12 ชม. ออก ${n} รายการ โดยไม่พิมพ์\n\nใช้เมื่อเป็นของกะก่อนที่จัดการไปแล้ว`,confirmLabel:"ล้างรายการเก่า",cancelLabel:"ไม่ล้าง",danger:true}))return;
    const holders=[...new Set(oldList.map(f=>f.holder))];
    try{for(const h of holders)await editPrintFail(h,l=>{const t=Date.now();const k=l.filter(x=>!isOldPrintFail(x,t));return k.length===l.length?null:k;});}
    catch(e){notifyDlg("ล้างไม่สำเร็จ: "+friendlyError(e));}
    await load();onChanged&&onChanged();
  }
  const KIND={void:"ใบยกเลิก",move:"ใบย้ายโต๊ะ",reprint:"ใบพิมพ์ซ้ำ"};
  const F="'Sarabun',sans-serif";
  const fmtFailAt=(at)=>{if(!at)return "";const d=new Date(+at);const today=new Date(now).toDateString()===d.toDateString();
    return today?d.toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",timeZone:"Asia/Bangkok"}):fmtDT(d.toISOString());};
  const recentList=(list||[]).filter(f=>!isOldPrintFail(f,now)),oldList=(list||[]).filter(f=>isOldPrintFail(f,now));
  const card=(f,old)=>{const its=Array.isArray(f.items)?f.items:[];const idle=its.filter(it=>!printRetryWaiting(it,now));const pj=f.kind==="pj";
    const errs=Array.isArray(f.errs)?f.errs:[];
    // ใบอาจออกไปแล้ว (DRAIN_TIMEOUT) → ปุ่มรีปริ้นคงสีอ่อนไว้ ให้บรรทัด "ถามครัวก่อน" นำ ไม่เชียร์ให้กดซ้ำ
    const maybeOut=errs.some(e=>e&&e.code==="DRAIN_TIMEOUT");
    return <div key={f.id||`${f.orderId}-${f.at}`} style={{border:`1.5px solid ${old?C.line:C.red+"55"}`,borderRadius:12,overflow:"hidden",opacity:old?.85:1}}>
      <div style={{padding:"9px 12px",background:old?C.lineLight:C.redLight,display:"flex",alignItems:"center",gap:8,flexWrap:"wrap",fontFamily:F}}>
        <span style={{fontSize:16,fontWeight:900,color:C.ink}}>{f.table?`โต๊ะ ${f.table}`:pj?"เคาน์เตอร์":"โต๊ะ -"}</span>
        <span style={{fontSize:11.5,fontWeight:800,color:C.red,background:C.white,borderRadius:6,padding:"1px 7px"}}>{pj?(f.what||"ใบจากเคาน์เตอร์"):(KIND[f.kind]||"ใบสั่งอาหาร")}</span>
        <span style={{fontSize:11.5,color:C.ink3}}>{fmtFailAt(f.at)}{f.orderId!=null?` · บิล #${f.orderId}`:""}{Array.isArray(f.pnames)&&f.pnames.length?` · ${f.pnames.join(" · ")}`:""}</span>
        <button onClick={()=>dismiss(f)} style={{marginLeft:"auto",border:`1px solid ${C.line}`,background:C.white,borderRadius:8,color:C.ink3,fontFamily:F,fontSize:12.5,fontWeight:700,cursor:"pointer",padding:"7px 12px",minHeight:36,whiteSpace:"nowrap",flexShrink:0}}>{pj&&f.what==="เรียกพนักงาน"?"รับทราบ":"ไม่ต้องพิมพ์แล้ว"}</button>
      </div>
      {errs.length>0&&<div style={{padding:"6px 12px",borderTop:`1px solid ${C.line}`,fontFamily:F,fontSize:12,fontWeight:700,color:"#92400E",background:"#FFFBEB",lineHeight:1.5}}>
        {errs.map((e,i)=><div key={i}>⚠️ {e.name?e.name+": ":""}{printErrText(e)}{!pj&&e.code==="DRAIN_TIMEOUT"?" · ใบอาจออกไปแล้ว ถามครัวก่อนกดรีปริ้น":""}</div>)}
      </div>}
      {pj?<div style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",borderTop:`1px solid ${C.line}`,fontFamily:F}}>
          <div style={{flex:1,minWidth:0,fontSize:12.5,color:C.ink3,lineHeight:1.5}}>{f.what==="เรียกพนักงาน"?(f.note==="no_rcpt"?"ลูกค้าโต๊ะนี้กดเรียกพนักงาน แต่สาขานี้ยังไม่ได้ติ๊กเครื่องพิมพ์ใบเสร็จ — เดินไปดูที่โต๊ะ แล้วตั้งที่ 🖨 เครื่องพิมพ์ → ติ๊ก \"ใช้เป็นเครื่องพิมพ์ใบเสร็จ\"":"ลูกค้าโต๊ะนี้กดเรียกพนักงาน แต่ใบไม่ออก — เดินไปดูที่โต๊ะ แล้วกด \"รับทราบ\" (มือถือลูกค้าขึ้นให้โบกมือเรียกแล้ว)"):f.what==="ใบเสร็จ"&&f.orderId!=null?"กดพิมพ์ใบเสร็จของบิลนี้ใหม่ได้เลย":"ตัวพิมพ์ไม่ได้เก็บใบนี้ไว้ — สั่งพิมพ์ใหม่จากจุดเดิม (เช่น เปิดโต๊ะ/บิลแล้วกดพิมพ์อีกครั้ง) แล้วกด \"ไม่ต้องพิมพ์แล้ว\""}</div>
          {f.what==="ใบเสร็จ"&&f.orderId!=null&&!old&&<Btn v="primary" onClick={()=>printReceiptAgain(f)} icon={I.print} s={{padding:"9px 14px",minHeight:40,fontSize:13.5,flexShrink:0}}>พิมพ์ใบเสร็จใหม่</Btn>}
        </div>
      :its.length?its.map(it=>{const wait=printRetryWaiting(it,now);const opt=optionsText(it.options);
        return <div key={it.k} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",borderTop:`1px solid ${C.line}`}}>
          <div style={{flex:1,minWidth:0,fontFamily:F,lineHeight:1.35,overflowWrap:"anywhere"}}>
            <div style={{fontSize:15,fontWeight:800,color:C.ink}}>{it.qty}× {it.name}</div>
            {opt&&<div style={{fontSize:12.5,fontWeight:700,color:C.teal}}>+ {opt}</div>}
            {it.note&&<div style={{fontSize:12.5,fontWeight:600,color:C.ink3}}>★ {it.note}</div>}
            {it.lastTry&&!wait&&<div style={{fontSize:11,fontWeight:800,color:C.red}}>ลองแล้วยังไม่ออก — เช็คเครื่องพิมพ์แล้วกดใหม่</div>}
          </div>
          {!old&&<Btn v={wait?"ghost":(idle.length>1||maybeOut)?"danger":"primary"} disabled={wait} onClick={()=>retry(f,[it.k])} icon={I.print} s={{padding:"9px 14px",minHeight:40,fontSize:13.5,flexShrink:0}}>{wait?"กำลังพิมพ์…":"รีปริ้น"}</Btn>}
        </div>;})
      :<div style={{padding:"9px 12px",fontFamily:F,fontSize:13,color:C.ink2,borderTop:`1px solid ${C.line}`}}>{(f.names||[]).join(" · ")}<div style={{fontSize:11.5,color:C.ink4,marginTop:3}}>รายการจากตัวพิมพ์รุ่นเก่า พิมพ์ใหม่จากที่นี่ไม่ได้ — เปิดโต๊ะแล้วปัดซ้ายที่รายการเพื่อพิมพ์ แล้วกด "ไม่ต้องพิมพ์แล้ว"</div></div>}
      {!old&&!pj&&idle.length>1&&<div style={{padding:"8px 12px",borderTop:`1px solid ${C.line}`}}><Btn v={maybeOut?"danger":"primary"} full onClick={()=>retry(f,idle.map(it=>it.k))} icon={I.print} s={{padding:"11px",minHeight:42,fontSize:14,fontWeight:900}}>รีปริ้นทั้งหมดของโต๊ะนี้ ({idle.length})</Btn></div>}
      {old&&!pj&&its.length>0&&<div style={{padding:"6px 12px",borderTop:`1px solid ${C.line}`,fontFamily:F,fontSize:11.5,color:C.ink4}}>ค้างเกิน 12 ชม. — รีปริ้นจากที่นี่ไม่ได้ (กันครัวทำของที่เสิร์ฟไปแล้ว)</div>}
    </div>;};
  return <Modal title="🖨️ พิมพ์ไม่สำเร็จ" onClose={onClose}>
    {list===null?<Loading text="กำลังโหลด..."/>
    :list.length===0?<div style={{textAlign:"center",padding:"28px 0",fontFamily:F,fontSize:15,fontWeight:800,color:C.green}}>✅ พิมพ์ออกครบแล้ว ไม่มีรายการค้าง</div>
    :<div style={{display:"grid",gap:12}}>
      {recentList.length>0&&<div style={{fontSize:12.5,color:C.ink3,fontFamily:F,lineHeight:1.6}}>เช็คเครื่องพิมพ์ให้พร้อมก่อน (เปิดเครื่อง · มีกระดาษ · ปิดฝาสนิท) แล้วกด <b>รีปริ้น</b> ท้ายชื่อเมนู — ออกจริงแล้วรายการจะหายเอง · ถ้าขึ้นว่า "ใบอาจออกไปแล้ว" ให้ถามครัวก่อนกด</div>}
      {recentList.slice().reverse().map(f=>card(f,false))}
      {oldList.length>0&&<div style={{display:"grid",gap:10,marginTop:recentList.length?6:0}}>
        <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap",fontFamily:F}}>
          <span style={{fontSize:13.5,fontWeight:900,color:C.ink3}}>รายการเก่า (ค้างเกิน 12 ชม.) · {oldList.length}</span>
          <Btn v="ghost" onClick={()=>clearOld(oldList)} s={{marginLeft:"auto",padding:"6px 12px",fontSize:12.5}}>ล้างรายการเก่าทั้งหมด</Btn>
        </div>
        {oldList.slice().reverse().map(f=>card(f,true))}
      </div>}
    </div>}
  </Modal>;
}

// ── มีเวอร์ชันใหม่ขึ้นระบบแล้วหรือยัง ────────────────────────────────────
// ร้านเจอซ้ำๆ ว่าแก้ไปแล้วแต่เครื่องที่ร้านยังใช้ของเก่า เพราะไม่มีใครรีเฟรช
// (บิล #129 จ่ายแบบแบ่งจ่ายแต่ไม่มีข้อมูลบันทึก เพราะเครื่องยังรันโค้ดชุดเก่า — 12 ก.ย. 69)
// วิธีเช็ค: ชื่อไฟล์โปรแกรมมีแฮชอยู่ในชื่อ เปลี่ยนทุกครั้งที่ขึ้นระบบใหม่
// อ่านชื่อไฟล์จาก index.html ตัวจริงแล้วเทียบกับไฟล์ที่เครื่องนี้กำลังรันอยู่
// ⚠️ ห้ามรีโหลดเอง — พนักงานอาจกำลังคิดเงินอยู่ ขึ้นแถบให้แตะเองเท่านั้น
function useNewBuild(){
  const[has,setHas]=useState(false);
  useEffect(()=>{
    let stop=false;
    const mine=()=>{try{const s=[...document.querySelectorAll("script[src]")].map(x=>x.src).filter(x=>/\/assets\/[^/]+\.js/.test(x));return s.length?s[0].split("/").pop():null;}catch{return null;}};
    const check=async()=>{
      const cur=mine();if(!cur)return;
      try{
        const r=await fetch("/index.html?_="+Date.now(),{cache:"no-store"});
        if(!r.ok)return;
        const t=await r.text();
        const fresh=(t.match(/\/assets\/[A-Za-z0-9_.-]+\.js/g)||[]).map(x=>x.split("/").pop());
        if(!stop&&fresh.length&&!fresh.includes(cur))setHas(true);
      }catch{}   // เน็ตสะดุด = ไม่ต้องบอกอะไร รอบหน้าเช็คใหม่
    };
    check();
    const t=setInterval(()=>{if(!document.hidden)check();},2*60*1000);
    const onVis=()=>{if(!document.hidden)check();};
    document.addEventListener("visibilitychange",onVis);
    return()=>{stop=true;clearInterval(t);document.removeEventListener("visibilitychange",onVis);};
  },[]);
  return has;
}
// ── เปิดโต๊ะ (สาขาที่มีแพ็คเกจบุฟเฟต์) ──────────────────────────────────
// แตะโต๊ะว่าง → เลือกแพ็คเกจ + จำนวนคน → เปิดโต๊ะ (สร้างบิลพร้อมบรรทัดแพ็คเกจ)
// หรือ "ไม่ใช้แพ็คเกจ" = สั่งตามเมนูแบบเดิมทุกอย่าง (โต๊ะกลับบ้าน/เดลิเวอรี)
// แพ็คเกจเลือกได้ครั้งเดียวตอนนี้ เปลี่ยนทีหลังไม่ได้ · ราคาอ่านสดจากคลังตอนเปิดจอนี้
function POSOpenTableStep({table,branch,posSettings,currentUser,printers=[],onCancel,onAlaCarte,onOpened,onPrintedQR}){
  const[lib,setLib]=useState(()=>activePkgsOf(posSettings));
  const[pick,setPick]=useState(null);
  const[counts,setCounts]=useState({});
  const[busy,setBusy]=useState(false);
  const busyRef=useRef(false);
  useEffect(()=>{let off=false;api.getBuffetPackages(branch.id).then(r=>{if(!off&&r&&Array.isArray(r.packages))setLib(r.packages.filter(p=>p.active!==false));}).catch(()=>{});return()=>{off=true;};},[branch.id]);
  // ตัวพิมพ์รุ่นเก่า (<48) พิมพ์หัวลูกค้าเข้าครัว — เปิดแบบแพ็คเกจไม่ได้จนกว่าจะอัปเดต ("ไม่ใช้แพ็คเกจ" ยังใช้ได้)
  // รายชื่อเครื่องบนจออาจยังไม่โหลด (ว่าง = ผ่าน) หรือค้าง 60 วิ ⟹ ถามสดครั้งเดียวตอนเปิดจอนี้ และอีกครั้งตอนกดเปิดโต๊ะ
  const freshPrinters=async()=>{try{const all=await api.getAllPrinters();if(Array.isArray(all))return all;}catch{}return printers;};
  const[agentOld,setAgentOld]=useState(()=>!canOpenPackageTables(printers,branch.id));
  useEffect(()=>{let off=false;freshPrinters().then(prs=>{if(!off)setAgentOld(!canOpenPackageTables(prs,branch.id));});return()=>{off=true;};},[branch.id]);// eslint-disable-line react-hooks/exhaustive-deps
  const pkg=lib.find(p=>String(p.id)===String(pick))||null;
  const lines=pkg&&Array.isArray(pkg.lines)?pkg.lines.filter(l=>l&&l.key!=null):[];
  const choose=(p)=>{setPick(p.id);const c={};(Array.isArray(p.lines)?p.lines:[]).forEach(l=>{if(l&&l.key!=null)c[l.key]=l.key==="adult"?1:0;});setCounts(c);};
  const setQ=(k,v)=>setCounts(c=>({...c,[k]:Math.max(0,Math.min(999,Math.floor(+v||0)))}));
  const guests=lines.filter(l=>l.guest).reduce((s,l)=>s+(+counts[l.key]||0),0);
  const sum=round2(lines.reduce((s,l)=>s+(+l.price||0)*(+counts[l.key]||0),0));
  async function open(){
    if(busyRef.current||!pkg)return;
    if(guests<1){notifyDlg("ต้องมีลูกค้าอย่างน้อย 1 คน");return;}
    busyRef.current=true;setBusy(true);
    try{
      // ถามรุ่นตัวพิมพ์สดก่อนเปิดทุกครั้ง · อ่านไม่ได้ = ใช้รายชื่อบนจอ
      const okAgent=canOpenPackageTables(await freshPrinters(),branch.id);
      setAgentOld(!okAgent);
      if(!okAgent){notifyDlg(PKG_AGENT_OLD_MSG);busyRef.current=false;setBusy(false);return;}
      // ราคาที่จดลงบิลต้องเป็นราคาล่าสุดในคลัง — จอนี้อาจเปิดค้างไว้ระหว่างที่ผู้จัดการแก้ราคา/ลบแพ็คเกจ
      // อ่านสดก่อนเปิดทุกครั้ง · ถูกลบ = เปิดไม่ได้ · ราคา/รายการเปลี่ยน = แสดงของใหม่ให้ตรวจแล้วกดอีกครั้ง
      const fresh=(await api.getBuffetPackages(branch.id)).packages.filter(p=>p&&p.active!==false);
      const cur=fresh.find(p=>String(p.id)===String(pkg.id));
      const sig=(p)=>JSON.stringify([p.name,(Array.isArray(p.lines)?p.lines:[]).map(l=>[l.key,l.label,+l.price||0,!!l.guest])]);
      if(!cur||sig(cur)!==sig(pkg)){
        setLib(fresh);if(!cur)setPick(null);
        notifyDlg(cur?"ราคา/รายการของแพ็คเกจนี้เพิ่งถูกแก้ — ตรวจราคาใหม่แล้วกดเปิดโต๊ะอีกครั้ง":"แพ็คเกจนี้เพิ่งถูกลบ — เลือกแพ็คเกจอื่น");
        busyRef.current=false;setBusy(false);return;
      }
      const who=currentUser?.username||currentUser?.name||null;
      const r=await api.posOpenTable({branch_id:branch.id,table_id:table.id,table_number:table.table_number,pkg:cur,counts,opened_by:who});
      if(r&&r.existing){posToast("โต๊ะ "+table.table_number+" มีบิลเปิดอยู่แล้ว — แสดงบิลเดิม (ไม่ได้เปิดซ้ำ)","warn",6000);onOpened(r.existing,{existing:true});return;}
      if(!r||!r.row)throw new Error("ไม่ได้รับบิลกลับมา — ลองใหม่อีกครั้ง");
      // พิมพ์ "ใบ QR + ใบเปิดโต๊ะ (เวลาสั่งอาหาร)" เป็นงานเดียวที่เครื่องพิมพ์ใบเสร็จ — ใบเปิดโต๊ะออกต่อจาก QR เสมอ (เจ้าของสั่ง 19 ต.ค. 69)
      // ไม่รอผล โต๊ะเปิดแล้วจริง ห้ามให้การพิมพ์ขวาง · ไม่มีเครื่องใบเสร็จ/ส่งไม่ได้ = printTableQR/printPkgOpenSet เตือนเอง
      const at=(r.row&&r.row.created_at)||new Date().toISOString();
      printPkgOpenSet({table,branch,printers,posSettings,items:r.row.items,at,pkg:cur,by:who,onPrinted:onPrintedQR});
      posToast("✅ "+pkgOpenSlipText({table:table.table_number,pkg,counts,at,by:who}),"ok",5000);
      onOpened(r.row,{slipAt:Date.now()});
      return;
    }catch(e){notifyDlg("เปิดโต๊ะไม่สำเร็จ: "+friendlyError(e));}
    busyRef.current=false;setBusy(false);
  }
  const sBtn={width:44,height:44,borderRadius:10,border:`1.5px solid ${C.line}`,background:C.white,fontSize:20,fontWeight:900,color:C.ink2,cursor:"pointer",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",padding:0};
  return <Modal title={`เปิดโต๊ะ ${table.table_number}${table.label?` — ${table.label}`:""}`} onClose={onCancel}>
    <div style={{fontFamily:"'Sarabun',sans-serif"}}>
      {agentOld&&<div role="alert" style={{background:C.redLight,color:C.red,border:`1px solid ${C.red}55`,borderRadius:10,padding:"8px 10px",fontSize:12.5,fontWeight:800,lineHeight:1.5,marginBottom:10}}>⚠️ {PKG_AGENT_OLD_MSG}</div>}
      <div style={{fontSize:13,fontWeight:800,color:C.ink2,marginBottom:8}}>เลือกแพ็คเกจ <span style={{fontWeight:600,color:C.ink4,fontSize:12}}>(เปลี่ยนทีหลังไม่ได้)</span></div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:8,marginBottom:10}}>
        {lib.map(p=>{const on=String(p.id)===String(pick);const ls=(Array.isArray(p.lines)?p.lines:[]).filter(l=>l&&l.guest);
          return <button key={p.id} onClick={()=>choose(p)} disabled={busy} style={{textAlign:"left",padding:"10px 12px",borderRadius:12,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",
            border:`2px solid ${on?C.brand:C.line}`,background:on?C.brandLight:C.white}}>
            <div style={{fontSize:14,fontWeight:900,color:on?C.brand:C.ink,overflowWrap:"anywhere"}}>{p.name}</div>
            <div style={{fontSize:12,color:C.ink3,marginTop:2,lineHeight:1.5}}>{ls.map(l=>`${l.label} ฿${+l.price||0}`).join(" · ")} · ⏱ {pkgDurText(pkgOrderMinutesOf(p))}</div>
          </button>;})}
        {lib.length===0&&<div style={{gridColumn:"1/-1",fontSize:12.5,color:C.ink4,padding:"8px 0"}}>ยังไม่มีแพ็คเกจที่เปิดใช้</div>}
      </div>
      <button onClick={onAlaCarte} disabled={busy} style={{width:"100%",padding:"11px 12px",borderRadius:12,border:`1.5px dashed ${C.ink4}`,background:C.white,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:800,color:C.ink2,marginBottom:12}}>ไม่ใช้แพ็คเกจ (สั่งตามเมนู)</button>
      {pkg&&<div style={{background:C.bg,borderRadius:12,padding:"10px 12px",marginBottom:12}}>
        {lines.map(l=>{const q=+counts[l.key]||0;return <div key={l.key} style={{display:"flex",alignItems:"center",gap:8,padding:"5px 0"}}>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:14,fontWeight:800,color:C.ink,overflowWrap:"anywhere"}}>{l.label}</div>
            <div style={{fontSize:12,color:C.ink4}}>฿{+l.price||0}{l.guest?" / คน":""}</div>
          </div>
          <button onClick={()=>setQ(l.key,q-1)} disabled={busy||q<=0} aria-label={"ลด "+l.label} style={{...sBtn,opacity:q<=0?.4:1}}>−</button>
          <input type="text" inputMode="numeric" value={String(q)} onChange={e=>setQ(l.key,e.target.value.replace(/[^0-9]/g,""))} aria-label={"จำนวน "+l.label}
            style={{width:52,height:44,textAlign:"center",fontSize:17,fontWeight:900,border:`1.5px solid ${C.line}`,borderRadius:10,fontFamily:"'Sarabun',sans-serif",boxSizing:"border-box"}}/>
          <button onClick={()=>setQ(l.key,q+1)} disabled={busy} aria-label={"เพิ่ม "+l.label} style={sBtn}>+</button>
        </div>;})}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"baseline",borderTop:`1px solid ${C.line}`,marginTop:6,paddingTop:8}}>
          <span style={{fontSize:13,color:C.ink3,fontWeight:700}}>ลูกค้า {guests} คน</span>
          <span style={{fontSize:20,fontWeight:900,color:C.brand}}>฿{sum.toLocaleString("en-US",{maximumFractionDigits:2})}</span>
        </div>
      </div>}
      <div style={{display:"flex",gap:8}}>
        <Btn v="ghost" onClick={onCancel} full s={{padding:"12px"}}>ยกเลิก</Btn>
        <Btn onClick={open} loading={busy} disabled={!pkg||guests<1||agentOld} full icon={I.check} s={{padding:"12px",fontWeight:900}}>เปิดโต๊ะ</Btn>
      </div>
    </div>
  </Modal>;
}
function POSSaleMode({menus,reloadMenus,reloadPrinters,currentBranch,currentUser,printers=[],shift,zones=[],posSettings,promotions=[],onUpdateShift,onCashDrawer,onCloseShift,onExitMode,saleOnly=false,reloadPosSettings,refreshTick=0,reloadZones}){
  const[posTab,setPosTab]=useState("tables");
  const[tables,setTables]=useState([]);const[activeOrders,setActiveOrders]=useState([]);
  const[moveFrom,setMoveFrom]=useState(null);   // {table,order} ระหว่างเลือกโต๊ะปลายทาง
  // ปุ่ม "พิมพ์ไม่สำเร็จ" — ขึ้นเฉพาะตอนมีใบที่ยังไม่ออก · พิมพ์ออกครบ ตัวพิมพ์ลบรายการเอง ปุ่มก็หายเอง
  // ถามเฉพาะเครื่องที่มีรายการค้าง ทุก 15 วิ (ปกติได้แถวว่าง) — ไม่ต้องรอรอบดึงเครื่องพิมพ์ 60 วิ
  const hasNewBuild=useNewBuild();   // มีเวอร์ชันใหม่รออยู่ไหม (ไม่รีโหลดเอง)
  const[failPrinters,setFailPrinters]=useState([]);
  const[showPrintFails,setShowPrintFails]=useState(false);
  const loadFails=useCallback(async()=>{try{const r=await api.getPrintersWithFails(currentBranch.id);if(Array.isArray(r))setFailPrinters(printersAt(r,currentBranch.id));}catch{}},[currentBranch.id]);
  useEffect(()=>{loadFails();const t=setInterval(()=>{if(!document.hidden)loadFails();},6000);return()=>clearInterval(t);},[loadFails]);
  // ปุ่มแดงนับเฉพาะของ 12 ชม.ล่าสุด · ของเก่ากว่านั้นแยกเป็นปุ่มเทา (ล้างทีเดียวได้ในแผง)
  // เดิมนับรวม รายการ 28 ก.ย. จึงทำปุ่มแดงติดตลอด 12 วัน — วันที่ใบไม่ออกจริงก็ไม่มีใครสังเกต
  const failSplit=useMemo(()=>{const now=Date.now();let recent=0,old=0;for(const f of printFailList(failPrinters)){if(isOldPrintFail(f,now))old+=printFailWeight(f);else recent+=printFailWeight(f);}return{recent,old};},[failPrinters]);
  const failCount=failSplit.recent;
  // ผังโต๊ะและจอโต๊ะใช้รายการจากรอบถามเร็ว ⟹ กดรีปริ้นแล้วป้ายหายภายในไม่กี่วินาที
  // (เดิมอ่านจากรายชื่อเครื่องพิมพ์ที่ดึงทุก 60 วิ ป้ายจึงค้างอยู่นานทั้งที่พิมพ์ออกแล้ว)
  const failPrintersLive=failPrinters;
  // เงินทอนหลังปิดบิลเงินสด — เก็บไว้ที่จอแม่ ไม่ใช่ในจอโต๊ะ
  // เพราะจอโต๊ะปิดตัวเองทันทีที่ปิดบิลเสร็จ (โต๊ะต้องว่างพร้อมรับลูกค้าใหม่ทันที)
  // ถ้าเอาป็อปอัพไว้ในจอโต๊ะ มันจะถูกถอดออกไปพร้อมกันแล้วพนักงานไม่เห็นยอดทอนเลย
  const[changeDlg,setChangeDlg]=useState(null);
  // ป็อปอัพ QR หลังกดพิมพ์ QR โต๊ะ — ให้พนักงานเอามือถือสแกนดูหน้าที่ลูกค้าจะเห็นจริง
  const[qrPeek,setQrPeek]=useState(null);   // {table,url}
  const[qrPeekErr,setQrPeekErr]=useState(false);
  const[loading,setLoading]=useState(true);
  const isMobile=useIsMobile();
  const[selTable,setSelTable]=useState(null);const[selOrder,setSelOrder]=useState(null);
  // แพ็คเกจบุฟเฟต์: โต๊ะว่างที่กำลังเลือกแพ็คเกจ · โต๊ะที่เพิ่งเปิด (ขึ้นแถบชวนพิมพ์ QR)
  // สาขาที่ไม่มีแพ็คเกจ (เช่น River) ไม่เห็นขั้นนี้เลย — แตะโต๊ะแล้วสั่งได้ทันทีเหมือนเดิม
  const[openStep,setOpenStep]=useState(null);
  const[justOpened,setJustOpened]=useState(null);   // {id,at}
  const hasPkgs=activePkgsOf(posSettings).length>0;
  // ใบเปิดโต๊ะกับใบ QR ใช้ช่องคำสั่งรูปช่องเดียวกันของเครื่องแคชเชียร์ — กดพิมพ์ QR ทันทีหลังเปิดโต๊ะ
  // ใบที่สองจะเขียนทับใบแรกก่อนตัวพิมพ์หยิบ ⟹ รอใบในคิว (เปิดโต๊ะ/เพิ่ม-ลดคน) เขียนเสร็จจริง แล้วเว้นจากเวลาที่เขียน
  // (เดิมนับจากตอนเปิดโต๊ะเสร็จ — แต่ใบเปิดโต๊ะอาจรอช่องว่างอีก 1.5 วิ ก่อนเขียน แล้วไปชนกับ QR พอดี)
  const printSelQR=()=>{
    const t=selTable;if(!t)return;
    setQrPeekErr(false);setQrPeek({table:t,url:null});
    cashierSlipIdle().then(lastAt=>setTimeout(()=>printTableQR(t,currentBranch,printers,()=>loadAll({silent:true}),(u)=>setQrPeek(p=>p?{...p,url:u}:p)),Math.max(0,2500-(Date.now()-(+lastAt||0)))));
  };
  // แถบเขียวหลังเปิดโต๊ะ: พิมพ์ QR + ใบเปิดโต๊ะซ้ำ (กระดาษหมด/ใบหาย) — ใบสร้างจากบิลจริง (ราคาที่จดตอนเปิด · จำนวนคนล่าสุด)
  // บิลไม่มีแพ็คเกจ (ไม่น่าเกิดในแถบนี้) = พิมพ์ QR อย่างเดียว
  const reprintOpenSet=async()=>{
    const t=selTable;let o=selOrder;if(!t)return;
    // บิลบนจออาจเก่า (เพิ่ม/ลดคนในจอโต๊ะไปแล้ว) — อ่านล่าสุดก่อน · อ่านไม่ได้ = ใช้ที่มี
    try{if(o&&o.id){const r=await api.getPOSOrderById(o.id);if(Array.isArray(r)&&r[0])o=r[0];}}catch{}
    const bp=pkgOfBill(o&&o.items);
    if(!bp){printSelQR();return;}
    const def=pkgLibOf(posSettings).find(p=>String(p.id)===String(bp.id))||null;
    // เวลาสั่งตามที่จดในบิล (ตรงกับนับถอยหลังของลูกค้าและตัวกันฝั่งส่ง) ไม่ใช่คลังที่อาจแก้ไปแล้ว
    const pkg=bpMinutes(bp.mins)!=null?{...(def||{}),order_minutes:bp.mins}:def;
    printPkgOpenSet({table:t,branch:currentBranch,printers,posSettings,items:o.items,at:o.created_at,pkg,by:o.ordered_by||currentUser?.username||currentUser?.name||null,onPrinted:()=>loadAll({silent:true})});
  };
  const[showPrinters,setShowPrinters]=useState(false);
  const[showReceipt,setShowReceipt]=useState(false);
  const[showOrders,setShowOrders]=useState(false);   // today's-orders modal (re-added after the tab was replaced)
  const[printStation,setPS]=useState(()=>isPrintStation(currentBranch.id));   // is THIS device the print station (of THIS branch)?
  useEffect(()=>{setPS(isPrintStation(currentBranch.id));},[currentBranch.id]);   // สลับสาขา = อ่านค่าของสาขานั้น
  // เครื่องที่เคยเปิดโหมดสถานีพิมพ์แบบเก่า (ไม่ระบุสาขา) — ไม่เปิดให้เอง บอกครั้งเดียวว่าปิดแล้ว
  // (ปุ่มเปิด/ปิดสถานีพิมพ์ถูกเอาออกไปแล้วตั้งแต่ใช้ตัวพิมพ์ — ห้ามบอกให้ไปเปิดใหม่ เพราะไม่มีที่ให้เปิด)
  useEffect(()=>{if(takeOldPrintStation())posToast("ℹ️ ปิดโหมดสถานีพิมพ์ของเครื่องนี้แล้ว — โปรแกรมตัวพิมพ์ที่ร้านพิมพ์ใบให้เอง ไม่ต้องตั้งอะไรเพิ่ม","warn",9000);},[]);
  const timerRef=useRef(null);
  const canEdit=hasPerm(currentUser,"pos");
  // คนเข้าด้วย PIN / พนักงานที่ไม่มีสิทธิ์ตั้งค่า: ห้ามแก้พร้อมเพย์/VAT/หัวใบเสร็จ (เงินเข้าบัญชีใครก็ได้)
  // และห้ามเพิ่ม/ลบเครื่องพิมพ์ — แต่ทดสอบพิมพ์ ดูสถานะ ดูตาราง 🧭 และย้ายหมวดตอนเครื่องดับ ยังทำได้ทุกคน
  const posAcc=posAccess(currentUser,saleOnly);

  const printedRef=useRef(new Set(JSON.parse(sessionStorage.getItem("fc_printed_orders")||"[]")));
  const lastSigRef=useRef(new Map());
  const stationPrimedRef=useRef(false);   // skip the first batch so a station restart doesn't reprint open orders
  const wakeLockRef=useRef(null);         // screen wake lock so the print station's screen never sleeps
  function persistPrinted(){try{sessionStorage.setItem("fc_printed_orders",JSON.stringify([...printedRef.current]));}catch{}}
  // Only the designated print station auto-prints — and it prints EVERY new order
  // (staff + customer), since the iPads can't print themselves.
  function autoPrintNew(orders){
    if(!isPrintStation(currentBranch.id))return;
    // ใบครัวเฉพาะอาหาร — ตัดรายการแพ็คเกจออกก่อนคิดลายเซ็น/ส่วนต่าง (เพิ่ม-ลดคนไม่มีใบ)
    orders=(orders||[]).map(o=>o&&Array.isArray(o.items)?{...o,items:o.items.filter(isKitchenLine)}:o);
    // First pass after (re)becoming the station: record what's already open WITHOUT
    // printing, so a restart doesn't spew a reprint of every active order.
    if(!stationPrimedRef.current){
      orders.forEach(o=>{if(!o||!o.items)return;const sig=JSON.stringify(o.items.map(i=>[i.menu_id,i.qty,i.note||""]));lastSigRef.current.set(o.id,sig);printedRef.current.add(`${o.id}:init`);});
      persistPrinted();stationPrimedRef.current=true;return;
    }
    // ส่วนต่างที่ต้องพิมพ์ — รวมจำนวนตามคีย์ทั้งสองฝั่งก่อนเทียบ
    // (คีย์ซ้ำต้องบวกกัน ไม่ใช่ทับกัน ไม่งั้นสั่งเมนูเดิมซ้ำจะไม่ออกใบครัว)
    const diffNew=(lastSig,items)=>{
      try{
        const sum=rows=>{const m=new Map();for(const[k,q]of rows)m.set(k,(m.get(k)||0)+(+q||0));return m;};
        const kOf=i=>`${i.menu_id}|${i.note||""}`;
        const old=sum(JSON.parse(lastSig).map(([m,q,n])=>[`${m}|${n}`,q]));
        const cur=sum((items||[]).map(i=>[kOf(i),i.qty]));
        const out=[],seen=new Set();
        for(const i of items||[]){const k=kOf(i);if(seen.has(k))continue;seen.add(k);
          const d=(cur.get(k)||0)-(old.get(k)||0);if(d>0)out.push({...i,qty:d});}
        return out;
      }catch{return items||[];}
    };
    orders.forEach(o=>{
      if(!o||!o.items||o.items.length===0)return;
      if(o.status==="paid"||o.status==="cancelled")return;
      const sig=JSON.stringify(o.items.map(i=>[i.menu_id,i.qty,i.note||""]));
      const lastSig=lastSigRef.current.get(o.id);
      const isFirst=!printedRef.current.has(`${o.id}:init`);
      if(isFirst){
        const newItems=lastSig?diffNew(lastSig,o.items):o.items;
        if(newItems.length>0){printKitchen(newItems,o.table_number,printers);}
        printedRef.current.add(`${o.id}:init`);persistPrinted();
      }else if(lastSig&&lastSig!==sig){
        try{
          const newItems=diffNew(lastSig,o.items);
          if(newItems.length>0)printKitchen(newItems,o.table_number,printers);
        }catch{}
      }
      lastSigRef.current.set(o.id,sig);
    });
  }

  async function loadTables(){const t=await api.getPOSTables(currentBranch.id);setTables(t);}
  // ── ออก QR ใหม่ให้โต๊ะว่าง ── ทางแก้เมื่อปล่อยโต๊ะไม่สำเร็จ (เน็ตสะดุดตอนปิดบิล/ย้ายโต๊ะ/ปิดกะ)
  // หรือใบ QR หลุดไปอยู่กับคนที่ไม่ควรมี · เช็คบิลเปิด "สดๆ" ก่อนเสมอ — โต๊ะที่ยังมีบิล ห้ามเปลี่ยนรหัส
  // (ลูกค้าที่นั่งอยู่จะสั่งต่อไม่ได้) · อ่านบิลไม่ได้ = ไม่ทำ ให้ลองใหม่
  async function reissueTableQR(t){
    if(!t||!t.id)return;
    if(!await confirmDlg({title:"ออก QR ใหม่",message:`โต๊ะ ${t.table_number}: QR เดิมทุกใบจะใช้สั่งไม่ได้ทันที\nถ้าจะมีลูกค้านั่งโต๊ะนี้ ต้องพิมพ์ QR ใหม่ให้`,confirmLabel:"🔄 ออก QR ใหม่"}))return;
    let open=null;try{open=await api.getOrderByTable(t.id);}catch{}
    if(!Array.isArray(open)){posToast("⚠️ เช็คบิลของโต๊ะนี้ไม่ได้ (เน็ตสะดุด) — ลองอีกครั้ง","warn",6000);return;}
    if(open.length){posToast("โต๊ะ "+t.table_number+" มีบิลเปิดอยู่ — ออก QR ใหม่ไม่ได้ (ลูกค้าที่นั่งอยู่จะสั่งต่อไม่ได้)","warn",7000);loadAll({silent:true});return;}
    const ok=await api.releaseTable(t.id).catch(()=>false);
    posToast(ok?"🔄 ออก QR ใหม่ให้โต๊ะ "+t.table_number+" แล้ว — QR เดิมใช้ไม่ได้แล้ว":"⚠️ ออก QR ใหม่ไม่สำเร็จ — QR เดิมยังใช้ได้อยู่ ลองอีกครั้ง",ok?"ok":"warn",ok?4000:8000);
    loadAll({silent:true});
  }
  // Table editing from the floor plan (optimistic local update + persist)
  async function handleAddTable(d){try{await api.addPOSTable({...d,branch_id:currentBranch.id,status:"available",active:true});await loadTables();}catch(e){alert("เพิ่มโต๊ะไม่สำเร็จ: "+(e&&e.message||e));}}
  async function handleUpdateTable(id,d){setTables(p=>p.map(t=>t.id===id?{...t,...d}:t));try{await api.updatePOSTable(id,d);}catch(e){alert("แก้ไขโต๊ะไม่สำเร็จ: "+(e&&e.message||e));loadTables();}}
  // โต๊ะที่เคยมีบิลลบทิ้งไม่ได้ — บิลเก่าอ้างถึงแถวนี้อยู่ (foreign key ของฐานข้อมูล)
  // ตัวกันนี้ถูกต้องแล้วและต้องคงไว้: ลบผ่านเมื่อไหร่ ประวัติการขายจะชี้ไปที่โต๊ะที่ไม่มีอยู่
  // แต่เดิมเด้งข้อความดิบของฐานข้อมูล (23503 ... violates foreign key constraint) ใส่หน้าพนักงาน
  // ซึ่งอ่านไม่รู้เรื่องและไม่บอกว่าต้องทำอะไรต่อ · ทางที่ถูกคือซ่อนออกจากผัง
  // (tables.active=false — getPOSTables กรอง active=eq.true อยู่แล้ว โต๊ะจึงหายจากหน้าขาย
  //  ส่วนบิลเก่ายังอ้างถึงแถวเดิมได้ครบ รายงานย้อนหลังไม่พัง)
  async function handleDeleteTable(id){
    const prev=tables;
    setTables(p=>p.filter(t=>t.id!==id));
    try{ await api.deletePOSTable(id); return; }
    catch(e){
      const fk=/23503|foreign key|still referenced/i.test(String((e&&e.message)||e));
      if(!fk){ alert("ลบโต๊ะไม่สำเร็จ: "+friendlyError(e)); setTables(prev); return; }
      setTables(prev);   // เอาโต๊ะกลับขึ้นจอก่อน แล้วค่อยถาม จะได้ไม่หายไปทั้งที่ยังไม่ตัดสินใจ
      const ok=await confirmDlg({
        title:"โต๊ะนี้มีประวัติการขาย",
        message:"ลบออกจากระบบไม่ได้ เพราะมีบิลเก่าอ้างถึงโต๊ะนี้อยู่ — ถ้าลบ ประวัติการขายและรายงานย้อนหลังจะเสียหาย\n\nซ่อนออกจากผังแทนไหม? โต๊ะจะหายจากหน้าขาย แต่บิลเก่ายังอยู่ครบ",
        confirmLabel:"ซ่อนออกจากผัง",
        cancelLabel:"ไม่ต้อง เก็บไว้",
        danger:false,
      });
      if(!ok)return;
      try{ await api.updatePOSTable(id,{active:false}); setTables(p=>p.filter(t=>t.id!==id)); }
      catch(e2){ alert("ซ่อนโต๊ะไม่สำเร็จ: "+friendlyError(e2)); }
    }
  }
  async function handleMoveTable(id,x,y){setTables(p=>p.map(t=>t.id===id?{...t,x,y}:t));try{await api.updatePOSTable(id,{x,y});}catch(e){console.error("move table save failed",e);}}
  // Zone rename/delete from the floor plan (rename cascades to tables; delete moves its tables to no-zone)
  async function handleRenameZone(oldName,newName,id){
    if(id)await api.updateZone(id,{name:newName});
    const affected=tables.filter(t=>t.zone===oldName);
    for(const t of affected)await api.updatePOSTable(t.id,{zone:newName});
    setTables(p=>p.map(t=>t.zone===oldName?{...t,zone:newName}:t));
    if(reloadZones)await reloadZones();
  }
  async function handleDeleteZone(name,id){
    const affected=tables.filter(t=>t.zone===name);
    for(const t of affected)await api.updatePOSTable(t.id,{zone:""});
    setTables(p=>p.map(t=>t.zone===name?{...t,zone:""}:t));
    if(id)await api.deleteZone(id);
    if(reloadZones)await reloadZones();
  }
  async function loadOrders(){const o=await api.getActiveOrders(currentBranch.id);setActiveOrders(o);autoPrintNew(o);}
  async function loadAll(o){
    const silent=!!(o&&o.silent===true);   // ปุ่ม "รีเฟรช" ส่ง event มา → ไม่ silent → เห็นสปินเนอร์ตามเดิม
    if(!silent)setLoading(true);
    try{await Promise.all([loadTables(),loadOrders()]);}catch(e){console.error(e);}
    if(!silent)setLoading(false);
  }

  useEffect(()=>{
    stationPrimedRef.current=false;   // re-prime on mount and whenever station mode flips
    loadAll();
    // The print station polls faster (6s) so kitchen tickets come out quickly; other devices stay light (20s).
    const period=printStation?10000:30000;   // ลดโหลดฐานข้อมูล — เดิม 6s/20s กินเครดิต Disk IO จนล่ม
    timerRef.current=setInterval(()=>{if(!document.hidden)loadOrders();},period);
    const onVis=()=>{if(!document.hidden)loadOrders();};
    document.addEventListener("visibilitychange",onVis);
    return()=>{clearInterval(timerRef.current);document.removeEventListener("visibilitychange",onVis);};
  },[printStation]);// eslint-disable-line react-hooks/exhaustive-deps
  // Keep the print-station screen awake (Screen Wake Lock — works on Android Chrome over
  // https). The OS drops the lock whenever the page is hidden, so re-acquire on re-show.
  useEffect(()=>{
    if(!printStation)return;
    let cancelled=false;
    async function acquire(){
      try{
        if("wakeLock" in navigator && navigator.wakeLock?.request && document.visibilityState==="visible"){
          wakeLockRef.current=await navigator.wakeLock.request("screen");
        }
      }catch(e){/* unsupported / denied / not visible — manual screen-timeout is the fallback */}
    }
    function onVis(){if(document.visibilityState==="visible"&&!cancelled)acquire();}
    acquire();
    document.addEventListener("visibilitychange",onVis);
    return()=>{
      cancelled=true;
      document.removeEventListener("visibilitychange",onVis);
      try{wakeLockRef.current&&wakeLockRef.current.release&&wakeLockRef.current.release();}catch{}
      wakeLockRef.current=null;
    };
  },[printStation]);
  // ปุ่มรีเฟรชต้องดึง "ทุกอย่าง" ไม่ใช่แค่ออเดอร์ — พนักงานกดปุ่มนี้ตอนสงสัยว่า
  // ข้อมูลไม่ตรงกับหลังบ้าน ถ้าดึงแค่ออเดอร์ก็ยังไม่ตรงอยู่ดี แล้วจะงงหนักกว่าเดิม
  useEffect(()=>{if(refreshTick){loadAll();try{reloadMenus&&reloadMenus();}catch{}try{reloadPosSettings&&reloadPosSettings();}catch{}}},[refreshTick]);// eslint-disable-line react-hooks/exhaustive-deps  (refresh button in the kiosk header)

  // QR-สั่งอาหาร tab removed — per-table QR is printed by tapping a table (one place only).
  const PTABS=[{id:"tables",l:"แผนผังโต๊ะ",icon:I.table}];  // "ออเดอร์วันนี้" replaced by the menu-management dropdown

  const TB={padding:"8px 12px",fontSize:13,minHeight:36};   // ปุ่มแถวเครื่องมือจอขาย — สูงพอให้นิ้วกดบนแท็บเล็ต
  if(loading)return <Loading text="กำลังโหลดข้อมูล POS..."/>;

  // ชนขอบกรอบให้พอดี: หลังบ้านเว้น 24/28 (มือถือ 14/12) · หน้าขาย PIN เว้น 20/24 และหัวจอมีขอบบนของ iPad/iPhone
  // ความสูงคิดให้พอดีจอ (เหลือขอบล่างนิดเดียว) ไม่ให้มีแถบเทาว่าง ~90px ใต้ผังโต๊ะ
  return <div style={{margin:isMobile?"-14px -12px":(saleOnly?"-20px -24px":"-24px -28px"),display:"flex",flexDirection:"column",height:saleOnly?"calc(100vh - 96px - env(safe-area-inset-top, 0px))":(isMobile?"calc(100vh - 94px)":"calc(100vh - 90px)")}}>
    {/* มีเวอร์ชันใหม่ขึ้นระบบแล้ว — แตะเพื่อโหลด (ไม่โหลดเองกลางบิล)
        แถบนี้เฉพาะจอขาย PIN — หลังบ้านมีแถบของ shell อยู่แล้ว ไม่ซ้อนสองแถบ */}
    {hasNewBuild&&saleOnly&&<button onClick={()=>{try{location.reload();}catch{}}}
      style={{padding:"10px 16px",background:C.brand,color:C.white,border:"none",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:10,fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:900,flexShrink:0,width:"100%"}}>
      🔄 มีระบบเวอร์ชันใหม่แล้ว — กดส่งรายการที่ค้างก่อน แล้วแตะตรงนี้เพื่ออัปเดต (บิลไม่หาย · ต้องใส่ PIN ใหม่)
    </button>}
    {/* Shift indicator strip */}
    <div style={{padding:"6px 16px",background:`linear-gradient(135deg,${C.green},#059669)`,color:C.white,display:"flex",alignItems:"center",gap:14,fontSize:12,fontFamily:"'Sarabun',sans-serif",flexShrink:0}}>
      <span style={{fontSize:14}}>💵</span>
      <span style={{fontWeight:700}}>กะ #{shift.id}</span>
      <span style={{opacity:.85}}>เปิดเมื่อ {new Date(shift.opened_at).toLocaleTimeString("th-TH",{hour:'2-digit',minute:'2-digit'})}</span>
      <span style={{opacity:.85}}>· ทอนเริ่มต้น ฿{(+shift.opening_cash||0).toLocaleString()}</span>
      <span style={{opacity:.85,marginLeft:"auto"}}>{shift.username}</span>
    </div>
    <PrintHealthStrip printers={printers} failPrinters={failPrinters} branchId={currentBranch.id} onOpenFails={()=>setShowPrintFails(true)} orders={activeOrders} who={currentUser?.username||currentUser?.name||null}/>
    <div style={{padding:"0 16px",background:C.white,borderBottom:`1px solid ${C.line}`,display:"flex",alignItems:"center",flexWrap:"wrap",minHeight:46,columnGap:2,flexShrink:0}}>
      {PTABS.map(t=>{const active=posTab===t.id;return <button key={t.id} onClick={()=>setPosTab(t.id)} style={{display:"flex",alignItems:"center",gap:6,padding:"0 12px",height:46,border:"none",background:"none",cursor:"pointer",fontSize:12,fontWeight:active?800:500,color:active?C.brand:C.ink3,fontFamily:"'Sarabun',sans-serif",borderBottom:active?`2.5px solid ${C.brand}`:"2.5px solid transparent",transition:"all .15s"}}><Ic d={t.icon} s={13} c={active?C.brand:C.ink4}/>{t.l}</button>;})}
      {canEdit&&<POSMenuTools currentBranch={currentBranch} currentUser={currentUser} saleOnly={saleOnly} menus={menus} variant="dropdown" onChanged={()=>{reloadMenus&&reloadMenus();reloadPosSettings&&reloadPosSettings();}}/>}
      {/* แถวปุ่มตัดบรรทัดได้ ไม่ให้ปุ่มท้ายแถวล้นจอจนกดไม่ได้บน iPad · ปุ่มสูง ≥36 ให้นิ้วกดง่าย
          ปิดกะ (ย้อนไม่ได้) แยกไว้ท้ายสุด มีเส้นคั่น ไม่ติดกับปุ่มเงินในลิ้นชักที่กดบ่อย */}
      <div style={{marginLeft:"auto",display:"flex",flexWrap:"wrap",justifyContent:"flex-end",alignItems:"center",gap:6,padding:"5px 0"}}>
        {failCount>0&&<Btn v="danger" onClick={()=>setShowPrintFails(true)} icon={I.print} s={TB}>พิมพ์ไม่สำเร็จ ({failCount})</Btn>}
        {failCount===0&&failSplit.old>0&&<Btn v="ghost" onClick={()=>setShowPrintFails(true)} icon={I.print} s={TB}>ใบค้างเก่า ({failSplit.old})</Btn>}
        <Btn v="ghost" onClick={()=>setShowOrders(true)} s={TB}>📊 รายงาน</Btn>
        <Btn v="success" onClick={onCashDrawer} s={TB}>💰 เงินในลิ้นชัก</Btn>
        {!saleOnly&&<Btn v="ghost" onClick={loadAll} icon={I.refresh} s={TB}>รีเฟรช</Btn>}
        <Btn v="ghost" onClick={()=>setShowPrinters(true)} s={TB}>🖨 เครื่องพิมพ์</Btn>
        {posAcc.settings&&<Btn v="ghost" onClick={()=>setShowReceipt(true)} s={TB}>🧾 จัดการใบเสร็จ</Btn>}
        {!saleOnly&&<Btn v="ghost" onClick={onExitMode} s={TB}>← โหมด</Btn>}
        {canEdit&&!saleOnly&&<span style={{display:"inline-flex",alignItems:"center",gap:6,alignSelf:"stretch"}}><span style={{width:1,alignSelf:"stretch",background:C.line,margin:"0 4px"}}/><Btn v="ghost" onClick={onCloseShift} s={{...TB,color:C.red,boxShadow:`0 0 0 1.5px ${C.red}66`}}>🔚 ปิดกะ</Btn></span>}
      </div>
    </div>
    <div style={{flex:1,overflow:"hidden",display:"flex",flexDirection:"column"}}>
      {posTab==="tables"&&<POSTableMap tables={tables} activeOrders={activeOrders} zones={zones} printers={printers} failPrinters={failPrintersLive} onSelectTable={(t,o)=>{if(!canEdit)return;if(!o&&hasPkgs){setOpenStep(t);return;}setSelTable(t);setSelOrder(o||null);}} onAddZone={canEdit?async(name)=>{if(zones.some(z=>String(z.name).toLowerCase()===name.toLowerCase())){alert("มีโซนนี้อยู่แล้ว");return;}const sortMax=zones.reduce((m,z)=>Math.max(m,z.sort_order||0),0);await api.addZone({branch_id:currentBranch.id,name,color:ZONE_COLORS[zones.length%ZONE_COLORS.length],sort_order:sortMax+1});if(reloadZones)await reloadZones();}:undefined} onAddTable={canEdit?handleAddTable:undefined} onUpdateTable={canEdit?handleUpdateTable:undefined} onDeleteTable={canEdit?handleDeleteTable:undefined} onMoveTable={canEdit?handleMoveTable:undefined} onRenameZone={canEdit?handleRenameZone:undefined} onDeleteZone={canEdit?handleDeleteZone:undefined}/>}
      {showOrders&&<SalesReportModal currentBranch={currentBranch} menus={menus} printers={printers} posSettings={posSettings} shift={shift} currentUser={currentUser} onEdited={loadAll} onClose={()=>setShowOrders(false)}/>}
      {showPrintFails&&<PrintFailModal branchId={currentBranch.id} branch={currentBranch} posSettings={posSettings} onChanged={loadFails} onClose={()=>{setShowPrintFails(false);loadFails();try{reloadPrinters&&reloadPrinters();}catch{}}}/>}
    </div>
    {openStep&&<POSOpenTableStep table={openStep} branch={currentBranch} posSettings={posSettings} currentUser={currentUser} printers={printers}
      onCancel={()=>setOpenStep(null)}
      onAlaCarte={()=>{const t=openStep;setOpenStep(null);setSelTable(t);setSelOrder(null);}}
      onPrintedQR={()=>loadAll({silent:true})}
      onOpened={(row,info)=>{const t=openStep;setOpenStep(null);setSelOrder(row||null);setSelTable(t);
        setJustOpened(info&&info.existing?null:{id:t.id,at:(info&&info.slipAt)||Date.now()});loadAll({silent:true});
        // ขั้นเปิดโต๊ะอ่านคลังสด แต่จอโต๊ะหาเมนูจากตั้งค่าที่โหลดไว้ (ทุก 60 วิ) — แพ็คเกจที่เพิ่งสร้างยังไม่อยู่ในนั้น
        // = ป้ายแดง "หาแพ็คเกจไม่เจอ" + กริดว่าง ⟹ อ่านตั้งค่าใหม่ครั้งเดียวเฉพาะตอนนั้น
        {const sc=row&&pkgMenuScopeOf(row.items,pkgLibOf(posSettings));if(sc&&sc.missing&&reloadPosSettings)reloadPosSettings();}}}/>}
    {selTable&&<Modal title={`โต๊ะ ${selTable.table_number}${selTable.label?` — ${selTable.label}`:""}`} onClose={()=>{setSelTable(null);setSelOrder(null);setJustOpened(null);loadAll({silent:true});}} wide noScroll>
      {justOpened&&justOpened.id===selTable.id&&<div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",padding:"9px 12px",marginBottom:8,borderRadius:11,background:"#ECFDF5",border:"1.5px solid #059669",fontFamily:"'Sarabun',sans-serif",flexShrink:0}}>
        <span style={{flex:1,minWidth:160,fontSize:13,fontWeight:800,color:"#065F46"}}>✅ เปิดโต๊ะแล้ว — ส่งพิมพ์ QR + ใบเปิดโต๊ะ (เวลาสั่งอาหาร) ที่เครื่องใบเสร็จแล้ว</span>
        <Btn onClick={reprintOpenSet} icon={I.print} s={{padding:"8px 14px",fontSize:13}}>พิมพ์ QR + ใบเปิดโต๊ะซ้ำ</Btn>
      </div>}
      <div style={{display:"flex",justifyContent:"flex-end",gap:8,marginBottom:10,flexShrink:0,flexWrap:"wrap"}}>
        {selOrder?.id&&<button onClick={()=>setMoveFrom({table:selTable,order:selOrder})} style={{display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:9,border:`1px solid ${C.blue}55`,background:C.blueLight,cursor:"pointer",fontSize:12,fontWeight:700,color:C.blue,fontFamily:"'Sarabun',sans-serif"}}>🔀 ย้ายโต๊ะ</button>}
        {/* ปุ่มพิมพ์ QR มีปุ่มเดียวเสมอ — โต๊ะที่เพิ่งเปิดใช้ปุ่มใหญ่ในแถบเขียวด้านบน (เจ้าของสั่ง 18 ต.ค. 69: เดิมขึ้นสองปุ่มซ้ำกัน) */}
        {!(justOpened&&justOpened.id===selTable.id)&&<button onClick={printSelQR} style={{display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:9,border:`1px solid ${C.line}`,background:C.white,cursor:"pointer",fontSize:12,fontFamily:"'Sarabun',sans-serif",fontWeight:600,color:C.ink2}}>🖨 พิมพ์ QR โต๊ะนี้</button>}
        {!selOrder?.id&&<button onClick={()=>reissueTableQR(selTable)} title="เปลี่ยนรหัส QR ของโต๊ะว่างนี้ — QR เดิมทุกใบใช้ไม่ได้ทันที" style={{display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:9,border:`1px dashed ${C.line}`,background:C.white,cursor:"pointer",fontSize:12,fontFamily:"'Sarabun',sans-serif",fontWeight:600,color:C.ink3}}>🔄 ออก QR ใหม่</button>}
      </div>
      <POSOrderPanel table={selTable} key={selOrder&&selOrder.id!=null?"o"+selOrder.id:"t"+selTable.id} existingOrder={selOrder}menus={menus} reloadMenus={reloadMenus} branch={currentBranch} currentUser={currentUser} printers={printers} shift={shift} posSettings={posSettings} promotions={promotions} onCashChange={setChangeDlg} onClose={()=>{setSelTable(null);setSelOrder(null);}} onDone={()=>loadAll({silent:true})}/>
    </Modal>}
    {/* ── เงินทอน ── ปิดบิลเงินสดเสร็จแล้ว โต๊ะว่างแล้ว เหลืออย่างเดียวคือทอนเงิน
        ตัวเลขใหญ่ที่สุดบนจอคือยอดที่ต้องทอน เพราะนั่นคือสิ่งเดียวที่ต้องทำต่อ */}
    {/* ── ป็อปอัพ QR โต๊ะ ── ลิงก์เดียวกับที่พิมพ์ลงกระดาษ (tableScanUrl ตัวเดียว)
        ขึ้นทันทีที่กด ไม่ผูกกับผลการพิมพ์ — พิมพ์ไม่ออกก็ยังเช็คหน้าลูกค้าได้ */}
    {qrPeek&&<div onClick={e=>{if(e.target===e.currentTarget)setQrPeek(null);}} style={{position:"fixed",inset:0,background:"rgba(15,23,42,.78)",zIndex:7300,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:C.white,borderRadius:22,width:"100%",maxWidth:"min(94vw,380px)",overflow:"hidden",fontFamily:"'Sarabun',sans-serif",boxShadow:"0 30px 80px rgba(0,0,0,.5)",textAlign:"center"}}>
        <div style={{padding:"18px 20px 6px"}}>
          <div style={{fontSize:13,fontWeight:800,color:C.ink3}}>มุมมองลูกค้า</div>
          <div style={{fontSize:30,fontWeight:900,color:C.ink,lineHeight:1.15}}>โต๊ะ {qrPeek.table&&qrPeek.table.table_number}</div>
        </div>
        <div style={{padding:"10px 20px 4px",display:"flex",justifyContent:"center"}}>
          {!qrPeek.url
            ?<div style={{width:"min(66vw,260px)",height:"min(66vw,260px)",borderRadius:12,border:`1.5px dashed ${C.line}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,color:C.ink3}}>กำลังเตรียม QR…</div>
          :!qrPeekErr
            ?<img src={`https://api.qrserver.com/v1/create-qr-code/?size=520x520&data=${encodeURIComponent(qrPeek.url)}&margin=12`}
                alt={"QR โต๊ะ "+(qrPeek.table&&qrPeek.table.table_number)} onError={()=>setQrPeekErr(true)}
                style={{width:"min(66vw,260px)",height:"min(66vw,260px)",borderRadius:12,border:`1px solid ${C.line}`,background:C.white}}/>
            :<div style={{width:"min(66vw,260px)",height:"min(66vw,260px)",borderRadius:12,border:`1.5px dashed ${C.line}`,display:"flex",alignItems:"center",justifyContent:"center",padding:18,fontSize:13,color:C.ink3,lineHeight:1.7}}>
              โหลดรูป QR ไม่ได้ (เน็ตสะดุด)<br/>ใช้ลิงก์ด้านล่างเปิดดูแทนได้
            </div>}
        </div>
        <div style={{padding:"8px 22px 4px",fontSize:13,color:C.ink2,lineHeight:1.7}}>
          เอามือถือสแกน เพื่อดูหน้าที่ลูกค้าเห็นจริง<br/>
          <span style={{fontSize:12,color:C.ink4}}>QR ตัวเดียวกับที่พิมพ์ออกไป</span>
        </div>
        {qrPeek.url&&<a href={qrPeek.url} target="_blank" rel="noopener noreferrer"
          style={{display:"inline-block",margin:"6px 0 2px",fontSize:12.5,fontWeight:800,color:C.blue,textDecoration:"underline"}}>เปิดหน้าลูกค้าบนเครื่องนี้ ↗</a>}
        <div style={{padding:"12px 20px 20px"}}>
          <button onClick={()=>setQrPeek(null)} style={{width:"100%",padding:"14px",borderRadius:14,border:"none",background:C.ink,color:C.white,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:15.5,fontWeight:900}}>ปิด</button>
        </div>
      </div>
    </div>}
    {changeDlg&&<div style={{position:"fixed",inset:0,background:"rgba(15,23,42,.8)",zIndex:7200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:C.white,borderRadius:22,width:"100%",maxWidth:"min(94vw,400px)",overflow:"hidden",fontFamily:"'Sarabun',sans-serif",boxShadow:"0 30px 80px rgba(0,0,0,.5)",textAlign:"center"}}>
        <div style={{padding:"22px 20px 8px"}}>
          <div style={{fontSize:38,lineHeight:1}}>{changeDlg.change>0?"💵":"✅"}</div>
          <div style={{fontSize:13,fontWeight:800,color:C.ink3,marginTop:8}}>โต๊ะ {changeDlg.table} · ปิดบิลเรียบร้อย</div>
          <div style={{fontSize:15,fontWeight:900,color:changeDlg.change>0?C.brand:C.green,marginTop:14}}>
            {changeDlg.change>0?"เงินทอนให้ลูกค้า":"รับเงินพอดี — ไม่มีเงินทอน"}
          </div>
          {changeDlg.change>0&&<div style={{fontSize:56,fontWeight:900,color:C.brand,lineHeight:1.1,marginTop:2}}>
            ฿{changeDlg.change.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}
          </div>}
          <div style={{fontSize:12.5,color:C.ink4,marginTop:10,lineHeight:1.7}}>
            รับมา ฿{(+changeDlg.received||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}
            {" · "}ยอดบิล ฿{(+changeDlg.total||0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}
          </div>
        </div>
        <div style={{padding:"14px 20px 20px"}}>
          <button onClick={()=>setChangeDlg(null)} style={{width:"100%",padding:"15px",borderRadius:14,border:"none",background:C.green,color:C.white,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:16,fontWeight:900}}>รับทราบ</button>
        </div>
      </div>
    </div>}
    {moveFrom&&<MoveTableModal from={moveFrom.table} order={moveFrom.order} tables={tables} activeOrders={activeOrders} branch={currentBranch} currentUser={currentUser}
      onClose={()=>setMoveFrom(null)} onDone={()=>{setMoveFrom(null);setSelTable(null);setSelOrder(null);loadAll({silent:true});}}/>}
    {showPrinters&&<PrinterStatusModal currentBranch={currentBranch} menus={menus} reloadMenus={reloadMenus} onClose={()=>setShowPrinters(false)} onTogglePrintStation={v=>setPS(v)} printStation={printStation} canAdmin={posAcc.admin}/>}
    {showReceipt&&posAcc.settings&&<ReceiptSettingsModal currentBranch={currentBranch} currentUser={currentUser} onClose={()=>setShowReceipt(false)} onSaved={reloadPosSettings}/>}
  </div>;
}

// ══════════════════════════════════════════════════════
// ── PRINTER STATUS + ADD-BY-IP (from the sale screen) ──
// ══════════════════════════════════════════════════════
// Lightweight printer panel for cashiers: see each printer online/offline and
// add a network printer by typing its IP. (Full routing/categories stay in the
// manager back office.)
// canAdmin=false (คนเข้าด้วย PIN / ไม่มีสิทธิ์ตั้งค่าหรือจัดการ POS): ซ่อนค้นหา/เพิ่ม/ลบเครื่อง และล็อกติ๊กใบเสร็จ/ลิ้นชัก
// ส่วนทดสอบพิมพ์ เช็คสถานะ ตาราง 🧭 และย้ายหมวดตอนเครื่องดับกลางร้าน ยังใช้ได้ทุกคน (ไม่ต้องรอผู้จัดการ)
function PrinterStatusModal({currentBranch,menus=[],reloadMenus,onClose,printStation=false,onTogglePrintStation,canAdmin=false}){
  const lbl={display:"block",fontSize:12,fontWeight:600,color:C.ink2,marginBottom:5,fontFamily:"'Sarabun',sans-serif"};
  const[printers,setPrinters]=useState([]);
  const[loading,setLoading]=useState(true);
  const[status,setStatus]=useState({});   // id -> 'testing'|'online'|'offline'|'bt'
  const[form,setForm]=useState({name:"",ip:"",port:9100});
  const[saving,setSaving]=useState(false);
  const[searched,setSearched]=useState(false);   // กด "ค้นหาเครื่องพิมพ์" แล้ว = แสดงทุกเครื่องในวง LAN (รวมที่เคยซ่อน/ลบ)
  const[searching,setSearching]=useState(false);
  const[rechecking,setRechecking]=useState(false);   // กำลังกด "เช็คสถานะใหม่" (รอ agent เช็คสด)
  const[settingsP,setSettingsP]=useState(null);      // เครื่องที่เปิดป๊อบอัพ "กำหนดการพิมพ์" อยู่ (null=ปิด)
  const[sName,setSName]=useState("");                // ชื่อที่กำลังแก้
  const[sCats,setSCats]=useState([]);
  // หมวดที่เครื่องนี้รับ: [] = ไม่รับอะไรเลย · [ชื่อ] = เฉพาะหมวดนั้น
  // ไม่มี catch-all แล้ว — ติ๊กคือตัวตัดสินอย่างเดียว ไม่มีสถานะซ่อนทับ
  const[sOverride,setSOverride]=useState({});        // menu_id → printer_id (ปักหมุดเมนูเฉพาะให้ออกเครื่องนี้)
  const[sOpenCats,setSOpenCats]=useState(()=>new Set());  // หมวดที่กางดูรายเมนู
  const[sSaving,setSSaving]=useState(false);
  const[sRcpt,setSRcpt]=useState(false);            // เครื่องนี้เป็นเครื่องพิมพ์ใบเสร็จด้วยหรือไม่ (description.rcpt)
  const[sDraw,setSDraw]=useState(false);           // ลิ้นชักเก็บเงินเสียบสาย RJ11 อยู่กับเครื่องนี้ (description.dw)
  const aliveRef=useRef(true);   // กันอัปเดต state หลังปิด modal (ระหว่างวนค้นหา 15 วินาที)
  useEffect(()=>()=>{aliveRef.current=false;},[]);
  const[station,setStation]=useState(printStation||isPrintStation(currentBranch.id));
  function toggleStation(){const v=!station;setStation(v);setPrintStation(currentBranch.id,v);onTogglePrintStation&&onTogglePrintStation(v);}
  async function load(){setLoading(true);try{const all=await api.getAllPrinters();if(aliveRef.current)setPrinters((all||[]).filter(p=>p.branch_id==null||+p.branch_id===+currentBranch.id));}catch(e){console.error("loadPrinters",e);}if(aliveRef.current)setLoading(false);}
  async function loadSilent(){try{const all=await api.getAllPrinters();if(aliveRef.current)setPrinters((all||[]).filter(p=>p.branch_id==null||+p.branch_id===+currentBranch.id));}catch(e){console.error("loadPrinters",e);}}
  async function findPrinters(){
    // คำสั่งสแกนฝากไว้ในแถวเครื่องพิมพ์ของสาขา ตัวพิมพ์อ่านจากตรงนั้น
    // ไม่มีแถวสักแถว = ไม่มีที่ให้ฝาก และแปลว่ายังไม่เคยมีตัวพิมพ์รายงานตัวที่สาขานี้
    if(!(printers||[]).length){
      setSearched(true);
      posToast("ยังไม่มีตัวพิมพ์ที่สาขานี้ — ต้องรันตัวพิมพ์บนเครื่องที่ต่อวงเดียวกับเครื่องพิมพ์ก่อน");
      return;
    }
    setSearched(true);setSearching(true);
    // สั่งให้ตัวพิมพ์ (agent) สแกนหาเครื่องใหม่ในวง LAN "ทันที" (ไม่รอรอบสแกนอัตโนมัติ 2 นาที)
    const at=Date.now();
    try{await Promise.all((printers||[]).map(p=>{let d={};try{d=JSON.parse(p.description||"{}");}catch{}return api.updatePrinter(p.id,{description:JSON.stringify({...d,scanReq:at})});}));}catch{}
    const beforeIds=new Set((printers||[]).map(p=>p.id));
    let foundNew=false;
    // ดึงซ้ำทุก 2 วิ จนกว่าจะเจอเครื่องใหม่ หรือครบ ~28 วิ (agent สแกน ~10 วิ) — หยุดทันทีถ้าปิด modal
    for(let i=0;i<14&&aliveRef.current;i++){
      await new Promise(r=>setTimeout(r,2000));
      let all=null;try{all=await api.getAllPrinters();}catch{}
      if(all&&aliveRef.current){
        const mine=all.filter(p=>p.branch_id==null||+p.branch_id===+currentBranch.id);
        setPrinters(mine);
        if(mine.some(p=>!beforeIds.has(p.id))){foundNew=true;break;}
      }
    }
    if(aliveRef.current){setSearching(false);if(foundNew)posToast("✅ พบเครื่องพิมพ์ใหม่ในเครือข่าย!","ok");}
  }
  useEffect(()=>{load();},[]);
  // เช็คสถานะเมื่อรายการโหลด/รีเฟรช (https = อ่าน description.on ที่ agent รายงาน · LAN = probe ตรง)
  useEffect(()=>{if(!loading)printers.forEach(p=>checkStatus(p));// eslint-disable-next-line
  },[loading,printers]);
  // รีเฟรชอัตโนมัติทุก 15 วิ ขณะเปิดหน้านี้ → จุดเขียว/แดงอัปเดตสดตามที่ตัวพิมพ์รายงาน
  useEffect(()=>{const t=setInterval(()=>{if(aliveRef.current&&!document.hidden)loadSilent();},60000);return ()=>clearInterval(t);// eslint-disable-next-line
  },[]);
  // เปิดผ่าน https (Vercel/iPad) → เบราว์เซอร์ต่อ http://printer:9100 ไม่ได้ (mixed content) → เช็ค/ทดสอบฝั่งเบราว์เซอร์ใช้ไม่ได้ จึงให้ตัวพิมพ์ (agent) จัดการแทน
  const isHttps=typeof location!=="undefined"&&location.protocol==="https:";
  async function checkStatus(p){
    const conn=getPConn(p);
    if(conn.type==="bluetooth"){setStatus(s=>({...s,[p.id]:"bt"}));return;}
    if(isHttps){   // iPad/https เช็คตรงไม่ได้ — อ่านสถานะที่ตัวพิมพ์ (agent) ping แล้วรายงานไว้ใน description.on (อัปเดตทุก 30 วิ)
      let d={};try{d=JSON.parse(p.description||"{}");}catch{}
      // ⚠️ ห้ามตัดสินจากอายุของ onAt — ตัวพิมพ์เขียน on/onAt "เฉพาะตอนสถานะเปลี่ยน"
      // (ตั้งใจ เพื่อลดจำนวนการเขียน) เครื่องที่ต่อติดนิ่งๆ มาครึ่งชั่วโมงจึงมี onAt เก่า
      // ถ้าดูอายุของมันจะขึ้น "ตัวพิมพ์อาจหยุด" ทั้งที่ทุกอย่างปกติ — ตกใจฟรี
      //
      // สัญญาณชีพของตัวพิมพ์คือ agentSeen ซึ่งเขียนทุกจังหวะหัวใจ ใช้ตัวนั้นตัดสิน
      // ตัวพิมพ์ยังหายใจ = เชื่อค่า on ตามที่มันรายงาน · ไม่หายใจ = ไม่รู้สถานะจริง
      const h=agentHealth(printers,currentBranch?.id);
      const agentOk=h.state==="ok";
      setStatus(s=>({...s,[p.id]:(agentOk&&d.on===1)?"online":"offline"}));return;
    }
    setStatus(s=>({...s,[p.id]:"testing"}));
    const ctrl=new AbortController();const tid=setTimeout(()=>ctrl.abort(),6000);
    try{
      await fetch(`http://${p.ip}:${p.port||9100}/`,{method:"POST",mode:"no-cors",cache:"no-store",headers:{"Content-Type":"application/octet-stream"},body:new Uint8Array([0x1B,0x40]),signal:ctrl.signal});
      clearTimeout(tid);setStatus(s=>({...s,[p.id]:"online"}));   // got a real (opaque) reply = definitely reachable (rare for raw printers)
    }catch(e){
      clearTimeout(tid);
      // no-cors hides the result. A network error = definitely can't reach it → OFFLINE (printer off /
      // wrong IP / คนละวง WiFi). A TIMEOUT is genuinely ambiguous — a silent reachable printer AND a
      // silently-dropped unreachable host both hang — so we say "ไม่ยืนยัน", NOT a fake "online".
      setStatus(s=>({...s,[p.id]:e.name==="AbortError"?"unknown":"offline"}));
    }
  }
  // ปุ่ม "เช็คสถานะใหม่": https → สั่งตัวพิมพ์ (agent) เช็คเดี๋ยวนี้ (เขียน pingReq) แล้วรอผล ~ไม่กี่วิ · LAN → probe ตรงเหมือนเดิม
  async function recheckStatus(){
    if(rechecking)return;
    if(!isHttps){printers.forEach(p=>checkStatus(p));return;}
    setRechecking(true);
    const before={};(printers||[]).forEach(p=>{try{before[p.id]=JSON.parse(p.description||"{}").onAt||0;}catch{}});   // จำเวลาเดิม เพื่อรู้ว่า agent อัปเดตแล้ว
    const at=Date.now();
    try{
      await Promise.all((printers||[]).filter(p=>p.ip&&getPConn(p).type!=="bluetooth").map(p=>{let d={};try{d=JSON.parse(p.description||"{}");}catch{}return api.updatePrinter(p.id,{description:JSON.stringify({...d,pingReq:at})});}));
    }catch(e){}
    // หยุดหมุน "ทันที" ที่ตัวพิมพ์ตอบกลับ (onAt ใหม่กว่าเดิม) — ไม่รอครบเวลา · เช็คทุก 0.8 วิ สูงสุด ~10 วิ
    for(let i=0;i<12&&aliveRef.current;i++){
      await new Promise(r=>setTimeout(r,800));
      let mine=null;try{const all=await api.getAllPrinters();mine=(all||[]).filter(p=>p.branch_id==null||+p.branch_id===+currentBranch.id);}catch{}
      if(mine&&aliveRef.current){
        setPrinters(mine);   // useEffect[printers] จะ re-derive จุดเขียว/แดง
        if(mine.some(p=>{try{return (JSON.parse(p.description||"{}").onAt||0)>(before[p.id]||0);}catch{return false;}}))break;
      }
    }
    if(aliveRef.current)setRechecking(false);
  }
  async function testPrint(p){
    const conn=getPConn(p);
    if(conn.type==="bluetooth"){
      setStatus(s=>({...s,[p.id]:"testing"}));
      try{await btPrint(buildTestPageESC(p.name),conn.btName);setStatus(s=>({...s,[p.id]:"online"}));posToast("🧾 ส่งหน้าทดสอบทางบลูทูธแล้ว — ดูว่ามีกระดาษออกไหม","ok");}
      catch(e){setStatus(s=>({...s,[p.id]:"offline"}));alert("❌ พิมพ์ทดสอบไม่สำเร็จ: "+(e.message||""));}
      return;
    }
    if(isHttps){   // iPad/https สั่งพิมพ์ตรงไม่ได้ → เรนเดอร์ไทยเป็นรูปภาพ (คมชัด) แล้วส่งให้ "ตัวพิมพ์ (agent)" พิมพ์ (~5 วิ) · ไม่แตะจุดสถานะ (ปล่อยให้เป็นเขียว/แดงตามที่ agent ping)
      try{
        const b64=await escposSlipRaster([
          {t:"ทดสอบพิมพ์ (รูปภาพ)",size:30,bold:true,align:"center"},
          {t:"ภาษาไทยคมชัด",size:24,align:"center"},
          {rule:true},
          {t:"ชาบูจัมโบ้ กุ้งเผา ผัดไทย",size:32,bold:true,align:"left"},
          {t:"ในวันเบาๆ + เพิ่มมาก",size:28,align:"left"},
          {rule:true},
          {t:fmtDT(),size:20,align:"center"},
        ],576);
        await api.updatePrinter(p.id,{description:cmdDesc(p,"pj",{at:Date.now(),b64,what:"ทดสอบพิมพ์"})});
        posToast("🧾 ส่งทดสอบพิมพ์ (แบบรูปภาพ ไทยคมชัด) ไปตัวพิมพ์แล้ว — กระดาษจะออกใน ~5 วินาที (ผลดูที่ งานล่าสุด ของเครื่อง)","ok");
      }catch(e){alert("ส่งคำสั่งทดสอบไม่สำเร็จ: "+(e&&e.message||e));}
      return;
    }
    setStatus(s=>({...s,[p.id]:"testing"}));
    try{
      await sendESCPOSToIP(p.ip,p.port,buildTestPageESC(p.name));
      setStatus(s=>({...s,[p.id]:"online"}));
      posToast("🧾 ส่งหน้าทดสอบไป “"+(p.name||"เครื่องพิมพ์")+"” แล้ว — ถ้ามีกระดาษออก = เชื่อมต่อได้จริง","ok");
    }catch(e){
      setStatus(s=>({...s,[p.id]:"offline"}));
      alert("❌ “"+(p.name||"เครื่องพิมพ์")+"” พิมพ์ทดสอบไม่สำเร็จ\n"+(e.message||"")+"\n\nตรวจสอบ: ไฟเครื่องพิมพ์ · สายแลน · เลข IP · อยู่ WiFi วงเดียวกับเครื่องนี้ไหม");
    }
  }
  async function add(){
    if(!canAdmin)return;   // ปุ่มซ่อนอยู่แล้ว — กันซ้ำอีกชั้น
    const name=(form.name||"").trim();const ip=(form.ip||"").trim();
    if(!name)return alert("ใส่ชื่อเครื่องพิมพ์");
    if(!/^\d{1,3}(\.\d{1,3}){3}$/.test(ip))return alert("ใส่เลข IP ให้ถูกต้อง เช่น 192.168.1.50");
    setSaving(true);
    try{
      await api.addPrinter({name,ip,port:+form.port||9100,type:"kitchen",branch_id:currentBranch.id,active:true,description:""});
      setForm({name:"",ip:"",port:9100});
      await load();
    }catch(e){alert("เพิ่มไม่สำเร็จ: "+(e&&e.message||e));}
    setSaving(false);
  }
  // จุดสถานะมีสองสีเท่านั้น: เขียว = ออนไลน์ · แดง = ออฟไลน์
  // ทุกกรณีที่ "ตอนนี้พิมพ์ไม่ได้" นับเป็นออฟไลน์หมด ไม่ว่าจะเพราะเครื่องพิมพ์ปิด
  // หรือตัวพิมพ์หยุดทำงาน — สำหรับพนักงานผลลัพธ์เหมือนกันคือต้องไปดูที่หน้างาน
  // มีสีที่สามไว้มีแต่ทำให้ลังเลว่าต้องทำอะไร
  const stView=(st)=>st==="online"
    ?{c:C.green,bg:C.greenLight,t:"🟢 ออนไลน์"}
    :{c:C.red,bg:C.redLight,t:"🔴 ออฟไลน์"};
  // งานล่าสุดที่เครื่องนี้ทำจริง — ตอบคำถาม "กดสั่งพิมพ์แล้วถึงเครื่องหรือยัง" ได้ทันที
  // ตัวพิมพ์จดไว้ตอนล้างคำสั่งที่ทำเสร็จ (เขียนอยู่แล้ว ไม่มีการเขียนเพิ่ม)
  // ใบครัวอัตโนมัติไม่จดที่นี่ (ไม่เพิ่มการเขียน) — ข้อความต้องบอกว่าเป็น "คำสั่งจากแอป" ไม่งั้นเครื่องครัวที่พิมพ์ทั้งคืนดูเหมือนไม่ได้ทำอะไร
  const JOB_LABEL={rp:"พิมพ์ซ้ำ/ใบยกเลิก/ย้ายโต๊ะ",qr:"QR โต๊ะ",pj:"ใบเสร็จ",dk:"เปิดลิ้นชัก",tp:"ทดสอบพิมพ์"};
  const lastJobText=(p)=>{
    let d={};try{d=JSON.parse(p.description||"{}");}catch{}
    const j=d.lastJob;if(!j||!j.at)return "";
    let tm="";try{tm=new Date(+j.at).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",timeZone:"Asia/Bangkok"});}catch{}
    // ตัวพิมพ์ v46+ บอกผลจริง (ok:false + เหตุ) · ok:true ของตัวพิมพ์รุ่นเก่าเป็นจริงเสมอแม้ส่งไม่ผ่าน
    // จึงขึ้นเฉพาะตอนไม่ออก — ไม่ขึ้น ✅ ที่อาจหลอกตา
    const res=j.ok===false?" — ❌ ไม่ออก: "+printErrText(j.err||{}):"";
    return "🖨 คำสั่งล่าสุดจากแอป (ไม่นับใบครัวอัตโนมัติ): "+((j.kind==="pj"&&j.what)?j.what:(JOB_LABEL[j.kind]||j.kind||""))+" "+tm+res;
  };
  const activePrinters=printers.filter(p=>p.active!==false);
  const isIgnored=(p)=>{try{return JSON.parse(p.description||"{}").ig===1;}catch{return false;}};
  const notAdded=printers.filter(p=>p.active===false);
  const discovered=searched?notAdded:notAdded.filter(p=>!isIgnored(p));   // กดค้นหาแล้วให้เห็นเครื่องที่เคยซ่อน/ลบด้วย
  // เพิ่มใช้งานเครื่องที่ค้นเจอ — รีเซ็ตชื่อเป็นค่าเริ่มต้น (เลข IP) เสมอ เผื่อเป็นเครื่องที่เคยลบแล้วชื่อเดิมค้างอยู่ · ผู้ใช้ค่อยตั้งชื่อใหม่ตามตำแหน่งจริง
  async function addDiscovered(p){if(!canAdmin)return;try{await api.updatePrinter(p.id,{name:`เครื่องพิมพ์ ${p.ip||""}`.trim(),active:true,description:""});await load();posToast("✅ เพิ่มเครื่องพิมพ์เข้าระบบแล้ว — ตั้งชื่อตามจุดที่วางได้ที่ \"กำหนดการพิมพ์\"");}catch(e){alert("เพิ่มไม่สำเร็จ: "+(e&&e.message||e));}}
  async function ignoreDiscovered(p){if(!canAdmin)return;try{await api.updatePrinter(p.id,{description:JSON.stringify({d:1,ig:1})});await load();}catch(e){alert("ไม่สำเร็จ: "+(e&&e.message||e));}}
  // หมวดหมู่คุมจากครัวกลางที่เดียว ทุกสาขาเห็นชุดเดียวกัน (menuCatOf อ่านจาก menus.category)
  // เมนูที่ยังไม่ได้ตั้งหมวดของสาขานี้จะไม่ขึ้นในตัวเลือก และจะพิมพ์ออกเครื่อง "พิมพ์ทุกหมวด" (catch-all)
  const effCat=menuCatOf;
  // เรียงตามพยัญชนะไทยทั้งหัวหมวดและเมนูข้างใน — 26 หมวด/169 เมนู ถ้าไม่เรียงคือไล่หาไม่เจอ
  // เห็นเฉพาะหมวดที่สาขานี้มีเมนูจริง — เหมือนจอตั้งค่าเครื่องพิมพ์หลังบ้าน ทั้งสองจอต้องตรงกัน
  const branchMenus=useMemo(()=>(menus||[]).filter(m=>menuVisibleAt(m,currentBranch&&currentBranch.id)),[menus,currentBranch]);
  const branchCategories=useMemo(()=>{const s=new Set();branchMenus.forEach(m=>{const e=effCat(m);if(e)s.add(e);});return [...s].sort(thCmp);},[branchMenus]);
  // .filter() คืนอาร์เรย์ใหม่อยู่แล้ว .sort() ตรงนี้จึงไม่ไปสลับลำดับ menus ตัวจริง
  const menusInCat=(c)=>branchMenus.filter(m=>effCat(m)===c).sort((a,b)=>thCmp(a.name,b.name));
  // สรุปว่า "หมวดนี้ออกเครื่องไหน" จากค่าที่ตั้งไว้จริง — หมวดที่ไม่มีเครื่องรับต้องเด้งขึ้นบนสุด
  const routing=useMemo(()=>{
    const byCat=new Map();
    for(const m of branchMenus){
      const c=effCat(m);if(!c)continue;
      if(!byCat.has(c))byCat.set(c,{cat:c,n:0,dead:0,set:new Set()});
      const r=byCat.get(c);r.n++;
      const hit=printersForMenu(m,printers);
      if(hit.length)hit.forEach(p=>r.set.add(p.name));else r.dead++;
    }
    return [...byCat.values()].map(r=>({...r,names:[...r.set]}))
      .sort((a,b)=>(b.dead>0?1:0)-(a.dead>0?1:0)||thCmp(a.cat,b.cat));
  },[branchMenus,printers]);
  const deadCount=routing.reduce((s,r)=>s+r.dead,0);
  function openSettings(p){
    setSettingsP(p);setSName(p.name||"");
    // เครื่องเก่าที่เก็บ categories=null คือ "รับทุกหมวด" อยู่เดิม — เปิดมาให้ติ๊กครบทุกหมวด
    // เพื่อให้เห็นตรงกับที่มันทำอยู่จริง ไม่ใช่โชว์ว่าไม่ได้ติ๊กอะไรแต่แอบพิมพ์ทุกอย่าง
    setSCats(Array.isArray(p.categories)?[...p.categories]:[...branchCategories]);
    let dd={};try{dd=JSON.parse(p.description||"{}");}catch{}setSRcpt(dd.rcpt===1);setSDraw(dd.dw===1);
    const ov={};(menus||[]).forEach(m=>{if(m.printer_id)ov[m.id]=+m.printer_id;});setSOverride(ov);setSOpenCats(new Set());
  }
  function toggleSOpenCat(c){setSOpenCats(prev=>{const n=new Set(prev);if(n.has(c))n.delete(c);else n.add(c);return n;});}
  async function saveSettings(){
    const p=settingsP;if(!p)return;
    const name=(sName||"").trim();if(!name)return alert("ใส่ชื่อเครื่องพิมพ์");
    setSSaving(true);
    try{
      // อ่าน description ล่าสุดก่อนรวม flag ใบเสร็จ (กันทับคำสั่งพิมพ์ tp/rp/qr/pj ที่อาจถูกเขียนมาระหว่างเปิดหน้าตั้งค่า)
      let fresh=p;try{const all=await api.getAllPrinters();const f=(all||[]).find(x=>+x.id===+p.id);if(f)fresh=f;}catch{}
      let dd={};try{dd=JSON.parse(fresh.description||"{}");}catch{}
      // ไม่มีสิทธิ์ = ไม่แตะธงใบเสร็จ/ลิ้นชักเลย ใช้ค่าล่าสุดในฐานข้อมูลตามเดิม (ย้ายหมวดอย่างเดียว)
      if(canAdmin){
        if(sRcpt)dd.rcpt=1;else delete dd.rcpt;
        if(sDraw)dd.dw=1;else delete dd.dw;
      }
      // เก็บเป็นรายการเสมอ ไม่เขียน null อีกแล้ว — null คือ catch-all ซึ่งเลิกใช้
      await api.updatePrinter(p.id,{name,categories:sCats,description:JSON.stringify(dd)});
      const ups=[];(menus||[]).forEach(m=>{const nw=sOverride[m.id]||null;const ol=m.printer_id||null;if(String(nw)!==String(ol))ups.push(api.updateMenu(m.id,{printer_id:nw}));});
      if(ups.length)await Promise.all(ups);
      await load();if(reloadMenus)await reloadMenus();
      if(aliveRef.current){setSettingsP(null);posToast("บันทึกการกำหนดการพิมพ์แล้ว");}
    }catch(e){alert("บันทึกไม่สำเร็จ: "+(e&&e.message||e));}
    if(aliveRef.current)setSSaving(false);
  }
  return <Modal title="🖨 เครื่องพิมพ์ & สถานะการเชื่อมต่อ" onClose={onClose} wide>
    {loading?<Loading text="โหลดเครื่องพิมพ์..."/>:<>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10,flexWrap:"wrap",gap:8}}>
        <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:13,color:C.ink3}}>เครื่องพิมพ์ของสาขา <b style={{color:C.ink}}>{currentBranch.name}</b> ({activePrinters.length})</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          {canAdmin&&<Btn v="info" onClick={findPrinters} disabled={searching} icon={I.search} s={{padding:"6px 12px",fontSize:12}}>{searching?"⟳ กำลังค้นหา...":"ค้นหาเครื่องพิมพ์"}</Btn>}
          <Btn v="ghost" onClick={recheckStatus} disabled={rechecking} icon={I.refresh} s={{padding:"6px 12px",fontSize:12}}>{rechecking?"⟳ กำลังเช็ค...":"เช็คสถานะใหม่"}</Btn>
        </div>
      </div>
      {activePrinters.length===0?<div style={{textAlign:"center",padding:"28px 16px",color:C.ink4,fontFamily:"'Sarabun',sans-serif",background:C.bg,borderRadius:12,marginBottom:14}}><Ic d={I.print} s={40} c={C.line}/><p style={{marginTop:8,fontSize:13,lineHeight:1.75,whiteSpace:"pre-line",maxWidth:520,marginLeft:"auto",marginRight:"auto",textAlign:"left"}}>{printers.length===0?"ยังไม่มีตัวพิมพ์ (Print Agent) ที่สาขานี้\n\nแท็บเล็ตกับเบราว์เซอร์สแกนหาเครื่องพิมพ์ในวง LAN เองไม่ได้ — ต้องมีเครื่องสักตัวที่ต่อ WiFi/LAN วงเดียวกับเครื่องพิมพ์ (มือถือ Android ลง Termux หรือคอมพิวเตอร์) รันตัวพิมพ์ค้างไว้ เป็นคนสแกนและสั่งพิมพ์ให้\n\nพอตัวพิมพ์ทำงานแล้ว เครื่องพิมพ์ที่เสียบสายไว้จะขึ้นเองภายใน ~2 นาที (หรือจะใส่ IP เองด้านล่างก็ได้)":'ยังไม่มีเครื่องพิมพ์ที่ใช้งาน — เพิ่มจาก "พบในเครือข่าย" ด้านล่าง หรือใส่ IP เอง'}</p></div>
      :<div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:16}}>
        {activePrinters.map(p=>{const conn=getPConn(p);const sv=stView(status[p.id]);const catLabel=(p.categories===undefined||p.categories===null)?"ทุกหมวด":(p.categories.length?p.categories.join(", "):"— ยังไม่กำหนด —");const ovCount=(menus||[]).filter(m=>+m.printer_id===+p.id).length;return <div key={p.id} style={{display:"flex",alignItems:"center",gap:12,padding:"11px 14px",border:`1px solid ${C.line}`,borderRadius:12,background:C.white,flexWrap:"wrap"}}>
          <span style={{width:11,height:11,borderRadius:"50%",background:sv.c,flexShrink:0,boxShadow:status[p.id]==="online"?`0 0 0 3px ${C.green}33`:"none"}}/>
          <div style={{minWidth:0,flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:7,flexWrap:"wrap"}}><span style={{fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:800,color:C.ink}}>{p.name}</span>{isReceiptPrinter(p)&&<span style={{fontSize:10,fontWeight:800,color:C.green,background:C.greenLight,border:`1px solid ${C.green}55`,borderRadius:20,padding:"1px 8px",fontFamily:"'Sarabun',sans-serif"}}>🧾 ใบเสร็จ</span>}</div>
            <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11.5,color:C.ink4}}>{conn.type==="bluetooth"?`บลูทูธ${conn.btName?" · "+conn.btName:""}`:`${p.ip||"-"}:${p.port||9100}`} · พิมพ์: {catLabel}{ovCount>0?` · +${ovCount} เมนู`:""}</div>
            {lastJobText(p)&&<div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11.5,color:C.ink3,fontWeight:700}}>{lastJobText(p)}</div>}
          </div>
          <span style={{fontSize:11.5,fontWeight:800,color:sv.c,background:sv.bg,border:`1px solid ${sv.c}44`,borderRadius:20,padding:"3px 12px",fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap"}}>{sv.t}</span>
          <button onClick={()=>openSettings(p)} title="กำหนดหมวดหมู่/เมนู ที่พิมพ์ออกเครื่องนี้ + แก้ชื่อ" style={{background:C.blueLight,border:`1px solid ${C.blue}55`,borderRadius:8,padding:"6px 12px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:700,color:C.blue,whiteSpace:"nowrap"}}>🖨️ กำหนดการพิมพ์</button>
          <button onClick={()=>testPrint(p)} title="พิมพ์หน้าทดสอบจริง — ยืนยันชัวร์ที่สุด" style={{background:C.brand,border:"none",borderRadius:8,padding:"6px 12px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:800,color:C.white,whiteSpace:"nowrap"}}>🧾 ทดสอบพิมพ์</button>
          {canAdmin&&<button onClick={async()=>{if(await confirmDlg({title:`🗑 นำเครื่องพิมพ์ "${p.name}" ออก?`,message:`นำเครื่องพิมพ์ "${p.name}" (${p.ip||"-"}) ออกจากการใช้งาน?\n\n⚠️ เมนูที่ส่งมาเครื่องนี้จะไม่ถูกพิมพ์จนกว่าจะเพิ่มกลับ\n\n💡 นำกลับมาได้ทุกเมื่อด้วยปุ่ม "ค้นหาเครื่องพิมพ์"`,confirmLabel:"นำออก",cancelLabel:"ยกเลิก",danger:true})){try{await api.updatePrinter(p.id,{active:false,description:JSON.stringify({d:1,ig:1})});await load();posToast("นำเครื่องพิมพ์ออกแล้ว — กด \"ค้นหาเครื่องพิมพ์\" เพื่อนำกลับ");}catch(e){alert("ไม่สำเร็จ: "+(e&&e.message||e));}}}} title="นำเครื่องพิมพ์ออก (นำกลับได้ด้วยปุ่มค้นหา)" style={{background:C.redLight,border:`1px solid #FCA5A5`,borderRadius:8,padding:"6px 10px",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}><Ic d={I.trash} s={14} c={C.red}/></button>}
        </div>;})}
      </div>}
      {/* ── หมวดไหนออกเครื่องไหน ──────────────────────────────────────────
          ตอบคำถาม "ทำไมเมนูนี้ไม่ออก" ได้ในจอเดียว โดยไม่ต้องไล่เปิดทีละเครื่อง
          เหตุจริง 9 ก.ย. 69: เจ้าของแจ้ง "น้ำเปล่าปริ้นไม่ออก" — ของจริงคือหมวด "น้ำ"
          ถูกตั้งให้ออกเครื่องแคชเชียร์เครื่องเดียว ใบจึงไปโผล่อีกที่ ครัวไม่มีทางรู้
          และถ้าไม่มีเครื่องไหนรับหมวดนั้นเลย ใบจะเงียบหายไปโดยไม่มีข้อความเตือนที่ไหน */}
      {routing.length>0&&<div style={{marginBottom:16}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6,flexWrap:"wrap"}}>
          <div style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>🧭 หมวดไหนออกเครื่องไหน</div>
          <div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>ตามที่ตั้งไว้จริงในตอนนี้ · เฉพาะเมนูที่สาขานี้ขาย</div>
        </div>
        {deadCount>0&&<div style={{marginBottom:8,padding:"10px 12px",borderRadius:10,background:C.redLight,border:`1px solid ${C.red}55`,fontFamily:"'Sarabun',sans-serif"}}>
          <div style={{fontSize:12.5,fontWeight:800,color:C.red}}>⚠️ {deadCount} เมนู ไม่มีเครื่องพิมพ์รับเลย — สั่งเข้ามาแล้วจะไม่มีใบออกที่ไหนทั้งนั้น</div>
          <div style={{fontSize:11,color:C.red,marginTop:3,opacity:.9}}>กด "กำหนดการพิมพ์" ที่เครื่องที่ต้องการ แล้วติ๊กหมวดที่ขึ้นสีแดงด้านล่าง</div>
        </div>}
        <div style={{display:"flex",flexDirection:"column",gap:4,maxHeight:"34vh",overflowY:"auto",paddingRight:2}}>
          {routing.map(r=><div key={r.cat} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 11px",borderRadius:9,flexWrap:"wrap",
            background:r.dead?C.redLight:C.bg,border:`1px solid ${r.dead?C.red+"44":C.line}`}}>
            <span style={{fontFamily:"'Sarabun',sans-serif",fontSize:12.5,fontWeight:800,color:r.dead?C.red:C.ink,minWidth:0}}>{r.cat}</span>
            <span style={{fontFamily:"'Sarabun',sans-serif",fontSize:11,color:C.ink4}}>{r.n} เมนู</span>
            <span style={{marginLeft:"auto",fontFamily:"'Sarabun',sans-serif",fontSize:11.5,fontWeight:700,color:r.dead?C.red:C.ink3,textAlign:"right"}}>
              {r.dead
                ? (r.names.length ? `❌ ${r.dead} เมนูไม่มีเครื่องรับ · ที่เหลือออก ${r.names.join(", ")}` : "❌ ไม่มีเครื่องรับ")
                : `→ ${r.names.join(", ")}`}
            </span>
          </div>)}
        </div>
      </div>}
      {settingsP&&<Modal title={`🖨️ กำหนดการพิมพ์ — ${settingsP.name}`} onClose={()=>setSettingsP(null)} extraWide>
        <label style={lbl}>ชื่อเครื่องพิมพ์ (แก้ไขได้)</label>
        <input value={sName} onChange={e=>setSName(e.target.value)} placeholder="เช่น ครัวร้อน · ครัวเย็น · แคชเชียร์" style={iS}/>
        {!canAdmin&&<div style={{margin:"12px 0 2px",padding:"9px 12px",borderRadius:10,background:C.bg,border:`1px dashed ${C.line}`,fontSize:11.5,color:C.ink3,fontFamily:"'Sarabun',sans-serif",lineHeight:1.6}}>🔒 ตั้งเครื่องใบเสร็จ/ลิ้นชัก ทำได้เฉพาะผู้จัดการ · ย้ายหมวด/เมนูให้ออกเครื่องนี้ (ตอนเครื่องอื่นดับ) ทำได้ตามปกติ</div>}
        <label style={{display:"flex",alignItems:"center",gap:11,margin:"13px 0 4px",padding:"11px 14px",borderRadius:10,border:`1.5px solid ${sRcpt?C.green:C.line}`,background:sRcpt?C.greenLight:C.white,cursor:canAdmin?"pointer":"not-allowed",opacity:canAdmin?1:.6}}>
          <input type="checkbox" checked={sRcpt} disabled={!canAdmin} onChange={e=>{if(canAdmin)setSRcpt(e.target.checked);}} style={{accentColor:C.green,width:19,height:19,cursor:canAdmin?"pointer":"not-allowed",flexShrink:0}}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:13.5,fontWeight:800,color:sRcpt?C.green:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>🧾 ใช้เป็นเครื่องพิมพ์ใบเสร็จ</div>
            <div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",lineHeight:1.5}}>เช็คบิล/พิมพ์ใบเสร็จซ้ำ/แบ่งจ่าย จะพิมพ์ออกเครื่องนี้ · ติ๊กได้หลายเครื่อง — ใบเสร็จจะออกทุกเครื่องที่เลือก</div>
          </div>
        </label>
        <label style={{display:"flex",alignItems:"center",gap:11,margin:"6px 0 4px",padding:"11px 14px",borderRadius:10,border:`1.5px solid ${sDraw?C.brand:C.line}`,background:sDraw?C.brandLight:C.white,cursor:canAdmin?"pointer":"not-allowed",opacity:canAdmin?1:.6}}>
          <input type="checkbox" checked={sDraw} disabled={!canAdmin} onChange={e=>{if(canAdmin)setSDraw(e.target.checked);}} style={{accentColor:C.brand,width:19,height:19,cursor:canAdmin?"pointer":"not-allowed",flexShrink:0}}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:13.5,fontWeight:800,color:sDraw?C.brand:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>💵 ลิ้นชักเก็บเงินต่อกับเครื่องนี้</div>
            <div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",lineHeight:1.5}}>เสียบสายลิ้นชัก (RJ11) ไว้ที่เครื่องนี้ — กดปุ่ม 💰 เงินในลิ้นชัก แล้วลิ้นชักจะเด้งออกเอง · ไม่ติ๊กเลยสักเครื่อง = สั่งไปที่เครื่องพิมพ์ใบเสร็จ</div>
          </div>
        </label>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",margin:"15px 0 8px",flexWrap:"wrap",gap:8}}>
          <div style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>📂 หมวดหมู่ / เมนู ที่พิมพ์ออกเครื่องนี้</div>
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            <button onClick={()=>setSCats([...branchCategories])} style={{padding:"4px 10px",borderRadius:7,border:`1px solid ${C.line}`,background:C.white,color:C.ink3,cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>เลือกทุกหมวด</button>
            <button onClick={()=>setSCats([])} style={{padding:"4px 10px",borderRadius:7,border:`1px solid ${C.line}`,background:C.white,color:C.ink3,cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif"}}>ล้าง</button>
          </div>
        </div>
        {branchCategories.length===0
            ?<div style={{padding:24,textAlign:"center",color:C.ink4,fontSize:13,fontFamily:"'Sarabun',sans-serif",lineHeight:1.6}}>ยังไม่มีหมวดหมู่ในสาขานี้ — ไปสร้างหมวดหมู่ที่หน้า "เมนู" ก่อน แล้วค่อยกลับมาเลือก</div>
            :<>
              <div style={{display:"flex",flexDirection:"column",gap:8,maxHeight:"50vh",overflowY:"auto",paddingRight:2}}>
                {branchCategories.map(c=>{const has=sCats.includes(c);const catMenus=menusInCat(c);const isOpen=sOpenCats.has(c);const pinHere=catMenus.filter(m=>{const cur=sOverride[m.id];return cur!=null&&+cur===+settingsP.id;}).length;
                  // ติ๊กครบทุกเมนู → หัวหมวดติ๊กให้อัตโนมัติ (รู้ว่าเลือกครบทั้งหมวด) · ติ๊กบางส่วน → ขีดครึ่ง (–) · ติ๊กหัวหมวด=เลือกทั้งหมวด · ปลด=ล้างทั้งหมวด
                  const allHere=catMenus.length>0&&pinHere===catMenus.length;const checked=has||allHere;const indet=!checked&&pinHere>0;
                  const toggleCatMaster=()=>{if(checked){setSCats(prev=>(prev||[]).filter(x=>x!==c));setSOverride(prev=>{const n={...prev};catMenus.forEach(m=>{if(n[m.id]!=null&&+n[m.id]===+settingsP.id)n[m.id]=null;});return n;});}else{setSCats(prev=>{const cur=prev===null?[]:prev;return cur.includes(c)?cur:[...cur,c];});}};
                  return <div key={c} style={{border:`1.5px solid ${checked?C.blue:(indet?`${C.blue}66`:C.line)}`,borderRadius:10,overflow:"hidden",background:checked?C.blueLight:C.white,flexShrink:0}}>
                  <div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px"}}>
                    <input type="checkbox" checked={checked} ref={el=>{if(el)el.indeterminate=indet;}} onChange={toggleCatMaster} style={{accentColor:C.blue,width:18,height:18,cursor:"pointer",flexShrink:0}}/>
                    <div style={{flex:1,minWidth:0,cursor:"pointer"}} onClick={()=>toggleSOpenCat(c)}>
                      <div style={{fontSize:14,fontFamily:"'Sarabun',sans-serif",fontWeight:checked?800:600,color:checked?C.blue:C.ink2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{c}</div>
                      <div style={{fontSize:10.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>{catMenus.length} เมนู{allHere?" · ✓ เลือกครบทั้งหมวด":pinHere>0?` · 📌 เลือกเฉพาะ ${pinHere}`:""}</div>
                    </div>
                    <button onClick={()=>toggleSOpenCat(c)} style={{display:"flex",alignItems:"center",gap:5,background:isOpen?C.blue:C.white,color:isOpen?C.white:C.ink3,border:`1px solid ${isOpen?C.blue:C.line}`,borderRadius:8,padding:"5px 10px",cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap",flexShrink:0}}><span style={{fontSize:9}}>{isOpen?"▼":"▶"}</span> เลือกเมนู</button>
                  </div>
                  {isOpen&&<div style={{borderTop:`1px dashed ${C.line}`,padding:"10px 12px",background:C.white}}>
                    {catMenus.length===0
                      ?<div style={{fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",textAlign:"center",padding:8}}>ไม่มีเมนูในหมวดนี้</div>
                      :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(min(220px,100%),1fr))",gap:6}}>
                        {catMenus.map(m=>{const cur=sOverride[m.id];const here=cur!=null&&+cur===+settingsP.id;const other=cur!=null&&+cur!==+settingsP.id;const otherName=other?(printers.find(pr=>+pr.id===+cur)?.name||"เครื่องอื่น"):"";return <label key={m.id} style={{display:"flex",alignItems:"center",gap:8,padding:"7px 10px",borderRadius:8,cursor:"pointer",background:here?C.blueLight:C.bg,border:`1px solid ${here?C.blue:C.line}`}}>
                          <input type="checkbox" checked={has||here} disabled={has} title={has?"หมวดนี้ถูกเลือกทั้งหมวดแล้ว — เอาติ๊กหน้าหมวดออกก่อนถ้าต้องการเลือกทีละเมนู":""} onChange={()=>{if(has)return;setSOverride(prev=>({...prev,[m.id]:here?null:settingsP.id}));}} style={{accentColor:C.blue,width:15,height:15,cursor:has?"not-allowed":"pointer",flexShrink:0,opacity:has?.75:1}}/>
                          <div style={{flex:1,minWidth:0}}>
                            <div style={{fontSize:12.5,fontFamily:"'Sarabun',sans-serif",fontWeight:here?800:600,color:here?C.blue:C.ink2,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.name}</div>
                            {other&&<div style={{fontSize:9.5,color:"#B45309",fontFamily:"'Sarabun',sans-serif",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>📌 เลือกไว้ที่ {otherName}</div>}
                          </div>
                        </label>;})}
                      </div>}
                  </div>}
                </div>;})}
              </div>
            </>}
        <div style={{display:"flex",justifyContent:"flex-end",gap:8,paddingTop:14,borderTop:`1px solid ${C.line}`,marginTop:14}}>
          <Btn v="ghost" onClick={()=>setSettingsP(null)}>ยกเลิก</Btn>
          <Btn v="success" onClick={saveSettings} loading={sSaving} icon={I.check}>บันทึก</Btn>
        </div>
      </Modal>}
      {canAdmin&&(discovered.length>0||searched)&&<div style={{background:"#EFF6FF",border:`1px solid ${C.blue}44`,borderRadius:12,padding:"12px 14px",marginBottom:14}}>
        <div style={{fontSize:13,fontWeight:800,color:C.blue,fontFamily:"'Sarabun',sans-serif",marginBottom:searched?4:8}}>{searched?`🔍 ผลการค้นหาในเครือข่าย (${discovered.length})`:`🔍 พบในเครือข่าย (${discovered.length}) — แตะ "เพิ่มใช้งาน" เฉพาะเครื่องที่ต้องการ`}</div>
        {searched&&<div style={{fontSize:11,color:C.ink3,fontFamily:"'Sarabun',sans-serif",marginBottom:8,lineHeight:1.6}}>แสดงทุกเครื่องที่พบในวง LAN รวมเครื่องที่<b>เคยซ่อน/ลบ</b>ไปแล้ว · เครื่องที่ <b>เพิ่มในระบบแล้ว</b> อยู่ด้านบน (กดเพิ่มซ้ำไม่ได้) · เครื่องที่ปิดอยู่/ไม่ได้ต่อสายจะไม่แสดง</div>}
        {discovered.length===0?<div style={{fontSize:12.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif",textAlign:"center",padding:"12px 6px",lineHeight:1.7,whiteSpace:"pre-line"}}>{searching?"⟳ กำลังค้นหาเครื่องพิมพ์ในวง LAN...":printers.length===0?"ยังไม่มีตัวพิมพ์ที่สาขานี้ จึงไม่มีใครไปสแกนวง LAN ให้\n\nกดปุ่ม \"ค้นหาเครื่องพิมพ์\" ตอนนี้จะไม่ได้ผล ต้องรันตัวพิมพ์ที่สาขานี้ก่อน (ดูคำอธิบายด้านบน)":"ไม่พบเครื่องพิมพ์อื่นในเครือข่าย\n(เครื่องที่เพิ่มแล้วอยู่ด้านบน · เครื่องที่ปิดอยู่/ไม่ได้ต่อสายจะไม่แสดง)\n\nเพิ่งเสียบเครื่องใหม่? ตัวพิมพ์สแกนเองทุก ~2 นาที — รอสักครู่แล้วกด \"ค้นหาเครื่องพิมพ์\" อีกครั้ง"}</div>
        :<div style={{display:"flex",flexDirection:"column",gap:8}}>
          {discovered.map(p=>{const ig=isIgnored(p);return <div key={p.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",border:`1px solid ${C.blue}33`,borderRadius:10,background:C.white,flexWrap:"wrap"}}>
            <div style={{minWidth:0,flex:1}}>
              <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:700,color:C.ink}}>{p.ip}:{p.port||9100}{ig&&<span style={{marginLeft:8,fontSize:10.5,fontWeight:700,color:C.ink4,background:C.bg,border:`1px solid ${C.line}`,borderRadius:20,padding:"1px 8px",whiteSpace:"nowrap"}}>เคยซ่อนไว้</span>}</div>
              <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11,color:C.ink4}}>พบเครื่องพิมพ์ในวง LAN — ยังไม่ได้ใช้งาน</div>
            </div>
            <button onClick={()=>addDiscovered(p)} style={{background:`linear-gradient(135deg,${C.green},#059669)`,border:"none",borderRadius:8,padding:"7px 14px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12.5,fontWeight:800,color:C.white,whiteSpace:"nowrap"}}>➕ เพิ่มใช้งาน</button>
            {!ig&&<button onClick={()=>ignoreDiscovered(p)} title="ไม่ใช้เครื่องนี้ (ซ่อนออกจากรายการ)" style={{background:C.bg,border:`1px solid ${C.line}`,borderRadius:8,padding:"7px 10px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:700,color:C.ink3,whiteSpace:"nowrap"}}>🙈 ซ่อน</button>}
          </div>;})}
        </div>}
      </div>}
      {!canAdmin&&<div style={{background:C.bg,border:`1px dashed ${C.line}`,borderRadius:12,padding:"12px 14px",fontFamily:"'Sarabun',sans-serif",fontSize:12,color:C.ink3,lineHeight:1.65}}>🔒 เพิ่ม/นำเครื่องพิมพ์ออก ทำได้เฉพาะผู้จัดการ (สิทธิ์ตั้งค่า หรือ จัดการ POS) · เครื่องดับกลางร้าน: กด "🖨️ กำหนดการพิมพ์" ที่เครื่องที่ยังใช้ได้ แล้วติ๊กหมวดของเครื่องที่ดับเพิ่ม</div>}
      {canAdmin&&<div style={{background:C.bg,border:`1px dashed ${C.line}`,borderRadius:12,padding:"14px 16px"}}>
        <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:13,fontWeight:800,color:C.ink,marginBottom:10}}>➕ เพิ่มเครื่องพิมพ์ (เครือข่าย / IP) ด้วยตัวเอง</div>
        <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"flex-end"}}>
          <div style={{flex:"2 1 160px"}}><label style={lbl}>ชื่อเครื่องพิมพ์</label><input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="เช่น ครัวร้อน" style={iS}/></div>
          <div style={{flex:"2 1 150px"}}><label style={lbl}>เลข IP</label><input value={form.ip} onChange={e=>setForm(f=>({...f,ip:e.target.value.replace(/[^\d.]/g,"")}))} inputMode="decimal" placeholder="192.168.1.50" style={iS}/></div>
          <div style={{flex:"1 1 90px"}}><label style={lbl}>พอร์ต</label><input value={form.port} onChange={e=>setForm(f=>({...f,port:e.target.value.replace(/\D/g,"")}))} inputMode="numeric" placeholder="9100" style={iS}/></div>
          <Btn onClick={add} loading={saving} icon={I.plus}>เพิ่ม</Btn>
        </div>
        <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11,color:C.ink4,marginTop:8,lineHeight:1.6}}>💡 ใช้เครื่องพิมพ์ความร้อนที่ต่อ LAN/WiFi · พอร์ตมาตรฐานคือ 9100 · ตั้งหมวดหมู่/เลือกเมนูให้แต่ละเครื่องได้ที่ "จัดการหลังบ้าน → เครื่องพิมพ์"</div>
      </div>}
    </>}
  </Modal>;
}

// ══════════════════════════════════════════════════════
// ── SALES REPORT (รายงานยอดขาย: เลือกวัน · ปิด/ยังไม่ปิดบิล · ดูแต่ละบิล) ─
// ══════════════════════════════════════════════════════
function BillDetailCard({order,branch=null,cfg=null,onBack,onEdit=null,onVoid=null,onFixPay=null}){
  const o=order;
  const items=o.items||[];
  const stL={pending:"รอยืนยัน",confirmed:"กำลังทำ",bill_requested:"เรียกบิล",paid:"ชำระแล้ว",cancelled:"ยกเลิก"};
  const stC={pending:C.yellow,confirmed:C.green,bill_requested:C.brand,paid:C.green,cancelled:C.ink4};
  const m=(n)=>"฿"+(+n||0).toLocaleString(undefined,{maximumFractionDigits:0});
  const paid=o.status==="paid";
  const Row=({l,v,c,big,plus})=><div style={{display:"flex",justifyContent:"space-between",alignItems:"baseline",fontSize:big?17:13,fontFamily:"'Sarabun',sans-serif",marginBottom:big?0:6,fontWeight:big?900:500,color:c||C.ink2}}><span>{l}</span><span style={{fontWeight:big?900:700,color:big?C.ink:(c||C.ink)}}>{plus||""}{v}</span></div>;
  // ต้องเรียกตรงๆ จากการกดปุ่ม ห้ามมี await คั่น ไม่งั้นเบราว์เซอร์ถือว่าไม่ใช่การกดของผู้ใช้แล้วบล็อกหน้าต่าง
  // (ตั้งค่าใบเสร็จจึงถูกโหลดไว้ตั้งแต่เปิดจอรายงาน ไม่ได้มาโหลดตอนกด)
  function printBill(){
    try{ printReceipt(o,o.table_number,branch?.name||"",cfg,{paid:o.status==="paid"}); }
    catch(e){ alert("เปิดหน้าต่างพิมพ์ไม่สำเร็จ: "+friendlyError(e)); }
  }
  // ส่งเข้าเครื่องพิมพ์ใบเสร็จของร้านจริงๆ (ใบเดียวกับตอนปิดบิล) — ไม่ใช่หน้าต่างพิมพ์ของเบราว์เซอร์
  const[sendingPrint,setSendingPrint]=useState(false);
  async function printToShop(){
    if(sendingPrint)return;
    if(!branch){printBill();return;}   // ไม่รู้ว่าสาขาไหน = เลือกเครื่องเองจากเบราว์เซอร์
    setSendingPrint(true);
    try{ await printBillReceipt(o,o.table_number,{branch,posSettings:cfg,paid:o.status==="paid"}); }
    catch(e){ alert("ส่งเข้าเครื่องพิมพ์ไม่สำเร็จ: "+friendlyError(e)); }
    setSendingPrint(false);
  }
  return <div>
    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:14,flexWrap:"wrap"}}>
      <button onClick={onBack} style={{display:"flex",alignItems:"center",gap:6,padding:"7px 14px",borderRadius:9,border:`1px solid ${C.line}`,background:C.white,cursor:"pointer",fontSize:12.5,fontWeight:700,color:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>← กลับไปรายการบิล</button>
      <button onClick={printBill} style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:7,padding:"9px 18px",borderRadius:10,border:"none",background:`linear-gradient(135deg,${C.brand},${C.brandDark})`,color:C.white,cursor:"pointer",fontSize:13,fontWeight:800,fontFamily:"'Sarabun',sans-serif",boxShadow:`0 6px 16px ${C.brand}44`}}>
        <Ic d={I.print} s={15} c={C.white}/>💾 บันทึก PDF
      </button>
      <button onClick={printToShop} disabled={sendingPrint} style={{display:"flex",alignItems:"center",gap:7,padding:"9px 18px",borderRadius:10,border:"none",background:sendingPrint?C.ink4:`linear-gradient(135deg,${C.green},#059669)`,color:C.white,cursor:sendingPrint?"wait":"pointer",fontSize:13,fontWeight:800,fontFamily:"'Sarabun',sans-serif"}}>
        <Ic d={I.print} s={15} c={C.white}/>{sendingPrint?"กำลังส่ง...":"🖨️ พิมพ์ที่เครื่องพิมพ์ร้าน"}
      </button>
    </div>
    <div style={{maxWidth:460,margin:"0 auto 10px",fontSize:11,color:C.ink4,fontFamily:"'Sarabun',sans-serif",textAlign:"center",lineHeight:1.6}}>
      <b style={{color:C.green}}>“พิมพ์ที่เครื่องพิมพ์ร้าน”</b> = กระดาษออกที่เครื่องใบเสร็จของสาขาใน ~5 วินาที · <b style={{color:C.ink3}}>“บันทึก PDF”</b> = เปิดหน้าต่างของเบราว์เซอร์ไว้เก็บไฟล์หรือเลือกเครื่องพิมพ์เอง
    </div>
    <div style={{maxWidth:460,margin:"0 auto",background:C.white,borderRadius:14,border:`1px solid ${C.line}`,overflow:"hidden",boxShadow:"0 2px 10px rgba(0,0,0,0.04)"}}>
      <div style={{padding:"14px 18px",background:C.bg,borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div>
          <div style={{fontSize:20,fontWeight:900,color:C.ink,fontFamily:"'Sarabun',sans-serif"}}>โต๊ะ {o.table_number}</div>
          <div style={{fontSize:11.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif",marginTop:3}}>บิล #{o.id} · {fmtDT(o.created_at)}</div>
        </div>
        <span style={{fontSize:12,fontWeight:800,color:stC[o.status]||C.ink3,background:`${stC[o.status]||C.ink3}22`,padding:"4px 12px",borderRadius:20,fontFamily:"'Sarabun',sans-serif"}}>{stL[o.status]||o.status}</span>
      </div>
      {o.status==="cancelled"&&<div style={{padding:"11px 18px",background:C.redLight,borderBottom:`1px solid ${C.red}33`,fontFamily:"'Sarabun',sans-serif"}}>
        <div style={{fontSize:12.5,fontWeight:900,color:C.red,marginBottom:3}}>🗑️ บิลนี้ถูกยกเลิก</div>
        <div style={{fontSize:12,color:"#991B1B",lineHeight:1.7}}>
          <div>ผู้ยกเลิก: <b>{o.cancelled_by||"— ไม่มีบันทึก (ยกเลิกก่อนเปิดระบบบันทึก) —"}</b></div>
          {o.cancelled_at&&<div>เวลา: {fmtDT(o.cancelled_at)}</div>}
          <div>เหตุผล: {o.cancel_reason||"— ไม่ได้ระบุ —"}</div>
        </div>
      </div>}
      {onEdit&&canEditPaidBill(o)&&<div style={{padding:"10px 18px",borderBottom:`1px solid ${C.line}`,background:C.white}}>
        <Btn v="primary" full onClick={()=>onEdit(o)} s={{padding:"9px",fontSize:13}}>✏️ แก้ไขบิลนี้ — เพิ่ม/ลดรายการ แล้วเก็บเพิ่มหรือคืนเงิน</Btn>
        {onFixPay&&<Btn v="ghost" full onClick={()=>onFixPay(o)} s={{padding:"9px",fontSize:13,marginTop:8}}>💳 แก้ช่องทางชำระ — กดผิดช่องทาง (ยอดไม่เปลี่ยน)</Btn>}
        {onVoid&&<Btn v="danger" full onClick={()=>onVoid(o)} s={{padding:"9px",fontSize:13,marginTop:8}}>🚫 ยกเลิกบิลนี้ (Void) — ต้องใส่เหตุผล</Btn>}
        {+o.edit_count>0&&<div style={{fontSize:11.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif",marginTop:6}}>บิลนี้ถูกแก้มาแล้ว {o.edit_count} ครั้ง · ล่าสุด {o.edited_at?fmtDT(o.edited_at):"-"}{o.edited_by?" โดย "+o.edited_by:""}</div>}
      </div>}
      {(o.ordered_by||(paid&&o.paid_by))&&<div style={{padding:"8px 18px",background:paid?C.greenLight:C.bg,borderBottom:`1px solid ${paid?C.green+"33":C.line}`,fontFamily:"'Sarabun',sans-serif",fontSize:12,color:paid?"#0F6E56":C.ink3,display:"flex",gap:14,flexWrap:"wrap"}}>
        {o.ordered_by&&<span>รับออเดอร์โดย <b>{o.ordered_by==="customer"?"ลูกค้าสแกนสั่งเอง":o.ordered_by}</b></span>}
        {paid&&o.paid_by&&<span>ปิดบิลโดย <b>{o.paid_by}</b></span>}
      </div>}
      <div style={{padding:"14px 18px"}}>
        {items.length===0?<div style={{color:C.ink4,fontFamily:"'Sarabun',sans-serif",fontSize:13,textAlign:"center",padding:"10px 0"}}>ไม่มีรายการอาหาร</div>:items.map((i,idx)=>{
          const disc=+i.item_discount||0;
          return <div key={idx} style={{marginBottom:idx<items.length-1?11:0,paddingBottom:idx<items.length-1?11:0,borderBottom:idx<items.length-1?`1px dashed ${C.lineLight}`:"none"}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:13.5,fontFamily:"'Sarabun',sans-serif",gap:10}}>
              <span style={{color:C.ink}}><span style={{color:C.brand,fontWeight:800}}>{i.qty}x</span> {i.name}</span>
              <span style={{color:C.ink,fontWeight:700,whiteSpace:"nowrap"}}>{m((+i.price||0)*(+i.qty||0)-disc)}</span>
            </div>
            {i.options&&i.options.length>0&&<div style={{fontSize:11.5,color:C.ink4,fontFamily:"'Sarabun',sans-serif",marginTop:3,paddingLeft:4}}>+ {optionsText(i.options)}</div>}
            {i.note&&<div style={{fontSize:11.5,color:C.ink4,fontStyle:"italic",fontFamily:"'Sarabun',sans-serif",marginTop:3,paddingLeft:4}}>* {i.note}</div>}
            {disc>0&&<div style={{fontSize:11.5,color:C.green,fontFamily:"'Sarabun',sans-serif",marginTop:3,paddingLeft:4}}>ลด {i.item_discount_type==="percent"?i.item_discount_value+"%":m(i.item_discount_value)}</div>}
          </div>;
        })}
      </div>
      <div style={{padding:"14px 18px",borderTop:`1px solid ${C.line}`,background:C.bg}}>
        <Row l="ยอดรวม" v={m(o.subtotal)}/>
        {/* o.discount = ส่วนลดทั้งหมด (รวมโปรฯ/คูปองแล้ว) — แตกก่อนแสดง ไม่งั้นโปรฯ/คูปองถูกหักซ้ำบนจอ */}
        {(()=>{const dp=billDiscParts(o);return <>
          {dp.manual>0&&<Row l={(dp.promo>0||dp.voucher>0)?"ส่วนลด":"ส่วนลดรวม"} v={m(dp.manual)} c={C.green} plus="-"/>}
          {dp.promo>0&&<Row l={stripEmoji(o.promo_name||"โปรโมชั่น")} v={m(dp.promo)} c={C.green} plus="-"/>}
          {dp.voucher>0&&<Row l={"Voucher"+(o.voucher.ref?" ("+stripEmoji(String(o.voucher.ref))+")":"")} v={m(dp.voucher)} c={C.green} plus="-"/>}
        </>;})()}
        {+o.service_charge>0&&<Row l="ค่าบริการ (Service)" v={m(o.service_charge)} plus="+"/>}
        {+o.vat>0&&<Row l={`VAT ${o.vat_rate||7}%${o.vat_included?" (รวมในราคา)":""}`} v={m(o.vat)} plus={o.vat_included?"":"+"}/>}
        {+o.round_adj?<Row l="ปัดเศษ" v={"฿"+Math.abs(+o.round_adj).toFixed(2)} plus={+o.round_adj>0?"+":"-"}/>:null}
        <div style={{borderTop:`1px solid ${C.line}`,margin:"8px 0 0",paddingTop:10}}><Row l="รวมทั้งสิ้น" v={m(o.total)} big/></div>
        {paid&&cashPartOf(o)>0&&o.cash_received&&<div style={{marginTop:8}}><Row l="รับเงิน" v={m(o.cash_received)}/><Row l="เงินทอน" v={m(Math.max(0,(+o.cash_received)-cashPartOf(o)))}/></div>}
        {paid&&<div style={{marginTop:8,paddingTop:8,borderTop:`1px dashed ${C.lineLight}`,fontSize:12.5,fontFamily:"'Sarabun',sans-serif",color:C.ink3,display:"flex",justifyContent:"space-between"}}><span>ชำระโดย</span><span style={{fontWeight:700,color:C.ink}}>{(Array.isArray(o.payments)&&o.payments.length>1)?payHeadOf(o):(PAY_LABEL[o.payment_method]||o.payment_method||"-")}</span></div>}
        {/* แบ่งจ่าย: ไล่ให้เห็นทีละขั้นว่าช่องทางไหนเท่าไร — เปิดย้อนดูทีหลังก็ยังตรวจได้ */}
        {paid&&Array.isArray(o.payments)&&o.payments.length>1&&<div style={{marginTop:4,fontSize:12.5,fontFamily:"'Sarabun',sans-serif",color:C.ink3}}>
          {o.payments.map((p,i)=><div key={i} style={{display:"flex",justifyContent:"space-between",padding:"1px 0"}}><span>{i+1}. {payMethodLabel(p.method)}</span><span style={{fontWeight:700,color:C.ink}}>{m(p.amount)}</span></div>)}
        </div>}
      </div>
    </div>
  </div>;
}

// พิมพ์ใบเสร็จ — ใช้ร่วมกันทั้งจอโต๊ะและจอแก้บิลที่ปิดแล้ว (ใบเดียวกันเป๊ะ)
// iPad/https พิมพ์ผ่านตัวพิมพ์ (agent) เป็นรูปภาพไทยคมชัด · เดสก์ท็อป/LAN ใช้หน้าต่างพิมพ์ปกติ
async function printBillReceipt(order,tableNum,{branch,posSettings,printers=[],paid=true,kick=false}){
  const isHttps=typeof location!=="undefined"&&location.protocol==="https:";
  let prs=printers;   // ดึงเครื่องพิมพ์ล่าสุดจาก DB — กันค่าค้างหลังเพิ่งติ๊ก "เครื่องพิมพ์ใบเสร็จ"
  try{const all=await api.getAllPrinters();if(Array.isArray(all))prs=all.filter(p=>p.branch_id==null||+p.branch_id===+branch.id);}catch{}
  const rcps=isHttps?getReceiptPrinters(prs):[];
  // kick = บิลเงินสด ต้องเปิดลิ้นชักด้วย · เครื่องเดียวกับใบเสร็จ = ไปในการเขียนครั้งเดียวกับใบเสร็จ
  // (เดิมยิงสองงานพร้อมกัน ต่างคนต่างอ่าน-แก้-เขียนแถวเดียวกัน → ลิ้นชักไม่เด้งหรือใบเสร็จหายเงียบ)
  // เครื่องลิ้นชักที่ไม่ได้รับใบเสร็จ = สั่งทันทีที่แถวของมันเอง (ไม่ชนใคร) · ปิดบิลสำคัญกว่าลิ้นชัก: กลืน error
  const kp=receiptKickPlan(rcps,kick?drawerPrinters(prs):[]);
  const dk=kp.alone.length||kp.withRcpt.size?{at:Date.now()}:null;
  const kickAlone=(list)=>{if(dk&&list.length)Promise.all(list.map(p=>api.updatePrinter(p.id,{description:cmdDesc(p,"dk",dk)}))).catch(()=>{});};
  kickAlone(kp.alone);
  if(isHttps&&rcps.length){
    let b64=null;
    try{b64=await buildReceiptB64(order,tableNum,branch.name,posSettings,paid);}
    catch(e){posToast("พิมพ์ไม่สำเร็จ: "+(e&&e.message||e),"warn");}
    // เรนเดอร์ใบไม่ได้ (ยังไม่ได้เขียนอะไร) — ลิ้นชักยังต้องเปิด สั่งแยกได้เพราะไม่มีใบเสร็จไปแข่ง
    if(!b64){kickAlone(rcps.filter(p=>kp.withRcpt.has(+p.id)));try{printReceipt(order,tableNum,branch.name,posSettings,{paid});}catch{}return false;}
    try{
      const at=Date.now();
      // ให้ทุกเครื่องเขียนจนจบ แล้วดูว่าเครื่องไหนไม่ถึง — ลิ้นชักที่ฝากไปกับใบนั้นต้องสั่งแยก (kickAfterFail)
      const bad=[];
      await Promise.all(rcps.map(rcp=>api.updatePrinter(rcp.id,{description:withKick(cmdDesc(rcp,"pj",{at,b64,what:paid?"ใบเสร็จ":"ใบแจ้งยอด",bill:order&&order.id!=null?order.id:null,table:String(tableNum??"")}),kp.withRcpt.has(+rcp.id)?dk:null)}).catch(e=>{bad.push({p:rcp,e});})));
      if(bad.length){kickAfterFail(bad.map(x=>x.p).filter(p=>kp.withRcpt.has(+p.id)),dk);throw bad[0].e;}
      posToast(`🧾 ส่ง${paid?"ใบเสร็จ":"ใบแจ้งยอด"}ไป ${rcps.length} เครื่องแล้ว — ไม่ออกใน 10 วิ ดูปุ่ม พิมพ์ไม่สำเร็จ`,"ok");
      return true;   // ส่งเข้าตัวพิมพ์แล้วจริง (ผู้เรียกบางที่ใช้ตัดสินว่าเอารายการ "ไม่ออก" เดิมออกได้)
    }catch(e){posToast("พิมพ์ไม่สำเร็จ: "+(e&&e.message||e),"warn");try{printReceipt(order,tableNum,branch.name,posSettings,{paid});}catch{}}
    return false;
  }
  if(isHttps&&!rcps.length){posToast("⚠️ ยังไม่ได้ติ๊กเครื่องพิมพ์ใบเสร็จ — ไปที่ ⚙️ เครื่องพิมพ์ → กำหนดการพิมพ์ → ติ๊ก \"🧾 ใช้เป็นเครื่องพิมพ์ใบเสร็จ\"","warn");return false;}
  printReceipt(order,tableNum,branch.name,posSettings,{paid});   // เดสก์ท็อป/LAN (ไม่ใช่ https) → หน้าต่างพิมพ์เบราว์เซอร์
  return false;
}
// ── แก้ช่องทางชำระของบิลที่ปิดแล้ว (เจ้าของสั่ง 21 ก.ย. 69) ──────────────
// เหตุจริง: บิล #357 ลูกค้าจ่ายสด ฿89 แต่พนักงานกดเป็นพร้อมเพย์ 79 + สด 10
// กว่าจะรู้ตัวก็ปิดกะแล้ว ต้องไล่แก้สามระบบ (บิล · ลิ้นชัก · บัญชี) ⟹ ให้แก้เองได้ตั้งแต่ยังไม่ปิดกะ
// กติกา: เฉพาะกะที่เปิดอยู่ · ยอดรวมต้องเท่าบิลเป๊ะ · บังคับเหตุผล · เงินสดที่เปลี่ยนต้องตามไปแก้ลิ้นชักเสมอ
function PayChannelFixModal({order,branch,currentUser,shift,onDone,onClose}){
  const o=order;
  const total=round2(+o.total||0);
  const before=(Array.isArray(o.payments)&&o.payments.length)?o.payments.map(p=>({method:p.method,amount:round2(+p.amount||0)})):[{method:o.payment_method||"other",amount:total}];
  const[parts,setParts]=useState([]);
  const[amt,setAmt]=useState("");
  const[reason,setReason]=useState("");
  const[saving,setSaving]=useState(false);
  const paid=round2(parts.reduce((s,p)=>s+p.amount,0));
  const remain=round2(total-paid);
  const canSave=remain===0&&parts.length>0&&reason.trim().length>=3&&!saving;
  const addPart=(m)=>{
    const want=round2(+amt||remain);
    if(!(want>0)||want>remain)return;
    setParts(a=>[...a,{method:m,amount:want}]);setAmt("");
  };
  async function saveNow(){
    if(!canSave)return;
    const beforeText=before.map(p=>payMethodLabel(p.method)+" "+bahtR(p.amount)).join(" + ");
    const afterText=parts.map(p=>payMethodLabel(p.method)+" "+bahtR(p.amount)).join(" + ");
    if(!await confirmDlg({title:"แก้ช่องทางชำระ",confirmLabel:"บันทึก",cancelLabel:"ยกเลิก",
      message:"บิล #"+o.id+" โต๊ะ "+o.table_number+"\nเดิม: "+beforeText+"\nใหม่: "+afterText+"\n\nยอดรวม "+bahtR(total)+" ไม่เปลี่ยน · เงินในลิ้นชักจะถูกปรับให้ตรงอัตโนมัติ"}))return;
    setSaving(true);
    try{
      const at=new Date().toISOString();
      const who=currentUser?.username||currentUser?.name||"-";
      const cashBefore=round2(before.filter(p=>p.method==="cash").reduce((s,p)=>s+p.amount,0));
      const cashAfter=round2(parts.filter(p=>p.method==="cash").reduce((s,p)=>s+p.amount,0));
      const kinds=[...new Set(parts.map(p=>p.method))];
      const payments=parts.map(p=>({...p,at,by:who,reason:"แก้ช่องทางชำระ: "+reason.trim()}));
      const patch={payment_method:kinds.length===1?kinds[0]:"mixed",payments,
        cash_received:cashAfter>0?cashAfter:null,updated_at:at};
      const row=await api.updatePOSOrderIfUnchanged(o.id,o.updated_at,patch);
      if(!row){notifyDlg("บิลนี้เพิ่งถูกแก้จากอุปกรณ์อื่น — ปิดหน้านี้แล้วเปิดบิลใหม่อีกครั้ง");setSaving(false);return;}
      // เงินสดเปลี่ยน = ลิ้นชักต้องเปลี่ยนตาม ไม่งั้นตอนปิดกะเงินจะขาด/เกินโดยไม่มีใครรู้สาเหตุ
      const delta=round2(cashAfter-cashBefore);
      if(delta!==0&&shift){
        try{
          const _ls=await liveShift(branch.id,shift);
          if(_ls.note)posToast(_ls.note,"warn",9000);
          await api.addCashMovement({shift_id:_ls.id,branch_id:branch.id,type:"sale",amount:delta,order_id:o.id,
            reason:"แก้ช่องทางชำระบิล #"+o.id+" โต๊ะ "+o.table_number+" ("+beforeText+" → "+afterText+")",
            user_id:currentUser?.id,username:who});
        }catch(err){
          console.error("ปรับเงินลิ้นชักไม่สำเร็จ:",err);
          notifyDlg("แก้ช่องทางในบิลแล้ว แต่ปรับเงินในลิ้นชักไม่สำเร็จ\nกรุณาไปที่ \"เงินในลิ้นชัก\" แล้วบันทึกเงิน"+(delta>0?"เข้า ":"ออก ")+bahtR(Math.abs(delta))+" ด้วยตัวเอง");
        }
      }
      // ลงประวัติการแก้บิล — ใบปิดกะจะรายงานว่าแก้กี่ครั้ง ใครแก้ เพราะอะไร
      try{
        await api.addOrderEdit({order_id:o.id,branch_id:branch.id,shift_id:shift?.id||null,edited_by:who,
          reason:"แก้ช่องทางชำระ: "+reason.trim()+" ("+beforeText+" → "+afterText+")",
          delta:0,settle_method:kinds.length===1?kinds[0]:"mixed",old_total:total,new_total:total,items_before:o.items||[]});
      }catch(err){console.warn("บันทึกประวัติการแก้บิลไม่สำเร็จ",err);}
      posToast("แก้ช่องทางชำระบิล #"+o.id+" แล้ว","ok");
      onDone&&onDone();
    }catch(e){notifyDlg("แก้ช่องทางชำระไม่สำเร็จ: "+friendlyError(e));}
    setSaving(false);
  }
  const chip={padding:"10px 14px",borderRadius:10,border:"1px solid "+C.line,background:C.white,cursor:"pointer",
    fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:700,color:C.ink2,minHeight:44};
  return <div style={{position:"fixed",inset:0,background:"rgba(15,23,42,.78)",zIndex:6200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
    <div style={{background:C.white,borderRadius:18,width:"100%",maxWidth:"min(95vw,540px)",maxHeight:"calc(100vh - 32px)",overflowY:"auto",WebkitOverflowScrolling:"touch",overscrollBehavior:"contain",boxShadow:"0 30px 80px rgba(0,0,0,.45)"}}>
      <div style={{padding:"16px 20px",background:C.brand,color:C.white,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div style={{fontFamily:"'Sarabun',sans-serif",fontWeight:900,fontSize:18}}>💳 แก้ช่องทางชำระ · บิล #{o.id}</div>
        <button onClick={onClose} style={{background:"rgba(255,255,255,.2)",border:"none",borderRadius:10,width:44,height:44,cursor:"pointer",color:C.white,fontSize:20}}>✕</button>
      </div>
      <div style={{padding:20,fontFamily:"'Sarabun',sans-serif"}}>
        <div style={{background:C.bg,borderRadius:12,padding:"12px 14px",marginBottom:14,fontSize:13.5,color:C.ink2,lineHeight:1.8}}>
          <div>โต๊ะ <b style={{color:C.ink}}>{o.table_number}</b> · ยอดบิล <b style={{color:C.ink,fontSize:18}}>{bahtR(total)}</b></div>
          <div>ตอนนี้บันทึกไว้ว่า <b style={{color:C.ink}}>{before.map(p=>payMethodLabel(p.method)+" "+bahtR(p.amount)).join(" + ")}</b></div>
        </div>
        <div style={{fontSize:13.5,fontWeight:800,color:C.ink2,marginBottom:8}}>ที่จ่ายจริงคือช่องทางไหน *</div>
        {parts.length>0&&<div style={{border:"1px solid "+C.line,borderRadius:12,padding:"8px 12px",marginBottom:10}}>
          {parts.map((p,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"6px 0",borderBottom:i<parts.length-1?"1px dashed "+C.lineLight:"none"}}>
            <span style={{flex:1,fontSize:14,fontWeight:700,color:C.ink2}}>{i+1}. {payMethodLabel(p.method)}</span>
            <span style={{fontSize:15,fontWeight:900,color:C.ink}}>{bahtR(p.amount)}</span>
            {i===parts.length-1&&<button onClick={()=>setParts(a=>a.slice(0,-1))} style={{...chip,padding:"6px 10px",minHeight:36,color:C.red,fontSize:12}}>ลบ</button>}
          </div>)}
        </div>}
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
          <NumInput value={amt} onValue={setAmt} placeholder={"เหลือ "+bahtR(remain)} style={{...iS,flex:1,fontSize:16,fontWeight:800,padding:"12px 14px",textAlign:"center"}}/>
          <button onClick={()=>setAmt(String(remain))} style={chip}>ทั้งหมด</button>
        </div>
        <div style={{display:"flex",flexWrap:"wrap",gap:7,marginBottom:12}}>
          {SETTLE_METHODS().map(mt=><button key={mt.v} onClick={()=>addPart(mt.v)} disabled={remain<=0}
            style={{...chip,opacity:remain<=0?.4:1,borderColor:mt.c,color:mt.c,fontWeight:800}}>{mt.icon} {mt.l}</button>)}
        </div>
        <div style={{fontSize:14,fontWeight:900,color:remain===0?C.green:C.red,marginBottom:14}}>
          {remain===0?"ครบยอดพอดี "+bahtR(total):"ยังเหลืออีก "+bahtR(remain)}
        </div>
        <div style={{fontSize:13.5,fontWeight:800,color:C.ink2,marginBottom:8}}>เหตุผล *</div>
        <input value={reason} onChange={e=>setReason(e.target.value)} placeholder="เช่น กดช่องทางผิด ลูกค้าจ่ายเงินสดทั้งหมด"
          style={{...iS,fontSize:14.5,padding:"12px 14px",marginBottom:14}}/>
        <div style={{fontSize:12.5,color:C.ink4,lineHeight:1.7,marginBottom:16}}>
          ยอดบิลไม่เปลี่ยน เปลี่ยนแค่ช่องทาง · ถ้าเงินสดเปลี่ยน ระบบจะปรับเงินในลิ้นชักให้เองและขึ้นบนใบปิดกะ
        </div>
        <div style={{display:"flex",gap:8}}>
          <Btn v="ghost" onClick={onClose} full s={{padding:"12px"}}>ยกเลิก</Btn>
          <Btn v="primary" onClick={saveNow} loading={saving} disabled={!canSave} full icon={I.check} s={{padding:"12px",fontWeight:900}}>บันทึกช่องทางใหม่</Btn>
        </div>
      </div>
    </div>
  </div>;
}
// ── ใบยกเลิกบิล — ออกที่เครื่องใบเสร็จทุกครั้งที่กด Void ────────────────
// เอกสารกระดาษคือสิ่งเดียวที่ผู้จัดการตรวจย้อนหลังได้โดยไม่ต้องเปิดคอม
// ห้ามเงียบ: ถ้ายังไม่ได้ติ๊กเครื่องใบเสร็จต้องบอกบนจอ ไม่ใช่ปล่อยผ่าน
async function printVoidBillSlip({order,branch,reason,refundText,by,at,printers=[],kick=false}){
  const L=[];
  L.push({t:(branch&&branch.name)||"",size:30,bold:true,align:"center",mb:2});
  L.push({t:"*** ยกเลิกบิล ***",size:34,bold:true,align:"center",mb:2});
  L.push({rule:true});
  L.push({l:"เลขที่บิล",r:"#"+order.id,size:22});
  L.push({l:"โต๊ะ",r:String(order.table_number||"-"),size:22});
  L.push({l:"ยอดบิล",r:bahtR(+order.total||0),size:28,bold:true});
  if(order.payment_method)L.push({l:"เดิมชำระโดย",r:payMethodLabel(order.payment_method),size:20});
  L.push({l:"ปิดบิลเมื่อ",r:fmtDT(order.updated_at||order.created_at),size:20});
  L.push({rule:true});
  L.push({t:"เหตุผล: "+stripEmoji(reason||"-"),size:24,bold:true});
  L.push({t:refundText||"",size:22});
  L.push({t:"ยกเลิกโดย "+stripEmoji(by||"-")+" · "+fmtDT(at),size:20});
  L.push({rule:true});
  L.push({t:"ผู้อนุมัติ .............................",size:20,mb:12});
  let prs=printers;
  try{const all=await api.getAllPrinters();if(Array.isArray(all))prs=all.filter(p=>p.branch_id==null||+p.branch_id===+branch.id);}catch{}
  const rcps=getReceiptPrinters(prs);
  // kick = คืนเงินสด ต้องเปิดลิ้นชัก — เครื่องเดียวกับใบยกเลิก เขียนรวมครั้งเดียว (เหตุผลเดียวกับใบเสร็จบิลเงินสด)
  const kp=receiptKickPlan(rcps,kick?drawerPrinters(prs):[]);
  const dk=kp.alone.length||kp.withRcpt.size?{at:Date.now()}:null;
  const kickAlone=(list)=>{if(dk&&list.length)Promise.all(list.map(p=>api.updatePrinter(p.id,{description:cmdDesc(p,"dk",dk)}))).catch(()=>{});};
  kickAlone(kp.alone);
  if(!rcps.length){posToast("⚠️ ยกเลิกบิลแล้ว แต่ยังไม่ได้ติ๊กเครื่องพิมพ์ใบเสร็จ — ใบยกเลิกไม่ได้พิมพ์","warn",7000);return;}
  let b64;
  try{b64=await escposSlipRaster(L,576);}catch(e){kickAlone(rcps.filter(p=>kp.withRcpt.has(+p.id)));throw e;}
  const stamp=Date.now();
  // เขียนไม่ถึงบางเครื่อง = ลิ้นชักที่ฝากไปด้วยไม่ถึง → สั่งแยกเฉพาะเครื่องนั้น (เหตุผลเดียวกับใบเสร็จบิลเงินสด)
  const bad=[];
  await Promise.all(rcps.map(p=>api.updatePrinter(p.id,{description:withKick(cmdDesc(p,"pj",{at:stamp,b64,what:"ใบยกเลิกบิล",bill:order.id,table:String(order.table_number||"")}),kp.withRcpt.has(+p.id)?dk:null)}).catch(e=>{bad.push({p,e});})));
  if(bad.length){kickAfterFail(bad.map(x=>x.p).filter(p=>kp.withRcpt.has(+p.id)),dk);throw bad[0].e;}
  posToast("🧾 ส่งใบยกเลิกบิลไปเครื่องพิมพ์แล้ว","ok");
}
// ── ยกเลิกบิลที่ปิดไปแล้ว (Void) — ผู้จัดการขอไว้ 21 ก.ย. 69 ──────────────
// กติกาที่เจ้าของเคาะ: ทุกคนที่เข้าระบบขายกดได้ · เฉพาะบิลของกะที่เปิดอยู่ · ต้องเลือกเรื่องเงินคืนทุกครั้ง
// เหตุผลบังคับใส่ และบิลไม่ถูกลบทิ้ง — เปลี่ยนสถานะเป็นยกเลิกพร้อมร่องรอยครบ (ใคร เมื่อไหร่ เพราะอะไร คืนเงินทางไหน)
const VOID_REASONS=["ลูกค้ายกเลิก","กดผิดโต๊ะ","คิดเงินซ้ำ","ทดสอบระบบ"];
function VoidBillModal({order,branch,currentUser,shift,printers=[],onDone,onClose}){
  const o=order;
  const[reason,setReason]=useState("");
  const[refund,setRefund]=useState("");
  const[saving,setSaving]=useState(false);
  const total=round2(+o.total||0);
  const paidWith=(Array.isArray(o.payments)&&o.payments.length)?[...new Set(o.payments.map(p=>p&&p.method))]:(o.payment_method?[o.payment_method]:[]);
  const canSave=reason.trim().length>=3&&!!refund&&!saving;
  async function voidNow(){
    if(!canSave)return;
    const refundText=refund==="none"?"ไม่ได้คืนเงิน":"คืนเงินทาง "+payMethodLabel(refund);
    if(!await confirmDlg({title:"ยกเลิกบิลนี้",danger:true,confirmLabel:"ยกเลิกบิล",cancelLabel:"ไม่ยกเลิก",
      message:"บิล #"+o.id+" โต๊ะ "+o.table_number+" ยอด "+bahtR(total)+"\n"+refundText+"\nเหตุผล: "+reason.trim()+"\n\nยกเลิกแล้วยอดขายของกะนี้จะลดลงทันที"}))return;
    setSaving(true);
    try{
      const at=new Date().toISOString();
      const who=currentUser?.username||currentUser?.name||"-";
      const rec={kind:"bill",total,refund_method:refund,reason:reason.trim(),by:who,at,table:o.table_number};
      const patch={status:"cancelled",cancelled_by:who,cancelled_at:at,cancel_reason:reason.trim()+" · "+refundText,updated_at:at};
      let row=null;
      try{row=await api.updatePOSOrderIfUnchanged(o.id,o.updated_at,{...patch,void_log:[...(Array.isArray(o.void_log)?o.void_log:[]),rec]});}
      catch(err){
        // ฐานยังไม่มีคอลัมน์ void_log = ยกเลิกบิลต้องทำได้เหมือนเดิม แค่ไม่มีบรรทัดรายละเอียดบนใบปิดกะ
        const schemaErr=/column .* does not exist|PGRST204|schema cache/i.test(String((err&&err.message)||err));
        if(!schemaErr)throw err;
        row=await api.updatePOSOrderIfUnchanged(o.id,o.updated_at,patch);
      }
      if(!row){notifyDlg("บิลนี้เพิ่งถูกแก้จากอุปกรณ์อื่น — ปิดหน้านี้แล้วเปิดบิลใหม่อีกครั้งก่อนยกเลิก");setSaving(false);return;}
      // คืนเงินสด = เงินออกจากลิ้นชักจริง ต้องบันทึกและเปิดลิ้นชักให้หยิบเงิน
      if(refund==="cash"&&shift){
        try{
          const _ls=await liveShift(branch.id,shift);
          if(_ls.note)posToast(_ls.note,"warn",9000);
          await api.addCashMovement({shift_id:_ls.id,branch_id:branch.id,type:"refund",amount:total,
          reason:"ยกเลิกบิล #"+o.id+" โต๊ะ "+o.table_number+" — "+reason.trim(),order_id:o.id,user_id:currentUser?.id,username:who});}
        catch(err){console.error("บันทึกคืนเงินไม่สำเร็จ:",err);posToast("⚠️ ยกเลิกบิลแล้ว แต่บันทึกคืนเงินสดไม่สำเร็จ — ลงบันทึกที่ลิ้นชักเงินสดด้วยตัวเอง","warn",8000);}
      }
      // คืนเงินสด = ลิ้นชักเปิดไปพร้อมใบยกเลิกในการเขียนครั้งเดียว (เดิมยิงแยกสองงานแข่งกันเขียนแถวเครื่องแคชเชียร์)
      printVoidBillSlip({order:o,branch,reason:reason.trim(),refundText,by:who,at,printers,kick:refund==="cash"&&!!shift}).catch(()=>{});
      posToast("ยกเลิกบิล #"+o.id+" แล้ว","ok");
      onDone&&onDone();
    }catch(e){notifyDlg("ยกเลิกบิลไม่สำเร็จ: "+friendlyError(e));}
    setSaving(false);
  }
  const pill=(on)=>({padding:"10px 14px",borderRadius:10,border:"2px solid "+(on?C.red:C.line),background:on?C.redLight:C.white,
    color:on?C.red:C.ink2,cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:13.5,fontWeight:on?900:700,minHeight:44});
  return <div style={{position:"fixed",inset:0,background:"rgba(15,23,42,.78)",zIndex:6200,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
    <div style={{background:C.white,borderRadius:18,width:"100%",maxWidth:"min(95vw,520px)",maxHeight:"calc(100vh - 32px)",overflowY:"auto",WebkitOverflowScrolling:"touch",overscrollBehavior:"contain",boxShadow:"0 30px 80px rgba(0,0,0,.45)"}}>
      <div style={{padding:"16px 20px",background:C.red,color:C.white,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div style={{fontFamily:"'Sarabun',sans-serif",fontWeight:900,fontSize:18}}>🚫 ยกเลิกบิล #{o.id}</div>
        <button onClick={onClose} style={{background:"rgba(255,255,255,.2)",border:"none",borderRadius:10,width:44,height:44,cursor:"pointer",color:C.white,fontSize:20}}>✕</button>
      </div>
      <div style={{padding:20,fontFamily:"'Sarabun',sans-serif"}}>
        <div style={{background:C.bg,borderRadius:12,padding:"12px 14px",marginBottom:14,fontSize:13.5,color:C.ink2,lineHeight:1.8}}>
          <div>โต๊ะ <b style={{color:C.ink}}>{o.table_number}</b> · {(o.items||[]).length} รายการ</div>
          <div>ยอดบิล <b style={{color:C.ink,fontSize:18}}>{bahtR(total)}</b></div>
          <div>เดิมชำระโดย <b style={{color:C.ink}}>{paidWith.map(m=>payMethodLabel(m)).join(" + ")||"-"}</b>{o.paid_by?" · ปิดโดย "+o.paid_by:""}</div>
        </div>
        <div style={{fontSize:13.5,fontWeight:800,color:C.ink2,marginBottom:8}}>เหตุผลที่ยกเลิก *</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:7,marginBottom:9}}>
          {VOID_REASONS.map(r=><button key={r} onClick={()=>setReason(r)} style={pill(reason===r)}>{r}</button>)}
        </div>
        <input value={reason} onChange={e=>setReason(e.target.value)} placeholder="พิมพ์เหตุผล (อย่างน้อย 3 ตัวอักษร)"
          style={{...iS,fontSize:14.5,padding:"12px 14px",marginBottom:16}}/>
        <div style={{fontSize:13.5,fontWeight:800,color:C.ink2,marginBottom:8}}>เงินที่รับมาแล้ว คืนทางไหน *</div>
        <div style={{display:"flex",flexWrap:"wrap",gap:7,marginBottom:6}}>
          <button onClick={()=>setRefund("none")} style={pill(refund==="none")}>ไม่ได้คืนเงิน</button>
          {SETTLE_METHODS().map(mt=><button key={mt.v} onClick={()=>setRefund(mt.v)} style={pill(refund===mt.v)}>{mt.icon} {mt.l}</button>)}
        </div>
        {refund==="cash"&&<div style={{fontSize:12.5,color:C.red,fontWeight:700,marginBottom:6}}>ลิ้นชักจะเปิดให้หยิบเงินคืน และบันทึกเงินออก {bahtR(total)}</div>}
        <div style={{fontSize:12.5,color:C.ink4,lineHeight:1.7,margin:"10px 0 16px"}}>
          บิลจะถูกทำเครื่องหมายว่ายกเลิก ไม่ได้ลบทิ้ง — รายการอาหารและร่องรอยยังอยู่ครบ และจะขึ้นบนใบปิดกะ
        </div>
        <div style={{display:"flex",gap:8}}>
          <Btn v="ghost" onClick={onClose} full s={{padding:"12px"}}>ไม่ยกเลิก</Btn>
          <Btn v="danger" onClick={voidNow} loading={saving} disabled={!canSave} full icon={I.trash} s={{padding:"12px",fontWeight:900}}>ยกเลิกบิลนี้</Btn>
        </div>
      </div>
    </div>
  </div>;
}
// ── แก้ไขบิลที่ปิดแล้ว ────────────────────────────────────────────────────
// เจ้าของสั่ง 12 ก.ย. 69: คนที่เข้าระบบขายได้แก้ได้ทุกคน · ย้อนหลัง 7 วัน ·
// เก็บเพิ่ม/คืนเงินคนละช่องทางกับที่จ่ายมาได้ · ต้องใส่เหตุผลทุกครั้ง
// กติกาเหล็กของจอนี้: เขียนบิล → ขยับลิ้นชัก → บันทึกร่องรอย → แจ้งครัว ทำครบทุกครั้ง
// ส่วนต่างบวก = เก็บเงินเพิ่ม · ลบ = คืนเงินลูกค้า · ศูนย์ = สลับเมนูราคาเท่ากัน (ยังต้องมีเหตุผล)
const EDIT_BILL_DAYS=7;
const canEditPaidBill=(o)=>{
  if(!o||o.status!=="paid")return false;
  const t=new Date(o.updated_at||o.created_at).getTime();
  if(!Number.isFinite(t))return false;
  return (Date.now()-t)<=EDIT_BILL_DAYS*86400000;
};
// ช่องทางที่เลือกได้ตอนเก็บเพิ่ม/คืนเงิน = ช่องทางเดียวกับที่ระบบใช้ปิดบิล (ไม่มีรายชื่อซ้อนที่สอง)
// ช่องทางที่ใช้ตอนแบ่งจ่าย / เก็บเพิ่ม / คืนเงิน / แก้ช่องทางชำระ = ปุ่มบนจอเก็บเงิน + ช่องทางนอกจอ
// รายชื่อเดียวของทั้งระบบ ห้ามมีรายชื่อซ้อนที่สอง ไม่งั้นแก้ที่เดียวแล้วอีกจอไม่ตาม
const SETTLE_METHODS=()=>[...PAY_METHODS,...OTHER_PAY_METHODS];
// ส่วนลดรายเมนูเก็บเป็น "ชนิด+ค่า" ไว้ด้วย — ลดจำนวนแล้วต้องคิดใหม่ตามสูตรเดิม
// (ถ้าคงยอดลดเดิมไว้ ลดจาก 2 เหลือ 1 จะกลายเป็นลดเกินราคาอาหาร)
function recalcItemDiscounts(items){
  return (items||[]).map(it=>{
    const t=it.item_discount_type,v=+it.item_discount_value||0;
    if(!t||!v)return it;
    const line=(+it.price||0)*(+it.qty||0);
    const amt=t==="percent"?round2(line*v/100):Math.min(v,line);
    return {...it,item_discount:amt};
  });
}
function EditPaidBillModal({order,branch,posSettings,menus=[],printers=[],currentUser,shift,onDone,onClose}){
  const[items,setItems]=useState(()=>recalcItemDiscounts((order.items||[]).map(i=>({...i,line_uid:i.line_uid||uuidv4()}))));
  const[step,setStep]=useState("items");
  const[q,setQ]=useState("");
  const[optPick,setOptPick]=useState(null);
  // ตั้งต้นเป็นช่องทางของบิลเฉพาะเมื่อเป็นปุ่มที่เลือกได้จริง · บิลแบ่งจ่าย ("mixed") / ช่องทางเก่า = ต้องให้พนักงานเลือกเอง
  // เดิมตั้งต้น "mixed" ⟹ ไม่มีปุ่มไหนติด แต่กดบันทึกได้ ⟹ ส่วนต่างถูกบันทึกเป็นช่องทาง "แบ่งจ่าย" ที่ไม่มีอยู่จริง (ตรวจเจอ 28 ก.ย. 69)
  const[method,setMethod]=useState(SETTLE_METHODS().some(mt=>mt.v===order.payment_method)?order.payment_method:null);
  const[reason,setReason]=useState("");
  const[saving,setSaving]=useState(false);
  const optionLib=useMemo(()=>posSettings?.option_library||[],[posSettings]);
  const origByUid=useMemo(()=>{const m=new Map();for(const i of (order.items||[]))if(i.line_uid)m.set(String(i.line_uid),i);return m;},[order]);
  // ส่วนลดของบิล: ถ้าเป็นส่วนลดรายเมนู คิดใหม่จากรายการจริง · ถ้าเป็นส่วนลดทั้งบิล คงยอดเดิมไว้
  // โปรฯ คงเดิม · คูปองคิดใหม่จากยอดใหม่ตามกติกาเดียวกับจอเก็บเงิน · ภาษีแบบเดียวกับตอนปิดบิลใบนี้ (paidBillRecalc)
  const T=paidBillRecalc({order,items,posSettings});
  const oldTotal=round2(+order.total||0);
  const delta=round2(T.total-oldTotal);
  const added=items.filter(i=>!origByUid.has(String(i.line_uid)));
  // รายการที่หายไป/ลดจำนวน = ของที่ครัวทำไปแล้ว ต้องมีใบยกเลิกไปบอกครัว
  const removed=[];
  for(const [uid,o] of origByUid){
    const now=items.find(i=>String(i.line_uid)===uid);
    const gone=(+o.qty||0)-(now?(+now.qty||0):0);
    if(gone>0)removed.push({...o,qty:gone});
  }
  const bizDay=(d)=>{try{return new Date(d).toLocaleDateString("en-CA",{timeZone:"Asia/Bangkok"});}catch{return "";}};
  const oldDay=bizDay(order.updated_at||order.created_at),today=bizDay(new Date());
  const pastDay=!!(oldDay&&today&&oldDay!==today);   // บิลของวันก่อน (ข้ามเที่ยงคืน)
  // บิลของกะที่ปิดแล้ว (วันเดียวกันก็ได้ — ร้านเปิดวันละหลายกะ) = ยอดกะนั้นส่งบัญชีไปแล้ว แก้ตรงนี้ฝั่งบัญชีไม่เปลี่ยนตาม
  // ตัดสินด้วยกะอย่างเดียว ไม่ใช่วันที่: ส่งบัญชีเกิดตอนปิดกะเท่านั้น ⟹ บิลเมื่อวานในกะที่ยังเปิด (กะคร่อมเที่ยงคืน)
  // ยังไม่ได้ส่ง ยอดที่แก้จะไปกับใบตอนปิดกะเอง · เดิมบอกให้แจ้งบัญชีแก้วันเก่า = ส่วนต่างลงสองรอบ
  const shiftClosed=billShiftClosed(order,shift);
  const changed=added.length>0||removed.length>0||delta!==0;
  const editPkgScope=useMemo(()=>pkgMenuScopeOf(order&&order.items,pkgLibOf(posSettings)),[order,posSettings]);
  const menuList=useMemo(()=>{
    const s=q.trim().toLowerCase();
    return pkgPriced(menus.filter(m=>menuVisibleAt(m,branch?.id)&&(!s||String(m.name||"").toLowerCase().includes(s))).slice(0,60),editPkgScope);
  },[menus,branch,q,editPkgScope]);
  function addMenu(m,chosen,qty){
    const opts=chosen||[];
    const add=(opts).reduce((s,o)=>s+(+o.price||0),0);
    setItems(p=>[...p,{line_uid:uuidv4(),menu_id:m.id,name:m.name,price:round2((+m.price||0)+add),qty:qty||1,note:"",options:opts,printer_id:m.printer_id||null,category:menuCatOf(m)}]);
    setOptPick(null);
  }
  const chQty=(uid,d)=>setItems(p=>recalcItemDiscounts(p.map(i=>String(i.line_uid)===String(uid)?{...i,qty:Math.max(0,(+i.qty||0)+d)}:i).filter(i=>(+i.qty||0)>0)));
  const rmLine=(uid)=>setItems(p=>p.filter(i=>String(i.line_uid)!==String(uid)));
  async function save(){
    if(saving)return;
    if(!changed){notifyDlg("ยังไม่ได้แก้อะไรในบิลนี้");return;}
    if(!items.length){notifyDlg("บิลต้องมีอย่างน้อย 1 รายการ — ถ้าจะยกเลิกทั้งบิล ให้ใช้ปุ่มยกเลิกบิลที่จอโต๊ะแทน");return;}
    if(!reason.trim()){notifyDlg("กรุณาใส่เหตุผลที่แก้บิล");return;}
    if(delta!==0&&!method){notifyDlg(delta>0?"กรุณาเลือกว่ารับเงินเพิ่มทางไหน":"กรุณาเลือกว่าคืนเงินทางไหน");return;}
    if(delta!==0&&method==="cash"&&!shift?.id){notifyDlg("ยังไม่ได้เปิดกะ — เงินสดเข้า/ออกต้องบันทึกในกะ กรุณาเปิดกะก่อน");return;}
    setSaving(true);
    const who=currentUser?.username||currentUser?.name||"ไม่ทราบชื่อ";
    const at=new Date().toISOString();
    const clean=items.map(({_new,...i})=>i);
    const prevPays=Array.isArray(order.payments)&&order.payments.length
      ?order.payments
      :[{method:order.payment_method||"cash",amount:oldTotal,at:order.updated_at||order.created_at,by:order.paid_by||null}];
    const payments=delta!==0?[...prevPays,{method,amount:delta,at,by:who,reason:reason.trim()}]:prevPays;
    // discount = ส่วนลดทั้งหมด (ลดเอง+โปรฯ+คูปอง) รูปเดียวกับตอนปิดบิล — เดิมเก็บแค่ส่วนลดรายเมนู โปรฯ/คูปองหลุดจากบิล
    const base={items:clean,subtotal:T.subtotal,discount:T.totalDiscount,total:T.total,vat:T.vat,service_charge:T.sc,round_adj:T.roundAdj,updated_at:at,...(T.voucher?{voucher:T.voucher}:{})};
    // เงินสดจ่ายพอดี = ยอดรับต้องขยับตามยอดใหม่ ไม่งั้นใบเสร็จโชว์เงินทอนผี
    if(order.payment_method==="cash"&&method==="cash"&&+order.cash_received===oldTotal)base.cash_received=T.total;
    const full={...base,payments,edited_at:at,edited_by:who,edit_count:(+order.edit_count||0)+1};
    let row=null,noTrail=false;
    try{row=await api.updatePOSOrderIfUnchanged(order.id,order.updated_at,full);}
    catch(err){
      // ยังไม่ได้รันคำสั่ง SQL เพิ่มคอลัมน์ → ยอมให้แก้บิลได้ แต่ต้องบอกดังๆ ว่าครั้งนี้ไม่มีร่องรอย
      if(!/column .* does not exist|PGRST204|schema cache/i.test(String((err&&err.message)||err))){setSaving(false);notifyDlg("แก้บิลไม่สำเร็จ: "+friendlyError(err));return;}
      noTrail=true;
      try{row=await api.updatePOSOrderIfUnchanged(order.id,order.updated_at,base);}
      catch(e2){setSaving(false);notifyDlg("แก้บิลไม่สำเร็จ: "+friendlyError(e2));return;}
    }
    if(!row){setSaving(false);notifyDlg("บิลนี้เพิ่งถูกแก้จากอุปกรณ์อื่น — กรุณาปิดแล้วเปิดบิลนี้ใหม่ก่อนแก้");return;}
    // ── เงินในลิ้นชัก — เงินสดเท่านั้นที่ขยับลิ้นชัก ช่องทางอื่นบันทึกไว้ในบิล/ร่องรอย ──
    let mv=null;
    if(delta!==0&&method==="cash")kickCashDrawer(printers,branch?.id).catch(()=>{});   // ต้องหยิบ/ใส่เงินจริง
    if(delta!==0&&method==="cash"&&shift?.id){
      try{
        const _ls=await liveShift(branch.id,shift);
        if(_ls.note)posToast(_ls.note,"warn",9000);
        mv=await api.addCashMovement({shift_id:_ls.id,branch_id:branch.id,type:delta>0?"sale":"refund",amount:Math.abs(delta),
          reason:delta>0?"เก็บเงินเพิ่ม (แก้บิล)":"คืนเงินลูกค้า (แก้บิล)",
          note:`บิล #${order.id} โต๊ะ ${order.table_number||"-"} · ${reason.trim()}`,order_id:order.id,user_id:currentUser?.id||null,username:who});
      }catch(e){posToast("⚠️ แก้บิลแล้ว แต่บันทึกเงินเข้า/ออกลิ้นชักไม่สำเร็จ — กรุณาบันทึกเองที่ 💰 เงินในลิ้นชัก","warn",9000);}
    }
    // ── ร่องรอย (ห้ามแก้เงียบ) ──
    try{
      await api.addOrderEdit({order_id:order.id,branch_id:branch.id,shift_id:shift?.id||null,edited_by:who,reason:reason.trim(),
        delta,settle_method:delta!==0?method:null,old_total:oldTotal,new_total:T.total,
        items_before:order.items||[],items_after:clean,
        cash_movement_id:(Array.isArray(mv)?(mv[0]&&mv[0].id):(mv&&mv.id))||null,
        needs_accounting:shiftClosed,created_at:at});
    }catch(e){noTrail=true;}
    if(noTrail)posToast("⚠️ แก้บิลแล้ว แต่บันทึกร่องรอยไม่ได้ (ยังไม่ได้รันคำสั่ง SQL ของระบบแก้บิล) — แจ้งแอดมิน","warn",9000);
    // ── ครัว: ของที่เพิ่ม = ใบสั่งอาหารปกติ · ของที่ลด/ลบ = ใบยกเลิก (เฉพาะอาหาร — รายการแพ็คเกจไม่ไปครัว) ──
    try{
      const addedK=added.filter(isKitchenLine),removedK=removed.filter(isKitchenLine);
      if(addedK.length)await agentPrintItems(addedK,String(order.table_number||"-"),branch?.id,{bill:order.id,by:who,kind:""});
      if(removedK.length)await agentPrintItems(removedK.map(i=>({...i,name:`ยกเลิก: ${i.name}`,note:[i.note,`แก้บิลโดย ${who}`].filter(Boolean).join(" · ")})),String(order.table_number||"-"),branch?.id,{bill:order.id,by:who,kind:"void"});
    }catch(e){posToast("⚠️ แก้บิลแล้ว แต่แจ้งครัวไม่สำเร็จ — กรุณาบอกครัวด้วยตัวเอง","warn",9000);}
    // ── ใบเสร็จใหม่ (ยอดที่ถูกต้อง) ──
    try{await printBillReceipt({...order,...full,id:order.id},order.table_number,{branch,posSettings,printers,paid:true});}catch{}
    posToast(delta>0?`✅ แก้บิลแล้ว — เก็บเงินเพิ่ม ฿${Math.abs(delta).toLocaleString()}`:delta<0?`✅ แก้บิลแล้ว — คืนเงินลูกค้า ฿${Math.abs(delta).toLocaleString()}`:"✅ แก้บิลแล้ว (ยอดเท่าเดิม)","ok",7000);
    setSaving(false);
    onDone&&onDone();onClose&&onClose();
  }
  const F="'Sarabun',sans-serif";
  const REASONS=["ลูกค้าสั่งเพิ่ม","กดสั่งเกิน","กดผิดเมนู","ลูกค้าเปลี่ยนใจ","คิดเงินผิด","แถมให้ลูกค้า"];
  return <Modal title={`✏️ แก้ไขบิล #${order.id} — โต๊ะ ${order.table_number||"-"}`} onClose={saving?undefined:onClose} wide disableEsc>
    {shiftClosed?<div style={{padding:"11px 13px",borderRadius:10,marginBottom:10,background:"#FFFBEB",border:"2px solid #F59E0B",fontFamily:F,fontSize:13,color:"#92400E",lineHeight:1.6}}>
      <div style={{fontSize:14.5,fontWeight:900,marginBottom:2}}>⚠️ บิลนี้อยู่ในกะ{order.shift_id!=null?` #${order.shift_id}`:""} ที่ปิดไปแล้ว</div>
      ยอดของกะนั้นสรุปและส่งเข้าระบบบัญชีไปแล้ว — แก้ตรงนี้ <b>ยอดฝั่งบัญชีจะไม่เปลี่ยนตาม</b> ต้องแจ้งฝ่ายบัญชีเอง (บิล #{order.id} · วันที่ {fmtD(order.updated_at||order.created_at)}{delta!==0?` · ส่วนต่าง ${delta>0?"+":"-"}฿${Math.abs(delta).toLocaleString()}`:""})
      {delta!==0&&<div style={{fontSize:12,marginTop:2}}>เงินส่วนต่างที่เป็นเงินสดจะลงลิ้นชักของกะที่เปิดอยู่ตอนนี้</div>}
    </div>
    :pastDay&&<div style={{padding:"9px 12px",borderRadius:10,marginBottom:10,background:C.bg,border:`1px solid ${C.line}`,fontFamily:F,fontSize:12.5,color:C.ink3,lineHeight:1.6}}>
      บิลนี้ปิดเมื่อวันที่ {fmtD(order.updated_at||order.created_at)} แต่ยังอยู่ในกะที่เปิดอยู่ (ยังไม่ได้ส่งยอดเข้าบัญชี) — ยอดที่แก้จะไปกับยอดตอนปิดกะนี้เอง ไม่ต้องแจ้งฝ่ายบัญชี
    </div>}
    {step==="items"?<div>
      <div style={{display:"grid",gap:8,marginBottom:12}}>
        {items.map(it=><div key={it.line_uid} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",borderRadius:11,border:`1.5px solid ${origByUid.has(String(it.line_uid))?C.line:C.green}`,background:origByUid.has(String(it.line_uid))?C.white:C.greenLight}}>
          <div style={{flex:1,minWidth:0,fontFamily:F,lineHeight:1.35,overflowWrap:"anywhere"}}>
            <div style={{fontSize:15,fontWeight:800,color:C.ink}}>{!origByUid.has(String(it.line_uid))&&<span style={{fontSize:10.5,fontWeight:900,color:C.white,background:C.green,borderRadius:5,padding:"1px 6px",marginRight:6}}>เพิ่มใหม่</span>}{it.name}</div>
            {optionsText(it.options)&&<div style={{fontSize:12.5,fontWeight:700,color:C.teal}}>+ {optionsText(it.options)}</div>}
            {it.note&&<div style={{fontSize:12.5,color:C.ink3}}>★ {it.note}</div>}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:6,flexShrink:0}}>
            <button onClick={()=>chQty(it.line_uid,-1)} aria-label="ลดจำนวน" style={{width:34,height:34,borderRadius:9,border:`1.5px solid ${C.line}`,background:C.white,cursor:"pointer"}}>−</button>
            <span style={{fontSize:16,fontWeight:900,minWidth:22,textAlign:"center",fontFamily:F}}>{it.qty}</span>
            <button onClick={()=>chQty(it.line_uid,1)} aria-label="เพิ่มจำนวน" style={{width:34,height:34,borderRadius:9,border:"none",background:C.brand,color:C.white,cursor:"pointer"}}>+</button>
            <span style={{fontSize:14,fontWeight:800,color:C.brand,fontFamily:F,minWidth:62,textAlign:"right"}}>฿{round2((+it.price||0)*(+it.qty||0)-(+it.item_discount||0)).toLocaleString()}</span>
            <button onClick={()=>rmLine(it.line_uid)} aria-label="ลบรายการ" style={{width:34,height:34,borderRadius:9,border:`1.5px solid ${C.red}`,background:C.white,color:C.red,cursor:"pointer",fontWeight:900}}>✕</button>
          </div>
        </div>)}
      </div>
      <div style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:F,marginBottom:6}}>➕ เพิ่มเมนูเข้าบิล</div>
      <input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหาเมนู..." style={{...iS,marginBottom:8}}/>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:8,maxHeight:220,overflowY:"auto"}}>
        {menuList.map(m=><button key={m.id} onClick={()=>{if(menuHasOptions(m,branch?.id,optionLib))setOptPick(m);else addMenu(m,[],1);}} style={{padding:"9px 10px",borderRadius:10,border:`1px solid ${C.line}`,background:C.white,cursor:"pointer",fontFamily:F,textAlign:"left"}}>
          <div style={{fontSize:13,fontWeight:700,color:C.ink,lineHeight:1.3,overflowWrap:"anywhere"}}>{m.name}</div>
          <div style={{fontSize:12,fontWeight:800,color:C.brand}}>฿{(+m.price||0).toLocaleString()}</div>
        </button>)}
      </div>
      <div style={{display:"flex",gap:10,marginTop:14,alignItems:"center",flexWrap:"wrap"}}>
        <div style={{fontFamily:F,fontSize:13,color:C.ink3}}>ยอดเดิม ฿{oldTotal.toLocaleString()} → <b style={{color:C.ink,fontSize:16}}>฿{T.total.toLocaleString()}</b></div>
        <div style={{marginLeft:"auto",display:"flex",gap:8}}>
          <Btn v="ghost" onClick={onClose}>ปิด</Btn>
          <Btn v="primary" onClick={()=>setStep("settle")} disabled={!changed} icon={I.check}>ถัดไป — คิดเงินส่วนต่าง</Btn>
        </div>
      </div>
      {optPick&&<MenuOptionPicker menu={optPick} groups={getMenuOptions(optPick,branch?.id,optionLib)} onConfirm={(chosen,qty)=>addMenu(optPick,chosen,qty)} onClose={()=>setOptPick(null)}/>}
    </div>
    :<div>
      <div style={{background:C.bg,borderRadius:12,padding:"12px 16px",marginBottom:14,fontFamily:F}}>
        <div style={{display:"flex",justifyContent:"space-between",fontSize:13,color:C.ink3}}><span>ยอดเดิม</span><span>฿{oldTotal.toLocaleString()}</span></div>
        <div style={{display:"flex",justifyContent:"space-between",fontSize:13,color:C.ink3}}><span>ยอดใหม่</span><span>฿{T.total.toLocaleString()}</span></div>
        <div style={{display:"flex",justifyContent:"space-between",fontSize:18,fontWeight:900,marginTop:6,color:delta>0?C.brand:delta<0?C.red:C.ink}}>
          <span>{delta>0?"ต้องเก็บเพิ่ม":delta<0?"ต้องคืนลูกค้า":"ยอดเท่าเดิม"}</span><span>฿{Math.abs(delta).toLocaleString()}</span>
        </div>
      </div>
      {delta!==0&&<>
        <div style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:F,marginBottom:6}}>{delta>0?"รับเงินเพิ่มทางไหน":"คืนเงินทางไหน"}</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:8,marginBottom:14}}>
          {SETTLE_METHODS().map(mt=><button key={mt.v} onClick={()=>setMethod(mt.v)} style={{display:"flex",alignItems:"center",gap:8,padding:"12px 14px",borderRadius:12,border:`2.5px solid ${method===mt.v?mt.c:C.line}`,background:method===mt.v?`${mt.c}12`:C.white,cursor:"pointer",fontFamily:F}}>
            <span style={{fontSize:22}}>{mt.icon||"💠"}</span>
            <span style={{fontSize:14,fontWeight:800,color:method===mt.v?mt.c:C.ink2}}>{mt.l}</span>
          </button>)}
        </div>
        {method==="cash"&&<div style={{fontSize:12,color:C.ink3,fontFamily:F,marginBottom:12}}>เงินสดจะบันทึกเข้า/ออกลิ้นชักของกะที่เปิดอยู่ให้อัตโนมัติ</div>}
      </>}
      <div style={{fontSize:13,fontWeight:800,color:C.ink2,fontFamily:F,marginBottom:6}}>เหตุผลที่แก้บิล <span style={{color:C.red}}>*</span></div>
      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:8}}>
        {REASONS.map(r=><button key={r} onClick={()=>setReason(r)} style={{padding:"6px 12px",borderRadius:20,border:`1px solid ${reason===r?C.brand:C.line}`,background:reason===r?C.brandLight:C.white,color:reason===r?C.brand:C.ink3,cursor:"pointer",fontFamily:F,fontSize:12.5,fontWeight:700}}>{r}</button>)}
      </div>
      <textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="เช่น ลูกค้าสั่งคาปูชิโน่เกิน 1 แก้ว คืนเงินสดให้แล้ว" rows={2} style={{...iS,resize:"vertical",fontFamily:F}}/>
      <div style={{display:"flex",gap:8,marginTop:14,justifyContent:"flex-end"}}>
        <Btn v="ghost" onClick={()=>setStep("items")} disabled={saving}>ย้อนกลับ</Btn>
        <Btn v="success" onClick={save} loading={saving} disabled={saving||!reason.trim()} icon={I.check}>ยืนยันแก้บิล</Btn>
      </div>
    </div>}
  </Modal>;
}

// เวลาที่ "มีอะไรเกิดขึ้นล่าสุด" กับบิลใบนี้ — ปิดบิล/แก้บิล/สั่งเพิ่ม ใช้ updated_at
// บิลที่ยังไม่เคยถูกแตะเลยก็ใช้เวลาที่เปิดโต๊ะ
const billActedAt=(o)=>{
  const t=Date.parse((o&&(o.updated_at||o.created_at))||"");
  return Number.isFinite(t)?t:0;
};
// ── แยกตามวิธีชำระเงิน (จอรายงานยอดขายใน POS) ────────────────────────────────
// แถวหลักยังจัดตาม "ชนิดบิล" เหมือนเดิม แต่บิลแบ่งจ่ายต้องแตกออกมาว่าจ่ายช่องทางไหนไปเท่าไร
// เจ้าของขอ 28 ก.ย. 69: เห็นแค่ "แบ่งจ่ายหลายช่องทาง · 1 บิล ฿25" (บิล #478 = พร้อมเพย์ ฿17 + เงินสด ฿8)
// พนักงานหน้าร้านไม่รู้ว่าเงินสด/ยอดโอนจริงต้องเป็นเท่าไร ⟹ บอกทั้งยอดแตกย่อย และยอดรับจริงต่อช่องทางที่รวมส่วนแบ่งจ่ายแล้ว
// กติกาเดียวกับใบปิดกะและท่อบัญชี: มี payments ใช้ payments · ไม่มีใช้ช่องทางของบิลทั้งใบ
// บิลป้าย mixed ที่ไม่มี payments (บิลเก่าก่อน 12 ก.ย. 69) = ไม่รู้ว่าเข้าช่องไหน ต้องบอกตรงๆ ห้ามเดา
function payBreakdown(paid){
  const r2=(n)=>Math.round((+n||0)*100)/100;
  // ขั้นที่ช่องทางเป็น "mixed" หรือว่าง ไม่ใช่ช่องทางจริง (เกิดได้จากแก้บิลแบ่งจ่ายแล้วไม่ได้เลือกช่องทาง ก่อน 28 ก.ย. 69)
  const mOf=(p)=>{const m=String((p&&p.method)||"");return(!m||m==="mixed"||m==="split")?"unknown":m;};
  const rows=new Map();
  const bump=(list,key,a)=>{let e=list.find(x=>x.key===key);if(!e){e={key,n:0,sum:0};list.push(e);}e.n++;e.sum=r2(e.sum+a);};
  const realList=[];
  for(const o of (paid||[])){
    const t=+o.total||0;
    const ps=Array.isArray(o.payments)?o.payments.filter(Boolean):[];
    const split=new Set(ps.map(mOf)).size>1||o.payment_method==="mixed";
    const k=split?"mixed":(o.payment_method||"other");
    const e=rows.get(k)||{key:k,n:0,sum:0,parts:[]};e.n++;e.sum=r2(e.sum+t);rows.set(k,e);
    const steps=ps.length?ps.map(p=>({m:mOf(p),a:+p.amount||0})):[{m:split?"unknown":k,a:t}];
    for(const s of steps){bump(realList,s.m,s.a);if(split)bump(e.parts,s.m,s.a);}
  }
  const byAmt=(a,b)=>b.sum-a.sum;
  const list=[...rows.values()].sort(byAmt);
  for(const e of list)e.parts.sort(byAmt);
  return{rows:list,hasSplit:rows.has("mixed"),real:realList.sort(byAmt)};
}
function SalesReportModal({currentBranch,onClose,menus=[],printers=[],posSettings=null,shift=null,currentUser=null,onEdited}){
  const[editBill,setEditBill]=useState(null);const[voidBill,setVoidBill]=useState(null);const[fixPayBill,setFixPayBill]=useState(null);const[reloadTick,setReloadTick]=useState(0);
  // ยกเลิกบิลได้เฉพาะบิลของ "กะที่เปิดอยู่" — บิลของกะที่ปิดไปแล้วส่งยอดเข้าบัญชีแล้ว ต้องแก้ผ่านบัญชี
  const canVoidBill=(o)=>!!(shift&&shift.status!=="closed"&&o&&o.status==="paid"&&shift.opened_at&&Date.parse(o.created_at||"")>=Date.parse(shift.opened_at));
  const isoKey=(d)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;  // machine key (ISO) — do NOT shadow the global BE fmtD
  const todayStr=isoKey(new Date());
  const[date,setDate]=useState(todayStr);
  const[span,setSpan]=useState(1);               // ดูย้อนหลังกี่วันนับจากวันที่เลือก (1 = วันเดียว)
  const[q,setQ]=useState("");                     // ค้นหา: เลขบิล · โต๊ะ · ชื่อเมนู · ยอด
  const[filter,setFilter]=useState("all");
  // เปิดจอมาให้เห็น "กะที่ทำอยู่" ก่อน เพราะคนกดส่วนใหญ่กำลังนับเงินในลิ้นชักของกะนั้น
  const[scope,setScope]=useState("shift");
  const[orders,setOrders]=useState([]);
  const[loading,setLoading]=useState(true);
  const[bill,setBill]=useState(null);
  const[cfg,setCfg]=useState(null);               // ตั้งค่าใบเสร็จ — โหลดล่วงหน้าไว้เลย
  const aliveRef=useRef(true);
  useEffect(()=>()=>{aliveRef.current=false;},[]);
  // โหลดตั้งค่าตั้งแต่เปิดจอ ไม่ใช่ตอนกดพิมพ์ — ถ้าไปโหลดตอนกด หน้าต่างพิมพ์จะเปิดหลัง await
  // แล้วเบราว์เซอร์จะบล็อกเพราะไม่นับว่าเป็นการกดของผู้ใช้แล้ว
  useEffect(()=>{let ok=true;(async()=>{
    try{const r=await api.getPOSSettings(currentBranch.id);if(ok)setCfg((r&&r[0])||null);}catch{}
  })();return()=>{ok=false;};},[currentBranch.id]);
  useEffect(()=>{
    let cancel=false;setLoading(true);setBill(null);
    (async()=>{
      try{
        // ช่วงวันที่: นับถอยหลังจากวันที่เลือก เช่น 7 วัน = วันที่เลือกและ 6 วันก่อนหน้า
        const end=new Date(date+"T00:00:00");end.setDate(end.getDate()+1);
        const start=new Date(date+"T00:00:00");start.setDate(start.getDate()-(span-1));
        const o=await api.getPOSOrdersByDay(currentBranch.id,start.toISOString(),end.toISOString());
        if(!cancel&&aliveRef.current)setOrders(Array.isArray(o)?o:[]);
      }catch(e){if(!cancel&&aliveRef.current)setOrders([]);}
      if(!cancel&&aliveRef.current)setLoading(false);
    })();
    return()=>{cancel=true;};
  },[date,span,currentBranch.id,reloadTick]);

  // ค้นหาจากสิ่งที่คนจำได้จริงตอนตามหาบิลเก่า: เลขบิล เลขโต๊ะ ชื่อเมนูที่สั่ง หรือยอดเงิน
  const hit=(o)=>{
    const t=q.trim().toLowerCase();
    if(!t)return true;
    if(String(o.id).includes(t))return true;
    if(String(o.table_number||"").toLowerCase().includes(t))return true;
    if(String(Math.round(+o.total||0)).includes(t.replace(/[,฿\s]/g,"")))return true;
    return (o.items||[]).some(i=>String(i&&i.name||"").toLowerCase().includes(t));
  };
  // ขอบเขตกะ: บิลที่ "เปิดโต๊ะ" ระหว่างกะนี้ — กติกาเดียวกับ api/sliptrack-push.js ที่ส่งบัญชี
  const inShift=(o)=>{
    if(!shift||!shift.opened_at)return true;
    const t=Date.parse(o&&o.created_at||"");
    if(!Number.isFinite(t))return false;
    if(t<Date.parse(shift.opened_at))return false;
    if(shift.closed_at&&t>=Date.parse(shift.closed_at))return false;
    return true;
  };
  // ดูเป็นรายกะได้เฉพาะตอนดูวันนี้วันเดียวและมีกะเปิดอยู่ — ย้อนหลังหลายวันไม่มีความหมาย
  const canShiftView=!!(shift&&shift.opened_at&&span===1&&date===todayStr);
  const shiftView=canShiftView&&scope==="shift";
  const all=(shiftView?orders.filter(inShift):orders).filter(hit);
  const paid=all.filter(o=>o.status==="paid");
  const unpaid=all.filter(o=>o.status!=="paid"&&o.status!=="cancelled");
  const cancelled=all.filter(o=>o.status==="cancelled");
  // discount ของบิลรวมโปรฯ และคูปองไว้แล้ว (billDiscParts) — บวก promo_amount เพิ่มอีก = โปรฯ นับสองรอบ
  const discTotal=paid.reduce((s,o)=>s+(+o.discount||0),0);
  const lostTotal=cancelled.reduce((s,o)=>s+(+o.total||0),0);
  const rev=paid.reduce((s,o)=>s+(+o.total||0),0);
  const avg=paid.length?rev/paid.length:0;
  // ── ตัวเลขที่จอนี้ยังไม่เคยบอก ─────────────────────────────────────────
  // "ยอดขายที่ปิดแล้ว" อย่างเดียวไม่พอสำหรับดูระหว่างวัน — เจ้าของอยากรู้ว่า
  // ตอนนี้ทั้งร้านมีเงินอยู่เท่าไหร่ รวมโต๊ะที่ยังไม่ปิดด้วย
  const openRev=unpaid.reduce((s2,o)=>s2+(+o.total||0),0);       // ยอดค้างในโต๊ะที่ยังไม่ปิด
  const grandRev=rev+openRev;                                     // ยอดขายทั้งหมดขณะนี้
  const grossTotal=paid.reduce((s2,o)=>s2+(+o.subtotal||0),0);   // ก่อนหักส่วนลด
  const vatTotal=paid.reduce((s2,o)=>s2+(+o.vat||0),0);
  const svcTotal=paid.reduce((s2,o)=>s2+(+o.service_charge||0),0);
  const roundTotal=paid.reduce((s2,o)=>s2+(+o.round_adj||0),0);
  const discPct=grossTotal>0?(discTotal/grossTotal*100):0;
  const itemQty=paid.reduce((s2,o)=>s2+(o.items||[]).reduce((a,i)=>a+(isPkgLine(i)?0:(+i.qty||0)),0),0);   // จานอาหาร ไม่นับหัวลูกค้าบุฟเฟต์
  const avgItem=itemQty>0?rev/itemQty:0;
  const pkgGuests=pkgGuestRowsOf(paid);   // ลูกค้าบุฟเฟต์ (ผู้ใหญ่/เด็ก) ของบิลที่ปิดแล้ว
  // บิลที่ยกเลิกโดยไม่มีบันทึกว่าใครยกเลิก = ตรวจย้อนหลังไม่ได้เลย ต้องเห็นตัวเลขนี้
  const cancelNoWho=cancelled.filter(o=>!o.cancelled_by).length;
  // เมนูขายดี — นับจากบิลที่ปิดแล้วเท่านั้น
  const topMenus=(()=>{
    const m2=new Map();
    for(const o of paid)for(const i of (o.items||[])){
      if(isPkgLine(i))continue;   // หัวลูกค้าบุฟเฟต์ไม่ใช่เมนู
      const k=String(i.name||"").trim();if(!k)continue;
      const cur=m2.get(k)||{qty:0,amt:0};
      cur.qty+=(+i.qty||0);cur.amt+=(+i.price||0)*(+i.qty||0);m2.set(k,cur);
    }
    return [...m2.entries()].map(([name,v])=>({name,...v})).sort((a,b)=>b.qty-a.qty).slice(0,5);
  })();
  // ช่วงเวลาที่ขายดี — ชั่วโมงไหนเงินเข้าเยอะสุด (ใช้จัดกำลังคน)
  const byHour=(()=>{
    const h=new Map();
    for(const o of paid){const d=new Date(o.updated_at||o.created_at);if(isNaN(d))continue;
      const k=d.getHours();h.set(k,(h.get(k)||0)+(+o.total||0));}
    return [...h.entries()].sort((a,b)=>b[1]-a[1]).slice(0,3);
  })();
  const PB=payBreakdown(paid);
  // ทุกตัวเลขในกล่องแยกตามวิธีชำระใช้ตัวนี้ตัวเดียว — แถวหลักปัดเป็นบาทแต่แถวย่อยมีสตางค์ = บวกกันบนจอไม่ลง (บิล 9 ก.ย. 69 มีสตางค์)
  const m2=(n)=>(+n||0).toLocaleString(undefined,{maximumFractionDigits:2});
  const payName=(k)=>k==="unknown"?"⚠️ ไม่มีรายละเอียดว่าจ่ายช่องทางไหน":(PAY_LABEL[k]||k);
  // เดิมบิลที่ยกเลิกถูกกรองทิ้งทุกตัวกรอง เหลือแค่ตัวเลขนับมุมขวา — กดดูไม่ได้เลย
  // ซึ่งแปลว่ากินเงินสดแล้วกดยกเลิกจะไม่มีใครเห็นอะไรเลย ต้องเปิดให้ดูได้
  const baseList=filter==="paid"?paid:filter==="unpaid"?unpaid:filter==="cancelled"?cancelled:[...paid,...unpaid,...cancelled];
  const list=baseList.slice().sort((a,b)=>billActedAt(b)-billActedAt(a));   // อะไรเพิ่งเกิดล่าสุด อยู่บนสุด
  const m=(n)=>(+n||0).toLocaleString(undefined,{maximumFractionDigits:0});

  const isToday=date===todayStr;
  const shiftDay=(delta)=>{const d=new Date(date+"T00:00:00");d.setDate(d.getDate()+delta);const ns=isoKey(d);if(ns<=todayStr)setDate(ns);};
  const stC={pending:C.yellow,confirmed:C.green,bill_requested:C.brand,paid:C.green,cancelled:C.ink4};
  const stL={pending:"รอยืนยัน",confirmed:"กำลังทำ",bill_requested:"เรียกบิล",paid:"ชำระแล้ว",cancelled:"ยกเลิก"};
  const navBtn={width:34,height:34,borderRadius:9,border:`1px solid ${C.line}`,background:C.white,cursor:"pointer",fontSize:13,color:C.ink2,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0};

  return <Modal title="📊 รายงานยอดขาย" onClose={onClose} extraWide>
    {/* ── เลือกวัน ── */}
    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:14,flexWrap:"wrap"}}>
      <button onClick={()=>shiftDay(-1)} style={navBtn} title="วันก่อนหน้า">◀</button>
      <input type="date" value={date} max={todayStr} onChange={e=>e.target.value&&setDate(e.target.value)} style={{padding:"10px 13px",borderRadius:9,border:`1px solid ${C.line}`,fontSize:15.5,fontFamily:"'Sarabun',sans-serif",color:C.ink,background:C.white}}/>
      <button onClick={()=>shiftDay(1)} disabled={isToday} style={{...navBtn,opacity:isToday?.4:1,cursor:isToday?"default":"pointer"}} title="วันถัดไป">▶</button>
      {!isToday&&<button onClick={()=>setDate(todayStr)} style={{padding:"8px 13px",borderRadius:9,border:`1px solid ${C.brand}`,background:`${C.brand}12`,color:C.brand,cursor:"pointer",fontSize:12.5,fontWeight:800,fontFamily:"'Sarabun',sans-serif"}}>วันนี้</button>}
      <span style={{marginLeft:"auto",fontSize:15,fontWeight:700,color:C.ink2,fontFamily:"'Sarabun',sans-serif"}}>{span>1?`ย้อนหลัง ${span} วัน ถึง ${fmtD(date)}`:(shiftView?`กะที่เปิดอยู่ · ตั้งแต่ ${new Date(shift.opened_at).toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit",timeZone:"Asia/Bangkok"})} น.`:`${fmtD(date)}${isToday?" · ทั้งวัน":""}`)}</span>
    </div>

    {/* ── ช่วงเวลา + ค้นหา ── */}
    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:12,flexWrap:"wrap"}}>
      {canShiftView&&<div style={{display:"flex",gap:5}}>
        {[{v:"shift",l:"กะนี้"},{v:"day",l:"ทั้งวัน"}].map(o=>{const on=(scope===o.v);
          return <button key={o.v} onClick={()=>setScope(o.v)} style={{padding:"9px 16px",borderRadius:20,border:`1px solid ${on?C.green:C.line}`,background:on?C.green:C.white,color:on?C.white:C.ink2,cursor:"pointer",fontSize:14.5,fontWeight:on?800:600,fontFamily:"'Sarabun',sans-serif"}}>{o.l}</button>;
        })}
      </div>}
      <div style={{display:"flex",gap:5}}>
        {[{v:1,l:"วันเดียว"},{v:7,l:"7 วัน"},{v:30,l:"30 วัน"}].map(o=>{const on=span===o.v;
          return <button key={o.v} onClick={()=>setSpan(o.v)} style={{padding:"9px 16px",borderRadius:20,border:`1px solid ${on?C.brand:C.line}`,background:on?C.brand:C.white,color:on?C.white:C.ink2,cursor:"pointer",fontSize:14.5,fontWeight:on?800:600,fontFamily:"'Sarabun',sans-serif"}}>{o.l}</button>;})}
      </div>
      <div style={{position:"relative",flex:"1 1 240px",minWidth:200}}>
        <input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหา: เลขบิล · โต๊ะ · ชื่อเมนู · ยอดเงิน"
          style={{width:"100%",padding:"10px 32px 10px 13px",borderRadius:9,border:`1px solid ${C.line}`,fontSize:15.5,fontFamily:"'Sarabun',sans-serif",color:C.ink}}/>
        {q&&<button onClick={()=>setQ("")} title="ล้างคำค้น" style={{position:"absolute",right:6,top:"50%",transform:"translateY(-50%)",border:"none",background:"transparent",cursor:"pointer",color:C.ink4,fontSize:15,lineHeight:1}}>×</button>}
      </div>
      {q&&<span style={{fontSize:14,fontWeight:700,color:C.ink3,fontFamily:"'Sarabun',sans-serif"}}>เจอ {all.length} บิล จาก {orders.length}</span>}
    </div>

    {loading?<div style={{padding:"40px 0"}}><Loading text="กำลังโหลดรายงาน..."/></div>
    :bill?<><BillDetailCard order={bill} branch={currentBranch} cfg={cfg} onBack={()=>setBill(null)} onEdit={()=>setEditBill(bill)}
        onVoid={canVoidBill(bill)?()=>setVoidBill(bill):null}
        onFixPay={canVoidBill(bill)?()=>setFixPayBill(bill):null}/>
      {fixPayBill&&<PayChannelFixModal order={fixPayBill} branch={currentBranch} currentUser={currentUser} shift={shift}
        onDone={()=>{setFixPayBill(null);setBill(null);setReloadTick(t=>t+1);onEdited&&onEdited();}} onClose={()=>setFixPayBill(null)}/>}
      {voidBill&&<VoidBillModal order={voidBill} branch={currentBranch} currentUser={currentUser} shift={shift} printers={printers}
        onDone={()=>{setVoidBill(null);setBill(null);setReloadTick(t=>t+1);onEdited&&onEdited();}} onClose={()=>setVoidBill(null)}/>}
      {editBill&&<EditPaidBillModal order={editBill} branch={currentBranch} posSettings={posSettings} menus={menus} printers={printers} currentUser={currentUser} shift={shift}
        onDone={()=>{setEditBill(null);setBill(null);setReloadTick(t=>t+1);onEdited&&onEdited();}} onClose={()=>setEditBill(null)}/>}</>
    :<>
      {/* ── สรุปยอด ── */}
      <div style={{display:"flex",gap:12,marginBottom:14,flexWrap:"wrap"}}>
        {[{l:"🧮 ยอดขายทั้งหมดขณะนี้",v:`฿${m(grandRev)}`,c:C.ink,sub:"ปิดแล้ว + ยังไม่ปิด"},
          {l:"💰 ยอดขาย (ปิดบิลแล้ว)",v:`฿${m(rev)}`,c:C.green,sub:`${paid.length} บิล`},
          {l:"⏳ ยอดค้างในโต๊ะ (ยังไม่ปิด)",v:`฿${m(openRev)}`,c:C.yellow,sub:`${unpaid.length} โต๊ะ`},
          ...(grossTotal>0?[{l:"🧾 ยอดก่อนส่วนลด",v:`฿${m(grossTotal)}`,c:C.ink2}]:[]),
          ...(discTotal>0?[{l:"🎁 ส่วนลดที่ให้ไป",v:`฿${m(discTotal)}`,c:C.purple,sub:`${discPct.toFixed(1)}% ของยอดก่อนลด`,warn:discPct>=15}]:[]),
          ...(lostTotal>0?[{l:"🗑️ มูลค่าบิลที่ยกเลิก",v:`฿${m(lostTotal)}`,c:C.red,sub:`${cancelled.length} ใบ`+(cancelNoWho?` · ${cancelNoWho} ใบไม่รู้ว่าใครยกเลิก`:""),warn:true}]:[]),
          ...(svcTotal>0?[{l:"💼 ค่าบริการ",v:`฿${m(svcTotal)}`,c:C.teal}]:[]),
          ...(vatTotal>0?[{l:"📊 VAT",v:`฿${m(vatTotal)}`,c:C.blue}]:[]),
          ...(roundTotal!==0?[{l:"🪙 ปัดเศษรวม",v:`${roundTotal>0?"+":"-"}฿${m(Math.abs(roundTotal))}`,c:C.ink3}]:[]),
          {l:"📈 เฉลี่ย/บิล",v:`฿${m(avg)}`,c:C.brand},
          ...(itemQty>0?[{l:"🍽️ จำนวนรายการที่ขาย",v:`${m(itemQty)} ชิ้น`,c:C.ink2,sub:`เฉลี่ย ฿${m(avgItem)}/ชิ้น`}]:[]),
          ...(pkgGuests.length?[{l:"🍖 ลูกค้าบุฟเฟต์",v:`${m(pkgGuests.reduce((t,g)=>t+g.qty,0))} คน`,c:"#065F46",sub:pkgGuests.map(g=>`${g.label} ${g.qty}`).join(" · ")}]:[])].map(s=><div key={s.l} style={{flex:"1 1 190px",background:C.white,borderRadius:12,padding:"14px 18px",border:`1px solid ${s.warn?C.red+"55":C.line}`}}><div style={{fontSize:14,color:C.ink4,fontFamily:"'Sarabun',sans-serif"}}>{s.l}</div><div style={{fontSize:28,fontWeight:900,color:s.c,fontFamily:"'Sarabun',sans-serif"}}>{s.v}</div>{s.sub&&<div style={{fontSize:12.5,color:s.warn?C.red:C.ink4,fontFamily:"'Sarabun',sans-serif",marginTop:2,lineHeight:1.4}}>{s.sub}</div>}</div>)}
      </div>
      {PB.rows.length>0&&<div style={{background:C.bg,borderRadius:12,padding:"12px 16px",marginBottom:14,border:`1px solid ${C.line}`}}>
        <div style={{fontSize:15,fontWeight:800,color:C.ink,fontFamily:"'Sarabun',sans-serif",marginBottom:9}}>💳 แยกตามวิธีชำระเงิน</div>
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {PB.rows.map(r=><div key={r.key}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,fontSize:14.5,fontFamily:"'Sarabun',sans-serif"}}><span style={{color:C.ink2,minWidth:0}}>{PAY_LABEL[r.key]||r.key} <span style={{color:C.ink4}}>· {r.n} บิล</span></span><span style={{fontWeight:800,color:C.ink,whiteSpace:"nowrap"}}>฿{m2(r.sum)}</span></div>
            {r.parts.length>0&&<div style={{margin:"5px 0 3px 12px",paddingLeft:12,borderLeft:`2px solid ${C.brand}55`,display:"flex",flexDirection:"column",gap:4}}>
              {r.parts.map(p=><div key={p.key} style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,fontSize:13.5,fontFamily:"'Sarabun',sans-serif"}}>
                <span style={{color:p.key==="unknown"?C.red:C.ink3,minWidth:0}}>↳ {payName(p.key)} <span style={{color:C.ink4}}>· {p.n} ครั้ง</span></span>
                <span style={{fontWeight:700,color:p.key==="unknown"?C.red:C.ink2,whiteSpace:"nowrap"}}>฿{m2(p.sum)}</span>
              </div>)}
            </div>}
          </div>)}
        </div>
        {PB.hasSplit&&<div style={{marginTop:11,paddingTop:10,borderTop:`1px dashed ${C.line}`}}>
          <div style={{fontSize:14,fontWeight:800,color:C.ink,fontFamily:"'Sarabun',sans-serif",marginBottom:7}}>🧾 ยอดรับจริงแต่ละช่องทาง <span style={{fontWeight:600,color:C.ink4,fontSize:12.5}}>(รวมส่วนที่แบ่งจ่ายแล้ว)</span></div>
          <div style={{display:"flex",flexDirection:"column",gap:5}}>
            {PB.real.map(p=><div key={p.key} style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,fontSize:14.5,fontFamily:"'Sarabun',sans-serif"}}>
              <span style={{color:p.key==="unknown"?C.red:C.ink2,minWidth:0}}>{payName(p.key)}</span>
              <span style={{fontWeight:900,color:p.key==="unknown"?C.red:C.green,whiteSpace:"nowrap"}}>฿{m2(p.sum)}</span>
            </div>)}
          </div>
        </div>}
      </div>}
      {/* เมนูขายดี + ช่วงเวลาที่ขายดี — สองอย่างที่ใช้ตัดสินใจสั่งของและจัดกำลังคน */}
      {(topMenus.length>0||byHour.length>0)&&<div style={{display:"flex",gap:12,marginBottom:14,flexWrap:"wrap"}}>
        {topMenus.length>0&&<div style={{flex:"1 1 280px",background:C.white,borderRadius:12,padding:"12px 16px",border:`1px solid ${C.line}`}}>
          <div style={{fontSize:15,fontWeight:800,color:C.ink,fontFamily:"'Sarabun',sans-serif",marginBottom:9}}>🔥 เมนูขายดี (จากบิลที่ปิดแล้ว)</div>
          {topMenus.map((t,i)=><div key={t.name} style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8,fontSize:14.5,fontFamily:"'Sarabun',sans-serif",padding:"4px 0"}}>
            <span style={{color:C.ink2,minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{i+1}. {t.name}</span>
            <span style={{color:C.ink3,whiteSpace:"nowrap"}}><b style={{color:C.ink}}>{m(t.qty)}</b> ชิ้น · ฿{m(t.amt)}</span>
          </div>)}
        </div>}
        {byHour.length>0&&<div style={{flex:"1 1 220px",background:C.white,borderRadius:12,padding:"12px 16px",border:`1px solid ${C.line}`}}>
          <div style={{fontSize:15,fontWeight:800,color:C.ink,fontFamily:"'Sarabun',sans-serif",marginBottom:9}}>⏰ ช่วงเวลาที่ขายดี</div>
          {byHour.map(([h,v])=><div key={h} style={{display:"flex",justifyContent:"space-between",fontSize:14.5,fontFamily:"'Sarabun',sans-serif",padding:"4px 0"}}>
            <span style={{color:C.ink2}}>{String(h).padStart(2,"0")}:00 - {String(h).padStart(2,"0")}:59</span>
            <span style={{fontWeight:800,color:C.ink}}>฿{m(v)}</span>
          </div>)}
        </div>}
      </div>}
      {/* ── ตัวกรอง: ทั้งหมด / ปิดบิลแล้ว / ยังไม่ปิดบิล ── */}
      <div style={{display:"flex",gap:6,marginBottom:12,flexWrap:"wrap",alignItems:"center"}}>
        {[{id:"all",l:"ทั้งหมด",n:paid.length+unpaid.length+cancelled.length},{id:"paid",l:"ปิดบิลแล้ว",n:paid.length},{id:"unpaid",l:"ยังไม่ปิดบิล",n:unpaid.length},{id:"cancelled",l:"🗑️ ยกเลิก",n:cancelled.length,warn:true}].map(t=>{const on=filter===t.id;const ac=t.warn?C.red:C.brand;return <button key={t.id} onClick={()=>setFilter(t.id)} style={{padding:"9px 17px",borderRadius:20,border:`1px solid ${on?ac:(t.warn&&t.n>0?`${C.red}66`:C.line)}`,background:on?ac:C.white,color:on?C.white:(t.warn&&t.n>0?C.red:C.ink2),cursor:"pointer",fontSize:14.5,fontWeight:on?800:600,fontFamily:"'Sarabun',sans-serif"}}>{t.l} ({t.n})</button>;})}
      </div>
      {/* ── รายการบิล (กดเข้าดูรายละเอียด) ── */}
      {list.length===0?<div style={{textAlign:"center",padding:"40px 0",color:C.ink4}}><Ic d={I.order} s={46} c={C.line}/><p style={{marginTop:12,fontFamily:"'Sarabun',sans-serif"}}>ไม่มีบิลในวันนี้</p></div>
      :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(260px,100%),1fr))",gap:10}}>
        {list.map(o=><button key={o.id} onClick={()=>setBill(o)} style={{textAlign:"left",background:C.white,borderRadius:12,border:`1px solid ${C.line}`,overflow:"hidden",cursor:"pointer",padding:0,fontFamily:"'Sarabun',sans-serif",transition:"box-shadow .15s,border-color .15s"}} onMouseEnter={e=>{e.currentTarget.style.boxShadow="0 4px 14px rgba(0,0,0,0.08)";e.currentTarget.style.borderColor=C.brand;}} onMouseLeave={e=>{e.currentTarget.style.boxShadow="none";e.currentTarget.style.borderColor=C.line;}}>
          <div style={{padding:"9px 12px",background:C.bg,borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <span style={{fontWeight:800,fontSize:17,color:C.ink}}>โต๊ะ {o.table_number}</span>
            <span style={{fontSize:13,fontWeight:700,color:stC[o.status]||C.ink3,background:`${stC[o.status]||C.ink3}22`,padding:"2px 8px",borderRadius:20}}>{stL[o.status]||o.status}</span>
          </div>
          <div style={{padding:"9px 12px"}}>
            {o.status==="cancelled"&&<div style={{background:C.redLight,border:`1px solid ${C.red}33`,borderRadius:8,padding:"7px 10px",marginBottom:7,fontSize:13,color:C.red,lineHeight:1.55}}>
              <div style={{fontWeight:800}}>ยกเลิกโดย {o.cancelled_by||"— ไม่มีบันทึก —"}</div>
              {o.cancel_reason&&<div style={{color:"#991B1B"}}>เหตุผล: {o.cancel_reason}</div>}
            </div>}
            {(o.items||[]).slice(0,3).map((i,idx)=><div key={idx} style={{display:"flex",justifyContent:"space-between",fontSize:14,marginBottom:3,gap:8}}><span style={{color:C.ink2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{i.qty}x {i.name}</span><span style={{color:C.brand,fontWeight:700,whiteSpace:"nowrap"}}>฿{m((+i.price||0)*(+i.qty||0))}</span></div>)}
            {(o.items||[]).length>3&&<div style={{fontSize:13,color:C.ink4}}>+อีก {o.items.length-3} รายการ</div>}
            {(o.items||[]).length===0&&<div style={{fontSize:13,color:C.ink4}}>ไม่มีรายการ</div>}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:6,paddingTop:6,borderTop:`1px solid ${C.lineLight}`}}>
              <span style={{fontSize:13,color:C.ink4}}>{(()=>{
                const hhmm=(t)=>new Date(t).toLocaleTimeString("th-TH",{hour:'2-digit',minute:'2-digit'});
                const open=hhmm(o.created_at),act=o.updated_at?hhmm(o.updated_at):open;
                // เวลาเปิดโต๊ะ · เวลาที่เพิ่งมีอะไรเกิดขึ้น (ปิดบิล/แก้บิล/สั่งเพิ่ม) ถ้าไม่ใช่เวลาเดียวกัน
                return act&&act!==open?`${open} · ล่าสุด ${act}`:open;
              })()}</span>
              <span style={{fontSize:18,fontWeight:900,color:C.ink}}>฿{m(o.total)}</span>
            </div>
            <div style={{fontSize:13,color:C.brand,fontWeight:700,marginTop:7,textAlign:"right"}}>ดูรายละเอียด →</div>
          </div>
        </button>)}
      </div>}
    </>}
  </Modal>;
}

// ══════════════════════════════════════════════════════
// ── POS TAB (top-level wrapper: mode + shift) ────────
// ══════════════════════════════════════════════════════
function POSTab({menus,currentBranch,currentUser,printers=[],branches=[],reloadPrinters,reloadMenus,saleOnly=false,onExit,refreshTick=0,closeShiftSignal=0,onShiftState}){
  // saleOnly = PIN-cashier kiosk: jump straight to the sale screen, no chooser,
  // no back office; "exit" logs the cashier out (back to the PIN gate).
  const[mode,setMode]=useState(saleOnly?'sale':null);  // null | 'sale' | 'manage'
  const[shift,setShift]=useState(null);
  const[loadingShift,setLoadingShift]=useState(false);
  const[showCashDrawer,setShowCashDrawer]=useState(false);
  const[showCloseShift,setShowCloseShift]=useState(false);
  const[zones,setZones]=useState([]);
  const[posSettings,setPosSettings]=useState(null);
  const[promotions,setPromotions]=useState([]);
  async function loadZones(){try{const z=await api.getZones(currentBranch.id);setZones(z);}catch(e){console.error("loadZones",e);}}
  // ดึงไม่ผ่าน (เน็ตสะดุดรอบเดียวในรอบ 60 วิ) = ใช้ค่าที่มีอยู่ต่อ — เดิมรีเซ็ตเป็นค่าเริ่มต้น ⟹ VAT ปิด แพ็คเกจ/ราคาในแพ็คเกจหาย
  // บิลที่ปิดในจังหวะนั้นคิดยอดผิด (ตรวจทาน 19 ต.ค. 69) · ยังไม่เคยโหลดได้เลยค่อยใช้ค่าเริ่มต้น
  async function loadPosSettings(){const dflt={branch_id:currentBranch.id,vat_enabled:false,vat_rate:7,vat_included:true,service_charge_enabled:false,service_charge_rate:10};try{const s=await api.getPOSSettings(currentBranch.id);setPosSettings(s&&s[0]?s[0]:dflt);}catch{setPosSettings(prev=>(prev&&+prev.branch_id===+currentBranch.id)?prev:dflt);}}
  async function loadPromotions(){try{const p=await api.getPromotions(currentBranch.id);setPromotions(p);}catch{setPromotions([]);}}
  useEffect(()=>{loadZones();loadPosSettings();loadPromotions();},[currentBranch.id]);

  // ── หน้าขายกับหลังบ้านต้องเห็นข้อมูลชุดเดียวกัน ─────────────────────────
  // เดิมหน้าขายโหลดตั้งค่า/เมนูครั้งเดียวตอนเปิดหน้า แล้วไม่โหลดอีกเลย
  // แก้ VAT / ค่าบริการ / QR จ่ายเงิน / ราคาเมนู ที่หลังบ้าน เครื่องขายจะยังใช้ค่าเก่า
  // จนกว่าพนักงานจะรีโหลดหน้าเอง — ซึ่งไม่มีใครรู้ว่าต้องทำ = คิดเงินผิดเงียบๆ
  //
  // ตั้งค่า/โปรโมชั่น/โซน/เครื่องพิมพ์ = แถวเล็ก ดึงถี่ได้ (60 วิ)
  // เมนูเป็นก้อนใหญ่ (~300 KB) ดึงห่างกว่า (5 นาที) — ราคาไม่ได้เปลี่ยนกลางมื้อ
  // ทุกตัวหยุดเมื่อสลับแท็บออก และดึงทันทีเมื่อกลับมาที่หน้าจอ
  useEffect(()=>{
    let n=0;
    const light=()=>{loadPosSettings();loadPromotions();loadZones();try{reloadPrinters&&reloadPrinters();}catch{}};
    const heavy=()=>{try{reloadMenus&&reloadMenus();}catch{}};
    const t=setInterval(()=>{
      if(document.hidden)return;
      light();
      if(++n%5===0)heavy();   // ทุก 5 รอบ = 5 นาที
    },60000);
    const onVis=()=>{if(!document.hidden){light();heavy();}};
    document.addEventListener("visibilitychange",onVis);
    return()=>{clearInterval(t);document.removeEventListener("visibilitychange",onVis);};
  },[currentBranch.id]);   // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(()=>{
    if(mode!=='sale'){setShift(null);return;}
    setLoadingShift(true);
    api.getActiveShift(currentBranch.id).then(s=>{
      setShift(s&&s.length?s[0]:null);
      setLoadingShift(false);
    }).catch(e=>{setLoadingShift(false);alert("โหลดข้อมูลกะไม่สำเร็จ: "+e.message);});
  },[mode,currentBranch.id]);
  // รายงานสถานะ "มีกะเปิดอยู่ไหม" ให้ตัวห่อหุ้ม (kiosk bar) ใช้โชว์/ซ่อนปุ่มปิดกะ + รับสัญญาณกดปิดกะจากบาร์ด้านบน
  useEffect(()=>{if(onShiftState)onShiftState(mode==='sale'&&!!shift);},[mode,shift]);// eslint-disable-line
  useEffect(()=>{if(closeShiftSignal>0&&mode==='sale'&&shift)setShowCloseShift(true);},[closeShiftSignal]);// eslint-disable-line

  // เจ้าของสั่ง 24 ก.ย. 69: รายงานยอดขายเปิดให้ทุกคนที่เข้าหน้าขายได้ (พนักงานสาขาต้องดูยอดของตัวเองได้)
  // แต่จัดการหลังบ้านยังจำกัดเฉพาะคนที่มีสิทธิ์ตั้งค่า หรือ "จัดการ POS" (pos_admin) — ผู้จัดการสาขาปิด PIN คนลาออกได้เองตอนดึก
  // ส่วนเรื่องเงินในหลังบ้าน (VAT/พร้อมเพย์/โปรโมชั่น) POSBackOffice ซ่อนเองถ้าไม่มีสิทธิ์ตั้งค่า
  // โหมดแคชเชียร์ที่เข้าด้วย PIN (ลิงก์ขายของสาขา) ยังเป็นจอขายล้วน — ไม่มีตัวเลือกโหมดให้กดอยู่แล้ว
  const canReport=!saleOnly;
  const posAcc=posAccess(currentUser,saleOnly);
  const canManage=posAcc.admin;
  // Where "exit" goes: kiosk cashier → logout to PIN gate; normal user → mode chooser.
  const exitSale=()=>{if(saleOnly){onExit&&onExit();}else{setMode(null);}};
  if(mode===null)return <POSModeSelect onSelect={setMode} canManage={canManage} canReport={canReport}/>;
  // รายงานยอดขาย — อ่านอย่างเดียว ไม่แตะบิลหรือกะ เปิดจากตัวเลือกโหมดเท่านั้น
  if(mode==='report'){
    if(!canReport){setMode(null);return null;}
    return <POSSalesReport currentBranch={currentBranch} currentUser={currentUser} onExit={()=>setMode(null)}/>;
  }
  if(mode==='manage'){
    if(!canManage){setMode(null);return null;}
    return <POSBackOffice currentBranch={currentBranch} currentUser={currentUser} printers={printers} reloadPrinters={reloadPrinters} branches={branches} zones={zones} reloadZones={loadZones} menus={menus} reloadMenus={reloadMenus} onExit={()=>{setMode(null);loadZones();loadPosSettings();loadPromotions();}}/>;
  }
  // mode === 'sale'
  if(loadingShift)return <Loading text="ตรวจสอบกะการขาย..."/>;
  if(!shift)return <OpenShiftModal currentBranch={currentBranch} currentUser={currentUser} onDone={s=>setShift(s)} onCancel={exitSale}/>;
  return <>
    <POSSaleMode menus={menus} reloadMenus={reloadMenus} reloadPrinters={reloadPrinters} currentBranch={currentBranch} currentUser={currentUser} printers={printers} shift={shift} zones={zones} posSettings={posSettings} promotions={promotions} onUpdateShift={setShift} onCashDrawer={()=>setShowCashDrawer(true)} onCloseShift={()=>setShowCloseShift(true)} onExitMode={exitSale} saleOnly={saleOnly} reloadPosSettings={loadPosSettings} refreshTick={refreshTick} reloadZones={loadZones}/>
    {showCashDrawer&&<CashDrawerModal shift={shift} currentBranch={currentBranch} currentUser={currentUser} printers={printers} onClose={()=>setShowCashDrawer(false)}/>}
    {showCloseShift&&<CloseShiftModal shift={shift} currentBranch={currentBranch} currentUser={currentUser} onClose={()=>setShowCloseShift(false)} onClosed={()=>{setShowCloseShift(false);setShowCashDrawer(false);setShift(null);if(!saleOnly)setMode(null);}}/>}
  </>;
}

// ══════════════════════════════════════════════════════
// ── POS PIN GATE (cashier sell link: ?pos=1&branch=ID) ─
// ══════════════════════════════════════════════════════
// Branch staff open the branch's sell link, type their 4-digit PIN, and drop
// straight into the sale screen. PINs are defined per-branch in POS back office
// (stored in pos_settings.sales_staff). No username/password, no main app.
function POSPinGate({branchId}){
  const[branch,setBranch]=useState(null);
  const[staff,setStaff]=useState([]);
  const[menus,setMenus]=useState([]);
  const[printers,setPrinters]=useState([]);
  const[loading,setLoading]=useState(true);
  const[err,setErr]=useState("");
  const[pin,setPin]=useState("");
  const[seller,setSeller]=useState(null);
  const[shake,setShake]=useState(false);
  const[tick,setTick]=useState(0);
  const[posRefreshTick,setPosRefreshTick]=useState(0);   // kiosk header → triggers POSSaleMode.loadAll
  const[shiftOpen,setShiftOpen]=useState(false);         // มีกะเปิดอยู่ไหม (POSTab รายงานมา) → โชว์ปุ่มปิดกะบนแถบบน
  const[closeShiftReq,setCloseShiftReq]=useState(0);     // กดปุ่มปิดกะบนแถบบน → ส่งสัญญาณให้ POSTab เปิดหน้าปิดกะ
  useEffect(()=>{
    let alive=true;setLoading(true);setErr("");
    (async()=>{
      try{
        const[bs,ps,ms,prs]=await Promise.all([api.getBranches(),api.getPOSSettings(branchId),api.getMenus(),api.getAllPrinters()]);
        if(!alive)return;
        const b=(bs||[]).find(x=>+x.id===+branchId);
        if(!b){setErr("ไม่พบสาขานี้ — ลิงก์อาจไม่ถูกต้อง");setLoading(false);return;}
        if(b.active===false){setErr("สาขานี้ถูกปิดใช้งาน");setLoading(false);return;}
        if(b.type==="central"){setErr("ครัวกลางไม่ได้เปิดขายหน้าร้าน");setLoading(false);return;}
        const settings=ps&&ps[0]?ps[0]:null;
        setBranch(b);setStaff(Array.isArray(settings?.sales_staff)?settings.sales_staff:[]);
        setMenus(ms||[]);setPrinters(printersAt(prs,branchId));
      }catch(e){if(alive)setErr(e&&e.message||String(e));}
      if(alive)setLoading(false);
    })();
    return()=>{alive=false;};
  },[branchId,tick]);
  useEffect(()=>{
    if(pin.length<4)return;
    const code=pin.slice(0,4);
    const found=(staff||[]).find(s=>s&&s.active!==false&&String(s.pin)===code);
    if(found){setSeller(found);setPin("");}
    else{setShake(true);setTimeout(()=>{setShake(false);setPin("");},480);}
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[pin]);
  // ── เปลี่ยนพนักงานกลางกะ ─────────────────────────────────────────────────
  // เดิมไม่มีทางเปลี่ยนคนบน iPad เครื่องเดิม → บิลที่ปิด/ยกเลิกตอนบ่ายขึ้นชื่อพนักงานกะเช้าทั้งหมด
  // กลับไปหน้า PIN อย่างเดียว ไม่แตะกะ (กะอยู่ในฐานข้อมูล คนถัดไปใส่ PIN แล้วเข้ากะเดิมต่อ)
  // และโหลดรายชื่อ PIN ใหม่ — PIN ที่เพิ่งเพิ่ม/ปิด (คนลาออก) ต้องมีผลทันทีโดยไม่ต้องรีโหลดหน้า
  async function reloadStaff(){try{const ps=await api.getPOSSettings(branchId);const st=ps&&ps[0]?ps[0]:null;setStaff(Array.isArray(st?.sales_staff)?st.sales_staff:[]);}catch{}}
  async function switchSeller(){
    if(!await confirmDlg({title:"👤 เปลี่ยนพนักงาน?",message:"กลับไปหน้าใส่ PIN ให้พนักงานคนถัดไป\n\nกะยังเปิดอยู่ตามเดิม ไม่ต้องปิดกะ — บิลต่อจากนี้จะขึ้นชื่อคนที่ใส่ PIN ใหม่\n\nถ้ามีโต๊ะที่กำลังเปิดอยู่และยังไม่ได้กดส่ง/บันทึก รายการนั้นจะหายไป",confirmLabel:"เปลี่ยนพนักงาน",cancelLabel:"ยกเลิก"}))return;
    setSeller(null);setPin("");setShiftOpen(false);
    reloadStaff();
  }
  const isMobile=useIsMobile();
  if(loading)return <><style>{globalStyle}</style><div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:`linear-gradient(135deg,${C.brandLight},#FEF3C7)`}}><Loading text="กำลังโหลด..."/></div></>;
  if(err)return <><style>{globalStyle}</style><div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:`linear-gradient(135deg,${C.redLight},#FEF3C7)`,padding:20,fontFamily:"'Sarabun',sans-serif"}}>
    <div style={{background:C.white,borderRadius:18,padding:"32px 28px",maxWidth:380,width:"100%",textAlign:"center",boxShadow:"0 20px 60px rgba(0,0,0,.12)"}}>
      <div style={{fontSize:48,marginBottom:10}}>⚠️</div>
      <div style={{fontSize:16,fontWeight:900,color:C.red,marginBottom:8}}>เปิดหน้าขายไม่ได้</div>
      <div style={{fontSize:13,color:C.ink3,marginBottom:16,lineHeight:1.6}}>{err}</div>
      <button onClick={()=>setTick(t=>t+1)} style={{background:C.brand,color:C.white,border:"none",borderRadius:10,padding:"10px 20px",cursor:"pointer",fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:800}}>ลองอีกครั้ง</button>
    </div>
  </div></>;
  // Authenticated → kiosk sale screen
  if(seller){
    const synthUser={id:null,username:seller.name||"พนักงานขาย",name:seller.name||"พนักงานขาย",role:"staff",perms:["pos"]};
    return <><style>{globalStyle}</style>
      <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",background:C.bg}}>
        <div style={{display:"flex",alignItems:"center",gap:12,padding:isMobile?"10px 14px":"12px 22px",paddingTop:isMobile?"calc(10px + env(safe-area-inset-top,0px))":"calc(12px + env(safe-area-inset-top,0px))",background:"linear-gradient(135deg,#0F172A,#1E293B)",color:"#F8FAFC",flexShrink:0,boxShadow:"0 2px 10px rgba(15,23,42,.25)"}}>
          <div style={{width:34,height:34,borderRadius:10,background:`linear-gradient(135deg,${C.brand},${C.brandDark})`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Ic d={I.shop} s={18} c="#fff"/></div>
          <div style={{minWidth:0,flex:1,display:"flex",alignItems:"center",gap:10}}>
            <div style={{minWidth:0}}>
              <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:14,fontWeight:900,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>🛒 ขายหน้าร้าน · {branch.name}</div>
              <div style={{fontFamily:"'Sarabun',sans-serif",fontSize:11,color:"#94A3B8"}}>พนักงาน: {seller.name}</div>
            </div>
            <button onClick={()=>setPosRefreshTick(t=>t+1)} title="รีเฟรชข้อมูลโต๊ะ/ออเดอร์" style={{background:"rgba(255,255,255,0.1)",border:"1px solid rgba(255,255,255,0.2)",borderRadius:8,padding:"6px 12px",cursor:"pointer",color:"#E2E8F0",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:800,flexShrink:0,display:"inline-flex",alignItems:"center",gap:5,whiteSpace:"nowrap"}}><Ic d={I.refresh} s={13} c="#E2E8F0"/>รีเฟรช</button>
            <button onClick={switchSeller} title="เปลี่ยนพนักงาน — กลับหน้าใส่ PIN (กะยังเปิดอยู่)" style={{background:"rgba(255,255,255,0.1)",border:"1px solid rgba(255,255,255,0.2)",borderRadius:8,padding:"6px 12px",cursor:"pointer",color:"#E2E8F0",fontFamily:"'Sarabun',sans-serif",fontSize:12,fontWeight:800,flexShrink:0,display:"inline-flex",alignItems:"center",gap:5,whiteSpace:"nowrap"}}>👤 {isMobile?"เปลี่ยนคน":"เปลี่ยนพนักงาน"}</button>
          </div>
          {shiftOpen&&<button onClick={()=>setCloseShiftReq(n=>n+1)} title="ปิดกะการขาย & พิมพ์สรุปยอด" style={{background:"linear-gradient(135deg,#EF4444,#DC2626)",border:"none",borderRadius:11,padding:isMobile?"10px 18px":"12px 26px",cursor:"pointer",color:"#fff",fontFamily:"'Sarabun',sans-serif",fontSize:isMobile?14.5:16,fontWeight:900,flexShrink:0,display:"inline-flex",alignItems:"center",gap:7,boxShadow:"0 3px 12px rgba(239,68,68,.4)",whiteSpace:"nowrap"}}>🔚 ปิดกะ</button>}
        </div>
        <div style={{flex:1,padding:isMobile?"14px 12px":"20px 24px",minWidth:0,minHeight:0}}>
          <POSTab menus={menus} reloadMenus={async()=>{try{setMenus(await api.getMenus());}catch{}}} currentBranch={branch} currentUser={synthUser} printers={printers} branches={[]} reloadPrinters={async()=>{try{setPrinters(printersAt(await api.getAllPrinters(),branchId));}catch{}}} saleOnly onExit={()=>{setSeller(null);setPin("");}} refreshTick={posRefreshTick} closeShiftSignal={closeShiftReq} onShiftState={setShiftOpen}/>
        </div>
      </div>
    </>;
  }
  // PIN pad
  const keys=["1","2","3","4","5","6","7","8","9","del","0","ok"];
  return <><style>{globalStyle}</style>
    <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:`linear-gradient(135deg,${C.brandLight} 0%,#FEF3C7 50%,${C.blueLight} 100%)`,padding:16,fontFamily:"'Sarabun',sans-serif"}}>
      <div style={{background:C.white,borderRadius:24,padding:isMobile?"28px 22px":"36px 32px",width:"100%",maxWidth:360,boxShadow:"0 30px 80px rgba(15,23,42,.18)",animation:shake?"shakeX .45s":"mIn .4s cubic-bezier(.34,1.56,.64,1)"}}>
        <div style={{textAlign:"center",marginBottom:22}}>
          <div style={{width:60,height:60,background:`linear-gradient(135deg,${C.brand},${C.brandDark})`,borderRadius:18,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 12px",boxShadow:`0 10px 26px ${C.brand}44`}}><Ic d={I.shop} s={28} c="#fff"/></div>
          <h1 style={{fontSize:18,fontWeight:900,color:C.ink,margin:"0 0 2px"}}>ขายหน้าร้าน</h1>
          <p style={{fontSize:13,color:C.ink3,margin:0}}>{branch.name}</p>
        </div>
        <div style={{fontSize:12.5,color:C.ink3,textAlign:"center",marginBottom:12,fontWeight:600}}>ใส่ PIN พนักงานขาย 4 หลัก</div>
        <div style={{display:"flex",justifyContent:"center",gap:12,marginBottom:22}}>
          {[0,1,2,3].map(i=><div key={i} style={{width:16,height:16,borderRadius:"50%",background:i<pin.length?C.brand:C.lineLight,border:`2px solid ${i<pin.length?C.brand:C.line}`,transition:"all .15s"}}/>)}
        </div>
        {staff.length===0&&<div style={{background:C.yellowLight,border:`1px solid ${C.yellow}55`,borderRadius:10,padding:"10px 12px",fontSize:11.5,color:"#92400E",textAlign:"center",marginBottom:16,lineHeight:1.6}}>⚠️ สาขานี้ยังไม่ได้กำหนดพนักงานขาย<br/>ให้ผู้จัดการเพิ่มที่ "หลังบ้าน → พนักงานขาย"</div>}
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10}}>
          {keys.map(k=>{
            if(k==="del")return <button key={k} onClick={()=>setPin(p=>p.slice(0,-1))} style={{padding:"16px 0",borderRadius:14,border:`1.5px solid ${C.line}`,background:C.bg,cursor:"pointer",fontSize:18,fontFamily:"'Sarabun',sans-serif",fontWeight:800,color:C.ink3}}>⌫</button>;
            if(k==="ok")return <button key={k} disabled style={{padding:"16px 0",borderRadius:14,border:"none",background:"transparent",cursor:"default"}}/>;
            return <button key={k} onClick={()=>setPin(p=>(p+k).slice(0,4))} style={{padding:"16px 0",borderRadius:14,border:`1.5px solid ${C.line}`,background:C.white,cursor:"pointer",fontSize:22,fontFamily:"'Sarabun',sans-serif",fontWeight:800,color:C.ink,transition:"all .1s"}} onMouseDown={e=>{e.currentTarget.style.background=C.brandLight;e.currentTarget.style.borderColor=C.brand;}} onMouseUp={e=>{e.currentTarget.style.background=C.white;e.currentTarget.style.borderColor=C.line;}} onMouseLeave={e=>{e.currentTarget.style.background=C.white;e.currentTarget.style.borderColor=C.line;}}>{k}</button>;
          })}
        </div>
      </div>
    </div>
  </>;
}


// BranchSelector with auto-load branches
function BranchSelectorWithLoad({user,onSelect,onLogout}){
  const[branches,setBranches]=useState([]);const[loading,setLoading]=useState(true);
  useEffect(()=>{api.getBranches().then(b=>setBranches(b)).finally(()=>setLoading(false));},[]);
  if(loading)return <><style>{globalStyle}</style><div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center"}}><Loading text="กำลังโหลดรายการสาขา..."/></div></>;
  return <BranchSelector branches={branches} onSelect={onSelect} user={user} onLogout={onLogout}/>;
}

const globalStyle=`@import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@400;500;600;700;800;900&display=swap');*{margin:0;padding:0;box-sizing:border-box}html{max-width:100vw;overflow-x:hidden}body{max-width:100vw}body{background:${C.bg};font-family:'Sarabun',sans-serif;-webkit-text-size-adjust:100%;-webkit-tap-highlight-color:transparent;touch-action:manipulation}@keyframes mIn{from{opacity:0;transform:scale(.94) translateY(10px)}to{opacity:1;transform:scale(1) translateY(0)}}@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}@keyframes slideInLeft{from{transform:translateX(-100%)}to{transform:translateX(0)}}@keyframes shakeX{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-9px)}40%,80%{transform:translateX(9px)}}@keyframes navSheen{0%{transform:translateX(-140%)}100%{transform:translateX(140%)}}.navitem{position:relative;overflow:hidden;transition:transform .16s cubic-bezier(.2,.7,.3,1),box-shadow .16s ease,background .14s ease}.navitem::after{content:"";position:absolute;top:0;bottom:0;left:0;width:55%;pointer-events:none;opacity:0;z-index:0;background:linear-gradient(100deg,transparent 0%,rgba(255,168,110,.55) 45%,rgba(255,214,170,.30) 60%,transparent 100%);transform:translateX(-140%)}.navitem>*{position:relative;z-index:1}.navitem:hover{transform:translateY(-6px) scale(1.035);box-shadow:0 16px 28px rgba(74,59,51,.26),0 6px 10px rgba(74,59,51,.16);z-index:2}.navitem:hover::after{opacity:1;animation:navSheen 1.9s ease-in-out infinite}.navitem:active{transform:translateY(-1px) scale(.99);box-shadow:0 2px 6px rgba(74,59,51,.18)}@media(prefers-reduced-motion:reduce){.navitem:hover{transform:none}.navitem:hover::after{animation:none;opacity:0}}*{scrollbar-color:${C.ink4} ${C.lineLight};scrollbar-width:auto}::-webkit-scrollbar{width:12px;height:12px}::-webkit-scrollbar-track{background:${C.lineLight};border-radius:999px}::-webkit-scrollbar-thumb{background:${C.ink4};border-radius:999px;border:2px solid ${C.lineLight};min-height:40px}::-webkit-scrollbar-thumb:hover{background:${C.brand};border-color:${C.brandLight}}::-webkit-scrollbar-thumb:active{background:${C.brandDark}}::-webkit-scrollbar-corner{background:transparent}div{overscroll-behavior:contain}body.modal-open{overflow:hidden}input,select,textarea{font-size:16px}input:focus,select:focus,textarea:focus{border-color:${C.brand}!important;box-shadow:0 0 0 3px ${C.brandLight}!important;outline:none}button{touch-action:manipulation}@media(max-width:768px){button{min-height:36px}input,select,textarea{min-height:40px;font-size:16px!important}input[type=checkbox],input[type=radio]{min-height:auto}table{font-size:12px}::-webkit-scrollbar{width:8px;height:8px}::-webkit-scrollbar-thumb{border-width:1px}}@media(max-width:480px){h1,h2,h3{letter-spacing:-.2px!important}}.mdl-ovl{background:rgba(15,23,42,.72)}@media(hover:hover){.mdl-ovl{background:rgba(15,23,42,.65);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}}.mcard{transition:border-color .15s ease,background .15s ease}@media(hover:hover){.mcard:hover{border-color:${C.brand};background:${C.brandLight}}}.mcard:active{background:${C.brandLight};border-color:${C.brand}}`;
